INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wibus-wee/mcpv/project-overview', 'project-overview', 'wibus-wee', 'mcpv', 'community', 'project-overview wibus-wee mcpv community The project-overview skill provides an elastic control plane and runtime for Model Context Protocol servers, benefiting developers managing multiple MCP servers locally. mcpd是一个轻量级的弹性编排器，为Model Context Protocol服务器提供自动实例生命周期管理和统一路由 mcpdは、MCPサーバーに自動インスタンスライフサイクル管理と統一ルーティングを提供する軽量エラスティックオーケストレーターです mcpd는 모델 컨텍스트 프로토콜 서버에 자동 인스턴스 라이프사이클 관리 및 통합 라우팅을 제공하는 경량 엘라스틱 오케스트레이터입니다 Project-overview es un plan de control elástico y tiempo de ejecución para servidores de Protocolo de Contexto de Modelo, proporcionando inicio y escalado automatizados Project-overview est un plan de contrôle élastique et runtime pour les serveurs de Protocole de Contexte de Modèle, offrant un démarrage et un scaling automatiques Project-overview ist eine elastische Steuerungsebene und Laufzeitumgebung für Model Context Protocol-Server, die automatisierte Start- und Skalierungsfunktionen bietet O MCP Gateway é um controlador elástico e tempo de execução para servidores MCP, oferecendo inicialização sob demanda e hibernação de escala zero ИИ Агенты - это эластичный контрольный план и время выполнения для серверов MCP, обеспечивающий запуск по требованию и масштабирование до нуля بوابة MCP هي مراقب مرن ووقت تشغيل لخادم MCP، توفر تشغيلًا حسب الطلب وتخزين بمقياس صفر how to use project-overview project-overview alternative project-overview install what is project-overview project-overview vs CloudWeGo project-overview setup guide Model Context Protocol server management MCP Gateway optimization elastic orchestrator for MCP servers AI工具 模型上下文协议 弹性控制平面 自动实例生命周期管理 统一路由 智能工具过滤 CloudWeGo/Eino Elastic runtime with automatic instance lifecycle management Unified gateway (mcpvmcp) providing single entry point for all MCP servers Smart SubAgent powered by CloudWeGo/Eino for context-aware tool filtering Supports scale-to-zero hibernation for efficient resource management Provides on-demand startup for flexible MCP server deployment Enables unified routing for simplified MCP server management project-overview is a lightweight elastic orchestrator for Model Context Protocol servers, enabling on-demand startup and scale-to-zero hibernation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Rudra370/s3manager/s3manager-git-workflow', 'community', 'Rudra370', 's3manager', 'Rudra370/s3manager', 's3manager-git-workflow', 0, 0, 39, '2026-03-08T01:57:15.339Z', '2026-03-08T02:03:24.321Z', '0d06e5a603fc392ffe2c1faf032f51afcc6d29d324da1d727b36b9e74b89f1d8', '{"id":"Rudra370/s3manager/s3manager-git-workflow","name":"s3manager-git-workflow","description":{"en":"The s3manager-git-workflow skill provides a self-hosted web interface for managing S3-compatible storage, benefiting developers who need to manage their storage efficiently.","zh":"S3 Manager Git 工作流是一套自托管的 Web 界面，用于管理 S3 兼容存储，遵循 CRITICAL 规则","ja":"S3 マネージャー Git ワークフローは、S3 互換ストレージを管理するためのセルフホスト型 Web インターフェースです","ko":"S3 매니저 Git 워크플로우는 S3 호환 스토리지를 관리하기 위한 自托管 Web 인터페이스입니다","es":"s3manager-git-workflow es una interfaz web autohospedada para administrar almacenamientos compatibles con S3, con un enfoque en flujos de trabajo de Git","fr":"s3manager-git-workflow est une interface web auto-hébergée pour gérer les stockages compatibles S3, avec un focus sur les flux de travail Git","de":"s3manager-git-workflow ist eine selbstgehostete Web-Oberfläche zur Verwaltung von S3-kompatiblen Speicher, mit Fokus auf Git-Workflows","pt":"O S3 Manager Git Workflow é uma interface web auto-hospedada para gerenciar armazenamento S3-compatível com regras críticas de git.","ru":"S3 Manager Git Workflow — это само-хостная веб-интерфейс для управления хранилищем S3-совместимым с критическими правилами git.","ar":"S3 Manager Git Workflow هو واجهة ويب ذاتية الاستضافة لإدارة التخزين المتوافق مع S3 بأدوات ذكية"},"seo":{"title":{"en":"s3manager-git-workflow: Git Workflow Setup Guide | AI Age...","zh":"S3 Manager Git 工作流 Setup Guide","ja":"S3 マネージャー Git ワークフロー ベストプラクティス","ko":"S3 매니저 Git 워크플로우 설정 가이드","es":"Guía de Configuración de s3manager-git-workflow para Desa...","fr":"Guide de Mise en Place de s3manager-git-workflow pour Dév...","de":"Einrichtungsleitfaden für s3manager-git-workflow-Entwickler","pt":"Guia de Configuração do S3 Manager Git Workflow","ru":"Настройка S3 Manager Git Workflow: ИИ Агенты для Dev","ar":"دليل إعداد S3 Manager Git Workflow للأدوات الذكية"},"description":{"en":"Learn how to manage S3-compatible storage with s3manager-git-workflow. Follow critical rules for a seamless Git workflow experience. Get started now!","zh":"了解 S3 Manager Git 工作流的 CRITICAL 规则，包括分支管理和提交指南，AIエージェント","ja":"S3 マネージャーの Git ワークフローで CRITICAL ルールをマスターする方法、AIエージェント","ko":"S3 매니저 Git 워크플로우의 CRITICAL 규칙을 알아보세요, 분기 관리 및 커밋 가이드, AI 도구","es":"Aprende a configurar s3manager-git-workflow para un flujo de trabajo de Git óptimo y descubre sus características clave para desarrolladores","fr":"Découvrez comment configurer s3manager-git-workflow pour un flux de travail Git optimal et explorez ses fonctionnalités clés pour les développeurs","de":"Erfahren Sie, wie Sie s3manager-git-workflow für einen optimalen Git-Workflow konfigurieren und entdecken Sie dessen wichtigste Funktionen für Entwickler","pt":"Aprenda a configurar o S3 Manager Git Workflow para gerenciar armazenamento S3-compatível com regras críticas de git","ru":"Узнайте, как настроить S3 Manager Git Workflow для управления хранилищем S3 с критическими правилами git и ИИ Агентами","ar":"تعرف على كيفية إعداد S3 Manager Git Workflow لإدارة التخزين المتوافق مع S3 بأدوات ذكية ومبادئ توجيهية حاسمة"},"definition":{"en":"s3manager-git-workflow is a skill that enforces critical Git workflow rules for managing S3-compatible storage, ensuring a smooth development experience.","zh":"S3 Manager Git 工作流是管理 S3 兼容存储的自托管 Web 界面","ja":"S3 マネージャー Git ワークフローとは、S3 互換ストレージを管理するためのツールです","ko":"S3 매니저 Git 워크플로우는 S3 호환 스토리지를 관리하기 위한 도구입니다","es":"s3manager-git-workflow es una herramienta de Agente de IA para administrar almacenamientos S3 mediante Git","fr":"s3manager-git-workflow est un outil d''Agent d''IA pour gérer les stockages S3 via Git","de":"s3manager-git-workflow ist ein Tool für künstliche Intelligenz-Agenten zur Verwaltung von S3-Speicher über Git","pt":"O que é S3 Manager Git Workflow? É uma ferramenta de gerenciamento de armazenamento S3-compatível com interface web.","ru":"Что такое S3 Manager Git Workflow? Это инструмент для управления хранилищем S3-совместимым с веб-интерфейсом.","ar":"ما هو S3 Manager Git Workflow؟ هو أداة لإدارة التخزين المتوافق مع S3 بواجهة ويب"},"features":{"en":["Enforces Git workflow rules using `git checkout dev` command","Prevents direct commits to `main` branch","Supports manual merging to `main` branch","Requires explicit branch creation from `dev` using `git checkout -b dev`","Mandates commit messages with explicit explanations","Utilizes Bash scripting for automation"],"zh":["基于 Git 的分支管理","CRITICAL 规则确保代码提交质量","支持 S3 兼容存储","自托管 Web 界面","严格的代码审查流程"],"ja":["Git ベースのブランチ管理","CRITICAL ルールによるコード品質の確保","S3 互換ストレージのサポート","セルフホスト型 Web インターフェース","厳格なコードレビューのプロセス"],"ko":["Git 기반 분기 관리","CRITICAL 규칙을 통한 코드 품질 보증","S3 호환 스토리지 지원","自托管 Web 인터페이스","엄격한 코드 리뷰 프로세스"],"es":["Trabajo en la rama ''dev'' para cambios de código","Uso de ''git checkout dev'' para cambios de código","Prohibición de commits directos en la rama ''main''","Soporte para flujos de trabajo de Git personalizados","Interfaz web autohospedada para administrar almacenamientos S3"],"fr":["Travail sur la branche ''dev'' pour les modifications de code","Utilisation de ''git checkout dev'' pour les modifications de code","Interdiction de commits directs sur la branche ''main''","Prise en charge de flux de travail Git personnalisés","Interface web auto-hébergée pour gérer les stockages S3"],"de":["Arbeit auf dem ''dev''-Zweig für Code-Änderungen","Verwendung von ''git checkout dev'' für Code-Änderungen","Verbot von direkten Commits auf dem ''main''-Zweig","Unterstützung für benutzerdefinierte Git-Workflows","Selbstgehostete Web-Oberfläche zur Verwaltung von S3-Speicher"],"pt":["Trabalhe na branch dev","Nunca commite diretamente na branch main","Nunca crie branches a partir da branch main","Nunca faça merge para a branch main","Use git checkout dev para começar a trabalhar"],"ru":["Работайте на ветке dev","Никогда не коммитите напрямую в ветку main","Никогда не создавайте ветки из ветки main","Никогда не сливайте в ветку main","Используйте git checkout dev для начала работы"],"ar":["اعمل على الفرع dev","لا تقم أبداً بالالتزام المباشر في الفرع الرئيسي","لا تقم أبداً بإنشاء فروع من الفرع الرئيسي","لا تقم أبداً بالدمج في الفرع الرئيسي","استخدم git checkout dev لبدء العمل"]},"keywords":{"en":["how to use s3manager-git-workflow","s3manager-git-workflow setup guide","s3manager-git-workflow alternative","s3manager-git-workflow vs AWS S3","git workflow management","S3-compatible storage solutions","self-hosted web interface for S3","git checkout dev command","manual merging to main branch"],"zh":["S3 Manager Git 工作流","AIエージェント","Git 分支管理","S3 兼容存储","自托管 Web 界面","CRITICAL 规则","代码提交指南"],"ja":["S3 マネージャー Git ワークフロー","AIエージェント","Git ブランチ管理","S3 互換ストレージ","セルフホスト型 Web インターフェース","CRITICAL ルール","コード品質の確保"],"ko":["S3 매니저 Git 워크플로우","AI 도구","Git 분기 관리","S3 호환 스토리지","自托管 Web 인터페이스","CRITICAL 규칙","코드 품질 보증"],"es":["s3manager-git-workflow","Agente de IA para S3","Flujo de trabajo de Git","Almacenamiento S3","Desarrollo de software","Herramientas de desarrollo","Git para desarrolladores","S3 compatible"],"fr":["s3manager-git-workflow","Agent d''IA pour S3","Flux de travail Git","Stockage S3","Développement de logiciels","Outils de développement","Git pour développeurs","S3 compatible"],"de":["s3manager-git-workflow","künstliche Intelligenz-Agent für S3","Git-Workflow","S3-Speicher","Software-Entwicklung","Entwicklertools","Git für Entwickler","S3-kompatibel"],"pt":["S3 Manager Git Workflow","gerenciamento de armazenamento S3","regras críticas de git","interface web auto-hospedada","desenvolvimento de software","ferramentas de desenvolvimento","git workflow","S3 compatible storage"],"ru":["S3 Manager Git Workflow","управление хранилищем S3","критические правила git","само-хостная веб-интерфейс","разработка программного обеспечения","инструменты разработки","git workflow","ИИ Агенты для dev","S3 совместимое хранилище"],"ar":["S3 Manager Git Workflow","إدارة التخزين المتوافق مع S3","مبادئ توجيهية حاسمة لجيت","واجهة ويب ذاتية الاستضافة","تطوير البرمجيات","أدوات التطوير","جيت ووركفلو","أدوات ذكية للتنمية","التخزين المتوافق مع S3"]}},"owner":"Rudra370","repo":"s3manager","repoPath":"Rudra370/s3manager","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.339Z","topics":[],"category":"community","skillMd":{"name":"s3manager-git-workflow","description":"MANDATORY git workflow for S3 Manager project. Triggers when asked to implement features, fix bugs, refactor code, make changes, or write tests. ENFORCES critical rules that must NEVER be violated.","bodyPreview":"# S3 Manager Git Workflow\n\nThis skill contains CRITICAL rules that MUST be followed for any code changes to the S3 Manager project.\n\n## ⚠️ CRITICAL RULES - NEVER VIOLATE\n\n### Rule 1: ALWAYS Work on `dev` Branch\n```bash\n# Before making ANY code changes, run:\ngit checkout dev\n\n# If dev doesn''t exist:\ngit checkout -b dev\n```\n- **NEVER** commit directly to `main`\n- **NEVER** create branches from `main`\n- **NEVER** merge to `main` — the user handles this manually\n\n### Rule 2: NEVER Commit Without Exp","body":"# S3 Manager Git Workflow\n\nThis skill contains CRITICAL rules that MUST be followed for any code changes to the S3 Manager project.\n\n## ⚠️ CRITICAL RULES - NEVER VIOLATE\n\n### Rule 1: ALWAYS Work on `dev` Branch\n```bash\n# Before making ANY code changes, run:\ngit checkout dev\n\n# If dev doesn''t exist:\ngit checkout -b dev\n```\n- **NEVER** commit directly to `main`\n- **NEVER** create branches from `main`\n- **NEVER** merge to `main` — the user handles this manually\n\n### Rule 2: NEVER Commit Without Explicit Permission\n- **ALWAYS ask**: \"Should I commit these changes?\"\n- Wait for explicit \"yes\" or \"commit them\" before running `git commit`\n- Do NOT use `git add -f` for gitignored files\n- The user handles commits and pushes\n\n### Rule 3: E2E Test-First Workflow (MANDATORY)\nFor ANY new feature or bug fix:\n\n1. **Write E2E test FIRST** — before touching implementation code\n   - Tests are in `/e2e/test_runner.py`\n   - Add test method to `S3ManagerE2ETests` class\n\n2. **Run test (expect failure)**\n   ```bash\n   cd /root/code/s3manager/e2e && python3 test_runner.py\n   ```\n\n3. **Implement the fix/feature**\n\n4. **Run test again (expect success)**\n   ```bash\n   cd /root/code/s3manager/e2e && python3 test_runner.py\n   ```\n\n5. **Ask permission to commit**\n\n## Workflow Checklist\n\nBefore starting any code change:\n- [ ] `git checkout dev` — on dev branch\n- [ ] Write E2E test first (if feature/fix)\n- [ ] Run test — confirm it fails\n- [ ] Implement change\n- [ ] Run test — confirm it passes\n- [ ] Ask user: \"Should I commit these changes?\"\n\n## Trigger Phrases\n\nThis skill activates when user says things like:\n- \"Fix this bug\"\n- \"Implement feature X\"\n- \"Add Y functionality\"\n- \"Refactor Z\"\n- \"Write a test for...\"\n- \"Update the code to...\"\n- Any request involving code changes\n\n## Quick Commands\n\n```bash\n# Check current branch\ngit branch --show-current\n\n# Checkout dev (or create if missing)\ngit checkout dev 2>/dev/null || git checkout -b dev\n\n# Run E2E tests\ncd /root/code/s3manager/e2e && python3 test_runner.py\n\n# Run fast E2E tests (truncate DB, ~10s faster)\nmake test-fast\n```\n\n## Project Context\n\n- **Backend**: FastAPI + SQLAlchemy + PostgreSQL\n- **Frontend**: React + Material-UI + Vite\n- **Tests**: Playwright E2E tests in `/e2e/`\n- **Default S3**: MinIO (no AWS credentials needed for testing)\n- **Working directory**: `/root/code/s3manager`\n\n## Reminder\n\n**STOP and CHECK**: Am I on `dev` branch? Have I asked permission before committing?\n\nIf the user explicitly says \"commit this\" or \"commit these changes\" — then commit. Otherwise, ask first.\n"},"lastSynced":"2026-03-08T02:03:24.321Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing streamlined S3 storage management and Git workflow automation.","zh":"非常适合需要简化 S3 存储管理和 Git 工作流自动化的 DevOps Agent。","ja":"DevOps Agent が S3 ストレージ管理と Git ワークフロー自動化を簡素化する必要がある場合は、最適です。","ko":"S3 저장소 관리와 Git 워크플ロー 자동화를 간소화해야 하는 DevOps 에이전트에게 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan una gestión de almacenamiento de S3 optimizada y una automatización de flujo de trabajo de Git.","fr":"Parfait pour les agents DevOps ayant besoin d''une gestion de stockage S3 rationalisée et d''une automatisation du flux de travail Git.","de":"Perfekt für DevOps-Agents, die eine optimierte S3-Speicherverwaltung und eine Automatisierung des Git-Workflows benötigen.","pt":"Perfeito para Agentes DevOps que necessitam de uma gestão simplificada do armazenamento S3 e automação de fluxo de trabalho Git.","ru":"Идеально подходит для DevOps-агентов, которым требуется упрощенное управление хранилищем S3 и автоматизация рабочих процессов Git.","ar":"مثالي لوكلاء DevOps الذين يحتاجون إلى إدارة مبسطة لتخزين S3 وأتمتة سير عمل Git."},"recommendation":{"en":"Empowers agents to manage S3-compatible storage efficiently through a self-hosted web interface, enforcing critical Git workflow rules such as always working on the ''dev'' branch and never committing without proper review, utilizing Git protocols and S3 storage protocols.","zh":"赋予代理管理 S3 兼容存储的能力，通过自托管的 web 界面高效地管理，强制执行关键的 Git 工作流规则，例如始终在 ''dev'' 分支上工作，且在未经适当审查的情况下不提交，利用 Git 协议和 S3 存储协议。","ja":"エージェントが S3 互換ストレージを効率的に管理できるようにし、セルフホストされた Web インターフェイスを介して重要な Git ワークフロー規則を適用する、たとえば常に ''dev'' ブランチで作業し、適切なレビューなしにコミットしない、Git プロトコルと S3 ストレージプロトコルを使用する。","ko":"에이전트가 S3 호환 저장소를 효율적으로 관리할 수 있도록 하며, 자체 호스팅 웹 인터페이스를 통해 중요한 Git 워크플ロー 규칙을 적용합니다. 예를 들어 항상 ''dev'' 브랜치에서 작업하고 적절한 검토 없이 커밋하지 않으며, Git 프로토콜과 S3 저장소 프로토콜을 사용합니다.","es":"Habilita a los agentes a gestionar el almacenamiento compatible con S3 de forma eficiente a través de una interfaz web autoalojada, aplicando reglas críticas de flujo de trabajo de Git como siempre trabajar en la rama ''dev'' y nunca confirmar sin una revisión adecuada, utilizando protocolos Git y protocolos de almacenamiento de S3.","fr":"Permet aux agents de gérer efficacement le stockage compatible S3 via une interface web auto-hébergée, en appliquant des règles critiques de flux de travail Git telles que travailler toujours sur la branche ''dev'' et ne jamais valider sans examen approprié, en utilisant les protocoles Git et les protocoles de stockage S3.","de":"Ermöglicht es Agenten, S3-kompatiblen Speicher über eine selbstgehostete Web-Oberfläche effizient zu verwalten, indem kritische Git-Workflow-Regeln wie immer auf dem ''dev''-Zweig arbeiten und nie ohne ordnungsgemäße Überprüfung committen, Git-Protokolle und S3-Speicherprotokolle verwendend.","pt":"Capacita os agentes a gerenciar o armazenamento compatível com S3 de forma eficiente através de uma interface web self-hosted, aplicando regras críticas de fluxo de trabalho Git, como trabalhar sempre no branch ''dev'' e nunca fazer commit sem uma revisão adequada, utilizando protocolos Git e protocolos de armazenamento S3.","ru":"Позволяет агентам эффективно управлять совместимым с S3 хранилищем через самостоятельно размещенный веб-интерфейс, применяя критически важные правила рабочего процесса Git, такие как работа исключительно в ветке ''dev'' и запрет коммитов без надлежащего ревью, с использованием протоколов Git и протоколов хранения S3.","ar":"يمكّن الوكلاء من إدارة التخزين المتوافق مع S3 بكفاءة من خلال واجهة ويب ذاتية الاستضافة، مع فرض قواعد حرجة لسير عمل Git مثل العمل دائمًا على الفرع ''dev'' وعدم الإيداع دون مراجعة مناسبة، باستخدام بروتوكولات Git وبروتوكولات تخزين S3."},"useCases":{"en":["Automating S3 bucket management","Enforcing Git workflow best practices","Streamlining developer storage management"],"zh":["自动化 S3 存储桶管理","强制执行 Git 工作流最佳实践","简化开发者存储管理"],"ja":["S3 バケット管理の自動化","Git ワークフローのベストプラクティスの適用","開発者のストレージ管理の簡素化"],"ko":["S3 버킷 관리 자동화","Git 워크플로우 최선의 관행 적용","개발자 저장소 관리 간소화"],"es":["Automatización de la gestión de cubetas de S3","Aplicación de las mejores prácticas de flujo de trabajo de Git","Optimización de la gestión de almacenamiento de desarrolladores"],"fr":["Automatisation de la gestion des buckets S3","Application des meilleures pratiques de flux de travail Git","Optimisation de la gestion de stockage des développeurs"],"de":["Automatisierung der S3-Bucket-Verwaltung","Einhalten der besten Praktiken für den Git-Workflow","Optimierung der Speicherverwaltung für Entwickler"],"pt":["Automatização da gestão de buckets S3","Aplicação das melhores práticas de fluxo de trabalho Git","Simplificação da gestão de armazenamento para desenvolvedores"],"ru":["Автоматизация управления бакетами S3","Внедрение лучших практик рабочего процесса Git","Упрощение управления хранилищем для разработчиков"],"ar":["أتمتة إدارة buckets في S3","فرض أفضل ممارسات سير عمل Git","تبسيط إدارة التخزين للمطورين"]},"limitations":{"en":["Requires Git version control system","Limited to S3-compatible storage","Manual merge to ''main'' branch required"],"zh":["需要 Git 版本控制系统","仅限 S3 兼容存储","需要手动合并到 ''main'' 分支"],"ja":["Git バージョン管理システムが必要","S3 互換ストレージに限定される","手動で ''main'' ブランチにマージする必要がある"],"ko":["Git 버전 관리 시스템이 필요합니다.","S3 호환 저장소로 제한됩니다.","수동으로 ''main'' 브랜치에 병합해야 합니다."],"es":["Requiere sistema de control de versiones Git","Limitado a almacenamiento compatible con S3","Se requiere una fusión manual en la rama ''main''"],"fr":["Nécessite un système de contrôle de version Git","Limité au stockage compatible S3","Une fusion manuelle dans la branche ''main'' est requise"],"de":["Benötigt Git-Versionssystem","Begrenzt auf S3-kompatiblen Speicher","Manuelle Zusammenführung in den ''main''-Zweig erforderlich"],"pt":["Requer o sistema de controle de versão Git","Limitado a armazenamento compatível com S3","Requer merge manual para o branch ''main''"],"ru":["Требует систему контроля версий Git","Ограничено хранилищем, совместимым с S3","Требуется ручное слияние в ветку ''main''"],"ar":["يتطلب نظام تحكم في الإصدار Git","يقتصر على التخزين المتوافق مع S3","يتطلب دمجًا يدويًا إلى الفرع ''main''"]},"version":4},"contentHash":"0d06e5a603fc392ffe2c1faf032f51afcc6d29d324da1d727b36b9e74b89f1d8","qualityScore":39}');
