INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Rudra370/s3manager/s3manager-git-workflow', 's3manager-git-workflow', 'Rudra370', 's3manager', 'community', 's3manager-git-workflow Rudra370 s3manager community The s3manager-git-workflow skill provides a self-hosted web interface for managing S3-compatible storage, benefiting developers who need to manage their storage efficiently. S3 Manager Git 工作流是一套自托管的 Web 界面，用于管理 S3 兼容存储，遵循 CRITICAL 规则 S3 マネージャー Git ワークフローは、S3 互換ストレージを管理するためのセルフホスト型 Web インターフェースです S3 매니저 Git 워크플로우는 S3 호환 스토리지를 관리하기 위한 自托管 Web 인터페이스입니다 s3manager-git-workflow es una interfaz web autohospedada para administrar almacenamientos compatibles con S3, con un enfoque en flujos de trabajo de Git s3manager-git-workflow est une interface web auto-hébergée pour gérer les stockages compatibles S3, avec un focus sur les flux de travail Git s3manager-git-workflow ist eine selbstgehostete Web-Oberfläche zur Verwaltung von S3-kompatiblen Speicher, mit Fokus auf Git-Workflows O S3 Manager Git Workflow é uma interface web auto-hospedada para gerenciar armazenamento S3-compatível com regras críticas de git. S3 Manager Git Workflow — это само-хостная веб-интерфейс для управления хранилищем S3-совместимым с критическими правилами git. S3 Manager Git Workflow هو واجهة ويب ذاتية الاستضافة لإدارة التخزين المتوافق مع S3 بأدوات ذكية how to use s3manager-git-workflow s3manager-git-workflow setup guide s3manager-git-workflow alternative s3manager-git-workflow vs AWS S3 git workflow management S3-compatible storage solutions self-hosted web interface for S3 git checkout dev command manual merging to main branch S3 Manager Git 工作流 AIエージェント Git 分支管理 S3 兼容存储 自托管 Web 界面 CRITICAL 规则 代码提交指南 Enforces Git workflow rules using `git checkout dev` command Prevents direct commits to `main` branch Supports manual merging to `main` branch Requires explicit branch creation from `dev` using `git checkout -b dev` Mandates commit messages with explicit explanations Utilizes Bash scripting for automation s3manager-git-workflow is a skill that enforces critical Git workflow rules for managing S3-compatible storage, ensuring a smooth development experience.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vonomarap/kanokna/frontend-patterns', 'community', 'vonomarap', 'kanokna', 'vonomarap/kanokna', 'frontend-patterns', 0, 0, 39, '2026-03-08T01:57:15.339Z', '2026-03-08T02:03:24.379Z', '193bfa61755991340c89e033b860fe7e84dd47ab013c844c09069e6e3543f21a', '{"id":"vonomarap/kanokna/frontend-patterns","name":"frontend-patterns","description":{"en":"The frontend-patterns skill provides modern frontend development patterns for React, Next.js, and performant user interfaces, benefiting developers who want to build efficient and scalable applications.","zh":"前端模式是指在 React 和 Next.js 中构建高性能用户界面的现代方法，包括组件模式和组合优于继承的技巧","ja":"フロントエンドパターンとは、React と Next.js で高パフォーマンスのユーザーインターフェイスを構築するためのモダンな方法であり、コンポーネントパターンとコンポジションオーバー継承のテクニックを含む","ko":"프론트엔드 패턴은 React와 Next.js에서 고성능 사용자 인터페이스를 구축하기 위한 현대적인 방법으로, 컴포넌트 패턴 및 구성 위에 상속 기술을 포함한다","es":"Patrones de frontend modernos para React y Next.js. Mejora la composición de componentes y la interfaz de usuario","fr":"Modèles de frontend modernes pour React et Next.js. Améliorez la composition de composants et l''interface utilisateur","de":"Moderne Frontend-Muster für React und Next.js. Verbessern Sie die Komposition von Komponenten und die Benutzeroberfläche","pt":"Padrões de frontend para React, Next.js e interfaces de usuário performáticas","ru":"Фронтенд-шаблоны для React, Next.js и производительных интерфейсов пользователя","ar":"نماذج واجهة المستخدم الأمامية للreact و Next.js وواجهات المستخدم عالية الأداء"},"seo":{"title":{"en":"frontend-patterns: Modern Frontend Development Setup Guid...","zh":"前端模式搭建指南 - React 和 Next.js 最佳实践","ja":"フロントエンドパターンの設定ガイド - React と Next.js のベストプラクティス","ko":"프론트엔드 패턴 설정 가이드 - React와 Next.js를 위한 모범 사례","es":"Patrones de frontend: Guía de configuración para React y ...","fr":"Modèles de frontend : Meilleures pratiques pour React et ...","de":"Frontend-Muster: Einrichtungsleitfaden für React und Next.js","pt":"Padrões de Frontend: Guia de Configuração para React e Ne...","ru":"Фронтенд-шаблоны: Настройка для React, Next.js и ИИ Агентов","ar":"نماذج واجهة المستخدم الأمامية: دليل الإعداد للreact و Nex..."},"description":{"en":"Unlock efficient frontend development with frontend-patterns. Learn how to implement modern patterns for React, Next.js, and performant user interfaces. Get ...","zh":"了解如何使用 React 和 Next.js 构建高性能用户界面，掌握组件模式和组合优于继承的技巧","ja":"React と Next.js を使用して高パフォーマンスのユーザーインターフェイスを構築する方法を学び、コンポーネントパターンとコンポジションオーバー継承のテクニックをマスターする","ko":"React와 Next.js를 사용하여 고성능 사용자 인터페이스를 구축하는 방법을 배우고, 컴포넌트 패턴 및 구성 위에 상속 기술을 마스터하십시오","es":"Descubre los patrones de frontend más modernos para React, Next.js y interfaces de usuario performantes. Mejora tu desarrollo con nuestros expertos","fr":"Découvrez les modèles de frontend les plus modernes pour React, Next.js et interfaces utilisateur performantes. Améliorez votre développement avec nos experts","de":"Entdecken Sie die modernsten Frontend-Muster für React, Next.js und performante Benutzeroberflächen. Verbessern Sie Ihre Entwicklung mit unseren Experten","pt":"Aprenda a implementar padrões de frontend modernos com React, Next.js e interfaces de usuário performáticas","ru":"Узнайте, как реализовать современные фронтенд-шаблоны с React, Next.js и производительными интерфейсами пользователя","ar":"تعلم كيفية تنفيذ نماذج واجهة المستخدم الأمامية الحديثة مع react و Next.js وواجهات المستخدم عالية الأداء"},"definition":{"en":"frontend-patterns is a set of modern frontend development patterns for building efficient and scalable applications with React, Next.js, and other technologies.","zh":"前端模式是指在前端开发中使用的设计模式和最佳实践","ja":"フロントエンドパターンとは、フロントエンド開発で使用されるデザインパターンとベストプラクティスのこと","ko":"프론트엔드 패턴은 프론트엔드 개발에서 사용되는 디자인 패턴과 모범 사례를 말한다","es":"Los patrones de frontend son técnicas para crear interfaces de usuario performantes y escalables con React y Next.js","fr":"Les modèles de frontend sont des techniques pour créer des interfaces utilisateur performantes et évolutives avec React et Next.js","de":"Frontend-Muster sind Techniken zur Erstellung von performanten und skalierbaren Benutzeroberflächen mit React und Next.js","pt":"Padrões de frontend são técnicas de desenvolvimento para criar interfaces de usuário eficientes","ru":"Фронтенд-шаблоны - это техники разработки для создания эффективных интерфейсов пользователя","ar":"نماذج واجهة المستخدم الأمامية هي تقنيات لتطوير واجهات المستخدم فعالة"},"features":{"en":["Implements component patterns using React and TypeScript","Supports composition over inheritance for reusable components","Generates performant user interfaces with Next.js","Uses interface CardProps for customizable card components","Exports functions like Card and CardHeader for easy integration"],"zh":["组件模式","组合优于继承","React 和 Next.js 支持","高性能用户界面构建","现代前端开发最佳实践"],"ja":["コンポーネントパターン","コンポジションオーバー継承","React と Next.js のサポート","高パフォーマンスのユーザーインターフェイス構築","モダンなフロントエンド開発のベストプラクティス"],"ko":["컴포넌트 패턴","구성 위에 상속","React와 Next.js 지원","고성능 사용자 인터페이스 구축","현대적인 프론트엔드 개발 모범 사례"],"es":["Composición de componentes con React","Creación de interfaces de usuario performantes con Next.js","Patrones de diseño para componentes reutilizables","Implementación de la herencia de componentes con TypeScript","Optimización del rendimiento de la aplicación con técnicas de frontend"],"fr":["Composition de composants avec React","Création d''interfaces utilisateur performantes avec Next.js","Modèles de conception pour des composants réutilisables","Mise en œuvre de l''héritage de composants avec TypeScript","Optimisation des performances de l''application avec des techniques de frontend"],"de":["Komposition von Komponenten mit React","Erstellung von performanten Benutzeroberflächen mit Next.js","Entwurfsmuster für wiederverwendbare Komponenten","Implementierung der Vererbung von Komponenten mit TypeScript","Optimierung der Leistung der Anwendung mit Frontend-Techniken"],"pt":["Componentes de composição em vez de herança","Criação de interfaces de usuário performáticas com React e Next.js","Utilização de padrões de componente para melhorar a manutenção do código","Desenvolvimento de aplicações web escaláveis com Spring Boot e Angular"],"ru":["Компоненты композиции вместо наследования","Создание производительных интерфейсов пользователя с React и Next.js","Применение шаблонов компонентов для улучшения поддержки кода","Разработка масштабируемых веб-приложений с Spring Boot и Angular"],"ar":["مكونات التركيب بدلاً من الوراثة","إنشاء واجهات المستخدم عالية الأداء مع react و Next.js","استخدام نماذج المكونات لتحسين صيانة الكود","تطوير تطبيقات الويب القابلة للتوسيع مع Spring Boot و Angular"]},"keywords":{"en":["how to use frontend-patterns","frontend-patterns tutorial","frontend-patterns vs React","frontend-patterns setup guide","what is frontend-patterns","frontend-patterns install","modern frontend development patterns","React component patterns","Next.js performance optimization"],"zh":["前端模式","React","Next.js","组件模式","组合优于继承","高性能用户界面","前端开发最佳实践","AIエージェント","前端开发工具"],"ja":["フロントエンドパターン","React","Next.js","コンポーネントパターン","コンポジションオーバー継承","高パフォーマンスのユーザーインターフェイス","フロントエンド開発のベストプラクティス","AIエージェント","フロントエンド開発ツール"],"ko":["프론트엔드 패턴","React","Next.js","컴포넌트 패턴","구성 위에 상속","고성능 사용자 인터페이스","프론트엔드 개발 모범 사례","AI 에이전트","프론트엔드 개발 도구"],"es":["patrones de frontend","react","next.js","composición de componentes","interfaces de usuario performantes","desarrollo de frontend","typescript","herramientas de frontend","mejores prácticas de frontend"],"fr":["modèles de frontend","react","next.js","composition de composants","interfaces utilisateur performantes","développement de frontend","typescript","outils de frontend","meilleures pratiques de frontend"],"de":["frontend-muster","react","next.js","komposition von komponenten","performante benutzeroberflächen","frontend-entwicklung","typescript","frontend-tools","beste praxis für frontend"],"pt":["padrões de frontend","react","next.js","interfaces de usuário performáticas","desenvolvimento web","spring boot","angular","componentes de composição"],"ru":["фронтенд-шаблоны","react","next.js","производительные интерфейсы пользователя","веб-разработка","spring boot","angular","компоненты композиции"],"ar":["نماذج واجهة المستخدم الأمامية","react","next.js","واجهات المستخدم عالية الأداء","تطوير الويب","spring boot","angular","مكونات التركيب"]}},"owner":"vonomarap","repo":"kanokna","repoPath":"vonomarap/kanokna","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.339Z","topics":[],"category":"community","skillMd":{"name":"frontend-patterns","description":"Frontend development patterns for React, Next.js, state management, performance optimization, and UI best practices.","bodyPreview":"# Frontend Development Patterns\n\nModern frontend patterns for React, Next.js, and performant user interfaces.\n\n## Component Patterns\n\n### Composition Over Inheritance\n\n```typescript\n// ✅ GOOD: Component composition\ninterface CardProps {\n  children: React.ReactNode\n  variant?: ''default'' | ''outlined''\n}\n\nexport function Card({ children, variant = ''default'' }: CardProps) {\n  return <div className={`card card-${variant}`}>{children}</div>\n}\n\nexport function CardHeader({ children }: { children: React.","body":"# Frontend Development Patterns\n\nModern frontend patterns for React, Next.js, and performant user interfaces.\n\n## Component Patterns\n\n### Composition Over Inheritance\n\n```typescript\n// ✅ GOOD: Component composition\ninterface CardProps {\n  children: React.ReactNode\n  variant?: ''default'' | ''outlined''\n}\n\nexport function Card({ children, variant = ''default'' }: CardProps) {\n  return <div className={`card card-${variant}`}>{children}</div>\n}\n\nexport function CardHeader({ children }: { children: React.ReactNode }) {\n  return <div className=\"card-header\">{children}</div>\n}\n\nexport function CardBody({ children }: { children: React.ReactNode }) {\n  return <div className=\"card-body\">{children}</div>\n}\n\n// Usage\n<Card>\n  <CardHeader>Title</CardHeader>\n  <CardBody>Content</CardBody>\n</Card>\n```\n\n### Compound Components\n\n```typescript\ninterface TabsContextValue {\n  activeTab: string\n  setActiveTab: (tab: string) => void\n}\n\nconst TabsContext = createContext<TabsContextValue | undefined>(undefined)\n\nexport function Tabs({ children, defaultTab }: {\n  children: React.ReactNode\n  defaultTab: string\n}) {\n  const [activeTab, setActiveTab] = useState(defaultTab)\n\n  return (\n    <TabsContext.Provider value={{ activeTab, setActiveTab }}>\n      {children}\n    </TabsContext.Provider>\n  )\n}\n\nexport function TabList({ children }: { children: React.ReactNode }) {\n  return <div className=\"tab-list\">{children}</div>\n}\n\nexport function Tab({ id, children }: { id: string, children: React.ReactNode }) {\n  const context = useContext(TabsContext)\n  if (!context) throw new Error(''Tab must be used within Tabs'')\n\n  return (\n    <button\n      className={context.activeTab === id ? ''active'' : ''''}\n      onClick={() => context.setActiveTab(id)}\n    >\n      {children}\n    </button>\n  )\n}\n\n// Usage\n<Tabs defaultTab=\"overview\">\n  <TabList>\n    <Tab id=\"overview\">Overview</Tab>\n    <Tab id=\"details\">Details</Tab>\n  </TabList>\n</Tabs>\n```\n\n### Render Props Pattern\n\n```typescript\ninterface DataLoaderProps<T> {\n  url: string\n  children: (data: T | null, loading: boolean, error: Error | null) => React.ReactNode\n}\n\nexport function DataLoader<T>({ url, children }: DataLoaderProps<T>) {\n  const [data, setData] = useState<T | null>(null)\n  const [loading, setLoading] = useState(true)\n  const [error, setError] = useState<Error | null>(null)\n\n  useEffect(() => {\n    fetch(url)\n      .then(res => res.json())\n      .then(setData)\n      .catch(setError)\n      .finally(() => setLoading(false))\n  }, [url])\n\n  return <>{children(data, loading, error)}</>\n}\n\n// Usage\n<DataLoader<Market[]> url=\"/api/markets\">\n  {(markets, loading, error) => {\n    if (loading) return <Spinner />\n    if (error) return <Error error={error} />\n    return <MarketList markets={markets!} />\n  }}\n</DataLoader>\n```\n\n## Custom Hooks Patterns\n\n### State Management Hook\n\n```typescript\nexport function useToggle(initialValue = false): [boolean, () => void] {\n  const [value, setValue] = useState(initialValue)\n\n  const toggle = useCallback(() => {\n    setValue(v => !v)\n  }, [])\n\n  return [value, toggle]\n}\n\n// Usage\nconst [isOpen, toggleOpen] = useToggle()\n```\n\n### Async Data Fetching Hook\n\n```typescript\ninterface UseQueryOptions<T> {\n  onSuccess?: (data: T) => void\n  onError?: (error: Error) => void\n  enabled?: boolean\n}\n\nexport function useQuery<T>(\n  key: string,\n  fetcher: () => Promise<T>,\n  options?: UseQueryOptions<T>\n) {\n  const [data, setData] = useState<T | null>(null)\n  const [error, setError] = useState<Error | null>(null)\n  const [loading, setLoading] = useState(false)\n\n  const refetch = useCallback(async () => {\n    setLoading(true)\n    setError(null)\n\n    try {\n      const result = await fetcher()\n      setData(result)\n      options?.onSuccess?.(result)\n    } catch (err) {\n      const error = err as Error\n      setError(error)\n      options?.onError?.(error)\n    } finally {\n      setLoading(false)\n    }\n  }, [fetcher, options])\n\n  useEffect(() => {\n    if (options?.enabled !== false) {\n      refetch()\n    }\n  }, [key, refetch, options?.enabled])\n\n  return { data, error, loading, refetch }\n}\n\n// Usage\nconst { data: markets, loading, error, refetch } = useQuery(\n  ''markets'',\n  () => fetch(''/api/markets'').then(r => r.json()),\n  {\n    onSuccess: data => console.log(''Fetched'', data.length, ''markets''),\n    onError: err => console.error(''Failed:'', err)\n  }\n)\n```\n\n### Debounce Hook\n\n```typescript\nexport function useDebounce<T>(value: T, delay: number): T {\n  const [debouncedValue, setDebouncedValue] = useState<T>(value)\n\n  useEffect(() => {\n    const handler = setTimeout(() => {\n      setDebouncedValue(value)\n    }, delay)\n\n    return () => clearTimeout(handler)\n  }, [value, delay])\n\n  return debouncedValue\n}\n\n// Usage\nconst [searchQuery, setSearchQuery] = useState('''')\nconst debouncedQuery = useDebounce(searchQuery, 500)\n\nuseEffect(() => {\n  if (debouncedQuery) {\n    performSearch(debouncedQuery)\n  }\n}, [debouncedQuery])\n```\n\n## State Management Patterns\n\n### Context + Reducer Pattern\n\n```typescript\ninterface State {\n  markets: Market[]\n  selectedMarket: Market | null\n  loading: boolean\n}\n\ntype Action =\n  | { type: ''SET_MARKETS''; payload: Market[] }\n  | { type: ''SELECT_MARKET''; payload: Market }\n  | { type: ''SET_LOADING''; payload: boolean }\n\nfunction reducer(state: State, action: Action): State {\n  switch (action.type) {\n    case ''SET_MARKETS'':\n      return { ...state, markets: action.payload }\n    case ''SELECT_MARKET'':\n      return { ...state, selectedMarket: action.payload }\n    case ''SET_LOADING'':\n      return { ...state, loading: action.payload }\n    default:\n      return state\n  }\n}\n\nconst MarketContext = createContext<{\n  state: State\n  dispatch: Dispatch<Action>\n} | undefined>(undefined)\n\nexport function MarketProvider({ children }: { children: React.ReactNode }) {\n  const [state, dispatch] = useReducer(reducer, {\n    markets: [],\n    selectedMarket: null,\n    loading: false\n  })\n\n  return (\n    <MarketContext.Provider value={{ state, dispatch }}>\n      {children}\n    </MarketContext.Provider>\n  )\n}\n\nexport function useMarkets() {\n  const context = useContext(MarketContext)\n  if (!context) throw new Error(''useMarkets must be used within MarketProvider'')\n  return context\n}\n```\n\n## Performance Optimization\n\n### Memoization\n\n```typescript\n// ✅ useMemo for expensive computations\nconst sortedMarkets = useMemo(() => {\n  return markets.sort((a, b) => b.volume - a.volume)\n}, [markets])\n\n// ✅ useCallback for functions passed to children\nconst handleSearch = useCallback((query: string) => {\n  setSearchQuery(query)\n}, [])\n\n// ✅ React.memo for pure components\nexport const MarketCard = React.memo<MarketCardProps>(({ market }) => {\n  return (\n    <div className=\"market-card\">\n      <h3>{market.name}</h3>\n      <p>{market.description}</p>\n    </div>\n  )\n})\n```\n\n### Code Splitting & Lazy Loading\n\n```typescript\nimport { lazy, Suspense } from ''react''\n\n// ✅ Lazy load heavy components\nconst HeavyChart = lazy(() => import(''./HeavyChart''))\nconst ThreeJsBackground = lazy(() => import(''./ThreeJsBackground''))\n\nexport function Dashboard() {\n  return (\n    <div>\n      <Suspense fallback={<ChartSkeleton />}>\n        <HeavyChart data={data} />\n      </Suspense>\n\n      <Suspense fallback={null}>\n        <ThreeJsBackground />\n      </Suspense>\n    </div>\n  )\n}\n```\n\n### Virtualization for Long Lists\n\n```typescript\nimport { useVirtualizer } from ''@tanstack/react-virtual''\n\nexport function VirtualMarketList({ markets }: { markets: Market[] }) {\n  const parentRef = useRef<HTMLDivElement>(null)\n\n  const virtualizer = useVirtualizer({\n    count: markets.length,\n    getScrollElement: () => parentRef.current,\n    estimateSize: () => 100,  // Estimated row height\n    overscan: 5  // Extra items to render\n  })\n\n  return (\n    <div ref={parentRef} style={{ height: ''600px'', overflow: ''auto'' }}>\n      <div\n        style={{\n          height: `${virtualizer.getTotalSize()}px`,\n          position: ''relative''\n        }}\n      >\n        {virtualizer.getVirtualItems().map(virtualRow => (\n          <div\n            key={virtualRow.index}\n            style={{\n              position: ''absolute'',\n              top: 0,\n              left: 0,\n              width: ''100%'',\n              height: `${virtualRow.size}px`,\n              transform: `translateY(${virtualRow.start}px)`\n            }}\n          >\n            <MarketCard market={markets[virtualRow.index]} />\n          </div>\n        ))}\n      </div>\n    </div>\n  )\n}\n```\n\n## Form Handling Patterns\n\n### Controlled Form with Validation\n\n```typescript\ninterface FormData {\n  name: string\n  description: string\n  endDate: string\n}\n\ninterface FormErrors {\n  name?: string\n  description?: string\n  endDate?: string\n}\n\nexport function CreateMarketForm() {\n  const [formData, setFormData] = useState<FormData>({\n    name: '''',\n    description: '''',\n    endDate: ''''\n  })\n\n  const [errors, setErrors] = useState<FormErrors>({})\n\n  const validate = (): boolean => {\n    const newErrors: FormErrors = {}\n\n    if (!formData.name.trim()) {\n      newErrors.name = ''Name is required''\n    } else if (formData.name.length > 200) {\n      newErrors.name = ''Name must be under 200 characters''\n    }\n\n    if (!formData.description.trim()) {\n      newErrors.description = ''Description is required''\n    }\n\n    if (!formData.endDate) {\n      newErrors.endDate = ''End date is required''\n    }\n\n    setErrors(newErrors)\n    return Object.keys(newErrors).length === 0\n  }\n\n  const handleSubmit = async (e: React.FormEvent) => {\n    e.preventDefault()\n\n    if (!validate()) return\n\n    try {\n      await createMarket(formData)\n      // Success handling\n    } catch (error) {\n      // Error handling\n    }\n  }\n\n  return (\n    <form onSubmit={handleSubmit}>\n      <input\n        value={formData.name}\n        onChange={e => setFormData(prev => ({ ...prev, name: e.target.value }))}\n        placeholder=\"Market name\"\n      />\n      {errors.name && <span className=\"error\">{errors.name}</span>}\n\n      {/* Other fields */}\n\n      <button type=\"submit\">Create Market</button>\n    </form>\n  )\n}\n```\n\n## Error Boundary Pattern\n\n```typescript\ninterface ErrorBoundaryState {\n  hasError: boolean\n  error: Error | null\n}\n\nexport class ErrorBoundary extends React.Component<\n  { children: React.ReactNode },\n  ErrorBoundaryState\n> {\n  state: ErrorBoundaryState = {\n    hasError: false,\n    error: null\n  }\n\n  static getDerivedStateFromError(error: Error): ErrorBoundaryState {\n    return { hasError: true, error }\n  }\n\n  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    console.error(''Error boundary caught:'', error, errorInfo)\n  }\n\n  render() {\n    if (this.state.hasError) {\n      return (\n        <div className=\"error-fallback\">\n          <h2>Something went wrong</h2>\n          <p>{this.state.error?.message}</p>\n          <button onClick={() => this.setState({ hasError: false })}>\n            Try again\n          </button>\n        </div>\n      )\n    }\n\n    return this.props.children\n  }\n}\n\n// Usage\n<ErrorBoundary>\n  <App />\n</ErrorBoundary>\n```\n\n## Animation Patterns\n\n### Framer Motion Animations\n\n```typescript\nimport { motion, AnimatePresence } from ''framer-motion''\n\n// ✅ List animations\nexport function AnimatedMarketList({ markets }: { markets: Market[] }) {\n  return (\n    <AnimatePresence>\n      {markets.map(market => (\n        <motion.div\n          key={market.id}\n          initial={{ opacity: 0, y: 20 }}\n          animate={{ opacity: 1, y: 0 }}\n          exit={{ opacity: 0, y: -20 }}\n          transition={{ duration: 0.3 }}\n        >\n          <MarketCard market={market} />\n        </motion.div>\n      ))}\n    </AnimatePresence>\n  )\n}\n\n// ✅ Modal animations\nexport function Modal({ isOpen, onClose, children }: ModalProps) {\n  return (\n    <AnimatePresence>\n      {isOpen && (\n        <>\n          <motion.div\n            className=\"modal-overlay\"\n            initial={{ opacity: 0 }}\n            animate={{ opacity: 1 }}\n            exit={{ opacity: 0 }}\n            onClick={onClose}\n          />\n          <motion.div\n            className=\"modal-content\"\n            initial={{ opacity: 0, scale: 0.9, y: 20 }}\n            animate={{ opacity: 1, scale: 1, y: 0 }}\n            exit={{ opacity: 0, scale: 0.9, y: 20 }}\n          >\n            {children}\n          </motion.div>\n        </>\n      )}\n    </AnimatePresence>\n  )\n}\n```\n\n## Accessibility Patterns\n\n### Keyboard Navigation\n\n```typescript\nexport function Dropdown({ options, onSelect }: DropdownProps) {\n  const [isOpen, setIsOpen] = useState(false)\n  const [activeIndex, setActiveIndex] = useState(0)\n\n  const handleKeyDown = (e: React.KeyboardEvent) => {\n    switch (e.key) {\n      case ''ArrowDown'':\n        e.preventDefault()\n        setActiveIndex(i => Math.min(i + 1, options.length - 1))\n        break\n      case ''ArrowUp'':\n        e.preventDefault()\n        setActiveIndex(i => Math.max(i - 1, 0))\n        break\n      case ''Enter'':\n        e.preventDefault()\n        onSelect(options[activeIndex])\n        setIsOpen(false)\n        break\n      case ''Escape'':\n        setIsOpen(false)\n        break\n    }\n  }\n\n  return (\n    <div\n      role=\"combobox\"\n      aria-expanded={isOpen}\n      aria-haspopup=\"listbox\"\n      onKeyDown={handleKeyDown}\n    >\n      {/* Dropdown implementation */}\n    </div>\n  )\n}\n```\n\n### Focus Management\n\n```typescript\nexport function Modal({ isOpen, onClose, children }: ModalProps) {\n  const modalRef = useRef<HTMLDivElement>(null)\n  const previousFocusRef = useRef<HTMLElement | null>(null)\n\n  useEffect(() => {\n    if (isOpen) {\n      // Save currently focused element\n      previousFocusRef.current = document.activeElement as HTMLElement\n\n      // Focus modal\n      modalRef.current?.focus()\n    } else {\n      // Restore focus when closing\n      previousFocusRef.current?.focus()\n    }\n  }, [isOpen])\n\n  return isOpen ? (\n    <div\n      ref={modalRef}\n      role=\"dialog\"\n      aria-modal=\"true\"\n      tabIndex={-1}\n      onKeyDown={e => e.key === ''Escape'' && onClose()}\n    >\n      {children}\n    </div>\n  ) : null\n}\n```\n\n**Remember**: Modern frontend patterns enable maintainable, performant user interfaces. Choose patterns that fit your project complexity.\n"},"lastSynced":"2026-03-08T02:03:24.379Z","agentAnalysis":{"suitability":{"en":"Ideal for Full Stack Agents needing modern React and Next.js development patterns for efficient and scalable applications.","zh":"适用于需要现代React和Next.js开发模式以实现高效和可扩展应用程序的全栈代理。","ja":"モダンなReactとNext.jsの開発パターンを使用して効率的でスケーラブルなアプリケーションを実現する必要があるフルスタックエージェントに最適です。","ko":"모던한 React와 Next.js 개발 패턴을 사용하여 효율적이고 확장 가능한 애플리케이션을 구현해야 하는 풀스택 에이전트에게 적합합니다.","es":"Ideal para Agentes de Full Stack que necesitan patrones de desarrollo modernos de React y Next.js para aplicaciones eficientes y escalables.","fr":"Idéal pour les agents Full Stack ayant besoin de modèles de développement modernes React et Next.js pour des applications efficaces et évolutives.","de":"Ideal für Full-Stack-Agents, die moderne React- und Next.js-Entwicklungsmuster für effiziente und skalierbare Anwendungen benötigen.","pt":"Ideal para Agentes Full Stack que necessitam de padrões de desenvolvimento modernos do React e Next.js para aplicações eficientes e escaláveis.","ru":"Идеально подходит для агентов Full Stack, которым необходимы современные шаблоны разработки React и Next.js для эффективных и масштабируемых приложений.","ar":"مثالي لعميل STACK الكامل الذي يحتاج إلى أنماط تطوير حديثة لـ React و Next.js من أجل تطبيقات فعالة وقابلة للتوسيع."},"recommendation":{"en":"Empowers agents to build performant user interfaces using composition over inheritance, leveraging TypeScript for type-safe component development, and optimizing React and Next.js applications for better user experience.","zh":"赋予代理人员使用组合而非继承来构建高性能的用户界面、利用TypeScript进行类型安全的组件开发以及优化React和Next.js应用程序以获得更好的用户体验的能力。","ja":"継承ではなく構成を使用してパフォーマンスの高いユーザーインターフェイスを構築し、TypeScriptを使用して型安全のコンポーネント開発を行い、ReactとNext.jsアプリケーションを最適化してユーザーエクスペリエンスを向上させる能力をエージェントに与えます。","ko":"상속 대신 구성으로 높은 성능의 사용자 인터페이스를 구축하고, TypeScript를 사용하여 유형 안전 컴포넌트 개발을 수행하며, React 및 Next.js 애플리케이션을 최적화하여 사용자 경험을 향상시키는 능력을 에이전트에게 부여합니다.","es":"Habilita a los agentes a crear interfaces de usuario de alto rendimiento utilizando la composición sobre la herencia, aprovechando TypeScript para el desarrollo de componentes seguros tipo y optimizando las aplicaciones de React y Next.js para una mejor experiencia del usuario.","fr":"Permet aux agents de créer des interfaces utilisateur performantes en utilisant la composition plutôt que l''héritage, en exploitant TypeScript pour le développement de composants sécurisés par type et en optimisant les applications React et Next.js pour une meilleure expérience utilisateur.","de":"Ermächtigt Agenten, leistungsstarke Benutzeroberflächen zu erstellen, indem sie die Komposition über die Vererbung verwenden, TypeScript für die Entwicklung von typsicheren Komponenten nutzen und React- und Next.js-Anwendungen für eine bessere Benutzererfahrung optimieren.","pt":"Permite que os agentes criem interfaces de usuário performáticas usando a composição em vez da herança, aproveitando o TypeScript para o desenvolvimento de componentes seguros em termos de tipo, e otimizando as aplicações React e Next.js para uma melhor experiência do usuário.","ru":"Позволяет агентам создавать высокопроизводительные пользовательские интерфейсы, используя композицию вместо наследования, используя TypeScript для разработки компонентов, безопасных с точки зрения типа, и оптимизируя приложения React и Next.js для лучшего пользовательского опыта.","ar":"تمكين العميل من إنشاء واجهات مستخدم تعمل بكفاءة باستخدام التركيب بدلاً من الوراثة، والاستفادة من TypeScript لتطوير مكونات آمنة من حيث النوع، وتحسين تطبيقات React و Next.js للحصول على تجربة مستخدم أفضل."},"useCases":{"en":["Implementing component patterns for reusable UI components","Optimizing Next.js applications for improved server-side rendering","Debugging React component trees for better error handling"],"zh":["实现可重用的UI组件的组件模式","优化Next.js应用程序以改善服务器端渲染","调试React组件树以获得更好的错误处理"],"ja":["再利用可能なUIコンポーネントのコンポーネントパターンの実装","Next.jsアプリケーションの最適化によるサーバーサイドレンダリングの改善","Reactコンポーネントツリーのデバッグによるエラーハンドリングの改善"],"ko":["재사용 가능한 UI 컴포넌트를 위한 컴포넌트 패턴 구현","Next.js 애플리케이션 최적화로 서버 측 렌더링 개선","React 컴포넌트 트리 디버깅을 통한 오류 처리 개선"],"es":["Implementar patrones de componentes para componentes de interfaz de usuario reutilizables","Optimizar aplicaciones Next.js para una mejor representación del lado del servidor","Depurar árboles de componentes React para un mejor control de errores"],"fr":["Mettre en œuvre des modèles de composants pour des composants d''interface utilisateur réutilisables","Optimiser les applications Next.js pour une meilleure représentation serveur","Déboguer les arbres de composants React pour une meilleure gestion des erreurs"],"de":["Implementieren von Komponentenmustern für wiederverwendbare Benutzeroberflächenkomponenten","Optimieren von Next.js-Anwendungen für eine verbesserte Server-seitige Rendering","Debuggen von React-Komponentenbäumen für eine bessere Fehlerbehandlung"],"pt":["Implementar padrões de componentes para componentes de UI reutilizáveis","Otimizar aplicações Next.js para melhor renderização do lado do servidor","Depurar árvores de componentes React para melhor tratamento de erros"],"ru":["Реализация шаблонов компонентов для многократно используемых компонентов UI","Оптимизация приложений Next.js для улучшения отрисовки на стороне сервера","Отладка деревьев компонентов React для лучшего обработки ошибок"],"ar":["تنفيذ أنماط المكونات لمكونات واجهة المستخدم القابلة لإعادة استخدام","تحسين تطبيقات Next.js لتحسين تقديم الخادم","تصحيح أخطاء أشجار مكونات React للحصول على معالجة أفضل للأخطاء"]},"limitations":{"en":["Requires React or Next.js project setup","Limited to frontend development patterns","TypeScript knowledge recommended for optimal usage"],"zh":["需要React或Next.js项目设置","仅限前端开发模式","TypeScript知识推荐用于最佳使用"],"ja":["ReactまたはNext.jsプロジェクトの設定が必要","フロントエンド開発パターンに限定される","TypeScriptの知識が推奨されるため、最適な使用が可能"],"ko":["React 또는 Next.js 프로젝트 설정이 필요","프론트엔드 개발 패턴에만 제한됨","TypeScript 지식이 권장되므로 최적의 사용이 가능"],"es":["Requiere configuración de proyecto React o Next.js","Limitado a patrones de desarrollo de frontend","Conocimiento de TypeScript recomendado para un uso óptimo"],"fr":["Nécessite une configuration de projet React ou Next.js","Limité aux modèles de développement de frontend","Connaissances de TypeScript recommandées pour une utilisation optimale"],"de":["Benötigt React- oder Next.js-Projektsetup","Begrenzt auf Frontend-Entwicklungsmuster","TypeScript-Kenntnisse werden für eine optimale Nutzung empfohlen"],"pt":["Requer configuração do projeto React ou Next.js","Limitado a padrões de desenvolvimento de frontend","Conhecimento de TypeScript recomendado para uso ótimo"],"ru":["Требуется настройка проекта React или Next.js","Ограничен шаблонами разработки frontend","Рекомендуется знание TypeScript для оптимального использования"],"ar":["يتطلب إعداد مشروع React أو Next.js","محدود بنمطيات تطوير واجهة المستخدم","م kiếnة معرفة TypeScript للاستخدام الأمثل"]},"version":4},"contentHash":"193bfa61755991340c89e033b860fe7e84dd47ab013c844c09069e6e3543f21a","qualityScore":39}');
