INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ojo-network/turbine-py-client/railway-deploy', 'railway-deploy', 'ojo-network', 'turbine-py-client', 'community', 'railway-deploy ojo-network turbine-py-client community The railway-deploy skill helps users deploy their Turbine trading bot to Railway for cloud operation. It checks prerequisites and sets up the bot for 24/7 operation. Railway 部署设置指南，帮助您将 Turbine 交易机器人部署到 Railway 的免费层，实现 24/7 云操作 Railway デプロイセットアップガイドは、Turbine トレーディングボットを Railway の無料プランにデプロイし、24/7 クラウド操作を実現するのに役立ちます Railway 배포 설정 가이드는 Turbine 트레이딩 봇을 Railway의 무료 계층에 배포하여 24/7 클라우드 운영을 가능하게 합니다 Despliega tu bot de trading Turbine en Railway para una operación en la nube 24/7 con nuestro railway-deploy. Déployez votre bot de trading Turbine sur Railway pour une exploitation en nuage 24/7 avec notre railway-deploy. Stellen Sie Ihren Turbine-Handelsbot auf Railway bereit, für einen 24/7-Cloud-Betrieb mit unserem railway-deploy. O skill railway-deploy ajuda a implantar o bot de negociação Turbine na Railway para operação em nuvem 24/7. Ele inclui verificações de pré-requisitos e configuração do CLI. Навык railway-deploy помогает развернуть бота Турбине на Railway для круглосуточной облачной операции. Он включает проверки предварительных условий и настройку CLI. المهارة railway-deploy تساعد على نشر.bot التجاري Turbine على Railway للتشغيل السحابي على مدار 24/7.她 تتضمن عمليات التحقق من المتطلبات المسبقة وإعداد CLI. how to use railway-deploy railway-deploy setup guide what is railway-deploy railway-deploy alternative railway-deploy vs turbine railway-deploy install deploy turbine bot to railway railway cloud deployment turbine trading bot deployment Railway 部署 Turbine 机器人 云操作 Python 交易机器人 Railway CLI 免费层 24/7 自动运行 AI 机器人部署 云平台部署 Checks Railway CLI command using `railway --version` Verifies presence of `.env` file for configuration Deploys Turbine trading bot to Railway''s cloud platform Utilizes Railway''s free tier with $5 credit for 30 days Supports Python trading bots for lightweight deployment Runs checks for bot Python files in the root directory railway-deploy is a skill that automates the deployment of Turbine trading bots to Railway''s cloud platform for continuous operation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NodeSentinel/beacon-chain-validators-monitor/github-issue', 'community', 'NodeSentinel', 'beacon-chain-validators-monitor', 'NodeSentinel/beacon-chain-validators-monitor', 'github-issue', 0, 0, 39, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:42.632Z', '37e77cc45a1ecf136420807eeca519987cab5bbea1c33dabb68771c89c2f09e8', '{"id":"NodeSentinel/beacon-chain-validators-monitor/github-issue","name":"github-issue","description":{"en":"The github-issue skill creates focused, self-contained GitHub issues for external contributors, while monitoring validator performance on the beacon chain. It benefits developers and contributors by providing real-time alerts and rewards.","zh":"GitHub Issue AIエージェント工具用于创建专注、自成体系的GitHub问题，实现实时验证器性能、奖励和警报","ja":"GitHub Issue AIエージェントは、外部貢献者が実装できる単一の明確な目標を持つGitHubの問題を作成するために使用されます","ko":"GitHub Issue AI 에이전트는 외부 기여자가 구현할 수 있는 단일의 명확한 목표를 갖는 GitHub 문제를 생성하는 데 사용됩니다","es":"github-issue es una herramienta para crear problemas de GitHub claros y autocontenidos, con funcionalidades como indexer, API y bot de Telegram","fr":"github-issue est un outil pour créer des problèmes GitHub clairs et autocontenus, avec des fonctionnalités telles que indexer, API et bot Telegram","de":"github-issue ist ein Tool zum Erstellen klarer und selbstenthaltener GitHub-Probleme, mit Funktionen wie Indexer, API und Telegram-Bot","pt":"O github-issue é uma ferramenta de validação de desempenho de validadores para a Beacon Chain, com recursos de indexer, API e bot do Telegram para alertas em tempo real.","ru":"ИИ Агент github-issue - это инструмент для мониторинга производительности валидаторов для Beacon Chain, с функциями индексирования, API и Telegram-бота для реальных уведомлений.","ar":"github-issue هو أداة للتحقق من أداء المصادقين لسلاسل البوصلة، مع ميزات الفهرسة وواجهة برمجة التطبيقات وбот التليجرام لتنبي