INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NodeSentinel/beacon-chain-validators-monitor/github-issue', 'github-issue', 'NodeSentinel', 'beacon-chain-validators-monitor', 'community', 'github-issue NodeSentinel beacon-chain-validators-monitor community The github-issue skill creates focused, self-contained GitHub issues for external contributors, while monitoring validator performance on the beacon chain. It benefits developers and contributors by providing real-time alerts and rewards. GitHub Issue AIエージェント工具用于创建专注、自成体系的GitHub问题，实现实时验证器性能、奖励和警报 GitHub Issue AIエージェントは、外部貢献者が実装できる単一の明確な目標を持つGitHubの問題を作成するために使用されます GitHub Issue AI 에이전트는 외부 기여자가 구현할 수 있는 단일의 명확한 목표를 갖는 GitHub 문제를 생성하는 데 사용됩니다 github-issue es una herramienta para crear problemas de GitHub claros y autocontenidos, con funcionalidades como indexer, API y bot de Telegram github-issue est un outil pour créer des problèmes GitHub clairs et autocontenus, avec des fonctionnalités telles que indexer, API et bot Telegram github-issue ist ein Tool zum Erstellen klarer und selbstenthaltener GitHub-Probleme, mit Funktionen wie Indexer, API und Telegram-Bot O github-issue é uma ferramenta de validação de desempenho de validadores para a Beacon Chain, com recursos de indexer, API e bot do Telegram para alertas em tempo real. ИИ Агент github-issue - это инструмент для мониторинга производительности валидаторов для Beacon Chain, с функциями индексирования, API и Telegram-бота для реальных уведомлений. github-issue هو أداة للتحقق من أداء المصادقين لسلاسل البوصلة، مع ميزات الفهرسة وواجهة برمجة التطبيقات وбот التليجرام لتنبيهات الوقت الفعلي. how to use github-issue github-issue setup guide github-issue alternative github-issue vs validator monitor creating focused github issues beacon chain validator performance github-issue install github-issue for developers github-issue for ai agents validator monitor for beacon chain GitHub Issue AIエージェント工具 实时验证器性能 奖励和警报 Decision Flow Scope Boundaries GitHub问题创建 外部貢献者 单一的明确目标 Creates single, clear-goal GitHub issues for external contributors Generates epics with sub-issues for multi-layered work requests Monitors validator performance on the beacon chain using an indexer and API Provides real-time alerts and rewards via a Telegram bot and mini-app Enforces scope boundaries to prevent feature creep Utilizes a decision flow to determine issue creation github-issue is a lightweight validator monitor for the beacon chain, comprising an indexer, API, Telegram bot, and mini-app for real-time performance tracking.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('junerver/ComposeHooks/compose-hooks', 'community', 'junerver', 'ComposeHooks', 'junerver/ComposeHooks', 'compose-hooks', 0, 0, 39, '2026-03-08T01:57:15.357Z', '2026-03-08T02:04:02.785Z', 'aa07aa0a552ce3301c46f685579bb64e3ffc8962f84496361907c14ff165747f', '{"id":"junerver/ComposeHooks/compose-hooks","name":"compose-hooks","description":{"en":"Compose-Hooks is a library for Compose Multiplatform that provides React style hooks for easier state management. It benefits developers using Jetpack Compose and Compose Multiplatform.","zh":"Compose Hooks是一个为Jetpack Compose/Compose Multiplatform设计的Hooks库，灵感来自React Hooks和ahooks，提供了useState、useGetState、useBoolean等Hooks函数","ja":"Compose HooksはJetpack Compose/Compose Multiplatform用に設計されたHooksライブラリで、React Hooksとahooksからインスピレーションを得て、useState、useGetState、useBooleanなどのHooks関数を提供","ko":"Compose Hooks는 Jetpack Compose/Compose Multiplatform용으로 설계된 Hooks 라이브러리로서 React Hooks와 ahooks에서 영감을 얻어 useState, useGetState, useBoolean 등의 Hooks 함수를 제공","es":"Compose Hooks es una biblioteca de Hooks para Jetpack Compose y Compose Multiplatform que facilita la gestión del estado","fr":"Compose Hooks est une bibliothèque de Hooks pour Jetpack Compose et Compose Multiplatform qui facilite la gestion de l''état","de":"Compose Hooks ist eine Hooks-Bibliothek für Jetpack Compose und Compose Multiplatform, die die Zustandsverwaltung erleichtert","pt":"Compose Hooks é uma biblioteca de hooks para Compose Multiplatform que facilita o gerenciamento de estado. Aprenda a usá-la!","ru":"Compose Hooks — это библиотека хуков для Compose Multiplatform, которая упрощает управление состоянием. Узнайте, как ею пользоваться!","ar":"Compose Hooks هي مكتبة hooks ل Compose Multiplatform التي تسهل إدارة الحالة. تعلم كيفية استخدامها!"},"seo":{"title":{"en":"Compose-Hooks: Simplify State Management with React Style...","zh":"Compose Hooks.setup指南 - 使用React风格的Hooks管理状态","ja":"Compose Hooks設定ガイド - ReactスタイルのHooksで状態を管理","ko":"Compose Hooks 설정 가이드 - React 스타일의 Hooks로 상태 관리","es":"Guía de configuración de Compose Hooks para React","fr":"Guide d''intégration de Compose Hooks pour React","de":"Einrichtungsleitfaden für Compose Hooks mit React","pt":"Compose Hooks: Guia de Configuração para Estado de Compos...","ru":"Compose Hooks: Руководство по настройке для управления со...","ar":"Compose Hooks: دليل الإعداد لإدارة الحالة في Compose Mult..."},"description":{"en":"Discover how to streamline your Compose Multiplatform development with Compose-Hooks. Learn how to use React style hooks for easier state management and get ...","zh":"使用Compose Hooks轻松管理Jetpack Compose/Compose Multiplatform中的状态，了解核心概念和快速参考指南","ja":"Compose Hooksを使ってJetpack Compose/Compose Multiplatformの状態を簡単に管理する方法を学ぶ，コアコンセプトとクイックリファレンスガイド","ko":"Compose Hooks를 사용하여 Jetpack Compose/Compose Multiplatform의 상태를 쉽게 관리하는 방법, 핵심 개념과 빠른 참조 가이드","es":"Aprende a usar Compose Hooks para gestionar el estado en Jetpack Compose y Compose Multiplatform de manera efectiva","fr":"Découvrez comment utiliser Compose Hooks pour gérer l''état dans Jetpack Compose et Compose Multiplatform de manière efficace","de":"Erfahren Sie, wie Sie Compose Hooks verwenden können, um den Zustand in Jetpack Compose und Compose Multiplatform effektiv zu verwalten","pt":"Aprenda a usar hooks do React em Compose Multiplatform para gerenciar estado de forma mais fácil. Confira nossa documentação para começar!","ru":"Узнайте, как использовать хуки React в Compose Multiplatform для упрощения управления состоянием. Просмотрите нашу документацию!","ar":"تعلم كيفية استخدام hooks React في Compose Multiplatform لإدارة الحالة بسهولة أكبر. استعرض وثائقنا لبدء استخدامها!"},"definition":{"en":"compose-hooks is a Hooks library for Compose Multiplatform, inspired by React Hooks and ahooks, designed to simplify state management.","zh":"Compose Hooks是什么：一个为Jetpack Compose/Compose Multiplatform设计的Hooks库","ja":"Compose Hooksとは：Jetpack Compose/Compose Multiplatform用に設計されたHooksライブラリ","ko":"Compose Hooks란：Jetpack Compose/Compose Multiplatform용으로 설계된 Hooks 라이브러리","es":"Compose Hooks es una biblioteca que proporciona funciones de tipo React para gestionar el estado en aplicaciones Compose","fr":"Compose Hooks est une bibliothèque qui fournit des fonctions de type React pour gérer l''état dans les applications Compose","de":"Compose Hooks ist eine Bibliothek, die React-ähnliche Funktionen zur Zustandsverwaltung in Compose-Anwendungen bereitstellt","pt":"Compose Hooks é uma biblioteca que fornece hooks do estilo React para Compose Multiplatform, facilitando o gerenciamento de estado","ru":"Compose Hooks — это библиотека, которая предоставляет хуки в стиле React для Compose Multiplatform, упрощая управление состоянием","ar":"Compose Hooks هي مكتبة توفر hooks بال스타يل React ل Compose Multiplatform، وتسهل إدارة الحالة"},"features":{"en":["Provides `useState` hook for basic state management","Offers `useGetState` hook for destructured state management","Includes `useBoolean` hook for boolean state management","Supports `rememberXxx` aliases for all `useXxx` functions","Enables easier state management with React style hooks"],"zh":["使用useState管理基础状态","使用useGetState进行解构使用的状态管理","使用useBoolean管理布尔状态","支持rememberXxx别名","核心概念和快速参考指南"],"ja":["useStateで基本的な状態を管理","useGetStateで解構使用の状態を管理","useBooleanでブール状態を管理","rememberXxxの別名をサポート","コアコンセプトとクイックリファレンスガイド"],"ko":["useState로 기본 상태 관리","useGetState로 해체 사용 상태 관리","useBoolean으로 불리언 상태 관리","rememberXxx 별칭 지원","핵심 개념과 빠른 참조 가이드"],"es":["useState para la gestión básica del estado","useGetState para la gestión del estado con desestructuración","useBoolean para la gestión de estados booleanos","Compatibilidad con Jetpack Compose y Compose Multiplatform","Inspiration en React Hooks y ahooks"],"fr":["useState pour la gestion de base de l''état","useGetState pour la gestion de l''état avec déstructuration","useBoolean pour la gestion des états booléens","Compatibilité avec Jetpack Compose et Compose Multiplatform","Inspiré de React Hooks et ahooks"],"de":["useState für die grundlegende Zustandsverwaltung","useGetState für die Zustandsverwaltung mit Destrukturierung","useBoolean für die Verwaltung von booleschen Zuständen","Kompatibilität mit Jetpack Compose und Compose Multiplatform","Inspiration von React Hooks und ahooks"],"pt":["useState para gerenciamento básico de estado","useGetState para gerenciamento de estado com desestruturação","useBoolean para gerenciamento de estado booleano","Compatibilidade com Jetpack Compose e Compose Multiplatform"],"ru":["useState для базового управления состоянием","useGetState для управления состоянием с деструктуризацией","useBoolean для управления булевым состоянием","Совместимость с Jetpack Compose и Compose Multiplatform"],"ar":["useState لإدارة الحالة الأساسية","useGetState لإدارة الحالة بالتفكيك","useBoolean لإدارة الحالة المنطقية","التوافق مع Jetpack Compose و Compose Multiplatform"]},"keywords":{"en":["how to use compose-hooks","compose-hooks setup guide","compose-hooks alternative","compose-hooks vs ahooks","compose-hooks install","what is compose-hooks","compose-hooks react style hooks","jetpack compose state management","compose multiplatform hooks"],"zh":["Compose Hooks","Jetpack Compose","Compose Multiplatform","React Hooks","ahooks","状态管理","Hooks函数","useState","useGetState","useBoolean"],"ja":["Compose Hooks","Jetpack Compose","Compose Multiplatform","React Hooks","ahooks","状態管理","Hooks関数","useState","useGetState","useBoolean"],"ko":["Compose Hooks","Jetpack Compose","Compose Multiplatform","React Hooks","ahooks","상태 관리","Hooks 함수","useState","useGetState","useBoolean"],"es":["Compose Hooks","Jetpack Compose","Compose Multiplatform","gestión del estado","React Hooks","ahooks","desarrollo de aplicaciones","bibliotecas de React"],"fr":["Compose Hooks","Jetpack Compose","Compose Multiplatform","gestion de l''état","React Hooks","ahooks","développement d''applications","bibliothèques de React"],"de":["Compose Hooks","Jetpack Compose","Compose Multiplatform","Zustandsverwaltung","React Hooks","ahooks","Anwendungsentwicklung","React-Bibliotheken"],"pt":["compose hooks","react hooks","compose multiplatform","gerenciamento de estado","jetpack compose","programação android","desenvolvimento de aplicativos"],"ru":["compose hooks","react хуки","compose multiplatform","управление состоянием","jetpack compose","программирование для android","разработка приложений"],"ar":["compose hooks","react hooks","compose multiplatform","إدارة الحالة","jetpack compose","برمجة أندرويد","تطوير التطبيقات"]}},"owner":"junerver","repo":"ComposeHooks","repoPath":"junerver/ComposeHooks","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.357Z","topics":[],"category":"community","skillMd":{"name":"compose-hooks","description":"|","bodyPreview":"# ComposeHooks 使用指南\n\nComposeHooks 是一个为 Jetpack Compose/Compose Multiplatform 设计的 Hooks 库，灵感来自 React Hooks 和 ahooks。\n\n## 核心概念\n\n所有 `useXxx` 函数都有对应的 `rememberXxx` 别名，选择你喜欢的命名风格。\n\n## 快速参考\n\n### 状态管理 Hooks\n\n| Hook | 用途 | 示例 |\n|------|------|------|\n| `useState` | 基础状态管理（推荐用 by 委托） | `var state by useState(\"\")` |\n| `useGetState` | 解构使用的状态管理（推荐） | `val (state, setState, getState) = useGetState(0)` |\n| `useBoolean` | 布尔状态管理 | `val (state, toggle, setValue, setTrue, setFalse) = useBoolean(false)` |\n| `use","body":"# ComposeHooks 使用指南\n\nComposeHooks 是一个为 Jetpack Compose/Compose Multiplatform 设计的 Hooks 库，灵感来自 React Hooks 和 ahooks。\n\n## 核心概念\n\n所有 `useXxx` 函数都有对应的 `rememberXxx` 别名，选择你喜欢的命名风格。\n\n## 快速参考\n\n### 状态管理 Hooks\n\n| Hook | 用途 | 示例 |\n|------|------|------|\n| `useState` | 基础状态管理（推荐用 by 委托） | `var state by useState(\"\")` |\n| `useGetState` | 解构使用的状态管理（推荐） | `val (state, setState, getState) = useGetState(0)` |\n| `useBoolean` | 布尔状态管理 | `val (state, toggle, setValue, setTrue, setFalse) = useBoolean(false)` |\n| `useReducer` | Redux 风格状态管理 | `val (state, dispatch) = useReducer(reducer, initialState)` |\n| `useRef` | 不触发重组的引用 | `val ref = useRef(0)` |\n| `useList` | 列表状态管理 | `val list = useList(1, 2, 3)` |\n| `useMap` | Map 状态管理 | `val map = useMap(\"key\" to \"value\")` |\n\n### 副作用 Hooks\n\n| Hook | 用途 | 示例 |\n|------|------|------|\n| `useEffect` | 副作用处理 | `useEffect(dep) { /* effect */ }` |\n| `useMount` | 组件挂载时执行 | `useMount { loadData() }` |\n| `useUnmount` | 组件卸载时执行 | `useUnmount { cleanup() }` |\n| `useUpdateEffect` | 跳过首次执行的 Effect | `useUpdateEffect(dep) { /* effect */ }` |\n\n### 网络请求\n\n| Hook | 用途 | 示例 |\n|------|------|------|\n| `useRequest` | 网络请求管理 | `val (data, loading, error, request) = useRequest(requestFn)` |\n\n### 工具 Hooks\n\n| Hook | 用途 | 示例 |\n|------|------|------|\n| `useDebounce` | 防抖值 | `val debouncedValue = useDebounce(value)` |\n| `useThrottle` | 节流值 | `val throttledValue = useThrottle(value)` |\n| `useInterval` | 定时器 | `useInterval { tick() }` |\n| `useTimeoutFn` | 延时执行 | `useTimeoutFn(fn, 1.seconds)` |\n| `useUndo` | 撤销/重做 | `val (state, set, reset, undo, redo) = useUndo(initial)` |\n\n## 详细参考\n\n- **状态管理 Hooks**: 见 [references/state-hooks.md](references/state-hooks.md)\n- **副作用 Hooks**: 见 [references/effect-hooks.md](references/effect-hooks.md)\n- **工具 Hooks**: 见 [references/utility-hooks.md](references/utility-hooks.md)\n- **网络请求 Hooks**: 见 [references/request-hooks.md](references/request-hooks.md)\n- **Table 相关 Hooks**: 见 [references/table-hooks.md](references/table-hooks.md)\n\n## 常见模式\n\n### 1. 受控组件\n\n```kotlin\n// 推荐：使用 useGetState 解构\nval (text, setText) = useGetState(\"\")\nOutlinedTextField(\n    value = text.value,\n    onValueChange = setText,\n    label = { Text(\"输入\") }\n)\n\n// 或使用 by 委托\nvar text by useState(\"\")\nOutlinedTextField(\n    value = text,\n    onValueChange = { text = it },\n    label = { Text(\"输入\") }\n)\n```\n\n### 2. 解决闭包问题（来自 UseStateExample.kt）\n\n```kotlin\n// 方式1: 使用 useGetState 函数式更新\nval (state, setState) = useGetState(\"initial\")\nLaunchedEffect(Unit) {\n    repeat(10) {\n        delay(1.seconds)\n        setState { \"$it.\" }  // 函数式更新，避免闭包问题\n    }\n}\n\n// 方式2: 使用 by 委托\nvar byState by useState(\"initial\")\nLaunchedEffect(Unit) {\n    repeat(10) {\n        delay(1.seconds)\n        byState += \".\"  // 直接修改，无闭包问题\n    }\n}\n\n// 方式3: 使用 useLatestRef\nval (state, setState) = useState(\"initial\")\nval stateRef = useLatestRef(state)\nLaunchedEffect(Unit) {\n    repeat(10) {\n        delay(1.seconds)\n        setState(\"${stateRef.current}.\")  // 通过 ref 获取最新值\n    }\n}\n```\n\n### 3. 网络请求（来自 Auto&Manual.kt）\n\n```kotlin\n// 自动请求\nval (userInfoState, loadingState, errorState) = useRequest(\n    requestFn = { NetApi.userInfo(it) },\n    optionsOf = {\n        defaultParams = \"junerver\"  // 自动请求必须设置默认参数\n    }\n)\nval userInfo by userInfoState\nval loading by loadingState\n\nif (loading) {\n    Text(text = \"loading ...\")\n}\nuserInfo?.let { Text(text = it.toString()) }\n\n// 手动请求\nval (repoInfoState, loadingState, errorState, request) = useRequest(\n    requestFn = { it: Tuple2<String, String> ->\n        NetApi.repoInfo(it.first, it.second)\n    },\n    optionsOf = {\n        manual = true\n        defaultParams = tuple(\"junerver\", \"ComposeHooks\")\n    }\n)\nTButton(text = \"request\") { request() }\n```\n\n### 4. Redux 风格状态管理（来自 UseReducerExample.kt）\n\n```kotlin\n// 定义 State 和 Action\ndata class SimpleData(val name: String, val age: Int)\n\nsealed interface SimpleAction {\n    data class ChangeName(val newName: String) : SimpleAction\n    data object AgeIncrease : SimpleAction\n}\n\n// 定义 Reducer\nval simpleReducer: Reducer<SimpleData, SimpleAction> = { prevState, action ->\n    when (action) {\n        is SimpleAction.ChangeName -> prevState.copy(name = action.newName)\n        is SimpleAction.AgeIncrease -> prevState.copy(age = prevState.age + 1)\n    }\n}\n\n// 使用\nval (state, dispatch) = useReducer(\n    simpleReducer,\n    initialState = SimpleData(\"default\", 18),\n    middlewares = arrayOf(logMiddleware())\n)\n\nTButton(text = \"Change Name\") { dispatch(SimpleAction.ChangeName(\"Alice\")) }\nTButton(text = \"Increase Age\") { dispatch(SimpleAction.AgeIncrease) }\nText(text = \"State: ${state.value}\")\n```\n\n### 5. 列表操作（来自 UseListExample.kt）\n\n```kotlin\nval listState = useList(1, 2, 3)\n\n// 操作方法\nlistState.add(4)              // 添加\nlistState.add(0, 0)           // 插入\nlistState.removeAt(0)         // 删除\nlistState.removeLast()        // 删除最后一个\nlistState[0] = 10             // 修改\nlistState.clear()             // 清空\nlistState.shuffle()           // 打乱\n\n// 配合 useListReduce\nval sum by useListReduce(listState) { a, b -> a + b }\n```\n\n### 6. 防抖输入（来自 UseDebounceExample.kt）\n\n```kotlin\nvar inputValue by useState(\"\")\nval debouncedValue by useDebounce(\n    value = inputValue,\n    optionsOf = {\n        wait = 500.milliseconds\n    }\n)\n\nOutlinedTextField(\n    value = inputValue,\n    onValueChange = { inputValue = it },\n    label = { Text(\"Type something...\") }\n)\n\nText(text = \"Debounced: $debouncedValue\")\n```\n"},"lastSynced":"2026-03-08T02:04:02.785Z","agentAnalysis":{"suitability":{"en":"Perfect for Android and Multiplatform Agents needing simplified state management with Jetpack Compose and Compose Multiplatform.","zh":"适用于需要简化状态管理的Android和多平台代理，并使用Jetpack Compose和Compose Multiplatform。","ja":"Androidとマルチプラットフォームエージェントで状態管理を簡素化する必要がある場合に適しています。Jetpack ComposeとCompose Multiplatformを使用します。","ko":"상태 관리를 단순화해야 하는 Android 및 멀티 플랫폼 에이전트에 적합합니다. Jetpack Compose 및 Compose Multiplatform을 사용합니다.","es":"Perfecto para agentes de Android y Multiplataforma que necesitan una gestión de estado simplificada con Jetpack Compose y Compose Multiplatform.","fr":"Parfait pour les agents Android et Multiplateforme ayant besoin d''une gestion d''état simplifiée avec Jetpack Compose et Compose Multiplatform.","de":"Perfekt für Android- und Multiplattform-Agents, die eine vereinfachte Zustandsverwaltung mit Jetpack Compose und Compose Multiplatform benötigen.","pt":"Perfeito para Agentes Android e Multiplataforma que necessitam de gerenciamento de estado simplificado com Jetpack Compose e Compose Multiplatform.","ru":"Идеально подходит для агентов Android и Multiplatform, которым требуется упрощенное управление состоянием с помощью Jetpack Compose и Compose Multiplatform.","ar":"مثالي للوكلاء Android و Multiplatform الذين يحتاجون إلى إدارة حالة مبسطة مع Jetpack Compose و Compose Multiplatform."},"recommendation":{"en":"Empowers agents to manage state with React-style hooks, utilizing libraries like ComposeHooks and ahooks, and supporting features such as useState, useGetState, and useBoolean for efficient state handling.","zh":"赋予代理使用React风格的钩子来管理状态，利用像ComposeHooks和ahooks这样的库，并支持诸如useState、useGetState和useBoolean等功能，以实现高效的状态处理。","ja":"エージェントがReactスタイルのフックを使用して状態を管理できるようにし、ComposeHooksやahooksなどのライブラリを利用し、useState、useGetState、useBooleanなどの機能をサポートして、効率的な状態処理を実現します。","ko":"에이전트가 React 스타일의 훅을 사용하여 상태를 관리할 수 있도록 하며 ComposeHooks 및 ahooks와 같은 라이브러리를 활용하며 useState, useGetState 및 useBoolean와 같은 기능을 지원하여 효율적인 상태 처리를实现합니다.","es":"Habilita a los agentes a gestionar el estado con ganchos de estilo React, utilizando bibliotecas como ComposeHooks y ahooks, y soportando características como useState, useGetState y useBoolean para una gestión de estado eficiente.","fr":"Permet aux agents de gérer l''état avec des crochets de style React, en utilisant des bibliothèques comme ComposeHooks et ahooks, et en prenant en charge des fonctionnalités telles que useState, useGetState et useBoolean pour une gestion d''état efficace.","de":"Ermöglicht es den Agents, den Zustand mit React-Style-Hooks zu verwalten, indem Bibliotheken wie ComposeHooks und ahooks verwendet werden, und Funktionen wie useState, useGetState und useBoolean für eine effiziente Zustandsverwaltung unterstützt.","pt":"Habilita os agentes a gerenciar o estado com ganchos no estilo React, utilizando bibliotecas como ComposeHooks e ahooks, e suportando recursos como useState, useGetState e useBoolean para manipulação de estado eficiente.","ru":"Наделяет агентов возможностью управлять состоянием с помощью крючков в стиле React, используя библиотеки như ComposeHooks и ahooks, и поддерживая функции như useState, useGetState и useBoolean для эффективного управления состоянием.","ar":"تمكين الوكلاء من إدارة الحالة باستخدام مشابك بالنمط React ، باستخدام مكتبات مثل ComposeHooks و ahooks ، ودعم ميزات مثل useState و useGetState و useBoolean للتعامل الفعال مع الحالة."},"useCases":{"en":["Simplifying state management in Jetpack Compose applications","Implementing boolean state management with useBoolean","Optimizing state updates with useGetState and useState"],"zh":["在Jetpack Compose应用程序中简化状态管理","使用useBoolean实现布尔状态管理","使用useGetState和useState优化状态更新"],"ja":["Jetpack Composeアプリケーションでの状態管理の簡素化","useBooleanを使用したブール状態管理の実装","useGetStateとuseStateを使用した状態更新の最適化"],"ko":["Jetpack Compose 애플리케이션에서 상태 관리를 단순화하는 것","useBoolean을 사용한 불리언 상태 관리 구현","useGetState 및 useState를 사용한 상태 업데이트 최적화"],"es":["Simplificar la gestión de estado en aplicaciones de Jetpack Compose","Implementar la gestión de estado booleano con useBoolean","Optimizar las actualizaciones de estado con useGetState y useState"],"fr":["Simplifier la gestion d''état dans les applications Jetpack Compose","Mettre en œuvre la gestion d''état booléen avec useBoolean","Optimiser les mises à jour d''état avec useGetState et useState"],"de":["Vereinfachen der Zustandsverwaltung in Jetpack Compose-Anwendungen","Implementierung der booleschen Zustandsverwaltung mit useBoolean","Optimieren der Zustandsaktualisierungen mit useGetState und useState"],"pt":["Simplificar o gerenciamento de estado em aplicações Jetpack Compose","Implementar gerenciamento de estado booleano com useBoolean","Otimizar atualizações de estado com useGetState e useState"],"ru":["Упрощение управления состоянием в приложениях Jetpack Compose","Реализация управления булевым состоянием с помощью useBoolean","Оптимизация обновлений состояния с помощью useGetState и useState"],"ar":["تبسيط إدارة الحالة في تطبيقات Jetpack Compose","تنفيذ إدارة الحالة المنطقية باستخدام useBoolean","تحسين تحديثات الحالة باستخدام useGetState و useState"]},"limitations":{"en":["Requires Jetpack Compose or Compose Multiplatform setup","Limited to Kotlin-based projects"],"zh":["需要Jetpack Compose或Compose Multiplatform设置","仅限于基于Kotlin的项目"],"ja":["Jetpack ComposeまたはCompose Multiplatformの設定が必要","Kotlinベースのプロジェクトに限定される"],"ko":["Jetpack Compose 또는 Compose Multiplatform 설정이 필요","Kotlin 기반 프로젝트로 제한됨"],"es":["Requiere configuración de Jetpack Compose o Compose Multiplatform","Limitado a proyectos basados en Kotlin"],"fr":["Nécessite une configuration de Jetpack Compose ou Compose Multiplatform","Limité aux projets basés sur Kotlin"],"de":["Benötigt eine Konfiguration von Jetpack Compose oder Compose Multiplatform","Begrenzt auf Kotlin-basierte Projekte"],"pt":["Requer configuração do Jetpack Compose ou Compose Multiplatform","Limitado a projetos baseados em Kotlin"],"ru":["Требует настройки Jetpack Compose или Compose Multiplatform","Ограничен проектами на основе Kotlin"],"ar":["يتطلب إعداد Jetpack Compose أو Compose Multiplatform","محدود بمشاريع Kotlin"]},"version":4},"contentHash":"aa07aa0a552ce3301c46f685579bb64e3ffc8962f84496361907c14ff165747f","qualityScore":39}');
