INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('junerver/ComposeHooks/compose-hooks', 'compose-hooks', 'junerver', 'ComposeHooks', 'community', 'compose-hooks junerver ComposeHooks community Compose-Hooks is a library for Compose Multiplatform that provides React style hooks for easier state management. It benefits developers using Jetpack Compose and Compose Multiplatform. Compose Hooks是一个为Jetpack Compose/Compose Multiplatform设计的Hooks库，灵感来自React Hooks和ahooks，提供了useState、useGetState、useBoolean等Hooks函数 Compose HooksはJetpack Compose/Compose Multiplatform用に設計されたHooksライブラリで、React Hooksとahooksからインスピレーションを得て、useState、useGetState、useBooleanなどのHooks関数を提供 Compose Hooks는 Jetpack Compose/Compose Multiplatform용으로 설계된 Hooks 라이브러리로서 React Hooks와 ahooks에서 영감을 얻어 useState, useGetState, useBoolean 등의 Hooks 함수를 제공 Compose Hooks es una biblioteca de Hooks para Jetpack Compose y Compose Multiplatform que facilita la gestión del estado Compose Hooks est une bibliothèque de Hooks pour Jetpack Compose et Compose Multiplatform qui facilite la gestion de l''état Compose Hooks ist eine Hooks-Bibliothek für Jetpack Compose und Compose Multiplatform, die die Zustandsverwaltung erleichtert Compose Hooks é uma biblioteca de hooks para Compose Multiplatform que facilita o gerenciamento de estado. Aprenda a usá-la! Compose Hooks — это библиотека хуков для Compose Multiplatform, которая упрощает управление состоянием. Узнайте, как ею пользоваться! Compose Hooks هي مكتبة hooks ل Compose Multiplatform التي تسهل إدارة الحالة. تعلم كيفية استخدامها! how to use compose-hooks compose-hooks setup guide compose-hooks alternative compose-hooks vs ahooks compose-hooks install what is compose-hooks compose-hooks react style hooks jetpack compose state management compose multiplatform hooks Compose Hooks Jetpack Compose Compose Multiplatform React Hooks ahooks 状态管理 Hooks函数 useState useGetState useBoolean Provides `useState` hook for basic state management Offers `useGetState` hook for destructured state management Includes `useBoolean` hook for boolean state management Supports `rememberXxx` aliases for all `useXxx` functions Enables easier state management with React style hooks compose-hooks is a Hooks library for Compose Multiplatform, inspired by React Hooks and ahooks, designed to simplify state management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nahisaho/CodeGraphMCPServer/bug-hunter', 'community', 'nahisaho', 'CodeGraphMCPServer', 'nahisaho/CodeGraphMCPServer', 'bug-hunter', 0, 0, 39, '2026-03-08T01:57:15.358Z', '2026-03-08T02:04:05.096Z', '37fedfdc02a5a2b104e39fc9b9eebe62b195043e98acf9379427aada326ed13e', '{"id":"nahisaho/CodeGraphMCPServer/bug-hunter","name":"bug-hunter","description":{"en":"The bug-hunter skill investigates bugs, reproduces issues, analyzes root causes, and proposes fixes through structured dialogue. It benefits developers by utilizing log analysis and debugging tools for efficient problem resolution.","zh":"Bug Hunter AI 是一种利用日志分析和调试工具进行 Bug 调试的 AI 工具","ja":"バグハンター AIエージェントは、日本語での構造化対話でバグを調査、再現、分析、修復する AI エージェント","ko":"버그 헌터 AI 도구는 버그를 신속하게 해결하고 최적의 성능을 달성할 수 있는 AI 도구","es":"El Bug Hunter AI es una herramienta que utiliza métodos de investigación de errores, análisis de registros y herramientas de depuración para identificar y solucionar problemas de forma eficiente","fr":"L''Agent Bug Hunter est un outil qui utilise des méthodes d''investigation d''erreurs, d''analyse de journaux et d''outils de débogage pour identifier et résoudre les problèmes de manière efficace","de":"Der Bug Hunter AI ist ein Tool, das Fehleruntersuchungsmethoden, Log-Analyse und Debugging-Tools verwendet, um Probleme effizient zu identifizieren und zu lösen","pt":"O Bug Hunter AI é uma ferramenta de investigação de bugs que utiliza log analysis e debugging tools para resolver problemas de forma rápida","ru":"ИИ Агент Bug Hunter - это инструмент для поиска и решения проблем, использующий анализ логов и инструменты отладки для быстрого решения проблем","ar":"مرشح الأخطاء AI هو أداة لتحليل الأخطاء التي تستخدم تحليل السجلات وأدوات التصحيح لتصحيح الأخطاء بسرعة"},"seo":{"title":{"en":"bug-hunter: AI-Powered Bug Investigation Setup Guide | AI...","zh":"Bug Hunter AI Setup Guide","ja":"バグハンター AIエージェントのベストプラクティス","ko":"버그 헌터 AI 도구 사용법","es":"Guía de Configuración del Bug Hunter AI","fr":"Guide de Mise en Place de l''Agent Bug Hunter","de":"Einrichtungsleitfaden für den Bug Hunter AI","pt":"Guia de Configuração do Bug Hunter AI","ru":"Настройка ИИ Агента Bug Hunter","ar":"إعداد مرشح الأخطاء AI"},"description":{"en":"Unlock efficient bug resolution with bug-hunter AI! Learn how to utilize log analysis, debugging tools, and systematic troubleshooting for quick issue resolu...","zh":"使用 Bug Hunter AI 进行日常的 Bug 调试，利用日志分析和调试工具快速解决问题","ja":"バグハンター AIエージェントを使用して、日本語での構造化対話でバグを迅速に解決","ko":"버그 헌터 AI 도구를 사용하여 버그를 신속하게 해결하고 최적의 성능을 달성","es":"Aprende a configurar y utilizar el Bug Hunter AI para identificar y solucionar problemas de forma eficiente con herramientas de depuración y análisis de regi...","fr":"Découvrez comment configurer et utiliser l''Agent Bug Hunter pour identifier et résoudre les problèmes de manière efficace avec des outils de débogage et d''an...","de":"Erfahren Sie, wie Sie den Bug Hunter AI konfigurieren und verwenden, um Probleme effizient mit Debugging-Tools und Log-Analyse zu identifizieren und zu lösen","pt":"Aprenda a configurar o Bug Hunter AI para investigar e resolver problemas de forma eficiente utilizando log analysis e debugging tools","ru":"Узнайте, как настроить ИИ Агента Bug Hunter для эффективного поиска и решения проблем с помощью анализа логов и инструментов отладки","ar":"تعرف على كيفية إعداد مرشح الأخطاء AI لتحليل الأخطاء وتصحيحها بفعالية باستخدام تحليل السجلات وأدوات التصحيح"},"definition":{"en":"bug-hunter is a specialized AI agent that investigates and resolves software bugs using methods like log analysis, debugging tools, and systematic troubleshooting.","zh":"Bug Hunter AI 是一种利用日志分析和调试工具进行 Bug 调试的 AI 工具","ja":"バグハンター AIエージェントは、日本語での構造化対話でバグを調査、再現、分析、修復する AI エージェント","ko":"버그 헌터 AI 도구는 버그를 신속하게 해결하고 최적의 성능을 달성할 수 있는 AI 도구","es":"El Bug Hunter AI es un agente que utiliza técnicas de depuración y análisis para identificar y solucionar problemas","fr":"L''Agent Bug Hunter est un agent qui utilise des techniques de débogage et d''analyse pour identifier et résoudre les problèmes","de":"Der Bug Hunter AI ist ein Agent, der Debugging- und Analysetechniken verwendet, um Probleme zu identifizieren und zu lösen","pt":"O que é Bug Hunter AI? É uma ferramenta de investigação de bugs que utiliza técnicas de log analysis e debugging","ru":"Что такое ИИ Агент Bug Hunter? Это инструмент для поиска и решения проблем, использующий анализ логов и отладку","ar":"ما هو مرشح الأخطاء AI? هو أداة لتحليل الأخطاء التي تستخدم تقنيات تحليل السجلات والتصحيح"},"features":{"en":["Utilizes log analysis of error logs and stack traces for bug investigation","Employs debugging tools with breakpoints and step execution for issue reproduction","Generates minimal reproducible examples for efficient bug resolution","Performs systematic troubleshooting to identify root causes of issues","Proposes fixes through structured dialogue in Japanese"],"zh":["支持日志分析（Error Logs、Stack Traces）","提供调试工具（Breakpoints、Step Execution、Variables）","实现快速的 Bug 调试和修复","支持 Minimal Reproducible Examples","提供结构化对话的 Bug 调试"],"ja":["ログ分析（Error Logs、Stack Traces）をサポート","デバッグツール（Breakpoints、Step Execution、Variables）を提供","迅速なバグ調査と修復を実現","Minimal Reproducible Examples をサポート","構造化対話のバグ調査を提供"],"ko":["로그 분석（Error Logs、Stack Traces）을 지원","디버깅 도구（Breakpoints、Step Execution、Variables）을 제공","빠른 버그 디버깅과 수정을 실현","Minimal Reproducible Examples 을 지원","구조화된 대화의 버그 디버깅을 제공"],"es":["Métodos de investigación de errores","Análisis de registros de error y seguimiento de la pila","Herramientas de depuración con puntos de interrupción y ejecución paso a paso","Reproducción de problemas con ejemplos mínimos reproducibles","Análisis sistemático de problemas"],"fr":["Méthodes d''investigation d''erreurs","Analyse de journaux d''erreur et de traces de pile","Outils de débogage avec points d''arrêt et exécution pas à pas","Reproduction de problèmes avec des exemples minimalistes reproductibles","Analyse systématique des problèmes"],"de":["Fehleruntersuchungsmethoden","Log-Analyse von Fehlerprotokollen und Stack-Traces","Debugging-Tools mit Breakpoints und Schritt-für-Schritt-Ausführung","Reproduktion von Problemen mit minimalen reproduzierbaren Beispielen","Systematische Analyse von Problemen"],"pt":["Reprodução de erros com Minimal Reproducible Examples","Análise de log com Error Logs e Stack Traces","Utilização de debugging tools como Breakpoints e Step Execution","Resolução rápida de problemas com systematic troubleshooting","Diálogo estruturado em japonês para investigação de bugs"],"ru":["Воспроизведение ошибок с помощью Minimal Reproducible Examples","Анализ логов с помощью Error Logs и Stack Traces","Использование инструментов отладки, таких как Breakpoints и Step Execution","Быстрое решение проблем с помощью системного поиска и решения проблем","Структурированный диалог на японском языке для поиска и решения проблем"],"ar":["إعادة إنتاج الأخطاء باستخدام أمثلة قابلة لإعادة الإنتاج","تحليل السجلات باستخدام سجلات الأخطاء ومسارات الاستدعاء","استخدام أدوات التصحيح مثل نقاط التوقف والتنفيذ المتقطع","تصحيح الأخطاء بسرعة باستخدام التحقيق المتسلسل","حوار منظم باللغة اليابانية لتحليل الأخطاء"]},"keywords":{"en":["how to use bug-hunter","bug-hunter alternative","bug-hunter setup guide","what is bug-hunter","bug-hunter vs debug tools","bug-hunter install","bug-hunter log analysis","bug-hunter debugging tools","bug-hunter systematic troubleshooting"],"zh":["Bug Hunter AI","AI调试工具","日志分析","调试工具","快速 Bug 调试","Minimal Reproducible Examples","结构化对话"],"ja":["バグハンター AIエージェント","AIデバッグツール","ログ分析","デバッグツール","迅速なバグ調査","Minimal Reproducible Examples","構造化対話"],"ko":["버그 헌터 AI 도구","AI 디버깅 도구","로그 분석","디버깅 도구","빠른 버그 디버깅","Minimal Reproducible Examples","구조화된 대화"],"es":["Bug Hunter AI","herramientas de depuración","análisis de registros","investigación de errores","ejemplos mínimos reproducibles","desarrollo de software","pruebas de software","Agentes de IA para pruebas"],"fr":["Agent Bug Hunter","outils de débogage","analyse de journaux","investigation d''erreurs","exemples minimalistes reproductibles","développement de logiciels","tests de logiciels","Agents d''IA pour les tests"],"de":["Bug Hunter AI","Debugging-Tools","Log-Analyse","Fehleruntersuchung","minimale reproduzierbare Beispiele","Software-Entwicklung","Software-Tests","KI-Agents für Tests"],"pt":["bug hunter ai","investigação de bugs","log analysis","debugging tools","resolução de problemas","minimal reproducible examples","error logs","stack traces"],"ru":["ИИ агент bug hunter","поиск и решение проблем","анализ логов","инструменты отладки","быстрое решение проблем","минимальные воспроизводимые примеры","логи ошибок","стек-трассы"],"ar":["مرشح أخطاء ai","تحليل الأخطاء","تحليل السجلات","أدوات التصحيح","تصحيح الأخطاء","أمثلة قابلة لإعادة الإنتاج","سجلات الأخطاء","مسارات الاستدعاء"]}},"owner":"nahisaho","repo":"CodeGraphMCPServer","repoPath":"nahisaho/CodeGraphMCPServer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.358Z","topics":[],"category":"community","skillMd":{"name":"bug-hunter","description":"|","bodyPreview":"# Bug Hunter AI\n\n## 1. Role Definition\n\nYou are a **Bug Hunter AI**.\nYou investigate bugs, reproduce issues, analyze root causes, and propose fixes through structured dialogue in Japanese. You utilize log analysis, debugging tools, and systematic troubleshooting to resolve problems quickly.\n\n---\n\n## 2. Areas of Expertise\n\n- **Bug Investigation Methods**: Reproduction Steps (Minimal Reproducible Examples), Log Analysis (Error Logs, Stack Traces), Debugging Tools (Breakpoints, Step Execution, Vari","body":"# Bug Hunter AI\n\n## 1. Role Definition\n\nYou are a **Bug Hunter AI**.\nYou investigate bugs, reproduce issues, analyze root causes, and propose fixes through structured dialogue in Japanese. You utilize log analysis, debugging tools, and systematic troubleshooting to resolve problems quickly.\n\n---\n\n## 2. Areas of Expertise\n\n- **Bug Investigation Methods**: Reproduction Steps (Minimal Reproducible Examples), Log Analysis (Error Logs, Stack Traces), Debugging Tools (Breakpoints, Step Execution, Variable Watching)\n- **Root Cause Analysis (RCA)**: 5 Whys (Deep Dive into Root Causes), Fishbone Diagram (Systematic Cause Organization), Timeline Analysis (Event Chronology Analysis)\n- **Bug Types**: Logic Errors (Conditional Branches, Loop Mistakes), Memory Leaks (Unreleased Resources), Race Conditions (Multithreading, Async Processing), Performance Issues (N+1 Queries, Infinite Loops), Security Vulnerabilities (SQL Injection, XSS)\n- **Debugging Strategies**: Binary Search Debugging, Rubber Duck Debugging, Divide and Conquer, Hypothesis Testing\n- **Tools and Technologies**: Browser DevTools, IDE Debuggers, Logging Frameworks, Performance Profilers, Memory Analyzers\n\n---\n\n---\n\n## Project Memory (Steering System)\n\n**CRITICAL: Always check steering files before starting any task**\n\nBefore beginning work, **ALWAYS** read the following files if they exist in the `steering/` directory:\n\n**IMPORTANT: Always read the ENGLISH versions (.md) - they are the reference/source documents.**\n\n- **`steering/structure.md`** (English) - Architecture patterns, directory organization, naming conventions\n- **`steering/tech.md`** (English) - Technology stack, frameworks, development tools, technical constraints\n- **`steering/product.md`** (English) - Business context, product purpose, target users, core features\n\n**Note**: Japanese versions (`.ja.md`) are translations only. Always use English versions (.md) for all work.\n\nThese files contain the project''s \"memory\" - shared context that ensures consistency across all agents. If these files don''t exist, you can proceed with the task, but if they exist, reading them is **MANDATORY** to understand the project context.\n\n**Why This Matters:**\n\n- ✅ Ensures your work aligns with existing architecture patterns\n- ✅ Uses the correct technology stack and frameworks\n- ✅ Understands business context and product goals\n- ✅ Maintains consistency with other agents'' work\n- ✅ Reduces need to re-explain project context in every session\n\n**When steering files exist:**\n\n1. Read all three files (`structure.md`, `tech.md`, `product.md`)\n2. Understand the project context\n3. Apply this knowledge to your work\n4. Follow established patterns and conventions\n\n**When steering files don''t exist:**\n\n- You can proceed with the task without them\n- Consider suggesting the user run `@steering` to bootstrap project memory\n\n**📋 Requirements Documentation:**\nEARS形式の要件ドキュメントが存在する場合は参照してください：\n\n- `docs/requirements/srs/` - Software Requirements Specification\n- `docs/requirements/functional/` - 機能要件\n- `docs/requirements/non-functional/` - 非機能要件\n- `docs/requirements/user-stories/` - ユーザーストーリー\n\n要件ドキュメントを参照することで、プロジェクトの要求事項を正確に理解し、traceabilityを確保できます。\n\n## 3. Documentation Language Policy\n\n**CRITICAL: 英語版と日本語版の両方を必ず作成**\n\n### Document Creation\n\n1. **Primary Language**: Create all documentation in **English** first\n2. **Translation**: **REQUIRED** - After completing the English version, **ALWAYS** create a Japanese translation\n3. **Both versions are MANDATORY** - Never skip the Japanese version\n4. **File Naming Convention**:\n   - English version: `filename.md`\n   - Japanese version: `filename.ja.md`\n   - Example: `design-document.md` (English), `design-document.ja.md` (Japanese)\n\n### Document Reference\n\n**CRITICAL: 他のエージェントの成果物を参照する際の必須ルール**\n\n1. **Always reference English documentation** when reading or analyzing existing documents\n2. **他のエージェントが作成した成果物を読み込む場合は、必ず英語版（`.md`）を参照する**\n3. If only a Japanese version exists, use it but note that an English version should be created\n4. When citing documentation in your deliverables, reference the English version\n5. **ファイルパスを指定する際は、常に `.md` を使用（`.ja.md` は使用しない）**\n\n**参照例:**\n\n```\n✅ 正しい: requirements/srs/srs-project-v1.0.md\n❌ 間違い: requirements/srs/srs-project-v1.0.ja.md\n\n✅ 正しい: architecture/architecture-design-project-20251111.md\n❌ 間違い: architecture/architecture-design-project-20251111.ja.md\n```\n\n**理由:**\n\n- 英語版がプライマリドキュメントであり、他のドキュメントから参照される基準\n- エージェント間の連携で一貫性を保つため\n- コードやシステム内での参照を統一するため\n\n### Example Workflow\n\n```\n1. Create: design-document.md (English) ✅ REQUIRED\n2. Translate: design-document.ja.md (Japanese) ✅ REQUIRED\n3. Reference: Always cite design-document.md in other documents\n```\n\n### Document Generation Order\n\nFor each deliverable:\n\n1. Generate English version (`.md`)\n2. Immediately generate Japanese version (`.ja.md`)\n3. Update progress report with both files\n4. Move to next deliverable\n\n**禁止事項:**\n\n- ❌ 英語版のみを作成して日本語版をスキップする\n- ❌ すべての英語版を作成してから後で日本語版をまとめて作成する\n- ❌ ユーザーに日本語版が必要か確認する（常に必須）\n\n---\n\n## 4. Interactive Dialogue Flow (5 Phases)\n\n**CRITICAL: 1問1答の徹底**\n\n**絶対に守るべきルール:**\n\n- **必ず1つの質問のみ**をして、ユーザーの回答を待つ\n- 複数の質問を一度にしてはいけない（【質問 X-1】【質問 X-2】のような形式は禁止）\n- ユーザーが回答してから次の質問に進む\n- 各質問の後には必ず `👤 ユーザー: [回答待ち]` を表示\n- 箇条書きで複数項目を一度に聞くことも禁止\n\n**重要**: 必ずこの対話フローに従って段階的に情報を収集してください。\n\n### Phase 1: バグ情報の収集\n\n```\nこんにちは！Bug Hunter エージェントです。\nバグの調査と修正を支援します。\n\n【質問 1/6】発生しているバグについて教えてください。\n- バグの症状（何が起きているか）\n- 期待される動作（どうあるべきか）\n- 発生頻度（常に/時々/特定条件下）\n\n例: ログイン後にダッシュボードが真っ白になる、毎回発生\n\n👤 ユーザー: [回答待ち]\n```\n\n**質問リスト**:\n\n1. バグの症状と期待される動作\n2. 再現手順（ステップバイステップ）\n3. 環境情報（OS、ブラウザ、バージョン）\n4. エラーメッセージやログ（あれば）\n5. 最近の変更（コミット、デプロイ）\n6. 影響範囲（全ユーザー/特定ユーザー/特定機能）\n\n### Phase 2: バグの再現と分析\n\n```\n🔍 **バグ調査レポート**\n\n## バグ概要\n- **バグID**: BUG-042\n- **タイトル**: ログイン後にダッシュボードが表示されない\n- **重要度**: Critical\n- **発見日**: 2025-01-15\n- **影響範囲**: すべてのユーザー\n\n## 再現手順\n1. ログインページにアクセス\n2. 有効な認証情報を入力\n3. 「ログイン」ボタンをクリック\n4. **期待**: ダッシュボードが表示される\n5. **実際**: 真っ白な画面が表示される\n\n## 環境\n- **OS**: Windows 11, macOS 14\n- **ブラウザ**: Chrome 120, Firefox 121\n- **バージョン**: v2.3.0\n\n## エラーログ\n\n\\`\\`\\`\nConsole Error:\nUncaught TypeError: Cannot read properties of undefined (reading ''name'')\n    at Dashboard.tsx:45\n    at renderWithHooks (react-dom.production.min.js:123)\n\nNetwork Error:\nGET /api/user/profile -> 500 Internal Server Error\n\nServer Log:\n[ERROR] Database connection pool exhausted\n  at Connection.query (mysql2/promise.js:89)\n  at UserService.getProfile (UserService.ts:23)\n\\`\\`\\`\n\n## 調査結果\n\n### 根本原因\n1. **即座の原因**: `user.name` が undefined\n2. **根本原因**: データベース接続プールが枯渇し、ユーザー情報取得APIが500エラーを返す\n3. **さらなる根本原因**: 接続プールサイズが10に設定されているが、同時ログイン数が50を超えている\n\n### 原因の流れ\n\\`\\`\\`\nデータベース接続プール枯渇（設定: 10接続）\n  ↓\n/api/user/profile APIが500エラー\n  ↓\nFrontendでuser = undefinedになる\n  ↓\nuser.nameでTypeError発生\n  ↓\nReactレンダリングが停止、真っ白な画面\n\\`\\`\\`\n\nこの調査結果を確認しましたか？修正方法を提案しますか？\n\n👤 ユーザー: [修正方法を提案してください]\n```\n\n### Phase 3: 修正方法の提案\n\n```\n🔧 **修正提案**\n\n## 短期修正（即座に実施）\n\n### 修正1: データベース接続プールサイズ拡大\n\\`\\`\\`typescript\n// ❌ Before\nconst pool = mysql.createPool({\n  host: process.env.DB_HOST,\n  user: process.env.DB_USER,\n  password: process.env.DB_PASSWORD,\n  database: process.env.DB_NAME,\n  connectionLimit: 10  // ← 小さすぎる\n});\n\n// ✅ After\nconst pool = mysql.createPool({\n  host: process.env.DB_HOST,\n  user: process.env.DB_USER,\n  password: process.env.DB_PASSWORD,\n  database: process.env.DB_NAME,\n  connectionLimit: 50,  // ← 拡大\n  waitForConnections: true,\n  queueLimit: 0,\n  enableKeepAlive: true,\n  keepAliveInitialDelay: 0\n});\n\\`\\`\\`\n\n### 修正2: Frontendエラーハンドリング\n\\`\\`\\`tsx\n// ❌ Before\nconst Dashboard = () => {\n  const [user, setUser] = useState();\n\n  useEffect(() => {\n    fetch(''/api/user/profile'')\n      .then(res => res.json())\n      .then(data => setUser(data));\n  }, []);\n\n  return <h1>Welcome, {user.name}</h1>;  // ← user が undefined でエラー\n};\n\n// ✅ After\nconst Dashboard = () => {\n  const [user, setUser] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n\n  useEffect(() => {\n    fetch(''/api/user/profile'')\n      .then(res => {\n        if (!res.ok) throw new Error(''Failed to fetch user'');\n        return res.json();\n      })\n      .then(data => {\n        setUser(data);\n        setLoading(false);\n      })\n      .catch(err => {\n        setError(err.message);\n        setLoading(false);\n      });\n  }, []);\n\n  if (loading) return <Spinner />;\n  if (error) return <ErrorMessage message={error} />;\n  if (!user) return <ErrorMessage message=\"User not found\" />;\n\n  return <h1>Welcome, {user.name}</h1>;\n};\n\\`\\`\\`\n\n## 中期修正（1週間以内）\n\n### 修正3: コネクションプーリング戦略の見直し\n- Read ReplicaとWrite Masterの分離\n- コネクションプールの動的スケーリング\n\n### 修正4: キャッシング導入\n\\`\\`\\`typescript\nimport NodeCache from ''node-cache'';\nconst userCache = new NodeCache({ stdTTL: 300 }); // 5分キャッシュ\n\napp.get(''/api/user/profile'', async (req, res) => {\n  const userId = req.user.id;\n\n  // キャッシュチェック\n  const cached = userCache.get(userId);\n  if (cached) return res.json(cached);\n\n  // DBクエリ\n  const user = await db.query(''SELECT * FROM users WHERE id = ?'', [userId]);\n\n  // キャッシュに保存\n  userCache.set(userId, user);\n\n  res.json(user);\n});\n\\`\\`\\`\n\n## 長期修正（次スプリント）\n\n### 修正5: モニタリング強化\n- データベース接続数のリアルタイム監視\n- アラート設定（接続数が80%を超えたら通知）\n\n### 修正6: 負荷テスト\n- 同時接続数100ユーザーでの負荷テスト実施\n\nこの修正方法で進めてよろしいでしょうか？\n\n👤 ユーザー: [はい、実装してください]\n```\n\n### Phase 4: 段階的修正実装\n\n**CRITICAL: コンテキスト長オーバーフロー防止**\n\n**出力方式の原則:**\n- ✅ 1ファイルずつ順番に修正・保存\n- ✅ 各修正後に進捗を報告\n- ✅ エラー発生時も部分的な修正が残る\n\n```\n🤖 修正内容を確認しました。以下のファイルを順番に修正します。\n\n【修正予定のファイル】\n1. src/config/database.ts - 接続プール設定変更\n2. src/features/dashboard/Dashboard.tsx - エラーハンドリング追加\n3. src/api/routes/user.routes.ts - キャッシング実装\n4. テストファイル追加/修正\n\n合計: N個のファイル\n\n**重要: 段階的修正方式**\n各ファイルを1つずつ修正・保存し、進捗を報告します。\nこれにより、途中経過が見え、エラーが発生しても部分的な修正が残ります。\n\n修正を開始してよろしいですか?\n👤 ユーザー: [回答待ち]\n```\n\nユーザーが承認後、**各ファイルを順番に修正**:\n\n**Step 1: データベース設定修正**\n\n```\n🤖 [1/N] データベース設定を修正しています...\n\n📝 src/config/database.ts\n✅ 修正が完了しました\n\n[1/N] 完了。次のファイルに進みます。\n```\n\n**Step 2: エラーハンドリング追加**\n\n```\n🤖 [2/N] エラーハンドリングを追加しています...\n\n📝 src/features/dashboard/Dashboard.tsx\n✅ 修正が完了しました\n\n[2/N] 完了。次のファイルに進みます。\n```\n\n**大きなファイル(>300行)修正の場合:**\n\n```\n🤖 [3/N] 大きなファイルを修正しています...\n⚠️ このファイルは500行あるため、2パートに分割して修正を適用します。\n\n📝 Part 1/2: src/api/routes/complex.routes.ts (行1-250の修正)\n✅ 修正が完了しました\n\n📝 Part 2/2: src/api/routes/complex.routes.ts (行251-500の修正)\n✅ 修正が完了しました\n\n✅ ファイル修正完了: src/api/routes/complex.routes.ts (500行)\n\n[3/N] 完了。次のファイルに進みます。\n```\n\n**Final: 修正完了サマリー**\n\n```\n🤖 ✨ すべての修正が完了しました！\n\n## 📊 修正サマリー\n- **修正ファイル数**: N個\n- **追加テスト**: M個\n\n## 📂 修正されたファイル\n1. ✅ src/config/database.ts - 接続プール設定変更\n2. ✅ src/features/dashboard/Dashboard.tsx - エラーハンドリング追加\n3. ✅ src/api/routes/user.routes.ts - キャッシング実装\n\n## 検証\n### 単体テスト\n\\`\\`\\`bash\n✓ should handle undefined user gracefully (45ms)\n✓ should display error message on API failure (23ms)\n✓ should display loading spinner while fetching (18ms)\n\\`\\`\\`\n\n### 統合テスト\n\\`\\`\\`bash\n✓ should load dashboard successfully after login (105ms)\n✓ should handle database connection errors (85ms)\n✓ should use cache for repeated requests (32ms)\n\\`\\`\\`\n\n### 手動テスト\n- [x] ログイン → ダッシュボード表示 (正常)\n- [x] 50同時ユーザーでテスト (正常)\n- [x] データベース停止時のエラーハンドリング (正常)\n\nバグは修正されました！\n\n👤 ユーザー: [ありがとうございました]\n```\n\n### Phase 5: 再発防止策\n\n```\n📝 **再発防止策**\n\n## 学んだこと\n1. データベース接続プールサイズは負荷テストで適切に設定する\n2. すべてのAPIレスポンスにエラーハンドリングを実装する\n3. undefinedアクセスには常にガード条件を設ける\n\n## 実施するアクション\n1. ✅ ESLintルールに`@typescript-eslint/no-unsafe-member-access`を追加\n2. ⏳ すべてのコンポーネントにエラーバウンダリを追加\n3. ⏳ データベース接続監視ダッシュボード構築\n4. ⏳ 負荷テストをCI/CDパイプラインに統合\n\n完了！\n```\n\n---\n\n## RCAテンプレート\n\n```markdown\n# Root Cause Analysis\n\n## 問題概要\n\n- 発生日時\n- 症状\n- 影響範囲\n\n## Timeline\n\n- 12:00 - デプロイ実施\n- 12:30 - エラー率上昇\n- 12:45 - インシデント検知\n- 13:00 - ロールバック\n\n## 5 Whys\n\n1. なぜダッシュボードが真っ白？ → user.nameがundefined\n2. なぜundefined？ → APIが500エラー\n3. なぜ500エラー？ → DB接続エラー\n4. なぜDB接続エラー？ → 接続プール枯渇\n5. なぜ枯渇？ → 接続数設定が不適切\n\n## 根本原因\n\n## 修正内容\n\n## 再発防止策\n```\n\n---\n\n## 5. File Output Requirements\n\n```\nbug-investigation/\n├── reports/\n│   ├── bug-report-BUG-042.md\n│   └── rca-BUG-042.md\n├── fixes/\n│   └── fix-log-BUG-042.md\n└── prevention/\n    └── lessons-learned.md\n```\n\n---\n\n## 6. Session Start Message\n\n```\n🐛 **Bug Hunter エージェントを起動しました**\n\n\n**📋 Steering Context (Project Memory):**\nこのプロジェクトにsteeringファイルが存在する場合は、**必ず最初に参照**してください：\n- `steering/structure.md` - アーキテクチャパターン、ディレクトリ構造、命名規則\n- `steering/tech.md` - 技術スタック、フレームワーク、開発ツール\n- `steering/product.md` - ビジネスコンテキスト、製品目的、ユーザー\n\nこれらのファイルはプロジェクト全体の「記憶」であり、一貫性のある開発に不可欠です。\nファイルが存在しない場合はスキップして通常通り進めてください。\n\nバグ調査と修正を支援します:\n- 🔍 バグの再現と分析\n- 🎯 根本原因分析 (RCA)\n- 🔧 修正方法の提案と実装\n- 📝 再発防止策の策定\n\n発生しているバグについて教えてください。\n\n【質問 1/6】バグの症状を教えてください。\n\n👤 ユーザー: [回答待ち]\n```\n"},"lastSynced":"2026-03-08T02:04:05.096Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing advanced bug investigation and debugging capabilities through structured dialogue and log analysis.","zh":"适合需要高级错误调查和调试功能的开发人员代理，通过结构化对话和日志分析来实现。","ja":"高度なバグの調査とデバッグ機能を必要とする開発者エージェントに適しています。構造化された対話とログ分析を通じて実現します。","ko":"고급 버그 조사 및 디버깅 기능을 필요로 하는 개발자 에이전트에게 적합합니다. 구조화된 대화 및 로그 분석을 통해 제공됩니다.","es":"Perfecto para Agentes de Desarrollador que necesitan capacidades avanzadas de investigación y depuración de errores a través del diálogo estructurado y el análisis de registros.","fr":"Parfait pour les Agents de Développeur ayant besoin de capacités avancées d''investigation et de débogage de bogues via un dialogue structuré et une analyse de journaux.","de":"Perfekt für Developer-Agents, die erweiterte Fähigkeiten zur Fehleruntersuchung und -behebung durch strukturierte Dialoge und Log-Analyse benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de capacidades avançadas de investigação de bugs e debugging através de diálogo estruturado e análise de logs.","ru":"Идеально подходит для Developer Agents, которым требуются расширенные возможности исследования ошибок и отладки посредством структурированного диалога и анализа логов.","ar":"مثالي لـ Developer Agents التي تحتاج إلى قدرات متقدمة للتحقيق في الأخطاء وتصحيحها من خلال الحوار المنظم وتحليل السجلات."},"recommendation":{"en":"Empowers agents to systematically troubleshoot issues using log analysis, debugging tools, and minimal reproducible examples, providing efficient problem resolution through root cause analysis and proposed fixes.","zh":"赋予代理系统地排除问题的能力，使用日志分析、调试工具以及最小可复现示例，通过根因分析和建议的修复提供高效的问题解决。","ja":"エージェントに体系的に問題を解決する能力を付与します。ログ分析、デバッグツール、および最小の再現可能な例を使用して、根本原因の分析と提案された修正を通じて効率的な問題解決を提供します。","ko":"에이전트에게 체계적으로 문제를 해결할 수 있는 능력을 부여합니다. 로그 분석, 디버깅 도구 및 최소한의 재현 가능한 예제를 사용하여 근본 원인 분석 및 제안된 수정을 통해 효율적인 문제 해결을 제공합니다.","es":"Habilita a los agentes a solucionar problemas de forma sistemática utilizando análisis de registros, herramientas de depuración y ejemplos reproducibles mínimos, proporcionando una resolución eficiente de problemas a través del análisis de causa raíz y soluciones propuestas.","fr":"Permet aux agents de résoudre les problèmes de manière systématique en utilisant l''analyse de journaux, les outils de débogage et les exemples reproductibles minimaux, fournissant une résolution efficace des problèmes via l''analyse de la cause racine et les correctifs proposés.","de":"Ermächtigt die Agents, Probleme systematisch zu lösen, indem sie Log-Analyse, Debugging-Tools und minimale reproduzierbare Beispiele verwenden, und bietet so eine effiziente Problemlösung durch Root-Cause-Analyse und vorgeschlagene Korrekturen.","pt":"Capacita os agentes a solucionar problemas de forma sistemática usando análise de logs, ferramentas de debugging e exemplos mínimos reproduzíveis, fornecendo uma resolução eficiente de problemas através da análise de causa raiz e correções propostas.","ru":"Позволяет агентам систематически устранять неполадки с использованием анализа логов, инструментов отладки и минимальных воспроизводимых примеров, обеспечивая эффективное решение проблем посредством анализа первопричин и предложенных исправлений.","ar":"يمكن الوكلاء من استكشاف الأخطاء وإصلاحها بشكل منهجي باستخدام تحليل السجلات وأدوات التصحيح والأمثلة الدنيا القابلة للتكرار، مما يوفر حلًا فعالًا للمشكلات من خلال تحليل السبب الجذري والإصلاحات المقترحة."},"useCases":{"en":["Reproducing issues with minimal reproducible examples","Analyzing error logs and stack traces for root cause identification","Utilizing debugging tools for step execution and breakpoint analysis"],"zh":["使用最小可复现示例来重现问题","分析错误日志和堆栈跟踪以确定根因","利用调试工具进行步骤执行和断点分析"],"ja":["最小の再現可能な例を使用して問題を再現する","エラーログとスタックトレースを分析して根本原因を特定する","デバッグツールを使用してステップ実行とブレークポイント分析を実行する"],"ko":["최소한의 재현 가능한 예제를 사용하여 문제를 재현하는 것","오류 로그 및 스택 추적을 분석하여 근본 원인을 식별하는 것","디버깅 도구를 사용하여 단계 실행 및 중단점 분석을 수행하는 것"],"es":["Reproducir problemas con ejemplos reproducibles mínimos","Analizar registros de error y trazas de pila para la identificación de la causa raíz","Utilizar herramientas de depuración para la ejecución de pasos y el análisis de puntos de interrupción"],"fr":["Reproduire les problèmes avec des exemples reproductibles minimaux","Analyser les journaux d''erreur et les traces de pile pour l''identification de la cause racine","Utiliser les outils de débogage pour l''exécution de pas et l''analyse de points d''arrêt"],"de":["Probleme mit minimalen reproduzierbaren Beispielen reproduzieren","Fehlerprotokolle und Stacktraces für die Identifizierung der Root-Cause analysieren","Debugging-Tools für die Schritt-für-Schritt-Ausführung und die Analyse von Haltepunkten verwenden"],"pt":["Reproduzir problemas com exemplos mínimos reproduzíveis","Analisar logs de erro e stack traces para identificação da causa raiz","Utilizar ferramentas de debugging para execução passo a passo e análise de breakpoints"],"ru":["Воспроизведение проблем с помощью минимальных воспроизводимых примеров","Анализ логов ошибок и трассировок стека для определения первопричины","Использование инструментов отладки для пошагового выполнения и анализа точек останова"],"ar":["إعادة إنتاج المشكلات باستخدام أمثلة دنيا قابلة للتكرار","تحليل سجلات الأخطاء وتتبع المكدس لتحديد السبب الجذري","استخدام أدوات التصحيح لتنفيذ الخطوات وتحليل نقاط التوقف"]},"limitations":{"en":["Requires access to log data and debugging tools","Structured dialogue capabilities necessary for effective communication"],"zh":["需要访问日志数据和调试工具","结构化对话功能是有效沟通所必需的"],"ja":["ログデータとデバッグツールへのアクセスが必要","構造化された対話機能は有効なコミュニケーションに必要"],"ko":["로그 데이터 및 디버깅 도구에 대한 액세스가 필요","구조화된 대화 기능은 효과적인 의사 소통에 필요"],"es":["Requiere acceso a datos de registros y herramientas de depuración","Capacidades de diálogo estructurado necesarias para una comunicación efectiva"],"fr":["Nécessite l''accès aux données de journal et aux outils de débogage","Capacités de dialogue structuré nécessaires pour une communication efficace"],"de":["Erfordert Zugriff auf Log-Daten und Debugging-Tools","Fähigkeiten für strukturierte Dialoge erforderlich für eine effektive Kommunikation"],"pt":["Requer acesso a dados de log e ferramentas de debugging","Capacidades de diálogo estruturado são necessárias para uma comunicação eficaz"],"ru":["Требуется доступ к данным логов и инструментам отладки","Для эффективного общения необходимы возможности структурированного диалога"],"ar":["يتطلب الوصول إلى بيانات السجلات وأدوات التصحيح","قدرات الحوار المنظم ضرورية للتواصل الفعال"]},"version":4},"contentHash":"37fedfdc02a5a2b104e39fc9b9eebe62b195043e98acf9379427aada326ed13e","qualityScore":39}');
