INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nahisaho/CodeGraphMCPServer/bug-hunter', 'bug-hunter', 'nahisaho', 'CodeGraphMCPServer', 'community', 'bug-hunter nahisaho CodeGraphMCPServer community The bug-hunter skill investigates bugs, reproduces issues, analyzes root causes, and proposes fixes through structured dialogue. It benefits developers by utilizing log analysis and debugging tools for efficient problem resolution. Bug Hunter AI 是一种利用日志分析和调试工具进行 Bug 调试的 AI 工具 バグハンター AIエージェントは、日本語での構造化対話でバグを調査、再現、分析、修復する AI エージェント 버그 헌터 AI 도구는 버그를 신속하게 해결하고 최적의 성능을 달성할 수 있는 AI 도구 El Bug Hunter AI es una herramienta que utiliza métodos de investigación de errores, análisis de registros y herramientas de depuración para identificar y solucionar problemas de forma eficiente L''Agent Bug Hunter est un outil qui utilise des méthodes d''investigation d''erreurs, d''analyse de journaux et d''outils de débogage pour identifier et résoudre les problèmes de manière efficace Der Bug Hunter AI ist ein Tool, das Fehleruntersuchungsmethoden, Log-Analyse und Debugging-Tools verwendet, um Probleme effizient zu identifizieren und zu lösen O Bug Hunter AI é uma ferramenta de investigação de bugs que utiliza log analysis e debugging tools para resolver problemas de forma rápida ИИ Агент Bug Hunter - это инструмент для поиска и решения проблем, использующий анализ логов и инструменты отладки для быстрого решения проблем مرشح الأخطاء AI هو أداة لتحليل الأخطاء التي تستخدم تحليل السجلات وأدوات التصحيح لتصحيح الأخطاء بسرعة how to use bug-hunter bug-hunter alternative bug-hunter setup guide what is bug-hunter bug-hunter vs debug tools bug-hunter install bug-hunter log analysis bug-hunter debugging tools bug-hunter systematic troubleshooting Bug Hunter AI AI调试工具 日志分析 调试工具 快速 Bug 调试 Minimal Reproducible Examples 结构化对话 Utilizes log analysis of error logs and stack traces for bug investigation Employs debugging tools with breakpoints and step execution for issue reproduction Generates minimal reproducible examples for efficient bug resolution Performs systematic troubleshooting to identify root causes of issues Proposes fixes through structured dialogue in Japanese bug-hunter is a specialized AI agent that investigates and resolves software bugs using methods like log analysis, debugging tools, and systematic troubleshooting.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pedrohcgs/claude-code-my-workflow/extract-tikz', 'community', 'pedrohcgs', 'claude-code-my-workflow', 'pedrohcgs/claude-code-my-workflow', 'extract-tikz', 0, 0, 39, '2026-03-08T01:57:15.360Z', '2026-03-08T02:04:13.203Z', '3863038e5efc05cc80a8f050a2fe987b7d1bf03284c7ceec14e07fd51c2a5e65', '{"id":"pedrohcgs/claude-code-my-workflow/extract-tikz","name":"extract-tikz","description":{"en":"extract-tikz is a Claude Code template for academics using LaTeX/Beamer and R, enabling the extraction of TikZ diagrams and conversion to SVG. It benefits researchers and students creating presentations with complex diagrams.","zh":"Extract TikZ是一个用于从LaTeX/Beamer源码中提取TikZ图表的工具，支持多页PDF转SVG","ja":"Extract TikZは、LaTeX/BeamerソースからTikZ図を抽出するツールで、複数ページPDFをSVGに変換","ko":"Extract TikZ는 LaTeX/Beamer 소스에서 TikZ 다이어그램을 추출하는 도구로, 다중 페이지 PDF를 SVG로 변환","es":"Extract-tikz es una plantilla de Claude Code para académicos que utilizan LaTeX/Beamer + R, que permite la extracción de diagramas TikZ y su conversión a SVG para uso en Quarto slides","fr":"Extract-tikz est un modèle de code Claude pour les universitaires utilisant LaTeX/Beamer + R, qui permet l''extraction de diagrammes TikZ et leur conversion en SVG pour une utilisation dans Quarto slides","de":"Extract-tikz ist eine Claude-Code-Vorlage für Akademiker, die LaTeX/Beamer + R verwenden, und ermöglicht die Extraktion von TikZ-Diagrammen und deren Umwandlung in SVG für die Verwendung in Quarto-Slides","pt":"O extract-tikz é um template Claude Code para acadêmicos que extrai diagramas TikZ de fontes Beamer e os converte para SVG","ru":"Extract-Tikz - это шаблон Claude Code для академов, который извлекает диаграммы TikZ из источников Beamer и конвертирует их в SVG","ar":"Extract-Tikz هو قالب Claude Code للأكاديميين لاستخراج مخططات TikZ من مصادر Beamer والتحويل إلى SVG"},"seo":{"title":{"en":"extract-tikz: LaTeX Beamer Diagram Extraction Setup Guide...","zh":"Extract TikZ Setup Guide: LaTeX/Beamer + R","ja":"Extract TikZ セットアップガイド: LaTeX/Beamer + R","ko":"Extract TikZ 설정 가이드: LaTeX/Beamer + R","es":"Guía de configuración para extract-tikz: Conversión de di...","fr":"Guide d''installation pour extract-tikz: Conversion de dia...","de":"Einrichtungsanleitung für extract-tikz: Umwandlung von Ti...","pt":"Guia de Configuração do Extract-Tikz para Acadêmicos","ru":"Настройка Extract-Tikz: ИИ Агенты для Академов","ar":"دليل إعداد Extract-Tikz للأكاديميين"},"description":{"en":"Discover how to extract TikZ diagrams from LaTeX Beamer sources and convert them to SVG for Quarto slides. Learn more and get started with extract-tikz today!","zh":"利用Extract TikZ从Beamer源码中提取TikZ图表，并将其转换为SVG格式，用于Quarto幻灯片","ja":"Extract TikZを使用してBeamerソースからTikZ図を抽出し、Quartoスライド用のSVG形式に変換","ko":"Extract TikZ를 사용하여 Beamer 소스에서 TikZ 다이어그램을 추출하고 Quarto 슬라이드용 SVG 형식으로 변환","es":"Aprende a utilizar extract-tikz para convertir diagramas TikZ en SVG y mejorar tus presentaciones con Quarto slides","fr":"Découvrez comment utiliser extract-tikz pour convertir des diagrammes TikZ en SVG et améliorer vos présentations avec Quarto slides","de":"Erfahren Sie, wie Sie extract-tikz verwenden, um TikZ-Diagramme in SVG umzuwandeln und Ihre Präsentationen mit Quarto-Slides zu verbessern","pt":"Aprenda a extrair diagramas TikZ de fontes Beamer e convertê-los para SVG com o template Claude Code","ru":"Извлеките диаграммы TikZ из источников Beamer и конвертируйте их в SVG с помощью шаблона Claude Code и ИИ Агентов","ar":"تعلم كيفية استخراج مخططات TikZ من مصادر Beamer والتحويل إلى SVG باستخدام قالب Claude Code"},"definition":{"en":"extract-tikz is a ready-to-fork template for extracting TikZ diagrams from LaTeX Beamer sources and converting them to SVG for use in Quarto slides.","zh":"Extract TikZ是一个用于提取和转换TikZ图表的AI工具，支持LaTeX/Beamer和R","ja":"Extract TikZは、TikZ図を抽出し変換するAIエージェントで、LaTeX/BeamerとRをサポート","ko":"Extract TikZ는 TikZ 다이어그램을 추출하고 변환하는 AI 에이전트로, LaTeX/Beamer와 R을 지원","es":"Extract-tikz es una herramienta de código abierto que permite la extracción y conversión de diagramas TikZ en SVG","fr":"Extract-tikz est un outil open source qui permet l''extraction et la conversion de diagrammes TikZ en SVG","de":"Extract-tikz ist ein Open-Source-Tool, das die Extraktion und Umwandlung von TikZ-Diagrammen in SVG ermöglicht","pt":"O que é extract-tikz? Um template para extrair diagramas TikZ de fontes Beamer","ru":"Что такое Extract-Tikz? Шаблон для извлечения диаграмм TikZ из источников Beamer","ar":"ما هو Extract-Tikz؟ قالب لاستخراج مخططات TikZ من مصادر Beamer"},"features":{"en":["Extracts TikZ diagrams from Beamer source using `extract_tikz.tex`","Compiles Beamer source to multi-page PDF","Converts each PDF page to SVG for use in Quarto slides","Performs freshness check to ensure `extract_tikz.tex` matches current Beamer source","Supports multi-agent review and quality gates for collaboration"],"zh":["从Beamer源码中提取TikZ图表","支持多页PDF转SVG","与LaTeX/Beamer和R集成","实现TikZ图表的自动化提取和转换","支持Quarto幻灯片"],"ja":["BeamerソースからTikZ図を抽出","複数ページPDFをSVGに変換","LaTeX/BeamerとRとの統合","TikZ図の自動抽出と変換","Quartoスライドのサポート"],"ko":["Beamer 소스에서 TikZ 다이어그램을 추출","다중 페이지 PDF를 SVG로 변환","LaTeX/Beamer와 R과의 통합","TikZ 다이어그램의 자동화 추출과 변환","Quarto 슬라이드 지원"],"es":["Extracción de diagramas TikZ de fuentes Beamer","Conversión de diagramas TikZ a SVG","Compatibilidad con Quarto slides","Integración con LaTeX/Beamer + R","Verificación de actualidad de los diagramas","Soporte para la creación de PDF multipágina"],"fr":["Extraction de diagrammes TikZ à partir de sources Beamer","Conversion de diagrammes TikZ en SVG","Compatibilité avec Quarto slides","Intégration avec LaTeX/Beamer + R","Vérification de l''actualité des diagrammes","Prise en charge de la création de PDF multipage"],"de":["Extraktion von TikZ-Diagrammen aus Beamer-Quellen","Umwandlung von TikZ-Diagrammen in SVG","Kompatibilität mit Quarto-Slides","Integration mit LaTeX/Beamer + R","Überprüfung der Aktualität der Diagramme","Unterstützung für die Erstellung von PDF-Multipage"],"pt":["Extração de diagramas TikZ de fontes Beamer","Compilação para PDF multi-página","Conversão de cada página para SVG","Integração com Quarto slides","Verificação de frescor antes da compilação"],"ru":["Извлечение диаграмм TikZ из источников Beamer","Компиляция в PDF multi-страницу","Конвертация каждой страницы в SVG","Интеграция с Quarto slides","Проверка свежести перед компиляцией"],"ar":["استخراج مخططات TikZ من مصادر Beamer","التجميع إلى PDF متعدد الصفحات","تحويل كل صفحة إلى SVG","التكامل مع Quarto slides","فحص النضج قبل التجميع"]},"keywords":{"en":["how to use extract-tikz","extract-tikz alternative","extract-tikz setup guide","latex beamer diagram extraction","tikz to svg conversion","quarto slides with tikz diagrams","extract-tikz vs other diagram extraction tools"],"zh":["Extract TikZ","LaTeX/Beamer","R语言","TikZ图表","SVG转换","Quarto幻灯片","AI工具","自动化提取","PDF转SVG"],"ja":["Extract TikZ","LaTeX/Beamer","R言語","TikZ図","SVG変換","Quartoスライド","AIエージェント","自動抽出","PDFからSVG"],"ko":["Extract TikZ","LaTeX/Beamer","R 언어","TikZ 다이어그램","SVG 변환","Quarto 슬라이드","AI 에이전트","자동화 추출","PDF에서 SVG로"],"es":["extract-tikz","TikZ a SVG","Quarto slides","LaTeX/Beamer + R","herramientas de código abierto","diagramas TikZ","conversión de diagramas","presentaciones académicas"],"fr":["extract-tikz","TikZ en SVG","Quarto slides","LaTeX/Beamer + R","outils open source","diagrammes TikZ","conversion de diagrammes","présentations universitaires"],"de":["extract-tikz","TikZ in SVG","Quarto-Slides","LaTeX/Beamer + R","Open-Source-Tools","TikZ-Diagramme","Umwandlung von Diagrammen","akademische Präsentationen"],"pt":["extract-tikz","TikZ","Beamer","LaTeX","Quarto slides","SVG","acadêmicos","template Claude Code"],"ru":["Extract-Tikz","TikZ","Beamer","LaTeX","Quarto slides","SVG","академов","шаблон Claude Code","ИИ Агенты"],"ar":["extract-tikz","TikZ","Beamer","LaTeX","Quarto slides","SVG","أداة أكاديمية","قالب Claude Code","أدوات الذكاء الاصطناعي"]}},"owner":"pedrohcgs","repo":"claude-code-my-workflow","repoPath":"pedrohcgs/claude-code-my-workflow","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.360Z","topics":[],"category":"community","skillMd":{"name":"extract-tikz","description":"Extract TikZ diagrams from Beamer source, compile to PDF, convert to SVG with 0-based indexing. Use when updating TikZ diagrams for Quarto slides.","bodyPreview":"# Extract TikZ Diagrams to SVG\n\nExtract TikZ diagrams from the Beamer source, compile to multi-page PDF, and convert each page to SVG for use in Quarto slides.\n\n## Steps\n\n### Step 0: Freshness Check (MANDATORY)\n\n**Before compiling, verify that `extract_tikz.tex` matches the current Beamer source.**\n\n1. Find the Beamer source: `ls Slides/$ARGUMENTS*.tex`\n2. Extract all `\\begin{tikzpicture}` blocks from Beamer\n3. Compare with `Figures/$ARGUMENTS/extract_tikz.tex`\n4. If ANY difference exists: updat","body":"# Extract TikZ Diagrams to SVG\n\nExtract TikZ diagrams from the Beamer source, compile to multi-page PDF, and convert each page to SVG for use in Quarto slides.\n\n## Steps\n\n### Step 0: Freshness Check (MANDATORY)\n\n**Before compiling, verify that `extract_tikz.tex` matches the current Beamer source.**\n\n1. Find the Beamer source: `ls Slides/$ARGUMENTS*.tex`\n2. Extract all `\\begin{tikzpicture}` blocks from Beamer\n3. Compare with `Figures/$ARGUMENTS/extract_tikz.tex`\n4. If ANY difference exists: update extract_tikz.tex from the Beamer source\n5. If extract_tikz.tex doesn''t exist: create it from scratch\n\n### Step 1: Navigate to the lecture''s Figures directory\n```bash\ncd Figures/$ARGUMENTS\n```\n\n### Step 2: Compile the extract_tikz.tex file\n```bash\nTEXINPUTS=../../Preambles:$TEXINPUTS xelatex -interaction=nonstopmode extract_tikz.tex\n```\n\n### Step 3: Count the number of pages\n```bash\npdfinfo extract_tikz.pdf | grep \"Pages:\"\n```\n\n### Step 4: Convert each page to SVG using 0-BASED INDEXING\n\n**CRITICAL: PDF pages are 1-indexed, but output SVG files are 0-indexed!**\n\n```bash\nPAGES=$(pdfinfo extract_tikz.pdf | grep \"Pages:\" | awk ''{print $2}'')\nfor i in $(seq 1 $PAGES); do\n  idx=$(printf \"%02d\" $((i-1)))\n  pdf2svg extract_tikz.pdf tikz_exact_$idx.svg $i\ndone\n```\n\n### Step 5: Sync to docs/ for deployment\n```bash\ncd ../..\n./scripts/sync_to_docs.sh $ARGUMENTS\n```\n\n### Step 6: Verify SVG files\n- Read 2-3 SVG files to confirm they contain valid SVG markup\n- Confirm file sizes are reasonable (not 0 bytes)\n\n### Step 7: Report results\n\n## Source of Truth Reminder\nTikZ diagrams MUST be edited in the Beamer `.tex` file first, then copied verbatim to `extract_tikz.tex`. See `.claude/rules/single-source-of-truth.md`.\n"},"lastSynced":"2026-03-08T02:04:13.203Z","agentAnalysis":{"suitability":{"en":"Perfect for Academic Agents needing advanced LaTeX and TikZ diagram conversion capabilities.","zh":"适合于需要高级 LaTeX 和 TikZ 图表转换功能的学术代理","ja":"学術エージェントが高度なLaTeXとTikZ図表変換機能を必要とする場合に最適","ko":"전문적인 LaTeX와 TikZ 다이어그램 변환 기능이 필요한 학술 에이전트에게 적합","es":"Perfecto para agentes académicos que necesitan capacidades avanzadas de conversión de LaTeX y TikZ.","fr":"Parfait pour les agents académiques ayant besoin de fonctionnalités avancées de conversion LaTeX et TikZ.","de":"Perfekt für akademische Agenten, die erweiterte LaTeX- und TikZ-Konvertierungsfunktionen benötigen.","pt":"Perfeito para Agentes Acadêmicos que precisam de capacidades avançadas de conversão de LaTeX e TikZ diagramas.","ru":"Идеально подходит для академических агентов, которым требуются расширенные возможности преобразования LaTeX и TikZ диаграмм.","ar":"مثالي للوكلاء الأكاديميين الذين يحتاجون إلى قدرات متقدمة لتحويل LaTeX و TikZ الرسوميات."},"recommendation":{"en":"Empowers agents to extract TikZ diagrams from Beamer sources, compile to multi-page PDF, and convert each page to SVG for use in Quarto slides, utilizing LaTeX, Beamer, and R for seamless presentation creation.","zh":"赋予代理从Beamer源提取TikZ图表、编译成多页PDF并将每页转换为SVG用于Quarto幻灯片的能力，利用LaTeX、Beamer和R实现无缝的演示文稿创建","ja":"BeamerソースからTikZ図表を抽出して複数ページのPDFにコンパイルし、Quartoスライドで使用するためにそれぞれのページをSVGに変換するエージェントの能力を与えることで、LaTeX、Beamer、Rを利用してシームレスなプレゼンテーションの作成を実現","ko":"Beamer 소스에서 TikZ 다이어그램을 추출하여 여러 페이지의 PDF로 컴파일하고 Quarto 슬라이드에서 사용하기 위해 각 페이지를 SVG로 변환하는 에이전트의 능력을 부여하여 LaTeX, Beamer, R를 활용한 무결점 프레젠테이션 생성을 가능하게 함","es":"Permite a los agentes extraer diagramas TikZ de fuentes Beamer, compilar a PDF de varias páginas y convertir cada página a SVG para su uso en diapositivas Quarto, utilizando LaTeX, Beamer y R para una creación de presentaciones sin problemas.","fr":"Permet aux agents d''extraire des diagrammes TikZ à partir de sources Beamer, de compiler en PDF multi-page et de convertir chaque page en SVG pour une utilisation dans des diapositives Quarto, en utilisant LaTeX, Beamer et R pour une création de présentations sans rupture.","de":"Ermöglicht es Agenten, TikZ-Diagramme aus Beamer-Quellen zu extrahieren, in Multi-Page-PDF zu kompilieren und jede Seite in SVG für den Einsatz in Quarto-Folien umzuwandeln, wobei LaTeX, Beamer und R für eine nahtlose Erstellung von Präsentationen verwendet werden.","pt":"Habilita os agentes a extrair diagramas TikZ de fontes Beamer, compilar para PDF de várias páginas e converter cada página para SVG para uso em slides Quarto, utilizando LaTeX, Beamer e R para criação de apresentações sem interrupções.","ru":"Наделяет агентов возможностью извлекать диаграммы TikZ из источников Beamer, компилировать в PDF с несколькими страницами и конвертировать каждую страницу в SVG для использования в слайдах Quarto, используя LaTeX, Beamer и R для бесшовного создания презентаций.","ar":"تمكّن الوكلاء من استخراج رسوميات TikZ من مصادر Beamer، وتجميعها إلى مستندات PDF متعددة الصفحات، وتحويل كل صفحة إلى SVG لاستخدامها في شرائح Quarto، باستخدام LaTeX و Beamer و R لإنشاء عرض تقديمي متوافق."},"useCases":{"en":["Automating TikZ diagram extraction from LaTeX Beamer sources","Generating SVG files from complex TikZ diagrams for web-based presentations","Converting multi-page PDFs to individual SVG files for flexible slide design"],"zh":["自动从LaTeX Beamer源提取TikZ图表","从复杂的TikZ图表生成SVG文件用于基于Web的演示","将多页PDF转换为单个SVG文件以实现灵活的幻灯片设计"],"ja":["LaTeX BeamerソースからTikZ図表を自動抽出する","複雑なTikZ図表からWebベースのプレゼンテーション用のSVGファイルを生成する","複数ページのPDFを個別のSVGファイルに変換して柔軟なスライドデザインを実現する"],"ko":["LaTeX Beamer 소스에서 TikZ 다이어그램을 자동으로 추출하는こと","복잡한 TikZ 다이어그램에서 웹 기반 프레젠테이션용 SVG 파일을 생성하는 것","여러 페이지의 PDF를 개별 SVG 파일로 변환하여 유연한 슬라이드 디자인을 구현하는 것"],"es":["Automatizar la extracción de diagramas TikZ de fuentes LaTeX Beamer","Generar archivos SVG a partir de diagramas TikZ complejos para presentaciones web","Convertir PDF de varias páginas en archivos SVG individuales para un diseño de diapositivas flexible"],"fr":["Automatiser l''extraction de diagrammes TikZ à partir de sources LaTeX Beamer","Générer des fichiers SVG à partir de diagrammes TikZ complexes pour des présentations web","Convertir des PDF multi-page en fichiers SVG individuels pour une conception de diapositives flexible"],"de":["Automatisieren der Extraktion von TikZ-Diagrammen aus LaTeX-Beamer-Quellen","Erzeugen von SVG-Dateien aus komplexen TikZ-Diagrammen für webbasierte Präsentationen","Umwandeln von Multi-Page-PDF in einzelne SVG-Dateien für einen flexiblen Folienentwurf"],"pt":["Automatizar a extração de diagramas TikZ de fontes LaTeX Beamer","Gerar arquivos SVG a partir de diagramas TikZ complexos para apresentações baseadas na web","Converter PDFs de várias páginas em arquivos SVG individuais para design de slides flexível"],"ru":["Автоматизировать извлечение диаграмм TikZ из источников LaTeX Beamer","Генерировать файлы SVG из сложных диаграмм TikZ для веб-презентаций","Преобразовывать PDF с несколькими страницами в отдельные файлы SVG для гибкого дизайна слайдов"],"ar":["تأتمتة استخراج رسوميات TikZ من مصادر LaTeX Beamer","إنشاء ملفات SVG من رسوميات TikZ المعقدة لشرائح الويب","تحويل مستندات PDF متعددة الصفحات إلى ملفات SVG فردية لتصميم شرائح مرن"]},"limitations":{"en":["Requires LaTeX and Beamer installation","Limited to TikZ diagram extraction and conversion","Dependent on R for compilation and conversion processes"],"zh":["需要安装LaTeX和Beamer","仅限于TikZ图表的提取和转换","依赖R进行编译和转换过程"],"ja":["LaTeXとBeamerのインストールが必要","TikZ図表の抽出と変換のみに限定される","コンパイルと変換プロセスにはRに依存する"],"ko":["LaTeX와 Beamer의 설치가 필요","TikZ 다이어그램 추출 및 변환에만 제한","컴파일 및 변환 프로세스에 R에 의존"],"es":["Requiere la instalación de LaTeX y Beamer","Limitado a la extracción y conversión de diagramas TikZ","Dependiente de R para los procesos de compilación y conversión"],"fr":["Nécessite l''installation de LaTeX et Beamer","Limité à l''extraction et à la conversion de diagrammes TikZ","Dépendant de R pour les processus de compilation et de conversion"],"de":["Benötigt die Installation von LaTeX und Beamer","Begrenzt auf die Extraktion und Umwandlung von TikZ-Diagrammen","Abhängig von R für die Kompilierungs- und Umwandlungsprozesse"],"pt":["Requer instalação do LaTeX e Beamer","Limitado à extração e conversão de diagramas TikZ","Dependente do R para processos de compilação e conversão"],"ru":["Требует установки LaTeX и Beamer","Ограничен извлечением и конвертацией диаграмм TikZ","Зависит от R для процессов компиляции и конвертации"],"ar":["يتطلب تثبيت LaTeX و Beamer","محدود باستخراج و تحويل رسوميات TikZ","يعتمد على R لعمليات التجميع و التحويل"]},"version":4},"contentHash":"3863038e5efc05cc80a8f050a2fe987b7d1bf03284c7ceec14e07fd51c2a5e65","qualityScore":39}');
