INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pedrohcgs/claude-code-my-workflow/extract-tikz', 'extract-tikz', 'pedrohcgs', 'claude-code-my-workflow', 'community', 'extract-tikz pedrohcgs claude-code-my-workflow community extract-tikz is a Claude Code template for academics using LaTeX/Beamer and R, enabling the extraction of TikZ diagrams and conversion to SVG. It benefits researchers and students creating presentations with complex diagrams. Extract TikZ是一个用于从LaTeX/Beamer源码中提取TikZ图表的工具，支持多页PDF转SVG Extract TikZは、LaTeX/BeamerソースからTikZ図を抽出するツールで、複数ページPDFをSVGに変換 Extract TikZ는 LaTeX/Beamer 소스에서 TikZ 다이어그램을 추출하는 도구로, 다중 페이지 PDF를 SVG로 변환 Extract-tikz es una plantilla de Claude Code para académicos que utilizan LaTeX/Beamer + R, que permite la extracción de diagramas TikZ y su conversión a SVG para uso en Quarto slides Extract-tikz est un modèle de code Claude pour les universitaires utilisant LaTeX/Beamer + R, qui permet l''extraction de diagrammes TikZ et leur conversion en SVG pour une utilisation dans Quarto slides Extract-tikz ist eine Claude-Code-Vorlage für Akademiker, die LaTeX/Beamer + R verwenden, und ermöglicht die Extraktion von TikZ-Diagrammen und deren Umwandlung in SVG für die Verwendung in Quarto-Slides O extract-tikz é um template Claude Code para acadêmicos que extrai diagramas TikZ de fontes Beamer e os converte para SVG Extract-Tikz - это шаблон Claude Code для академов, который извлекает диаграммы TikZ из источников Beamer и конвертирует их в SVG Extract-Tikz هو قالب Claude Code للأكاديميين لاستخراج مخططات TikZ من مصادر Beamer والتحويل إلى SVG how to use extract-tikz extract-tikz alternative extract-tikz setup guide latex beamer diagram extraction tikz to svg conversion quarto slides with tikz diagrams extract-tikz vs other diagram extraction tools Extract TikZ LaTeX/Beamer R语言 TikZ图表 SVG转换 Quarto幻灯片 AI工具 自动化提取 PDF转SVG Extracts TikZ diagrams from Beamer source using `extract_tikz.tex` Compiles Beamer source to multi-page PDF Converts each PDF page to SVG for use in Quarto slides Performs freshness check to ensure `extract_tikz.tex` matches current Beamer source Supports multi-agent review and quality gates for collaboration extract-tikz is a ready-to-fork template for extracting TikZ diagrams from LaTeX Beamer sources and converting them to SVG for use in Quarto slides.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SprocketLab/slop-code-bench/checkpoint-ambiguity-review', 'community', 'SprocketLab', 'slop-code-bench', 'SprocketLab/slop-code-bench', 'checkpoint-ambiguity-review', 0, 0, 39, '2026-03-08T01:57:15.376Z', '2026-03-08T02:05:18.564Z', '9fe11cc04eba1fa7dac9842ba3d40b74cc3986fe396c90aabb89a6f9b416dcf2', '{"id":"SprocketLab/slop-code-bench/checkpoint-ambiguity-review","name":"checkpoint-ambiguity-review","description":{"en":"The checkpoint-ambiguity-review skill reviews a checkpoint''s spec and tests to find and report non-explicit interpretations. It benefits developers by ensuring test accuracy.","zh":"Checkpoint 不明确性审查是一种代码审查技术，用于识别和解决代码中不明确的部分","ja":"チェックポイントの曖昧性レビューは、コード中の不明確な部分を識別して解決するコードレビューテクニックです","ko":"체크포인트 모호성 검토는 코드 중 모호한 부분을 식별하여 해결하는 코드 리뷰 테크닉입니다","es":"La revisión de ambigüedad de puntos de control es una herramienta que ayuda a identificar y corregir interpretaciones no explícitas en las pruebas de código","fr":"La revue d''ambiguïté des points de contrôle est un outil qui aide à identifier et corriger les interprétations non explicites dans les tests de code","de":"Die Prüfung von Ungenauigkeiten bei Kontrollpunkten ist ein Tool, das hilft, nicht explizite Interpretationen in Code-Tests zu identifizieren und zu korrigieren","pt":"A ferramenta de revisão de ambiguidade de checkpoint ajuda a identificar e corrigir interpretações não explícitas no código","ru":"ИИ Агент для проверки точек неоднозначности помогает обнаружить и исправить неявные интерпретации в коде","ar":"أداة مراجعة غموض النقاط تساعد في تحديد وتصحيح التفسيرات الغير صريحة في الكود"},"seo":{"title":{"en":"checkpoint-ambiguity-review: Automated Test Review for AI...","zh":"Checkpoint 不明确性审查设置指南","ja":"チェックポイントの曖昧性レビュー ベストプラクティス - AIエージェント","ko":"체크포인트 모호성 검토 가이드 - AI 툴","es":"Guía de Configuración de Revisión de Ambigüedad de Puntos...","fr":"Guide de Configuration de la Revue d''Ambiguïté des Points...","de":"Konfigurationsleitfaden für die Prüfung von Ungenauigkeit...","pt":"Guia de Configuração do Ferramenta de Revisão de Ambiguid...","ru":"Настройка ИИ Агента для Проверки Точек Неоднозначности","ar":"دليل إعداد أداة مراجعة غموض النقاط"},"description":{"en":"Discover how checkpoint-ambiguity-review simplifies test validation. Learn to identify implicit interpretations and fix tests with our expert guide.","zh":"了解如何使用Checkpoint 不明确性审查来改进代码质量，减少不明确性带来的问题","ja":"チェックポイントの曖昧性レビューを使用してコード品質を向上させる方法を学びましょう - AIエージェント","ko":"체크포인트 모호성 검토를 사용하여 코드 품질을 향상시키는 방법을 알아보세요 - AI 툴","es":"Aprende a utilizar la herramienta de revisión de ambigüedad de puntos de control para mejorar la precisión de tus pruebas de código","fr":"Découvrez comment utiliser l''outil de revue d''ambiguïté des points de contrôle pour améliorer la précision de vos tests de code","de":"Erfahren Sie, wie Sie das Tool zur Prüfung von Ungenauigkeiten bei Kontrollpunkten verwenden, um die Genauigkeit Ihrer Code-Tests zu verbessern","pt":"Aprenda a configurar a ferramenta de revisão de ambiguidade de checkpoint para melhorar a qualidade do código","ru":"Узнайте, как настроить ИИ Агент для проверки точек неоднозначности и улучшить качество кода","ar":"تعرف على كيفية إعداد أداة مراجعة غموض النقاط لتحسين جودة الكود"},"definition":{"en":"checkpoint-ambiguity-review is a skill that analyzes checkpoint specifications and tests to detect and resolve ambiguity issues.","zh":"Checkpoint 不明确性审查是一种代码审查技术，用于识别和解决代码中不明确的部分","ja":"チェックポイントの曖昧性レビューは、コード中の不明確な部分を識別して解決するコードレビューテクニックです","ko":"체크포인트 모호성 검토는 코드 중 모호한 부분을 식별하여 해결하는 코드 리뷰 테크닉입니다","es":"La revisión de ambigüedad de puntos de control es un proceso que analiza las pruebas de código para detectar interpretaciones razonables pero no explícitas","fr":"La revue d''ambiguïté des points de contrôle est un processus qui analyse les tests de code pour détecter les interprétations raisonnables mais non explicites","de":"Die Prüfung von Ungenauigkeiten bei Kontrollpunkten ist ein Prozess, der Code-Tests analysiert, um vernünftige, aber nicht explizite Interpretationen zu erkennen","pt":"Revisão de ambiguidade de checkpoint é um processo de análise de código para identificar interpretações não explícitas","ru":"Проверка точек неоднозначности - это процесс анализа кода для обнаружения неявных интерпретаций","ar":"مراجعة غموض النقاط هي عملية تحليل الكود لتحديد التفسيرات الغير صريحة"},"features":{"en":["Collects inputs from problem name, checkpoint number, and file paths","Scans test files and spec paths, including `problems/{problem}/tests/test_checkpoint_{N}.py`","Reports tests with non-explicit interpretations and provides rationale and fixes","Supports inference of spec and test file paths if not provided","Works with Markdown files, such as `problems/{problem}/checkpoint_{N}.md`"],"zh":["支持Python代码审查","集成Spec和Test文件扫描","识别不明确的代码部分","提供修复建议","支持命令行界面（CLI）"],"ja":["Pythonコードレビューをサポート","SpecとTestファイルのスキャンを統合","不明確なコード部分を識別","修復提案を提供","コマンドラインインターフェース（CLI）をサポート"],"ko":["Python 코드 리뷰를 지원","Spec과 Test 파일 스캔을 통합","모호한 코드 부분을 식별","수정 제안을 제공","명령줄 인터페이스（CLI）를 지원"],"es":["Análisis de especificaciones de puntos de control","Detección de interpretaciones no explícitas en las pruebas de código","Informes de casos con razonamiento y soluciones","Integración con herramientas de prueba de código como Python","Soporte para la refactorización de código"," Mejora de la precisión de las pruebas de código"],"fr":["Analyse des spécifications des points de contrôle","Détection d''interprétations non explicites dans les tests de code","Rapports de cas avec raisonnement et solutions","Intégration avec des outils de test de code tels que Python","Prise en charge de la refactorisation de code","Amélioration de la précision des tests de code"],"de":["Analyse von Spezifikationen von Kontrollpunkten","Erkennung nicht expliziter Interpretationen in Code-Tests","Berichte über Fälle mit Begründung und Lösungen","Integration mit Code-Test-Tools wie Python","Unterstützung für die Refaktorisierung von Code","Verbesserung der Genauigkeit von Code-Tests"],"pt":["Análise de código para identificar interpretações não explícitas","Correção de interpretações não explícitas com base em especificações","Suporte a múltiplos arquivos de teste e especificação","Integração com o framework SlopCodeBench","Suporte a linguagem Python","Análise de código em tempo de execução"],"ru":["Анализ кода для обнаружения неявных интерпретаций","Исправление неявных интерпретаций на основе спецификаций","Поддержка множества тестовых файлов и спецификаций","Интеграция с фреймворком SlopCodeBench","Поддержка языка Python","Анализ кода в режиме реального времени"],"ar":["تحليل الكود لتحديد التفسيرات الغير صريحة","تصحيح التفسيرات الغير صريحة بالاعتماد على المواصفات","دعم لملفات الاختبار والمواصفات المتعددة","التكامل مع إطار عمل SlopCodeBench","دعم لغة بايثون","تحليل الكود في وقت التشغيل"]},"keywords":{"en":["how to use checkpoint-ambiguity-review","checkpoint-ambiguity-review setup guide","what is checkpoint-ambiguity-review","checkpoint-ambiguity-review vs manual test review","checkpoint-ambiguity-review install for AI agents","automated test review with checkpoint-ambiguity-review"],"zh":["Checkpoint 不明确性审查","代码审查技术","Python代码审查","Spec和Test文件扫描","代码质量改进","AIエージェント","代码审查工具"],"ja":["チェックポイントの曖昧性レビュー","コードレビューテクニック","Pythonコードレビュー","SpecとTestファイルのスキャン","コード品質向上","AIエージェント","コードレビューツール"],"ko":["체크포인트 모호성 검토","코드 리뷰 테크닉","Python 코드 리뷰","Spec과 Test 파일 스캔","코드 품질 향상","AI 툴","코드 리뷰 도구"],"es":["revisión de ambigüedad de puntos de control","herramientas de prueba de código","Python","refactorización de código","precisión de pruebas de código","desarrollo de software","pruebas de código","Herramientas de AI para desarrollo","Agentes de IA para pruebas de código"],"fr":["revue d''ambiguïté des points de contrôle","outils de test de code","Python","refactorisation de code","précision des tests de code","développement de logiciels","tests de code","Outils d''IA pour le développement","Agents d''IA pour les tests de code"],"de":["Prüfung von Ungenauigkeiten bei Kontrollpunkten","Code-Test-Tools","Python","Refaktorisierung von Code","Genauigkeit von Code-Tests","Software-Entwicklung","Code-Tests","AI-Tools für Entwicklung","KI-Agents für Code-Tests"],"pt":["revisão de ambiguidade de checkpoint","análise de código","interpretações não explícitas","especificações","SlopCodeBench","Python","desenvolvimento de software","qualidade de código","ferramentas de desenvolvimento"],"ru":["проверка точек неоднозначности","анализ кода","неявные интерпретации","спецификации","SlopCodeBench","Python","разработка программного обеспечения","качество кода","инструменты разработки"],"ar":["مراجعة غموض النقاط","تحليل الكود","التفسيرات الغير صريحة","المواصفات","SlopCodeBench","بايثون","تطوير البرمجيات","جودة الكود","أدوات التطوير"]}},"owner":"SprocketLab","repo":"slop-code-bench","repoPath":"SprocketLab/slop-code-bench","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.376Z","topics":[],"category":"community","skillMd":{"name":"checkpoint-ambiguity-review","description":"Review checkpoint specs and tests to identify tests that encode ambiguous interpretations rather than explicit requirements. Use when asked to check checkpoint_N.md against test_checkpoint_N.py, when auditing tests for ambiguity, or when reviewing snapshot eval failures for interpretive issues.","bodyPreview":"# Checkpoint Ambiguity Review\n\n## Overview\n\nReview a checkpoint''s spec and tests to find tests that enforce a reasonable but\nnon-explicit interpretation, and report those cases with rationale and fixes.\n\n## Workflow\n\n### 1) Collect inputs\n\n- Problem name and checkpoint number (N).\n- Test file path(s) and checkpoint spec path (if not provided, infer):\n  - Spec: `problems/{problem}/checkpoint_{N}.md`\n  - Tests: `problems/{problem}/tests/test_checkpoint_{N}.py`\n  - Also scan `problems/{problem}/tes","body":"# Checkpoint Ambiguity Review\n\n## Overview\n\nReview a checkpoint''s spec and tests to find tests that enforce a reasonable but\nnon-explicit interpretation, and report those cases with rationale and fixes.\n\n## Workflow\n\n### 1) Collect inputs\n\n- Problem name and checkpoint number (N).\n- Test file path(s) and checkpoint spec path (if not provided, infer):\n  - Spec: `problems/{problem}/checkpoint_{N}.md`\n  - Tests: `problems/{problem}/tests/test_checkpoint_{N}.py`\n  - Also scan `problems/{problem}/tests/conftest.py` and\n    `problems/{problem}/tests/data/` if they influence expectations.\n- Optional: snapshot path for ambiguity verification.\n\n### 2) Read the spec and tests\n\n- Extract explicit requirements from the spec.\n- Map each test assertion to a specific spec clause or an implied behavior.\n- Note any test assumptions that are not spelled out in the spec.\n\n### 3) Flag ambiguous interpretations\n\nOnly report tests that enforce an interpretation that could reasonably differ\ngiven the spec wording. Do not report tests that are simply incorrect against\nexplicit requirements.\n\nCommon ambiguity cues:\n- Output ordering when the spec does not mandate order.\n- Tie-breaking rules that are unstated.\n- Whitespace, casing, or formatting details not defined by the spec.\n- Rounding or precision requirements not defined.\n- Error handling for invalid inputs when not specified.\n- Boundary behavior (inclusive/exclusive) not stated.\n- Default values or optional fields not defined.\n- Determinism or randomness expectations not specified.\n- Multiple reasonable data structure representations (list vs set, map order).\n\n### 4) Optional snapshot verification\n\nIf a snapshot is provided, run:\n\n```bash\nslop-code --quiet eval-snapshot {snapshot} -p {problem} -o /tmp/eval -c {N} -e configs/environments/docker-python3.12-uv.yaml --json\n```\n\nUse failures to corroborate ambiguity, not to invent it. A failing test is\nambiguous only if the spec supports multiple reasonable interpretations.\n\n### 5) Report format\n\nUse the following structure for each ambiguous test:\n\n```\n## {test name} ({path}::{node_id})\n\n**Why:** {spec language + alternate interpretation that could be valid}\n**Fix:** {proposed test relaxation or spec clarification}\n```\n\nKeep entries concise and actionable. If no ambiguity is found, state that\nclearly (e.g., \"No ambiguity issues found.\").\n"},"lastSynced":"2026-03-08T02:05:18.564Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced test analysis and ambiguity detection capabilities.","zh":"非常适合需要高级测试分析和模糊性检测能力的代码审查代理。","ja":"コードレビュー代理が高度なテスト分析および曖昧性検出機能を必要とする場合に最適です。","ko":"고급 테스트 분석 및 모호성 검색 기능이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan capacidades de análisis de pruebas avanzadas y detección de ambigüedad.","fr":"Parfait pour les Agents de Révision de Code ayant besoin d''une analyse de test avancée et de capacités de détection d''ambiguïté.","de":"Perfekt für Code-Review-Agents, die erweiterte Testanalyse- und Mehrdeutigkeits-Erkennungsfunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de análise de teste avançada e capacidades de detecção de ambiguidade.","ru":"Идеально подходит для агентов проверки кода, которым необходимы расширенный анализ тестов и возможности обнаружения двусмысленностей.","ar":"مثالي للوكلاء المراجعة الكود الذين يحتاجون إلى تحليل اختبار متقدم وقدرات الكشف عن الغموض."},"recommendation":{"en":"Empowers agents to review checkpoint specs and tests, detecting non-explicit interpretations and providing rationale and fixes, utilizing Markdown and Python file analysis.","zh":"赋予代理审查检查点规范和测试的能力，检测非显式解释并提供理由和解决方案，利用Markdown和Python文件分析。","ja":"エージェントにチェックポイントの仕様とテストをレビューする能力を与え、明示的でない解釈を検出し、理由と修正を提供し、MarkdownとPythonファイルの分析を利用する。","ko":"에이전트가 체크포인트 사양과 테스트를 검토하고, 명시적이지 않은 해석을 감지하여 이유와 수정을 제공하며, Markdown과 Python 파일 분석을 활용합니다.","es":"Habilita a los agentes a revisar especificaciones de puntos de control y pruebas, detectar interpretaciones no explícitas y proporcionar razonamiento y soluciones, utilizando análisis de archivos Markdown y Python.","fr":"Permet aux agents de réviser les spécifications de points de contrôle et les tests, de détecter les interprétations non explicites et de fournir un raisonnement et des corrections, en utilisant l''analyse de fichiers Markdown et Python.","de":"Ermächtigt Agents, Prüfpunktspezifikationen und -tests zu überprüfen, nicht explizite Interpretationen zu erkennen und Begründungen und Lösungen bereitzustellen, unter Verwendung von Markdown- und Python-Dateianalyse.","pt":"Habilita os agentes a revisar especificações de checkpoint e testes, detectando interpretações não explícitas e fornecendo justificativa e soluções, utilizando análise de arquivos Markdown e Python.","ru":"Наделяет агентов возможностью проверять спецификации checkpoint и тесты, обнаруживая неявные интерпретации и предоставляя обоснование и исправления, используя анализ файлов Markdown и Python.","ar":"يمنح الوكلاء القدرة على مراجعة مواصفات الحجر الزاوي والاختبارات، واكتشاف التأويلات غير الصريحة وتقديم مبررات والإصلاحات، باستخدام تحليل ملفات Markdown و Python."},"useCases":{"en":["Reviewing checkpoint tests for ambiguity and implicit assumptions","Generating reports on non-explicit interpretations with rationale and fixes","Automating test accuracy validation for checkpoint specs"],"zh":["审查检查点测试以检测模糊性和隐含假设","生成非显式解释的报告，包括理由和解决方案","自动化检查点规范的测试准确性验证"],"ja":["曖昧性と暗黙の仮定を検出するためのチェックポイントテストのレビュー","理由と修正を含む、明示的でない解釈のレポートの生成","チェックポイント仕様のテスト精度の検証の自動化"],"ko":["모호성과 암시적 가정을 감지하기 위한 체크포인트 테스트 검토","理由와 수정을 포함한 명시적이지 않은 해석의 보고서 생성","체크포인트 사양의 테스트 정확도 검증 자동화"],"es":["Revisar pruebas de puntos de control para ambigüedad y suposiciones implícitas","Generar informes sobre interpretaciones no explícitas con razonamiento y soluciones","Automatizar la validación de precisión de pruebas para especificaciones de puntos de control"],"fr":["Réviser les tests de points de contrôle pour l''ambiguïté et les hypothèses implicites","Générer des rapports sur les interprétations non explicites avec un raisonnement et des corrections","Automatiser la validation de l''exactitude des tests pour les spécifications de points de contrôle"],"de":["Überprüfen von Prüfpunkttests auf Mehrdeutigkeit und implizite Annahmen","Erstellen von Berichten über nicht explizite Interpretationen mit Begründungen und Lösungen","Automatisieren der Validierung der Prüfgenauigkeit für Prüfpunktspezifikationen"],"pt":["Revisar testes de checkpoint para ambiguidade e suposições implícitas","Gerar relatórios sobre interpretações não explícitas com justificativa e soluções","Automatizar a validação de precisão de testes para especificações de checkpoint"],"ru":["Проверка тестов checkpoint на двусмысленность и неявные предположения","Генерация отчетов о неявных интерпретациях с обоснованием и исправлениями","Автоматизация проверки точности тестов для спецификаций checkpoint"],"ar":["مراجعة اختبارات الحجر الزاوي للغموض والافتراضات الضمنية","توليد تقارير حول التأويلات غير الصريحة مع المبررات والإصلاحات","آليّة التحقق من دقة الاختبارات لمواصفات الحجر الزاوي"]},"limitations":{"en":["Requires access to problem directories and files (e.g., .md and .py files)","Limited to reviewing checkpoint specs and tests in Markdown and Python formats","May require inference of spec and test file paths if not provided"],"zh":["需要访问问题目录和文件（例如.md和.py文件）","仅限于审查Markdown和Python格式的检查点规范和测试","如果未提供，可能需要推断规范和测试文件路径"],"ja":["問題ディレクトリとファイル（例：.mdおよび.pyファイル）へのアクセスが必要","チェックポイント仕様とテストのレビューは、MarkdownとPython形式に限定される","ファイルパスが提供されていない場合、仕様とテストファイルパスの推論が必要になる場合がある"],"ko":["문제 디렉토리와 파일(예: .md 및 .py 파일)への 액세스가 필요","체크포인트 사양 및 테스트의 검토는 Markdown 및 Python 형식으로 제한","파일 경로가 제공되지 않은 경우 사양 및 테스트 파일 경로의 추론이 필요할 수 있음"],"es":["Requiere acceso a directorios y archivos de problemas (por ejemplo, archivos .md y .py)","Limitado a la revisión de especificaciones y pruebas de puntos de control en formatos Markdown y Python","Puede requerir inferencia de rutas de archivos de especificaciones y pruebas si no se proporcionan"],"fr":["Nécessite un accès aux répertoires et aux fichiers de problèmes (par exemple, des fichiers .md et .py)","Limité à la révision des spécifications et des tests de points de contrôle au format Markdown et Python","Peut nécessiter une inférence des chemins de fichiers de spécifications et de tests si ceux-ci ne sont pas fournis"],"de":["Erfordert Zugriff auf Problemverzeichnisse und -dateien (z. B. .md- und .py-Dateien)","Begrenzt auf die Überprüfung von Prüfpunktspezifikationen und -tests im Markdown- und Python-Format","Kann die Inferenz von Spezifikations- und Testdateipfaden erfordern, wenn diese nicht bereitgestellt werden"],"pt":["Exige acesso a diretórios e arquivos de problemas (por exemplo, arquivos .md e .py)","Limitado à revisão de especificações de checkpoint e testes nos formatos Markdown e Python","Pode requerer inferência de caminhos de arquivo de especificação e teste se não fornecidos"],"ru":["Требует доступа к директориям и файлам проблем (например, файлам .md и .py)","Ограничен проверкой спецификаций checkpoint и тестов в форматах Markdown и Python","Может требовать вывода путей файла спецификации и теста, если они не предоставлены"],"ar":["يتطلب الوصول إلى الدلائل والملفات الخاصة بالمشاكل (على سبيل المثال، الملفات .md و .py)","محدود بمراجعة مواصفات الحجر الزاوي والاختبارات بصيغ Markdown و Python","يمكن أن يتطلب استنتاج مسارات ملفات المواصفة والاختبار إذا لم توفر"]},"version":4},"contentHash":"9fe11cc04eba1fa7dac9842ba3d40b74cc3986fe396c90aabb89a6f9b416dcf2","qualityScore":39}');
