INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SprocketLab/slop-code-bench/checkpoint-ambiguity-review', 'checkpoint-ambiguity-review', 'SprocketLab', 'slop-code-bench', 'community', 'checkpoint-ambiguity-review SprocketLab slop-code-bench community The checkpoint-ambiguity-review skill reviews a checkpoint''s spec and tests to find and report non-explicit interpretations. It benefits developers by ensuring test accuracy. Checkpoint 不明确性审查是一种代码审查技术，用于识别和解决代码中不明确的部分 チェックポイントの曖昧性レビューは、コード中の不明確な部分を識別して解決するコードレビューテクニックです 체크포인트 모호성 검토는 코드 중 모호한 부분을 식별하여 해결하는 코드 리뷰 테크닉입니다 La revisión de ambigüedad de puntos de control es una herramienta que ayuda a identificar y corregir interpretaciones no explícitas en las pruebas de código La revue d''ambiguïté des points de contrôle est un outil qui aide à identifier et corriger les interprétations non explicites dans les tests de code Die Prüfung von Ungenauigkeiten bei Kontrollpunkten ist ein Tool, das hilft, nicht explizite Interpretationen in Code-Tests zu identifizieren und zu korrigieren A ferramenta de revisão de ambiguidade de checkpoint ajuda a identificar e corrigir interpretações não explícitas no código ИИ Агент для проверки точек неоднозначности помогает обнаружить и исправить неявные интерпретации в коде أداة مراجعة غموض النقاط تساعد في تحديد وتصحيح التفسيرات الغير صريحة في الكود how to use checkpoint-ambiguity-review checkpoint-ambiguity-review setup guide what is checkpoint-ambiguity-review checkpoint-ambiguity-review vs manual test review checkpoint-ambiguity-review install for AI agents automated test review with checkpoint-ambiguity-review Checkpoint 不明确性审查 代码审查技术 Python代码审查 Spec和Test文件扫描 代码质量改进 AIエージェント 代码审查工具 Collects inputs from problem name, checkpoint number, and file paths Scans test files and spec paths, including `problems/{problem}/tests/test_checkpoint_{N}.py` Reports tests with non-explicit interpretations and provides rationale and fixes Supports inference of spec and test file paths if not provided Works with Markdown files, such as `problems/{problem}/checkpoint_{N}.md` checkpoint-ambiguity-review is a skill that analyzes checkpoint specifications and tests to detect and resolve ambiguity issues.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yuichi176/artlyst/openai-knowledge', 'community', 'yuichi176', 'artlyst', 'yuichi176/artlyst', 'openai-knowledge', 0, 0, 39, '2026-03-08T01:57:15.381Z', '2026-03-08T02:05:39.729Z', 'c8593bb84c584924e654df22aed6334018fb070905298eb7a1606a10d38c8fda', '{"id":"yuichi176/artlyst/openai-knowledge","name":"openai-knowledge","description":{"en":"The openai-knowledge skill enables AI agents to search and fetch exact documentation from the OpenAI Developer Documentation MCP server, providing accurate information for development purposes. This skill benefits developers working with OpenAI APIs.","zh":"OpenAI知识是使用MCP服务器搜索和获取精确文档的技能，帮助开发者快速找到所需信息","ja":"OpenAI Knowledgeは、AIエージェントとMCPサーバー検索を使用して正確な文書を取得する技能です","ko":"OpenAI 지식은 MCP 서버 검색과 문서를 사용하여 정확한 정보를 얻는技能입니다","es":"OpenAI Knowledge permite a los desarrolladores buscar y recuperar documentos exactos de la documentación de OpenAI Developer utilizando la herramienta MCP.","fr":"OpenAI Knowledge permet aux développeurs de rechercher et de récupérer des documents exacts de la documentation OpenAI Developer à l''aide de l''outil MCP.","de":"OpenAI Knowledge ermöglicht es Entwicklern, genaue Dokumente aus der OpenAI-Entwicklerdokumentation mithilfe des MCP-Tools zu suchen und abzurufen.","pt":"O OpenAI Knowledge é uma habilidade que utiliza o servidor MCP de documentação do OpenAI para buscar e recuperar documentos exatos.","ru":"OpenAI Knowledge — это навык, который использует сервер MCP документации OpenAI для поиска и извлечения точных документов.","ar":"أداة المعرفة_OPENAI هي ميزة تستخدم خادم MCP لتوثيق OpenAI للبحث عن واسترجاع المستندات الدقيقة."},"seo":{"title":{"en":"openai-knowledge: Setup Guide for AI Agents | AI Agent Skill","zh":"OpenAI 知识设置指南 - MCP 服务器搜索和文档","ja":"OpenAI Knowledge Setup Guide - AIエージェントとMCPサーバー検索","ko":"OpenAI 지식 설정 가이드 - MCP 서버 검색과 문서","es":"Guía de configuración de OpenAI Knowledge para desarrolla...","fr":"Guide de mise en route de OpenAI Knowledge pour les dével...","de":"Einrichtungsleitfaden für OpenAI Knowledge für Entwickler","pt":"Guia de Configuração do OpenAI Knowledge para Desenvolved...","ru":"Настройка OpenAI Knowledge: Руководство для Разработчиков","ar":"إعداد أداة المعرفة_OPENAI للباحثين"},"description":{"en":"Unlock the power of OpenAI knowledge with our expert guide. Learn how to search and fetch exact docs using the MCP server and improve your AI agent''s perform...","zh":"使用OpenAI Developer Documentation MCP服务器搜索和获取精确文档，了解OpenAI知识的设置和使用方法","ja":"OpenAI Knowledgeの設定方法を学ぶ - AIエージェントとMCPサーバー検索を使用した正確な文書取得","ko":"OpenAI 지식의 설정과 사용 방법을 알아보세요 - MCP 서버 검색과 문서를 사용하여 정확한 정보를 얻으세요","es":"Aprende a utilizar la documentación de OpenAI Developer para buscar y recuperar documentos exactos con la herramienta MCP","fr":"Découvrez comment utiliser la documentation OpenAI Developer pour rechercher et récupérer des documents exacts avec l''outil MCP","de":"Erfahren Sie, wie Sie die OpenAI-Entwicklerdokumentation verwenden, um genaue Dokumente mit dem MCP-Tool zu suchen und abzurufen","pt":"Aprenda a configurar o OpenAI Knowledge para melhorar a precisão das respostas com o servidor MCP de documentação do OpenAI","ru":"Узнайте, как настроить OpenAI Knowledge для улучшения точности ответов с помощью сервера MCP документации OpenAI","ar":"تعلم كيفية إعداد أداة المعرفة_OPENAI لتحسين دقة الإجابات باستخدام خادم MCP لتوثيق OpenAI"},"definition":{"en":"openai-knowledge is a skill that utilizes the OpenAI Developer Documentation MCP server to retrieve exact documentation, enabling AI agents to provide accurate and reliable information.","zh":"OpenAI知识是一种使用MCP服务器搜索和获取精确文档的技能","ja":"OpenAI Knowledgeは、AIエージェントとMCPサーバー検索を使用した技能です","ko":"OpenAI 지식은 MCP 서버 검색과 문서를 사용하는技能입니다","es":"OpenAI Knowledge es una habilidad que utiliza la documentación de OpenAI Developer para proporcionar respuestas precisas","fr":"OpenAI Knowledge est une compétence qui utilise la documentation OpenAI Developer pour fournir des réponses précises","de":"OpenAI Knowledge ist eine Fähigkeit, die die OpenAI-Entwicklerdokumentation nutzt, um genaue Antworten zu liefern","pt":"O que é OpenAI Knowledge? Uma habilidade que utiliza o servidor MCP para buscar e recuperar documentos exatos de desenvolvedores.","ru":"Что такое OpenAI Knowledge? Навык, который использует сервер MCP для поиска и извлечения точных документов для разработчиков.","ar":"ما هي أداة المعرفة_OPENAI؟ ميزة تستخدم خادم MCP للبحث عن واسترجاع المستندات الدقيقة للمطورين."},"features":{"en":["Searches for specific documentation using the MCP server","Fetches exact docs in markdown format","Checks availability of the MCP server using the `codex mcp list` command","Utilizes the `mcp__openaiDeveloperDocs` tool for documentation retrieval","Follows a structured workflow for efficient documentation search and retrieval"],"zh":["使用MCP服务器搜索和获取精确文档","支持codex mcp list命令","提供openaiDeveloperDocs工具","实现快速和准确的信息检索","支持多种搜索和获取文档的方式"],"ja":["AIエージェントとMCPサーバー検索を使用した正確な文書取得","codex mcp list命令のサポート","openaiDeveloperDocsツールの提供","高速かつ正確な情報検索の実現","複数の検索と文書取得方法のサポート"],"ko":["MCP 서버 검색과 문서를 사용하여 정확한 정보를 얻기","codex mcp list 명령어 지원","openaiDeveloperDocs 도구 제공","빠르고 정확한 정보 검색 구현","여러 가지 검색과 문서 얻기 방법 지원"],"es":["Utiliza la herramienta MCP para buscar y recuperar documentos exactos","Verifica la disponibilidad de la documentación de OpenAI Developer","Ejecuta comandos como `codex mcp list` para verificar la disponibilidad de herramientas","Utiliza comandos como `mcp__op` para recuperar documentos específicos","Permite a los desarrolladores acceder a la documentación de OpenAI Developer de manera eficiente"],"fr":["Utilise l''outil MCP pour rechercher et récupérer des documents exacts","Vérifie la disponibilité de la documentation OpenAI Developer","Exécute des commandes comme `codex mcp list` pour vérifier la disponibilité des outils","Utilise des commandes comme `mcp__op` pour récupérer des documents spécifiques","Permet aux développeurs d''accéder à la documentation OpenAI Developer de manière efficace"],"de":["Verwendet das MCP-Tool, um genaue Dokumente zu suchen und abzurufen","Überprüft die Verfügbarkeit der OpenAI-Entwicklerdokumentation","Führt Befehle wie `codex mcp list` aus, um die Verfügbarkeit von Tools zu überprüfen","Verwendet Befehle wie `mcp__op`, um spezifische Dokumente abzurufen","Ermöglicht es Entwicklern, auf die OpenAI-Entwicklerdokumentation effizient zuzugreifen"],"pt":["Utiliza o servidor MCP de documentação do OpenAI","Busca e recupera documentos exatos de desenvolvedores","Verifica a disponibilidade do servidor MCP","Executa comandos como `codex mcp list`","Utiliza ferramentas MCP para pull de documentos"],"ru":["Использует сервер MCP документации OpenAI","Ищет и извлекает точные документы для разработчиков","Проверяет доступность сервера MCP","Выполняет команды как `codex mcp list`","Использует инструменты MCP для извлечения документов"],"ar":["تستخدم خادم MCP لتوثيق OpenAI","تبحث عن واسترجع المستندات الدقيقة للمطورين","تتحقق من توافر خادم MCP","تنفذ أوامر مثل `codex mcp list`","تستخدم أدوات MCP لاسترجاع المستندات"]},"keywords":{"en":["how to use openai-knowledge","openai-knowledge setup guide","openai-knowledge alternative","openai-knowledge vs other AI skills","what is openai-knowledge","installing openai-knowledge","openai-knowledge documentation","mcp server tutorial","openai developer documentation"],"zh":["OpenAI知识","MCP服务器","文档搜索","codex mcp list","openaiDeveloperDocs","AI技能","开发者工具","信息检索"],"ja":["OpenAI Knowledge","AIエージェント","MCPサーバー","文書検索","codex mcp list","openaiDeveloperDocs","AIスキル","開発者ツール","情報検索"],"ko":["OpenAI 지식","MCP 서버","문서 검색","codex mcp list","openaiDeveloperDocs","AI 스킬","개발자 도구","정보 검색"],"es":["OpenAI Knowledge","documentación de OpenAI Developer","herramienta MCP","desarrollo de AI","agentes de AI","herramientas de desarrollo de AI","OpenAI Developer Documentation","MCP tool","AI development"],"fr":["OpenAI Knowledge","documentation OpenAI Developer","outil MCP","développement d''IA","agents d''IA","outils de développement d''IA","OpenAI Developer Documentation","MCP tool","IA development"],"de":["OpenAI Knowledge","OpenAI-Entwicklerdokumentation","MCP-Tool","Entwicklung von KI","KI-Agents","Entwicklertools für KI","OpenAI Developer Documentation","MCP-Tool","KI-Entwicklung"],"pt":["OpenAI Knowledge","Servidor MCP","Documentação do OpenAI","Desenvolvedores","Busca de documentos","Recuperação de documentos","Ferramentas MCP","Comandos CLI"],"ru":["OpenAI Knowledge","Сервер MCP","Документация OpenAI","Разработчики","Поиск документов","Извлечение документов","Инструменты MCP","Команды CLI"],"ar":["أداة المعرفة_OPENAI","خادم MCP","توثيق OpenAI","المطورين","البحث عن المستندات","استرجاع المستندات","أدوات MCP","أوامر CLI"]}},"owner":"yuichi176","repo":"artlyst","repoPath":"yuichi176/artlyst","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.381Z","topics":[],"category":"community","skillMd":{"name":"openai-knowledge","description":"Use when working with the OpenAI API (Responses API) or OpenAI platform features (tools, streaming, Realtime API, auth, models, rate limits, MCP) and you need authoritative, up-to-date documentation (schemas, examples, limits, edge cases). Prefer the OpenAI Developer Documentation MCP server tools when available; otherwise guide the user to enable `openaiDeveloperDocs`.","bodyPreview":"# OpenAI Knowledge\n\n## Overview\n\nUse the OpenAI Developer Documentation MCP server to search and fetch exact docs (markdown), then base your answer on that text instead of guessing.\n\n## Workflow\n\n### 1) Check whether the Docs MCP server is available\n\nIf the `mcp__openaiDeveloperDocs__*` tools are available, use them.\n\nIf you are unsure, run `codex mcp list` and check for `openaiDeveloperDocs`.\n\n### 2) Use MCP tools to pull exact docs\n\n- Search first, then fetch the specific page(s).\n  - `mcp__op","body":"# OpenAI Knowledge\n\n## Overview\n\nUse the OpenAI Developer Documentation MCP server to search and fetch exact docs (markdown), then base your answer on that text instead of guessing.\n\n## Workflow\n\n### 1) Check whether the Docs MCP server is available\n\nIf the `mcp__openaiDeveloperDocs__*` tools are available, use them.\n\nIf you are unsure, run `codex mcp list` and check for `openaiDeveloperDocs`.\n\n### 2) Use MCP tools to pull exact docs\n\n- Search first, then fetch the specific page(s).\n  - `mcp__openaiDeveloperDocs__search_openai_docs` → pick the best URL.\n  - `mcp__openaiDeveloperDocs__fetch_openai_doc` → retrieve the exact markdown (optionally with an `anchor`).\n- When you need endpoint schemas or parameters, use:\n  - `mcp__openaiDeveloperDocs__get_openapi_spec`\n  - `mcp__openaiDeveloperDocs__list_api_endpoints`\n\nBase your answer on the fetched text and quote or paraphrase it precisely. Do not invent flags, field names, defaults, or limits.\n\n### 3) If MCP is not configured, guide setup (do not change config unless asked)\n\nProvide one of these setup options, then ask the user to restart the Codex session so the tools load:\n\n- CLI:\n  - `codex mcp add openaiDeveloperDocs --url https://developers.openai.com/mcp`\n- Config file (`~/.codex/config.toml`):\n  - Add:\n    ```toml\n    [mcp_servers.openaiDeveloperDocs]\n    url = \"https://developers.openai.com/mcp\"\n    ```\n\nAlso point to: https://developers.openai.com/resources/docs-mcp#quickstart"},"lastSynced":"2026-03-08T02:05:39.729Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing accurate OpenAI API documentation and development resources","zh":"适合需要准确的OpenAI API文档和开发资源的AI代理","ja":"OpenAI APIの正確なドキュメントと開発リソースが必要なAIエージェントに適しています","ko":"정확한 OpenAI API 문서 및 개발 리소스가 필요한 AI 에이전트에 적합합니다","es":"Perfecto para agentes de IA que necesitan documentación y recursos de desarrollo precisos de OpenAI API","fr":"Parfait pour les agents IA nécessitant une documentation et des ressources de développement précises d''OpenAI API","de":"Perfekt für KI-Agents, die genaue OpenAI API-Dokumentation und Entwicklungsressourcen benötigen","pt":"Perfeito para Agentes de IA que necessitam de documentação precisa da API OpenAI e recursos de desenvolvimento","ru":"Идеально для агентов ИИ, которым необходима точная документация API OpenAI и ресурсы для разработки","ar":"مثالي للوكلاء الذكيين الذين يحتاجون إلى توثيق دقيق لبروتوكول OpenAI و موارد تطوير"},"recommendation":{"en":"Empowers agents to search and fetch exact OpenAI Developer Documentation using the MCP server, providing accurate information for development purposes with markdown support and reducing guesswork in API integration, leveraging tools like `mcp__openaiDeveloperDocs` and protocols","zh":"赋予代理搜索和获取精确的OpenAI开发者文档的能力，使用MCP服务器，提供准确的开发信息，并支持markdown，减少API集成中的猜测，利用像`mcp__openaiDeveloperDocs`的工具和协议","ja":"エージェントにOpenAIデベロッパードキュメントを検索して取得する機能を提供し、MCPサーバーを使用して開発目的の正確な情報を提供し、マークダウンをサポートし、API統合における推測を減らし、`mcp__openaiDeveloperDocs`のようなツールやプロトコルを利用する","ko":"에이전트가 MCP 서버를 사용하여 개발 목적의 정확한 정보를 제공하고 마크다운을 지원하며 API 통합에서 추측을 줄이고 `mcp__openaiDeveloperDocs`와 같은 도구 및 프로토콜을 활용하여 정확한 OpenAI 개발자 문서를 검색하고 가져올 수 있는 기능을 제공합니다","es":"Habilita a los agentes a buscar y recuperar la documentación exacta de OpenAI Developer utilizando el servidor MCP, proporcionando información precisa para fines de desarrollo con soporte de markdown y reduciendo el trabajo de adivinanza en la integración de API, aprovechando herramientas como `mcp__openaiDeveloperDocs` y protocolos","fr":"Permet aux agents de rechercher et de récupérer la documentation exacte d''OpenAI Developer à l''aide du serveur MCP, fournissant des informations précises à des fins de développement avec une prise en charge de markdown et réduisant le travail de devinette dans l''intégration d''API, en exploitant des outils comme `mcp__openaiDeveloperDocs` et des protocoles","de":"Ermöglicht es Agenten, die genaue OpenAI-Entwicklerdokumentation mithilfe des MCP-Servers zu suchen und abzurufen, wodurch genaue Informationen für Entwicklungs Zwecke mit Markdown-Unterstützung bereitgestellt und die Vermutungsarbeit bei der API-Integration reduziert wird, indem Tools wie `mcp__openaiDeveloperDocs` und Protokolle genutzt werden","pt":"Habilita os agentes a procurar e buscar a documentação exata do OpenAI Developer usando o servidor MCP, fornecendo informações precisas para fins de desenvolvimento com suporte a markdown e reduzindo o trabalho de adivinhação na integração da API, utilizando ferramentas como `mcp__openaiDeveloperDocs` e protocolos","ru":"Наделяет агентов возможностью искать и получать точную документацию OpenAI Developer с помощью сервера MCP, предоставляя точную информацию для целей разработки с поддержкой markdown и сокращая работу по угадыванию при интеграции API, используя инструменты как `mcp__openaiDeveloperDocs` и протоколы","ar":"تمكين الوكلاء من البحث والحصول على توثيق دقيق لبروتوكول OpenAI Developer باستخدام خادم MCP ، وتوفير معلومات دقيقة لغرض التطوير مع دعم markdown وتقليل عمل التخمين في تكامل API ، باستخدام أدوات مثل `mcp__openaiDeveloperDocs` وبروتوكولات"},"useCases":{"en":["Fetching specific OpenAI API documentation pages","Searching OpenAI Developer Documentation for development purposes","Validating API usage with exact documentation"],"zh":["获取特定的OpenAI API文档页面","搜索OpenAI开发者文档以实现开发目的","使用精确的文档验证API使用"],"ja":["特定のOpenAI APIドキュメントページを取得する","開発目的のためにOpenAIデベロッパードキュメントを検索する","正確なドキュメントを使用してAPIの使用を検証する"],"ko":["특정 OpenAI API 문서 페이지 가져오기","개발 목적으로 OpenAI 개발자 문서 검색","정확한 문서를 사용하여 API 사용 검증"],"es":["Recuperar páginas de documentación específicas de OpenAI API","Buscar la documentación de OpenAI Developer para fines de desarrollo","Validar el uso de la API con documentación exacta"],"fr":["Récupérer des pages de documentation spécifiques d''OpenAI API","Rechercher la documentation d''OpenAI Developer pour des fins de développement","Valider l''utilisation de l''API avec une documentation exacte"],"de":["Abrufen spezifischer OpenAI API-Dokumentationsseiten","Suchen der OpenAI-Entwicklerdokumentation für Entwicklungs Zwecke","Validieren der API-Nutzung mit genauer Dokumentation"],"pt":["Buscar páginas de documentação específicas da API OpenAI","Procurar documentação do OpenAI Developer para fins de desenvolvimento","Validar uso da API com documentação exata"],"ru":["Получение конкретных страниц документации API OpenAI","Поиск документации OpenAI Developer для целей разработки","Проверка использования API с точной документацией"],"ar":["البحث عن صفحات توثيق محددة لبروتوكول OpenAI","البحث عن توثيق بروتوكول OpenAI Developer لغرض التطوير","التحقق من استخدام بروتوكول API مع توثيق دقيق"]},"limitations":{"en":["Requires availability of `mcp__openaiDeveloperDocs` tools","Dependent on MCP server accessibility"],"zh":["需要`mcp__openaiDeveloperDocs`工具可用","依赖MCP服务器的可访问性"],"ja":["`mcp__openaiDeveloperDocs`ツールの可用性が必要","MCPサーバーの可達性に依存する"],"ko":["`mcp__openaiDeveloperDocs` 도구 가용성이 필요","MCP 서버의 접근 가능성에 의존"],"es":["Requiere la disponibilidad de herramientas `mcp__openaiDeveloperDocs`","Depende de la accesibilidad del servidor MCP"],"fr":["Nécessite la disponibilité d''outils `mcp__openaiDeveloperDocs`","Dépend de l''accessibilité du serveur MCP"],"de":["Erfordert die Verfügbarkeit von Tools `mcp__openaiDeveloperDocs`","Hängt von der Erreichbarkeit des MCP-Servers ab"],"pt":["Requer a disponibilidade de ferramentas `mcp__openaiDeveloperDocs`","Dependente da acessibilidade do servidor MCP"],"ru":["Требует наличия инструментов `mcp__openaiDeveloperDocs`","Зависит от доступности сервера MCP"],"ar":["يتطلب توافر أدوات `mcp__openaiDeveloperDocs`","يعتمد على إمكانية الوصول إلى خادم MCP"]},"version":4},"contentHash":"c8593bb84c584924e654df22aed6334018fb070905298eb7a1606a10d38c8fda","qualityScore":39}');
