INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yuichi176/artlyst/openai-knowledge', 'openai-knowledge', 'yuichi176', 'artlyst', 'community', 'openai-knowledge yuichi176 artlyst community The openai-knowledge skill enables AI agents to search and fetch exact documentation from the OpenAI Developer Documentation MCP server, providing accurate information for development purposes. This skill benefits developers working with OpenAI APIs. OpenAI知识是使用MCP服务器搜索和获取精确文档的技能，帮助开发者快速找到所需信息 OpenAI Knowledgeは、AIエージェントとMCPサーバー検索を使用して正確な文書を取得する技能です OpenAI 지식은 MCP 서버 검색과 문서를 사용하여 정확한 정보를 얻는技能입니다 OpenAI Knowledge permite a los desarrolladores buscar y recuperar documentos exactos de la documentación de OpenAI Developer utilizando la herramienta MCP. OpenAI Knowledge permet aux développeurs de rechercher et de récupérer des documents exacts de la documentation OpenAI Developer à l''aide de l''outil MCP. OpenAI Knowledge ermöglicht es Entwicklern, genaue Dokumente aus der OpenAI-Entwicklerdokumentation mithilfe des MCP-Tools zu suchen und abzurufen. O OpenAI Knowledge é uma habilidade que utiliza o servidor MCP de documentação do OpenAI para buscar e recuperar documentos exatos. OpenAI Knowledge — это навык, который использует сервер MCP документации OpenAI для поиска и извлечения точных документов. أداة المعرفة_OPENAI هي ميزة تستخدم خادم MCP لتوثيق OpenAI للبحث عن واسترجاع المستندات الدقيقة. how to use openai-knowledge openai-knowledge setup guide openai-knowledge alternative openai-knowledge vs other AI skills what is openai-knowledge installing openai-knowledge openai-knowledge documentation mcp server tutorial openai developer documentation OpenAI知识 MCP服务器 文档搜索 codex mcp list openaiDeveloperDocs AI技能 开发者工具 信息检索 Searches for specific documentation using the MCP server Fetches exact docs in markdown format Checks availability of the MCP server using the `codex mcp list` command Utilizes the `mcp__openaiDeveloperDocs` tool for documentation retrieval Follows a structured workflow for efficient documentation search and retrieval openai-knowledge is a skill that utilizes the OpenAI Developer Documentation MCP server to retrieve exact documentation, enabling AI agents to provide accurate and reliable information.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('go-go-golems/geppetto/inference-smoke-tests', 'community', 'go-go-golems', 'geppetto', 'go-go-golems/geppetto', 'inference-smoke-tests', 0, 0, 39, '2026-03-08T01:57:15.383Z', '2026-03-08T02:05:42.288Z', 'b1e5a1a2e041efb51c0f42d3de84ed0a0b33dfd8ad0b1b5cd7c81bececb9dc1a', '{"id":"go-go-golems/geppetto/inference-smoke-tests","name":"inference-smoke-tests","description":{"en":"The inference-smoke-tests skill provides a golang GPT3 tooling solution for running smoke tests. It benefits developers by offering a quick start guide and manual checklist for test execution.","zh":"Inference Smoke Tests 是一个 Golang GPT3 工具，用于运行快速测试套件和手动检查清单","ja":"Inference Smoke Tests は Golang GPT3 ツールであり、高速テストスイートと手動チェックリストを実行するために使用されます","ko":"Inference Smoke Tests는 Golang GPT3 도구로 빠른 테스트 세트와 수동 체크리스트를 실행하는 데 사용됩니다","es":"Inference-smoke-tests es una herramienta de GPT3 que permite a los desarrolladores probar y validar la inferencia de modelos de lenguaje","fr":"Les tests de fumée d''inference sont un outil GPT3 qui permet aux développeurs de tester et de valider l''inférence des modèles de langage","de":"Inference-smoke-tests ist ein GPT3-Tool, das es Entwicklern ermöglicht, die Inferenz von Sprachmodellen zu testen und zu überprüfen","pt":"O skill de inference-smoke-tests fornece uma solução para testar a inferência com ferramentas de Golang GPT3. Execute testes rápidos e eficientes com o script run_smoke.sh","ru":"Навык inference-smoke-tests предоставляет решение для тестирования вывода с помощью инструментов Golang GPT3 и ИИ Агентов. Запустите быстрые и эффективные тесты с помощью скрипта run_smoke.sh","ar":"المهارة اختبارات الدخان للاستدلال توفر حلًا لاختبار الاستدلال مع أدوات Golang GPT3 ووكلاء الذكاء الاصطناعي. تشغيل اختبارات سريعة وفعالة مع سكريبت run_smoke.sh"},"seo":{"title":{"en":"inference-smoke-tests: Golang GPT3 Tooling Setup Guide | ...","zh":"Inference Smoke Tests 设置指南 - Golang GPT3 工具","ja":"Inference Smoke Tests セットアップガイド - Golang GPT3 ツール","ko":"Inference Smoke Tests 설정 가이드 - Golang GPT3 도구","es":"Guía de configuración de inference-smoke-tests para herra...","fr":"Guide de configuration des tests de fumée d''inference pou...","de":"Einrichtungsleitfaden für inference-smoke-tests in AI-Tools","pt":"Guia de Configuração para Inference Smoke Tests com Ferra...","ru":"Руководство по настройке Inference Smoke Tests с использо...","ar":"دليل إعداد اختبارات الدخان للاستدلال مع أدوات Golang GPT3..."},"description":{"en":"Discover how to run inference smoke tests with golang GPT3 tooling. Learn to set up and execute tests with the bundled script and optimize your workflow today!","zh":"了解如何设置和运行 Inference Smoke Tests，包括 Golang GPT3 工具和 OpenAI API 密钥的使用","ja":"Inference Smoke Tests の設定と実行方法を学ぶ、Golang GPT3 ツールと OpenAI API キーの使用を含む","ko":"Inference Smoke Tests 설정과 실행 방법을 알아보세요. Golang GPT3 도구와 OpenAI API 키 사용을 포함합니다","es":"Aprende a configurar inference-smoke-tests con GPT3 y herramientas de Go para desarrolladores","fr":"Découvrez comment configurer les tests de fumée d''inference avec GPT3 et les outils Go pour les développeurs","de":"Erfahren Sie, wie Sie inference-smoke-tests mit GPT3 und Go-Tools für Entwickler konfigurieren","pt":"Aprenda a configurar e executar testes de inference smoke com o skill de inference-smoke-tests e ferramentas de Golang GPT3 para melhorar a eficiência do seu...","ru":"Узнайте, как настроить и запустить тесты inference smoke с помощью навыка inference-smoke-tests и инструментов Golang GPT3 для улучшения эффективности вашего...","ar":"تعرف على كيفية إعداد وتشغيل اختبارات الدخان للاستدلال باستخدام مهارة اختبارات الدخان للاستدلال وأدوات Golang GPT3 لتحسين كفاءة تطوير البرمجيات مع وكلاء الذكا..."},"definition":{"en":"inference-smoke-tests is a golang GPT3 tooling skill that enables running smoke tests via a bundled script and supports OpenAI and Claude credentials","zh":"Inference Smoke Tests 是一种用于验证 AI 模型的快速测试方法，使用 Golang GPT3 工具","ja":"Inference Smoke Tests は、Golang GPT3 ツールを使用して AI モデルを検証するための高速テスト方法である","ko":"Inference Smoke Tests는 Golang GPT3 도구를 사용하여 AI 모델을 검증하는 빠른 테스트 방법입니다","es":"Inference-smoke-tests es un conjunto de pruebas para validar la inferencia de modelos de lenguaje con GPT3","fr":"Les tests de fumée d''inference sont un ensemble de tests pour valider l''inférence des modèles de langage avec GPT3","de":"Inference-smoke-tests sind eine Reihe von Tests zur Überprüfung der Inferenz von Sprachmodellen mit GPT3","pt":"Inference smoke tests são testes rápidos que verificam a integridade da inferência com ferramentas de Golang GPT3","ru":"Тесты inference smoke — это быстрые тесты, проверяющие целостность вывода с помощью инструментов Golang GPT3 и ИИ Агентов","ar":"اختبارات الدخان للاستدلال هي اختبارات سريعة تتحقق من سلامة الاستدلال مع أدوات Golang GPT3 ووكلاء الذكاء الاصطناعي"},"features":{"en":["Runs the fast suite via the bundled script using geppetto/.codex/skills/inference-smoke-tests/scripts/run_smoke.sh","Supports OpenAI API key and Claude credentials for authentication","Provides a manual checklist in playbook.md for test execution","Utilizes geppetto non-TUI and pinocchio agent TUI for test runs","Requires OPENAI_API_KEY and ANTHROPIC_API credentials for setup"],"zh":["支持 Golang GPT3 工具","使用 OpenAI API 密钥","包含快速测试套件","支持手动检查清单","需要 Claude 凭证","支持 bash 脚本运行"],"ja":["Golang GPT3 ツールをサポート","OpenAI API キーを使用","高速テストスイートを含む","手動チェックリストをサポート","Claude 資格情報が必要","bash スクリプトの実行をサポート"],"ko":["Golang GPT3 도구를 지원","OpenAI API 키를 사용","빠른 테스트 세트를 포함","수동 체크리스트를 지원","Claude 자격 증명이 필요","bash 스크립트 실행을 지원"],"es":["Soporte para GPT3 y herramientas de Go","Pruebas de fumée para validar la inferencia de modelos de lenguaje","Compatibilidad con OpenAI Chat y OpenAI Responses","Credenciales de Claude disponibles para una mayor funcionalidad","Script de inicio rápido para una implementación sencilla"],"fr":["Prise en charge de GPT3 et des outils Go","Tests de fumée pour valider l''inférence des modèles de langage","Compatibilité avec OpenAI Chat et OpenAI Responses","Informations d''identification de Claude disponibles pour une fonctionnalité étendue","Script de démarrage rapide pour une mise en œuvre simple"],"de":["Unterstützung für GPT3 und Go-Tools","Rauchtests zur Überprüfung der Inferenz von Sprachmodellen","Kompatibilität mit OpenAI Chat und OpenAI Responses","Claude-Anmeldeinformationen verfügbar für erweiterte Funktionalität","Schnellstart-Script für eine einfache Implementierung"],"pt":["Execução de testes rápidos com script run_smoke.sh","Suporte a ferramentas de Golang GPT3","Integração com OpenAI API e Claude credentials","Compatibilidade com geppetto e pinocchio agent TUI"],"ru":["Запуск быстрых тестов с помощью скрипта run_smoke.sh","Поддержка инструментов Golang GPT3 и ИИ Агентов","Интеграция с OpenAI API и учетными данными Claude","Совместимость с geppetto и pinocchio agent TUI"],"ar":["تشغيل اختبارات سريعة مع سكريبت run_smoke.sh","دعم أدوات Golang GPT3 ووكلاء الذكاء الاصطناعي","التكامل مع OpenAI API وبيانات اعتماد Claude","التوافق مع geppetto و pinocchio agent TUI"]},"keywords":{"en":["how to use inference-smoke-tests","inference-smoke-tests setup guide","golang GPT3 tooling","inference-smoke-tests alternative","inference-smoke-tests vs gpt3 tooling","running smoke tests with golang","OpenAI API key setup","inference-smoke-tests install"],"zh":["Inference Smoke Tests","Golang GPT3","OpenAI API","AI 模型验证","快速测试","手动检查清单","Claude 凭证","bash 脚本","AI 工具","AI エージェント"],"ja":["Inference Smoke Tests","Golang GPT3","OpenAI API","AI モデル検証","高速テスト","手動チェックリスト","Claude 資格情報","bash スクリプト","AI ツール","AI エージェント"],"ko":["Inference Smoke Tests","Golang GPT3","OpenAI API","AI 모델 검증","빠른 테스트","수동 체크리스트","Claude 자격 증명","bash 스크립트","AI 도구","AI 에이전트"],"es":["inference-smoke-tests","herramientas de AI","GPT3","Go","OpenAI Chat","OpenAI Responses","pruebas de fumée","validación de inferencia","desarrollo de modelos de lenguaje"],"fr":["tests de fumée d''inference","outils d''IA","GPT3","Go","OpenAI Chat","OpenAI Responses","tests de fumée","validation de l''inférence","développement de modèles de langage"],"de":["inference-smoke-tests","AI-Tools","GPT3","Go","OpenAI Chat","OpenAI Responses","Rauchtests","Inferenz-Überprüfung","Sprachmodell-Entwicklung"],"pt":["inference smoke tests","Golang GPT3","testes de inferência","ferramentas de desenvolvimento de software","OpenAI API","Claude credentials","geppetto","pinocchio agent TUI"],"ru":["тесты inference smoke","Golang GPT3","ИИ Агенты","инструменты разработки программного обеспечения","OpenAI API","учетные данные Claude","geppetto","pinocchio agent TUI"],"ar":["اختبارات الدخان للاستدلال","Golang GPT3","وكلاء الذكاء الاصطناعي","أدوات تطوير البرمجيات","OpenAI API","بيانات اعتماد Claude","geppetto","pinocchio agent TUI"]}},"owner":"go-go-golems","repo":"geppetto","repoPath":"go-go-golems/geppetto","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.383Z","topics":[],"category":"community","skillMd":{"name":"inference-smoke-tests","description":"Run repeatable inference smoke tests using geppetto/pinocchio example binaries (single-pass, streaming, tool-loop, OpenAI Responses thinking) including tmux-driven TUI tests. Use when refactors touch InferenceState/Session/EngineBuilder, tool calling loop, event sinks, provider request formatting, or when you need a quick does inference still work? checklist.","bodyPreview":"# Inference Smoke Tests\n\n## Quick Start (Recommended)\n\nRun the fast suite (geppetto non-TUI + pinocchio agent TUI) via the bundled script:\n\n```bash\nbash geppetto/.codex/skills/inference-smoke-tests/scripts/run_smoke.sh --quick\n```\n\nIf you need the full manual checklist, open:\n\n`geppetto/.codex/skills/inference-smoke-tests/references/playbook.md`\n\n## Preconditions\n\n- Ensure `OPENAI_API_KEY` is set (for OpenAI Chat + OpenAI Responses).\n- Ensure Claude credentials are available (e.g. `ANTHROPIC_API","body":"# Inference Smoke Tests\n\n## Quick Start (Recommended)\n\nRun the fast suite (geppetto non-TUI + pinocchio agent TUI) via the bundled script:\n\n```bash\nbash geppetto/.codex/skills/inference-smoke-tests/scripts/run_smoke.sh --quick\n```\n\nIf you need the full manual checklist, open:\n\n`geppetto/.codex/skills/inference-smoke-tests/references/playbook.md`\n\n## Preconditions\n\n- Ensure `OPENAI_API_KEY` is set (for OpenAI Chat + OpenAI Responses).\n- Ensure Claude credentials are available (e.g. `ANTHROPIC_API_KEY`) if you want the Claude tool-calling smoke step to pass.\n- Ensure `tmux` is installed (required for non-interactive TUI runs).\n- Expect costs: these tests make real API calls.\n\n## Workflow Decision Tree\n\n1) Validate provider “thinking” streaming (Responses)?\n- Run `geppetto/cmd/examples/openai-tools` in `--mode thinking`.\n\n2) Validate tool loop orchestration?\n- Run `geppetto/cmd/examples/generic-tool-calling`.\n\n3) Validate Bubble Tea TUI event flow (thinking deltas + final)?\n- Run `pinocchio/cmd/agents/simple-chat-agent` in tmux.\n\n4) Validate Claude tool calling?\n- Run `geppetto/cmd/examples/claude-tools` with `--ai-api-type claude --ai-engine claude-haiku-4-5`.\n\n5) Validate multi-turn chat state persistence?\n- Run pinocchio TUI chat in tmux (manual) and/or pinocchio webchat in browser (manual).\n\n## What “Benefits From InferenceState” (Rules of Thumb)\n\nAlready benefits (multi-turn, cancel-sensitive, tool-loop, strict provider validation):\n- pinocchio TUI chat (`pinocchio/cmd/pinocchio … --chat`)\n- pinocchio agent TUI (`pinocchio/cmd/agents/simple-chat-agent …`)\n- pinocchio webchat (`pinocchio/cmd/web-chat`)\n- geppetto example runners that execute via `geppetto/pkg/inference/core.Session`\n\nCould benefit (optional; mainly consistency/cancel):\n- `pinocchio/cmd/examples/simple-redis-streaming-inference` (transport-focused; currently `eng.RunInference` direct)\n- `pinocchio/cmd/examples/simple-chat` (exercises PinocchioCommand runner; could benefit indirectly if that runner standardizes on `InferenceState`)\n\nDoes not apply (not an inference runner):\n- `geppetto/cmd/examples/citations-event-stream`\n\n## Troubleshooting (Common Failure Modes)\n\n### “OpenAI Responses 400” errors\n- Re-run with higher logging:\n  - Add `--log-level debug --with-caller` where supported.\n- Confirm you’re using the correct provider mode:\n  - `--ai-api-type openai-responses`\n- If the error mentions invalid parameter support (e.g., `temperature` unsupported), it’s model-dependent; reduce parameters and retry.\n\n### TUI doesn’t submit the prompt\n- Some TUIs submit on `Tab` (not `Enter`).\n- Always capture logs to a file and confirm inference actually ran (look for `EventPartialCompletionStart`, `EventFinal`).\n\n## References\n\nWhen you need copy/paste commands for the full sweep, read:\n- `geppetto/.codex/skills/inference-smoke-tests/references/playbook.md`\n\nWhen you need to find new example entry points, search:\n\n```bash\nrg -n \"cmd/examples\" -S geppetto/cmd/examples pinocchio/cmd/examples\nrg -n \"cmd/agents\" -S pinocchio/cmd/agents\n```\n"},"lastSynced":"2026-03-08T02:05:42.288Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code requiring streamlined inference smoke testing with GPT3 tooling","zh":"适合像 Cursor、Windsurf 和 Claude Code 这样的 AI Agents，它们需要使用 GPT3 工具进行简化的推理烟雾测试","ja":"Cursor、Windsurf、Claude Code などの AI エージェントに最適で、GPT3 ツールを使用した推論の煙霧テストをストリームライン化する必要があります","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합하며 GPT3 툴을 사용하여 推論의 연기 테스트를 간소화해야 함","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que requieren pruebas de humo de inferencia optimizadas con herramientas GPT3","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant des tests de fumée d''inférence rationalisés avec des outils GPT3","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die eine optimierte Inferenz-Rauchtestung mit GPT3-Tooling erfordern","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que exigem testes de fumaça de inferência otimizados com ferramentas GPT3","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих оптимизированного тестирования дымовых испытаний с инструментами GPT3","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code التي تتطلب اختبارات الدخان الاستدلال المُoptim化ة مع أدوات GPT3"},"recommendation":{"en":"Empowers agents to run comprehensive smoke tests via a bundled script, utilizing Geppetto and Pinocchio agent TUI, while leveraging OpenAI API and Claude credentials for seamless execution, supporting protocols like bash scripting and markdown references","zh":"赋予代理运行通过捆绑脚本进行全面烟雾测试的能力，利用 Geppetto 和 Pinocchio 代理 TUI，同时利用 OpenAI API 和 Claude 凭证实现无缝执行，支持诸如 bash 脚本和 markdown 引用的协议","ja":"エージェントがバンドルされたスクリプトを使用して包括的な煙霧テストを実行できるようにし、Geppetto と Pinocchio エージェント TUI を利用し、OpenAI API と Claude の資格情報を使用してシームレスに実行します。bash スクリプティングや markdown 参照などのプロトコルもサポートします","ko":"에이전트가 comprehensive한 연기 테스트를 실행할 수 있도록하며, Geppetto와 Pinocchio 에이전트 TUI를 사용하며, OpenAI API와 Claude 자격 증명을 사용하여無斷으로 실행되며, bash 스크립트 및 markdown 참조와 같은 프로토콜을 지원함","es":"Permite a los agentes ejecutar pruebas de humo comprehensivas a través de un script empaquetado, utilizando Geppetto y Pinocchio agent TUI, aprovechando OpenAI API y credenciales de Claude para una ejecución sin problemas, soportando protocolos como scripting bash y referencias markdown","fr":"Permet aux agents d''exécuter des tests de fumée complets via un script bundle, en utilisant Geppetto et Pinocchio agent TUI, en exploitant OpenAI API et les informations d''identification de Claude pour une exécution sans problème, en prenant en charge des protocoles tels que le scripting bash et les références markdown","de":"Ermöglicht es Agents, umfassende Rauchtests über ein gebündeltes Skript durchzuführen, wobei Geppetto und Pinocchio Agent TUI verwendet werden, OpenAI API und Claude-Anmeldeinformationen für eine reibungslose Ausführung nutzt und Protokolle wie bash-Scripting und markdown-Verweise unterstützt","pt":"Habilita os agentes a executar testes de fumaça abrangentes por meio de um script empacotado, utilizando Geppetto e Pinocchio agente TUI, ao mesmo tempo em que aproveita a OpenAI API e credenciais Claude para execução sem problemas, suportando protocolos como script de bash e referências de markdown","ru":"Наделяет агентов возможностью выполнять комплексные тесты дымовых испытаний через пакетный скрипт, использующий Geppetto и Pinocchio агент TUI, а также использует OpenAI API и учетные данные Claude для бесперебойного выполнения, поддерживая протоколы, такие как скрипты bash и ссылки markdown","ar":"تمكّن الوكلاء من تشغيل اختبارات الدخان الشاملة من خلال سكربت معبأ، مستخدمًا Geppetto و Pinocchio وكلاء TUI، في نفس الوقت الذي يستفيد من OpenAI API وأرصدة Claude للتنفيذ السلس، يدعم بروتوكولات مثل البرمجة النصية bash والإشارات المرجعية markdown"},"useCases":{"en":["Automating inference smoke tests with Geppetto","Debugging Pinocchio agent TUI integrations","Validating OpenAI API key setups"],"zh":["使用 Geppetto 自动化推理烟雾测试","调试 Pinocchio 代理 TUI 集成","验证 OpenAI API 密钥设置"],"ja":["Geppetto を使用して推論の煙霧テストを自動化する","Pinocchio エージェント TUI の統合をデバッグする","OpenAI API キーの設定を検証する"],"ko":["Geppetto를 사용하여 推論의 연기 테스트를 자동화함","Pinocchio 에이전트 TUI 통합을 디버깅함","OpenAI API 키 설정을 검증함"],"es":["Automatizar pruebas de humo de inferencia con Geppetto","Depurar integraciones de Pinocchio agent TUI","Validar configuraciones de claves de API de OpenAI"],"fr":["Automatiser les tests de fumée d''inférence avec Geppetto","Déboguer les intégrations de Pinocchio agent TUI","Valider les configurations de clés API OpenAI"],"de":["Automatisierung von Inferenz-Rauchtests mit Geppetto","Fehlerbehebung bei Pinocchio Agent TUI-Integrationen","Validierung von OpenAI API-Schlüsselkonfigurationen"],"pt":["Automatizar testes de fumaça de inferência com Geppetto","Depurar integrações de agente TUI Pinocchio","Validar configurações de chave de API OpenAI"],"ru":["Автоматизировать тесты дымовых испытаний с помощью Geppetto","Отладить интеграции агента TUI Pinocchio","Проверить настройки ключа API OpenAI"],"ar":["تأتميم اختبارات الدخان الاستدلال مع Geppetto","تصحيح أخطاء دمج وكلاء TUI Pinocchio"," التحقق من إعدادات مفتاح API OpenAI"]},"limitations":{"en":["Requires OpenAI API Key","Needs Claude credentials","Dependent on bash scripting and markdown format compatibility"],"zh":["需要 OpenAI API 密钥","需要 Claude 凭证","依赖于 bash 脚本和 markdown 格式的兼容性"],"ja":["OpenAI API キーが必要","Claude の資格情報が必要","bash スクリプティングと markdown 形式の互換性に依存"],"ko":["OpenAI API 키가 필요함","Claude 자격 증명이 필요함","bash 스크립트 및 markdown 형식의 호환성에 의존함"],"es":["Requiere clave de API de OpenAI","Necesita credenciales de Claude","Dependiente de la compatibilidad de scripting bash y formato markdown"],"fr":["Nécessite une clé API OpenAI","Nécessite des informations d''identification de Claude","Dépend de la compatibilité du scripting bash et du format markdown"],"de":["Benötigt OpenAI API-Schlüssel","Benötigt Claude-Anmeldeinformationen","Abhängig von der Kompatibilität von bash-Scripting und markdown-Format"],"pt":["Exige Chave de API OpenAI","Necessita de credenciais Claude","Dependente da compatibilidade de formatação de script de bash e markdown"],"ru":["Требует ключ API OpenAI","Требует учетных данных Claude","Зависит от совместимости форматирования скриптов bash и markdown"],"ar":["يتطلب مفتاح API OpenAI","يحتاج إلى أرصدة Claude","يعتمد على توافق تنسيق البرمجة النصية bash والإشارات المرجعية markdown"]},"version":4},"contentHash":"b1e5a1a2e041efb51c0f42d3de84ed0a0b33dfd8ad0b1b5cd7c81bececb9dc1a","qualityScore":39}');
