INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('go-go-golems/geppetto/inference-smoke-tests', 'inference-smoke-tests', 'go-go-golems', 'geppetto', 'community', 'inference-smoke-tests go-go-golems geppetto community The inference-smoke-tests skill provides a golang GPT3 tooling solution for running smoke tests. It benefits developers by offering a quick start guide and manual checklist for test execution. Inference Smoke Tests 是一个 Golang GPT3 工具，用于运行快速测试套件和手动检查清单 Inference Smoke Tests は Golang GPT3 ツールであり、高速テストスイートと手動チェックリストを実行するために使用されます Inference Smoke Tests는 Golang GPT3 도구로 빠른 테스트 세트와 수동 체크리스트를 실행하는 데 사용됩니다 Inference-smoke-tests es una herramienta de GPT3 que permite a los desarrolladores probar y validar la inferencia de modelos de lenguaje Les tests de fumée d''inference sont un outil GPT3 qui permet aux développeurs de tester et de valider l''inférence des modèles de langage Inference-smoke-tests ist ein GPT3-Tool, das es Entwicklern ermöglicht, die Inferenz von Sprachmodellen zu testen und zu überprüfen O skill de inference-smoke-tests fornece uma solução para testar a inferência com ferramentas de Golang GPT3. Execute testes rápidos e eficientes com o script run_smoke.sh Навык inference-smoke-tests предоставляет решение для тестирования вывода с помощью инструментов Golang GPT3 и ИИ Агентов. Запустите быстрые и эффективные тесты с помощью скрипта run_smoke.sh المهارة اختبارات الدخان للاستدلال توفر حلًا لاختبار الاستدلال مع أدوات Golang GPT3 ووكلاء الذكاء الاصطناعي. تشغيل اختبارات سريعة وفعالة مع سكريبت run_smoke.sh how to use inference-smoke-tests inference-smoke-tests setup guide golang GPT3 tooling inference-smoke-tests alternative inference-smoke-tests vs gpt3 tooling running smoke tests with golang OpenAI API key setup inference-smoke-tests install Inference Smoke Tests Golang GPT3 OpenAI API AI 模型验证 快速测试 手动检查清单 Claude 凭证 bash 脚本 AI 工具 AI エージェント Runs the fast suite via the bundled script using geppetto/.codex/skills/inference-smoke-tests/scripts/run_smoke.sh Supports OpenAI API key and Claude credentials for authentication Provides a manual checklist in playbook.md for test execution Utilizes geppetto non-TUI and pinocchio agent TUI for test runs Requires OPENAI_API_KEY and ANTHROPIC_API credentials for setup inference-smoke-tests is a golang GPT3 tooling skill that enables running smoke tests via a bundled script and supports OpenAI and Claude credentials');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('semanticdreams/space/git-commit', 'community', 'semanticdreams', 'space', 'semanticdreams/space', 'git-commit', 0, 0, 39, '2026-03-08T01:57:15.386Z', '2026-03-08T02:05:52.126Z', '43edc8255e370ef823462ebce448eea65d663c2135801e716e498aa78eceeecf', '{"id":"semanticdreams/space/git-commit","name":"git-commit","description":{"en":"The git-commit skill helps developers manage their Git workflow by verifying change sets and staging code safely. It benefits developers working with Git repositories.","zh":"Git Commit 消息是版本控制的重要部分，本指南将帮助您了解如何编写高质量的 Commit 消息","ja":"Git Commit メッセージはバージョン管理の重要な部分です。このガイドでは、高品質の Commit メッセージの作成方法について説明します","ko":"Git Commit 메시지는 버전 관리의 중요한 부분입니다. 이 가이드에서는 높은 품질의 Commit 메시지를 작성하는 방법에 대해 설명합니다","es":"Git-commit es una herramienta fundamental para los desarrolladores. Nuestra guía cubre las mejores prácticas para su uso efectivo.","fr":"Git-commit est un outil essentiel pour les développeurs. Notre guide présente les meilleures pratiques pour son utilisation efficace.","de":"Git-commit ist ein grundlegendes Werkzeug für Entwickler. Unser Leitfaden deckt die besten Praktiken für seine effektive Nutzung ab.","pt":"O Git Commit é uma ferramenta essencial para desenvolvedores, permitindo a criação de commits seguros e eficazes","ru":"Git Commit - это важнейший инструмент для разработчиков, позволяющий создавать безопасные и эффективные коммиты с помощью ИИ Агентов","ar":"Git Commit هو أداة أساسية للمطورين، تمكن من إنشاء Commitات آمنة وفعالة باستخدام الآليات الذكية"},"seo":{"title":{"en":"git-commit: Best Practices for AI Agents | AI Agent Skill","zh":"Git Commit 消息最佳实践指南","ja":"Git Commit メッセージの設定方法","ko":"Git Commit 메시지 작성 가이드","es":"Guía de configuración de git-commit para desarrolladores","fr":"Meilleures pratiques pour git-commit dans le développement","de":"Einrichtungsleitfaden für git-commit in der Softwareentwi...","pt":"Guia de Configuração do Git Commit","ru":"Настройка Git Commit: Лучшие Практики","ar":"إعداد Git Commit: دليل المستخدم"},"description":{"en":"Learn how to use git-commit effectively with our expert guide. Discover tips and tricks for verifying change sets and staging code safely.","zh":"学习 Git Commit 消息的最佳实践，包括验证更改集、分阶段提交和避免提交秘密","ja":"Git Commit メッセージのベストプラクティスを学び、変更セットの検証、ステージングのコミット、秘密のコミットの回避について学ぶ","ko":"Git Commit 메시지의最佳实践을学습하고 변경セット 검증, 스테이징 커밋, 비밀 커밋 회피에 대해 학습합니다","es":"Aprende a utilizar git-commit de manera efectiva con nuestra guía de mejores prácticas para desarrolladores de software","fr":"Découvrez comment utiliser git-commit pour améliorer votre flux de travail de développement avec nos conseils et astuces","de":"Erfahren Sie, wie Sie git-commit optimal in Ihrem Softwareentwicklungsprozess einsetzen können, mit unseren Tipps und Best Practices","pt":"Aprenda a usar o Git Commit de forma eficaz com nosso guia passo a passo, incluindo dicas de segurança e boas práticas","ru":"Узнайте, как настроить Git Commit с помощью нашего пошагового руководства, включая советы по безопасности и лучшие практики для ИИ Агентов","ar":"تعلم كيفية إعداد Git Commit بفعالية مع دليلنا الخطوة خطوة، بما في ذلك نصائح الأمان وأفضل الممارسات للآليات الذكية"},"definition":{"en":"git-commit is a novel computing interface that assists with creating commit messages and managing Git workflows.","zh":"Git Commit 消息是 Git 中用于描述更改的文本","ja":"Git Commit メッセージは Git で変更を説明するために使用されるテキストです","ko":"Git Commit 메시지는 Git에서 변경을 설명하는 데 사용되는 텍스트입니다","es":"Git-commit es una función que permite a los desarrolladores confirmar cambios en su código de manera segura y organizada","fr":"Git-commit est une fonctionnalité qui permet aux développeurs de valider des modifications dans leur code de manière sécurisée et organisée","de":"Git-commit ist eine Funktion, die es Entwicklern ermöglicht, Änderungen in ihrem Code auf sichere und organisierte Weise zu bestätigen","pt":"O que é Git Commit? É uma ferramenta de controle de versão que permite criar commits com segurança e eficácia","ru":"Что такое Git Commit? Это инструмент контроля версий, позволяющий создавать коммиты с безопасностью и эффективностью для ИИ Агентов","ar":"ما هو Git Commit? هو أداة تحكم بالإصدارات تمكن من إنشاء Commitات بأمان وفعالية باستخدام الآليات الذكية"},"features":{"en":["Verifies change sets using git status, git diff, and git diff --staged","Stages code safely with git add -p for mixed diffs","Detects secrets and credentials in commit messages using rg -n -i","Prevents accidental commits of sensitive information","Supports Git workflow best practices"],"zh":["验证更改集使用 `git status` 和 `git diff`","分阶段提交使用 `git add -p`","避免提交秘密和凭证","使用 `git diff --staged` 检查分阶段的更改","使用正则表达式搜索秘密和凭证","支持多种 Git 命令"],"ja":["変更セットの検証に `git status` と `git diff` を使用","ステージングのコミットに `git add -p` を使用","秘密と資格情報のコミットを避ける","ステージングされた変更を `git diff --staged` で確認","正規表現を使用して秘密と資格情報を検索","複数の Git コマンドをサポート"],"ko":["변경セット 검증을 위해 `git status`와 `git diff`를 사용","스테이징 커밋을 위해 `git add -p`를 사용","비밀과 자격증명의 커밋을 피함","스테이징된 변경을 `git diff --staged`로 확인","정규식을 사용하여 비밀과 자격증명을 검색","여러 Git 명령어 지원"],"es":["Verificación del conjunto de cambios con `git status` y `git diff`","Etapa solo lo que se desea enviar con `git add -p`","Evitación de la confirmación de secretos y credenciales","Uso de `git diff --staged` para revisar los cambios antes de la confirmación","Detección de secretos en el conjunto de cambios con `git diff --staged | rg -n -i`"],"fr":["Vérification de l''ensemble des modifications avec `git status` et `git diff`","Staging uniquement ce que vous souhaitez envoyer avec `git add -p`","Évitement de la validation des secrets et des informations d''identification","Utilisation de `git diff --staged` pour examiner les modifications avant la validation","Détection des secrets dans l''ensemble des modifications avec `git diff --staged | rg -n -i`"],"de":["Überprüfung des Änderungssatzes mit `git status` und `git diff`","Staging nur dessen, was Sie senden möchten, mit `git add -p`","Vermeidung der Bestätigung von Geheimnissen und Anmeldeinformationen","Verwendung von `git diff --staged` zur Überprüfung der Änderungen vor der Bestätigung","Erkennung von Geheimnissen im Änderungssatz mit `git diff --staged | rg -n -i`"],"pt":["Verificação do conjunto de alterações com `git status`","Uso de `git add -p` para diffs mistos","Evitar a commit de segredos e credenciais","Uso de `git diff --staged` para verificar as alterações","Integração com ferramentas de desenvolvimento como CLI"],"ru":["Проверка набора изменений с помощью `git status`","Использование `git add -p` для смешанных диффов","Избегание коммита секретов и учетных данных","Использование `git diff --staged` для проверки изменений","Интеграция с инструментами разработки, такими как CLI, для ИИ Агентов"],"ar":["التحقق من مجموعة التغييرات باستخدام `git status`","استخدام `git add -p` لDIFFs المخلوطة","تجنب Commit السرية والاعتمادات","استخدام `git diff --staged` للتحقق من التغييرات","التكامل مع أدوات التطوير مثل CLI للآليات الذكية"]},"keywords":{"en":["how to use git-commit","git-commit best practices","git-commit alternative","git-commit vs git add","git-commit install","git-commit setup guide","what is git-commit","git-commit for AI agents","git-commit and Git workflow"],"zh":["Git Commit 消息","Git 版本控制","Commit 消息最佳实践","Git 命令","版本管理","代码提交","秘密和凭证管理","正则表达式搜索","Git 工具"],"ja":["Git Commit メッセージ","Git バージョン管理","Commit メッセージのベストプラクティス","Git コマンド","バージョン管理","コードのコミット","秘密と資格情報の管理","正規表現検索","Git ツール"],"ko":["Git Commit 메시지","Git 버전 관리","Commit 메시지의最佳实践","Git 명령어","버전 관리","코드 커밋","비밀과 자격증명 관리","정규식 검색","Git 툴"],"es":["git-commit","desarrollo de software","mejores prácticas","control de versiones","git status","git diff","git add -p","seguridad en el desarrollo"],"fr":["git-commit","développement de logiciels","meilleures pratiques","contrôle de version","git status","git diff","git add -p","sécurité dans le développement"],"de":["git-commit","Softwareentwicklung","Best Practices","Versionskontrolle","git status","git diff","git add -p","Sicherheit in der Entwicklung"],"pt":["git commit","controle de versão","desenvolvimento de software","segurança de código","boas práticas de git","guias de configuração","ferramentas de desenvolvimento"],"ru":["git commit","контроль версий","разработка программного обеспечения","безопасность кода","лучшие практики git","руководства по настройке","инструменты разработки для ИИ Агентов"],"ar":["git commit","تحكم بالإصدارات","تطوير البرمجيات","أمان الشفرة","أفضل الممارسات لجيت","دلائل الإعداد","أدوات التطوير للآليات الذكية"]}},"owner":"semanticdreams","repo":"space","repoPath":"semanticdreams/space","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.386Z","topics":[],"category":"community","skillMd":{"name":"git-commit","description":"Commit changes (git commit) for this repo and write consistent commit messages (type(scope) prefix, impact/risk, what/why/how, testing summary, follow-ups, references).","bodyPreview":"# Git Commit Messages (space)\n\nUse this skill whenever you''re about to create a commit (or when asked to \"commit\", \"write a commit message\", \"draft a commit\", etc.).\n\n## Workflow and safety\n\n- Verify the change set:\n  - `git status`\n  - `git diff`\n  - `git diff --staged`\n- Stage only what you intend to ship; prefer `git add -p` for mixed diffs.\n- Never commit secrets/credentials. When in doubt:\n  - `git diff --staged | rg -n -i \"api[_-]?key|secret|token|password|-----begin|private key\"`\n- Avoid","body":"# Git Commit Messages (space)\n\nUse this skill whenever you''re about to create a commit (or when asked to \"commit\", \"write a commit message\", \"draft a commit\", etc.).\n\n## Workflow and safety\n\n- Verify the change set:\n  - `git status`\n  - `git diff`\n  - `git diff --staged`\n- Stage only what you intend to ship; prefer `git add -p` for mixed diffs.\n- Never commit secrets/credentials. When in doubt:\n  - `git diff --staged | rg -n -i \"api[_-]?key|secret|token|password|-----begin|private key\"`\n- Avoid destructive history ops unless explicitly asked (`reset --hard`, `clean -fdx`, `rebase`, `--amend`, force-push).\n\n## Commit subject line\n\n- Format: `type(scope): <imperative subject>` (scope optional).\n- Keep it <= 72 chars and in imperative mood (\"Add\", \"Fix\", \"Refactor\").\n- Types: `feat`, `fix`, `docs`, `style`, `refactor`, `perf`, `test`, `build`, `ci`, `chore`, `revert`.\n- Scopes (when useful): `engine`, `render`, `physics`, `audio`, `lua`, `ui`, `assets`, `scripts`.\n- Breaking changes: append an exclamation mark after type/scope (e.g. feat!:) and call it out in Impact + Risk.\n\n## Body (required for non-trivial changes)\n\nBe explicit about **impact** (user-visible) vs **what** changed (code/data). Include **risk** when plausible.\n\nTemplate:\n\n```\ntype(scope): Short imperative subject (<= 72 chars)\n\nImpact:\n- <user-visible result / behavior change; include repro if useful>\n\nWhat:\n- <key code/data changes>\n\nWhy:\n- <motivation / constraints>\n\nHow:\n- <implementation approach, key files/systems>\n\nRisk:\n- <what could go wrong + mitigations/rollback>\n\nTesting:\n- <commands run + brief summary; DO NOT paste full logs>\n\nFollow-ups:\n- <next steps / cleanup / tech debt>\n\nReferences:\n- Refs: #123\n```\n\n## Testing section expectations\n\n- Prefer running the full suite before committing:\n  - `SKIP_KEYRING_TESTS=1 XDG_DATA_HOME=/tmp/space/tests/xdg-data SPACE_DISABLE_AUDIO=1 SPACE_ASSETS_PATH=$(pwd)/assets make test`\n- For targeted runs, include the command and a short result summary (e.g., “passed” / “failed: <test name>”).\n- Do not paste full test output into the commit message; keep it to a couple lines.\n\n## Practical: avoid shell-quoting footguns\n\n- Prefer writing the message to a file and committing with `-F`, especially if the body contains backticks:\n  - `cat > /tmp/commitmsg.txt <<''EOF'' ... EOF`\n  - `git commit -F /tmp/commitmsg.txt`\n"},"lastSynced":"2026-03-08T02:05:52.126Z","agentAnalysis":{"suitability":{"en":"Ideal for Version Control Agents needing precise Git workflow management and commit message drafting capabilities.","zh":"适合需要精确Git工作流管理和提交消息草稿功能的版本控制代理。","ja":"Gitワークフローの正確な管理とコミットメッセージの草稿化機能が必要なバージョン管理エージェントに適しています。","ko":"정확한 Git 워크플로 관리 및 커밋 메시지 초안 작성 기능이 필요한 버전 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Control de Versiones que necesitan una gestión de flujo de trabajo de Git precisa y capacidades de redacción de mensajes de commit.","fr":"Idéal pour les Agents de Contrôle de Version nécessitant une gestion précise du workflow Git et des capacités de rédaction de messages de commit.","de":"Ideal für Version Control Agents, die eine präzise Git-Workflow-Verwaltung und Commit-Nachrichten-Erstellungsfunktionen benötigen.","pt":"Ideal para Agentes de Controle de Versão que precisam de gerenciamento de fluxo de trabalho Git preciso e capacidades de redação de mensagens de commit.","ru":"Идеально для агентов контроля версий, которым необходим точный менеджмент рабочего процесса Git и возможности составления сообщений о commit.","ar":"مثالي لعميل إدارة الإصدارات الذي يحتاج إلى إدارة دقيقة لتدفق العمل Git وقدرات صياغة رسائل Commit."},"recommendation":{"en":"Empowers agents to verify change sets using git status, git diff, and git diff --staged, ensuring safe staging of code with git add -p, while preventing accidental commits of secrets or credentials via regex pattern matching with rg -n -i.","zh":"赋予代理人使用git status、git diff和git diff --staged验证更改集的能力，确保使用git add -p安全地分阶段代码，同时通过rg -n -i的正则表达式匹配防止意外提交秘密或凭据。","ja":"git status、git diff、git diff --stagedを使用して変更セットを検証するエージェントの能力を提供し、git add -pを使用してコードを安全にステージングし、rg -n -iの正規表現マッチングによって機密情報や資格情報の誤ったコミットを防止します。","ko":"git status, git diff 및 git diff --staged를 사용하여 변경 집합을 검증할 수 있는 에이전트의 능력을 제공하며, git add -p를 사용하여 코드를 안전하게 스테이징하고, rg -n -i의 정규식 일치를 통해 기밀 정보 또는 자격 증명의 잘못된 커밋을 방지합니다.","es":"Habilita a los agentes para verificar conjuntos de cambios utilizando git status, git diff y git diff --staged, garantizando una puesta en escena segura del código con git add -p, mientras evita commits accidentales de secretos o credenciales a través de coincidencia de patrones de regex con rg -n -i.","fr":"Permet aux agents de vérifier les ensembles de modifications à l''aide de git status, git diff et git diff --staged, assurant une mise en scène sécurisée du code avec git add -p, tout en empêchant les commits accidentels d''informations sensibles via la correspondance de modèles regex avec rg -n -i.","de":"Ermächtigt die Agenten, Änderungssätze mit git status, git diff und git diff --staged zu überprüfen, wodurch eine sichere Staging des Codes mit git add -p gewährleistet wird, während unbeabsichtigte Commits von Geheimnissen oder Anmeldeinformationen durch Regex-Musterabgleich mit rg -n -i verhindert werden.","pt":"Habilita os agentes a verificar conjuntos de alterações usando git status, git diff e git diff --staged, garantindo o estágio seguro do código com git add -p, enquanto impede commits acidentais de segredos ou credenciais via correspondência de padrão regex com rg -n -i.","ru":"Наделяет агентов возможностью проверять наборы изменений с помощью git status, git diff и git diff --staged, обеспечивая безопасную подготовку кода с помощью git add -p, а также предотвращая случайные коммиты секретов или учетных данных через сопоставление с помощью regex с rg -n -i.","ar":"تمكّن الوكيل من التحقق من مجموعات التغييرات باستخدام git status و git diff و git diff --staged، مما يضمن مرحلة آمنة من الشفرة مع git add -p، بينما يمنع الإلتزامات العرضية للأسرار أو بيانات الاعتماد من خلال مطابقة النمط regex مع rg -n -i."},"useCases":{"en":["Verifying change sets before commit","Safely staging mixed diffs with git add -p","Preventing accidental commits of sensitive information"],"zh":["提交前验证更改集","使用git add -p安全地分阶段混合的差异","防止敏感信息的意外提交"],"ja":["コミット前の変更セットの検証","git add -pを使用して混合差分を安全にステージング","機密情報の誤ったコミットを防止"],"ko":["커밋 전 변경 집합 검증","git add -p를 사용하여 혼합된 차이를 안전하게 스테이징","민감한 정보의 잘못된 커밋 방지"],"es":["Verificar conjuntos de cambios antes del commit","Poner en escena de forma segura diffs mixtos con git add -p","Prevenir commits accidentales de información sensible"],"fr":["Vérifier les ensembles de modifications avant le commit","Mettre en scène de manière sécurisée les diffs mixtes avec git add -p","Empêcher les commits accidentels d''informations sensibles"],"de":["Änderungssätze vor dem Commit überprüfen","Sichere Staging von gemischten Diffs mit git add -p","Unbeabsichtigte Commits von sensiblen Informationen verhindern"],"pt":["Verificar conjuntos de alterações antes do commit","Estagiar diferenças mistas de forma segura com git add -p","Prevenir commits acidentais de informações sensíveis"],"ru":["Проверка наборов изменений перед коммитом","Безопасная подготовка смешанных диффов с помощью git add -p","Предотвращение случайных коммитов конфиденциальной информации"],"ar":["التحقق من مجموعات التغييرات قبل الالتزام","المرحلة الآمنة للفرق المخلوطة مع git add -p","منع الإلتزامات العرضية للمعلومات الحساسة"]},"limitations":{"en":["Requires Git repository access","Command-line interface needed for git commands"],"zh":["需要Git仓库访问","需要命令行接口来运行git命令"],"ja":["Gitリポジトリへのアクセスが必要","gitコマンドを実行するためにコマンドラインインターフェイスが必要"],"ko":["Git 저장소 액세스가 필요","git 명령을 실행하기 위해 명령줄 인터페이스가 필요"],"es":["Requiere acceso al repositorio Git","Se necesita una interfaz de línea de comandos para los comandos git"],"fr":["Nécessite un accès au référentiel Git","Une interface de ligne de commande est nécessaire pour les commandes git"],"de":["Benötigt Zugriff auf das Git-Repository","Benötigt eine Kommandozeilenoberfläche für Git-Befehle"],"pt":["Requer acesso ao repositório Git","Interface de linha de comando necessária para comandos Git"],"ru":["Требуется доступ к репозиторию Git","Необходим интерфейс командной строки для команд Git"],"ar":["يتطلب الوصول إلى مستودع Git","الواجهة 命令 الضرورية لاوامر Git"]},"version":4},"contentHash":"43edc8255e370ef823462ebce448eea65d663c2135801e716e498aa78eceeecf","qualityScore":39}');
