INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('semanticdreams/space/git-commit', 'git-commit', 'semanticdreams', 'space', 'community', 'git-commit semanticdreams space community The git-commit skill helps developers manage their Git workflow by verifying change sets and staging code safely. It benefits developers working with Git repositories. Git Commit 消息是版本控制的重要部分，本指南将帮助您了解如何编写高质量的 Commit 消息 Git Commit メッセージはバージョン管理の重要な部分です。このガイドでは、高品質の Commit メッセージの作成方法について説明します Git Commit 메시지는 버전 관리의 중요한 부분입니다. 이 가이드에서는 높은 품질의 Commit 메시지를 작성하는 방법에 대해 설명합니다 Git-commit es una herramienta fundamental para los desarrolladores. Nuestra guía cubre las mejores prácticas para su uso efectivo. Git-commit est un outil essentiel pour les développeurs. Notre guide présente les meilleures pratiques pour son utilisation efficace. Git-commit ist ein grundlegendes Werkzeug für Entwickler. Unser Leitfaden deckt die besten Praktiken für seine effektive Nutzung ab. O Git Commit é uma ferramenta essencial para desenvolvedores, permitindo a criação de commits seguros e eficazes Git Commit - это важнейший инструмент для разработчиков, позволяющий создавать безопасные и эффективные коммиты с помощью ИИ Агентов Git Commit هو أداة أساسية للمطورين، تمكن من إنشاء Commitات آمنة وفعالة باستخدام الآليات الذكية how to use git-commit git-commit best practices git-commit alternative git-commit vs git add git-commit install git-commit setup guide what is git-commit git-commit for AI agents git-commit and Git workflow Git Commit 消息 Git 版本控制 Commit 消息最佳实践 Git 命令 版本管理 代码提交 秘密和凭证管理 正则表达式搜索 Git 工具 Verifies change sets using git status, git diff, and git diff --staged Stages code safely with git add -p for mixed diffs Detects secrets and credentials in commit messages using rg -n -i Prevents accidental commits of sensitive information Supports Git workflow best practices git-commit is a novel computing interface that assists with creating commit messages and managing Git workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yusifeng/formax/formax-repomix-handoff-workflow', 'community', 'yusifeng', 'formax', 'yusifeng/formax', 'formax-repomix-handoff-workflow', 0, 0, 39, '2026-03-08T01:57:15.388Z', '2026-03-08T02:05:59.413Z', '96f19b328a9ee07a5c8c63581472ee482beb3abf8feb8f8c95d07818139f0d64', '{"id":"yusifeng/formax/formax-repomix-handoff-workflow","name":"formax-repomix-handoff-workflow","description":{"en":"formax-repomix-handoff-workflow is a terminal-first AI assistant that helps software engineers create a clean handoff package with a smallest correct repomix bundle and predictable artifact naming. It benefits developers working on AI-related projects.","zh":"formax-repomix-handoff-workflow 是一种 Terminal-first AI 助手，用于软件工程任务，提供清晰的手off 包和可预测的构件命名","ja":"formax-repomix-handoff-workflow は、ソフトウェアエンジニアリングタスク用の Terminal-first AI エージェントです","ko":"formax-repomix-handoff-workflow은 터미널 우선 AI 에이전트로, 소프트웨어 엔지니어링 작업을 위한 핸드오버 패키지와 아티팩트命名을 제공합니다","es":"formax-repomix-handoff-workflow es un asistente de IA de terminal para tareas de ingeniería de software que crea paquetes de entrega limpios con la menor cantidad de código correcto","fr":"formax-repomix-handoff-workflow est un assistant d''IA de terminal pour les tâches d''ingénierie logicielle qui crée des packages de passation de main propres avec le moins de code correct","de":"formax-repomix-handoff-workflow ist ein Terminal-IA-Assistent für Software-Engineering-Aufgaben, der saubere Übergabepakete mit minimalem korrektem Code erstellt","pt":"O formax-repomix-handoff-workflow é um assistente de terminal para tarefas de engenharia de software que cria pacotes de handoff limpos e eficientes","ru":"formax-repomix-handoff-workflow - это терминальный помощник для задач программной инженерии, создающий чистые и эффективные пакеты передачи","ar":"formax-repomix-handoff-workflow هو مساعد طرفية لأدوات هندسة البرمجيات التي tạo حزم تسليم نظيفة وفعالة"},"seo":{"title":{"en":"formax-repomix-handoff-workflow: Streamlined AI Handoff W...","zh":"formax-repomix-handoff-workflow Terminal-first AI 工具设置指南","ja":"formax-repomix-handoff-workflow AIエージェントのベストプラクティス","ko":"formax-repomix-handoff-workflow 터미널 우선 AI 에이전트 설정 가이드","es":"Configuración de formax-repomix-handoff-workflow: Guía de...","fr":"Configurer formax-repomix-handoff-workflow: Guide de Mise...","de":"Einrichtung von formax-repomix-handoff-workflow: Leitfade...","pt":"Guia de Configuração do formax-repomix-handoff-workflow p...","ru":"Настройка ИИ Агентов formax-repomix-handoff-workflow для ...","ar":"دليل إعداد formax-repomix-handoff-workflow لأدوات الذكاء ..."},"description":{"en":"Discover how to create a clean handoff package with formax-repomix-handoff-workflow. Learn to optimize your AI handoff workflow and ensure consistent uploads...","zh":"了解 formax-repomix-handoff-workflow，这是一种 Terminal-first AI 助手，用于软件工程任务，提供清晰的手off 包和可预测的构件命名","ja":"formax-repomix-handoff-workflow は、ソフトウェアエンジニアリングタスク用の Terminal-first AI エージェントです。クリーンなハンドオフパッケージと予測可能なアーティファクト命名を提供します","ko":"formax-repomix-handoff-workflow은 터미널 우선 AI 에이전트로, 소프트웨어 엔지니어링 작업을 위한 깨끗한 핸드오버 패키지와 예측 가능한 아티팩트命名을 제공합니다","es":"Aprende a configurar formax-repomix-handoff-workflow para crear paquetes de entrega limpios con la menor cantidad de código correcto para tareas de ingenierí...","fr":"Découvrez comment configurer formax-repomix-handoff-workflow pour créer des packages de passation de main propres avec le moins de code correct pour les tâch...","de":"Erfahren Sie, wie Sie formax-repomix-handoff-workflow konfigurieren, um saubere Übergabepakete mit minimalem korrektem Code für Software-Engineering-Aufgaben...","pt":"Aprenda a configurar o formax-repomix-handoff-workflow para criar pacotes de handoff limpos e eficientes para outras AI","ru":"Узнайте, как настроить formax-repomix-handoff-workflow для создания чистых и эффективных пакетов передачи для других ИИ Агентов","ar":"تعلم كيفية إعداد formax-repomix-handoff-workflow لإنشاء حزم تسليم نظيفة وفعالة لأدوات الذكاء الاصطناعي الأخرى"},"definition":{"en":"formax-repomix-handoff-workflow is a terminal-first AI assistant for software engineering tasks that creates a clean handoff package with a smallest correct repomix bundle and predictable artifact naming.","zh":"formax-repomix-handoff-workflow 是一种 Terminal-first AI 助手，用于软件工程任务","ja":"formax-repomix-handoff-workflow は、ソフトウェアエンジニアリングタスク用の Terminal-first AI エージェント","ko":"formax-repomix-handoff-workflow은 터미널 우선 AI 에이전트로, 소프트웨어 엔지니어링 작업을 위한 도구입니다","es":"formax-repomix-handoff-workflow es un asistente de IA que crea paquetes de entrega limpios para tareas de ingeniería de software","fr":"formax-repomix-handoff-workflow est un assistant d''IA qui crée des packages de passation de main propres pour les tâches d''ingénierie logicielle","de":"formax-repomix-handoff-workflow ist ein IA-Assistent, der saubere Übergabepakete für Software-Engineering-Aufgaben erstellt","pt":"O formax-repomix-handoff-workflow é um assistente de terminal que cria pacotes de handoff para outras AI","ru":"formax-repomix-handoff-workflow - это терминальный помощник, создающий пакеты передачи для других ИИ Агентов","ar":"formax-repomix-handoff-workflow هو مساعد طرفية لإنشاء حزم تسليم لأدوات الذكاء الاصطناعي الأخرى"},"features":{"en":["Creates a smallest correct repomix bundle for AI handoff","Generates a prompt that matches the target environment","Includes explicit acceptance criteria and non-goals for clarity","Enables predictable artifact naming and validation for consistent uploads","Stores all handoff artifacts in a single folder: repomix-output/","Supports bundle output in repomix-<topic>-<tier>.txt format"],"zh":["提供最小的正确 repomix 包","支持可预测的构件命名和验证","提供明确的接受标准和非目标","支持手off 提示和输出文件"],"ja":["最小の正しい repomix パッケージを提供","予測可能なアーティファクト命名と検証をサポート","明確な受け入れ基準と非目標を提供","ハンドオフプロンプトと出力ファイルをサポート"],"ko":["최소의 올바른 repomix 패키지를 제공","예측 가능한 아티팩트命名과 검증을 지원","명확한 수락 기준과 비목표를 제공","핸드오버 프로ンプ트와 출력 파일을 지원"],"es":["Crea paquetes de entrega limpios con la menor cantidad de código correcto","Genera un prompt que coincide con el entorno objetivo","Incluye criterios de aceptación y objetivos explícitos","Nombra artefactos de manera predecible y válida","Utiliza la carpeta repomix-output para almacenar artefactos de entrega"],"fr":["Crée des packages de passation de main propres avec le moins de code correct","Génère un prompt qui correspond à l''environnement cible","Inclut des critères d''acceptation et des objectifs explicites","Nomme les artefacts de manière prévisible et valide","Utilise le dossier repomix-output pour stocker les artefacts de passation de main"],"de":["Erstellt saubere Übergabepakete mit minimalem korrektem Code","Generiert einen Prompt, der mit der Zielumgebung übereinstimmt","Inkludiert explizite Akzeptanzkriterien und Ziele","Benennt Artefakte auf vorhersehbare und gültige Weise","Verwendet den Ordner repomix-output zum Speichern von Übergabeartefakten"],"pt":["Criação de pacotes de handoff limpos e eficientes","Suporte a repomix bundle mínimo correto","Prompt personalizado para o ambiente de destino","Critérios de aceitação explícitos e não objetivos","Nomenclatura de artefatos previsível e validação"],"ru":["Создание чистых и эффективных пакетов передачи","Поддержка минимального корректного репомикс-пакета","Персонализированный промпт для целевой среды","Явные критерии приемки и нецели","Предсказуемое именование артефактов и валидация"],"ar":["إنشاء حزم تسليم نظيفة وفعالة","دعم حزمة repomix الأقل صحيحة","مؤشر مخصص للبيئة المستهدفة","معايير قبول صريحة وغير أهداف","تسمية الكائنات المتوقعة والتحقق"]},"keywords":{"en":["how to use formax-repomix-handoff-workflow","formax-repomix-handoff-workflow setup guide","formax-repomix-handoff-workflow alternative","formax-repomix-handoff-workflow vs Claude Code","what is formax-repomix-handoff-workflow","formax-repomix-handoff-workflow install","AI handoff workflow optimization","repomix bundle creation","predictable artifact naming"],"zh":["Terminal-first AI 工具","软件工程任务 AI","repomix 包","构件命名","AI 助手","软件开发工具"],"ja":["Terminal-first AI エージェント","ソフトウェアエンジニアリングタスク AI","repomix パッケージ","アーティファクト命名","AI ツール","ソフトウェア開発ツール"],"ko":["터미널 우선 AI 에이전트","소프트웨어 엔지니어링 작업 AI","repomix 패키지","아티팩트命名","AI 도구","소프트웨어 개발 도구"],"es":["formax-repomix-handoff-workflow","AI Agents","Herramientas de IA","Ingeniería de software","Paquetes de entrega limpios","Código correcto mínimo","Prompt de entrega","Criterios de aceptación"],"fr":["formax-repomix-handoff-workflow","Outils d''IA","Agents d''IA","Ingénierie logicielle","Packages de passation de main propres","Code correct minimal","Prompt de passation de main","Critères d''acceptation"],"de":["formax-repomix-handoff-workflow","KI-Tools","KI-Agents","Software-Engineering","Saubere Übergabepakete","Minimaler korrekter Code","Übergabeprompt","Akzeptanzkriterien"],"pt":["formax-repomix-handoff-workflow","assistente de terminal","engenharia de software","pacotes de handoff","repomix bundle","prompt personalizado","critérios de aceitação","nomenclatura de artefatos"],"ru":["formax-repomix-handoff-workflow","терминальный помощник","программная инженерия","пакеты передачи","репомикс-пакет","персонализированный промпт","критерии приемки","именование артефактов"],"ar":["formax-repomix-handoff-workflow","مساعد طرفية","هندسة البرمجيات","حزم تسليم","حزمة repomix","مؤشر مخصص","معايير قبول","تسمية الكائنات"]}},"owner":"yusifeng","repo":"formax","repoPath":"yusifeng/formax","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.388Z","topics":[],"category":"community","skillMd":{"name":"formax-repomix-handoff-workflow","description":"Use when preparing a Formax code handoff: selecting files, generating repomix bundles, and writing a high-quality prompt for WebGPT or another coding agent with clear constraints and validation scope.","bodyPreview":"# formax-repomix-handoff-workflow\n\n## Goal\nCreate a clean handoff package for another AI with:\n- the smallest correct repomix bundle\n- a prompt that matches the target environment\n- explicit acceptance criteria and non-goals\n- predictable artifact naming + validation (so uploads stay consistent)\n\n## Where to change what\n- All handoff artifacts live in one folder: `repomix-output/`\n- Bundle output: `repomix-output/repomix-<topic>-<tier>.txt`\n- Handoff prompt: `repomix-output/<topic>-handoff-promp","body":"# formax-repomix-handoff-workflow\n\n## Goal\nCreate a clean handoff package for another AI with:\n- the smallest correct repomix bundle\n- a prompt that matches the target environment\n- explicit acceptance criteria and non-goals\n- predictable artifact naming + validation (so uploads stay consistent)\n\n## Where to change what\n- All handoff artifacts live in one folder: `repomix-output/`\n- Bundle output: `repomix-output/repomix-<topic>-<tier>.txt`\n- Handoff prompt: `repomix-output/<topic>-handoff-prompt.md`\n- File manifest notes: `repomix-output/repomix-<topic>-files.md`\n- Template references: `references/prompt-templates.md`\n\n> Required hygiene: each new pack run must clear previous files in `repomix-output/` first, so users can upload that folder as-is without manual file picking.\n\n## Pack tiers (default taxonomy)\nUse exactly one tier label in bundle filename:\n\n- `minimal`: changed runtime files + direct dependencies + adjacent tests.\n- `core`: `minimal` + only critical contract/design docs needed for intent.\n- `full`: broad context pack for deep investigations (cross-subsystem docs/tests).\n\nExample names:\n- `repomix-topic-minimal.txt`\n- `repomix-topic-core.txt`\n- `repomix-topic-full.txt`\n\n## Patterns\n1. Classify target runtime first\n- `Static consumer` (e.g., WebGPT): cannot run local commands or tests.\n- `Executable agent` (repo access): can run local commands/tests.\n\n2. Pick a pack tier first (`minimal` / `core` / `full`)\n- Default to `minimal`.\n- Upgrade to `core` only when architecture/contracts matter.\n- Use `full` only when root cause plausibly spans multiple subsystems.\n\n3. Build the include set for that tier\n- Include changed runtime files + direct dependencies + adjacent tests.\n- Include only docs needed for intent/constraints at the chosen tier.\n- Avoid unrelated folders to keep context small.\n\n4. Pack with deterministic command (single folder, auto-clean)\n```sh\nbunx repomix . \\\n  --style plain \\\n  --no-git-sort-by-changes \\\n  -o repomix-output/repomix-<topic>-<tier>.txt \\\n  --include \"<comma-separated-file-list>\"\n```\nOr use the helper script:\n```sh\nbash .codex/skills/formax-repomix-handoff-workflow/scripts/build-repomix.sh \\\n  repomix-<topic>-<tier>.txt \\\n  \"<comma-separated-file-list>\"\n```\nThe helper script will:\n- create `repomix-output/` if missing\n- delete previous files under `repomix-output/` (except `.gitkeep`)\n- write the new bundle into `repomix-output/`\n\n5. Write prompt + file manifest with naming convention\n- Prompt: `repomix-output/<topic>-handoff-prompt.md`\n- Manifest: `repomix-output/repomix-<topic>-files.md`\n- Always use **repo-relative paths** in prompt + manifest (no machine absolute paths).\n\n6. Write prompt with explicit boundaries\n- State known symptoms.\n- State hard constraints (what must not change).\n- Define deliverables (root cause model, options, recommended plan, test/validation matrix).\n- Include acceptance criteria with observable assertions.\n\n7. Run artifact validation (required)\n```sh\nbash .codex/skills/formax-repomix-handoff-workflow/scripts/check-handoff-artifacts.sh \\\n  repomix-<topic>-<tier>.txt \\\n  <topic>\n```\nThis check enforces:\n- Bundle/prompt/manifest files all exist.\n- Prompt and manifest reference the current bundle name.\n- Manifest references the prompt filename.\n- Prompt + manifest do not contain local absolute paths.\n\n8. Sanity-check before handoff\n- `repomix-output/` only contains current-round artifacts.\n- Bundle exists and includes the expected files.\n- Prompt has no impossible instructions for the target runtime.\n- Prompt does not ask static consumers to run commands.\n- Naming is topic-driven and consistent across all three artifacts.\n\nSee `references/prompt-templates.md` for copy-ready templates.\n\n## Tests to update\n- No repository tests required for creating the handoff itself.\n- If target is executable, include a suggested minimal test list in the handoff prompt.\n\n## Guardrails\n- Never include `bun run test:coverage` in a static-consumer prompt.\n- Never assume the other AI can read files outside the provided bundle unless explicitly attached.\n- Keep asks decision-oriented first (root cause/options) before patch implementation.\n- Prefer concrete acceptance checks over vague goals.\n- Avoid mixing unrelated bugfixes into one handoff package.\n- Never leak machine absolute paths (e.g., `/Users/...`) in prompt/manifest.\n"},"lastSynced":"2026-03-08T02:05:59.413Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents involved in collaborative software development needing streamlined handoff workflows with minimal repomix bundles and predictable artifact naming.","zh":"适合参与协作软件开发的AI代理，需要简化的交接工作流程，具有最小的repomix包和可预测的构件命名。","ja":"コラボレーションソフトウェア開発に携わるAIエージェントに適しており、手渡しワークフローをストリームライン化し、最小のrepomixバンドルと予測可能なアーティファクト命名を必要とする。","ko":"협력 소프트웨어 개발에 참여하는 AI 에이전트에게 적합하며, 최소한의 repomix 번들 및 예측 가능한 아티팩트 명명과 함께 손쉬운 인도 워크플로가 필요합니다.","es":"Perfecto para agentes de IA involucrados en el desarrollo de software colaborativo que necesitan flujos de trabajo de entrega simplificados con paquetes mínimos de repomix y nombres de artefactos predecibles.","fr":"Parfait pour les agents IA impliqués dans le développement de logiciels collaboratifs nécessitant des flux de travail de passation simplifiés avec des bundles repomix minimaux et des noms d''artefacts prévisibles.","de":"Perfekt für KI-Agenten, die an der Zusammenarbeit bei der Software-Entwicklung beteiligt sind und gestreamte Arbeitsabläufe mit minimalen repomix-Bündeln und vorhersehbaren Artefakt-Namen benötigen.","pt":"Perfeito para agentes de IA envolvidos no desenvolvimento de software colaborativo que necessitam de fluxos de trabalho de entrega simplificados com pacotes repomix mínimos e nomes de artefatos previsíveis.","ru":"Идеально подходит для агентов ИИ, участвующих в совместном развитии программного обеспечения, требующих оптимизированных рабочих процессов передачи с минимальными пакетами repomix и предсказуемыми именами артефактов.","ar":"مثالي لعمليات الوكيل الذكي المشاركة في تطوير البرمجيات التعاونية التي تحتاج إلى سير عمل تسليم مبسط مع حزم repomix|minimum واسماء أثرية قابلة للتوقع."},"recommendation":{"en":"Empowers agents to create clean handoff packages with the smallest correct repomix bundle, matching prompts for target environments, and explicit acceptance criteria, utilizing terminal-first interactions and standardized artifact naming and validation, ensuring consistent uploads via repomix-output folders and .txt files.","zh":"赋予代理创建干净的交接包的能力，具有最小的正确repomix包、匹配目标环境的提示、明确的验收标准，利用基于终端的交互和标准化的构件命名和验证，确保通过repomix-output文件夹和.txt文件的一致性上传。","ja":"エージェントにクリーンなハンドオフパッケージを作成する能力を与え、最小の正しいrepomixバンドル、ターゲット環境に合わせたプロンプト、明示的な受け入れ基準を使用し、ターミナルファーストのインタラクションと標準化されたアーティファクト命名と検証を利用し、repomix-outputフォルダーと.txtファイルを介した一貫したアップロードを保証する。","ko":"에이전트가 깨끗한 인도 패키지를 생성할 수 있도록 하며, 최소의 올바른 repomix 번들, 대상 환경에 맞는 프롬프트, 명시적인 수락 기준을 사용하며, 터미널 우선 상호 작용 및 표준화된 아티팩트 명명 및 유효성 검사를 사용하고, repomix-output 폴더 및 .txt 파일을 통해 일관된 업로드를 보장합니다.","es":"Habilita a los agentes a crear paquetes de entrega limpios con el bundle repomix más pequeño correcto, promtps coincidentes para entornos de destino y criterios de aceptación explícitos, utilizando interacciones de terminal en primer lugar y nombres de artefactos y validación estandarizados, garantizando cargas consistentes a través de carpetas de repomix-output y archivos .txt.","fr":"Permet aux agents de créer des paquets de passation propres avec le bundle repomix le plus petit correct, des invites correspondant aux environnements cibles et des critères d''acceptation explicites, en utilisant des interactions de terminal en premier et une nomination et une validation d''artefacts standardisées, garantissant des téléchargements cohérents via les dossiers de repomix-output et les fichiers .txt.","de":"Ermächtigt Agenten, saubere Übergabepakete mit dem kleinsten korrekten repomix-Bundle, passenden Prompts für Zielumgebungen und expliziten Akzeptanzkriterien zu erstellen, unter Verwendung von terminalerstinteraktionen und standardisierter Artefaktbenennung und -validierung, um konsistente Uploads über repomix-Output-Ordner und .txt-Dateien zu gewährleisten.","pt":"Habilita os agentes a criar pacotes de entrega limpos com o menor pacote repomix correto, prompts correspondentes para ambientes de destino e critérios de aceitação explícitos, utilizando interações de terminal-first e nomes de artefatos padronizados e validação, garantindo uploads consistentes via pastas repomix-output e arquivos .txt.","ru":"Наделяет агентов возможностью создавать чистые пакеты передачи с наименьшим правильным пакетом repomix, соответствующими подсказками для целевой среды и явными критериями приемки, используя взаимодействия с терминалом в первую очередь и стандартизированные имена артефактов и проверку, обеспечивая последовательные загрузки через папки repomix-output и файлы .txt.","ar":"تمكن الوكيل من إنشاء حزم تسليم نظيفة مع حزمة repomix الصحيحة الأصغر، وتوجيهات مطابقة للبيئات المستهدفة ومعايير قبول صريحة، باستخدام التفاعلات الأولى للمحطة واسماء الأثرية ومعايير القبول الموحدة والتحقق، مما يضمن التحميل المتسق عبر مجلدات repomix-output وملفات .txt."},"useCases":{"en":["Generating minimal repomix bundles for efficient handoffs","Creating predictable artifact naming conventions for version control","Validating handoff packages against explicit acceptance criteria"],"zh":["为高效交接生成最小的repomix包","为版本控制创建可预测的构件命名约定","验证交接包是否符合明确的验收标准"],"ja":["効率的なハンドオフのために最小のrepomixバンドルを生成する","バージョン管理のために予測可能なアーティファクト命名規約を作成する","ハンドオフパッケージを明示的な受け入れ基準に対して検証する"],"ko":["효율적인 인도를 위해 최소한의 repomix 번들을 생성하는 것","버전 관리를 위한 예측 가능한 아티팩트 명명 규약을 생성하는 것","명시적인 수락 기준에 대해 인도 패키지를 검증하는 것"],"es":["Generación de bundles repomix mínimos para entregas eficientes","Creación de convenciones de nombres de artefactos predecibles para el control de versiones","Validación de paquetes de entrega contra criterios de aceptación explícitos"],"fr":["Génération de bundles repomix minimaux pour des passations efficaces","Création de conventions de nomination d''artefacts prévisibles pour le contrôle de version","Validation des paquets de passation contre des critères d''acceptation explicites"],"de":["Erzeugung von minimalen repomix-Bündeln für effiziente Übergaben","Erstellung von vorhersehbaren Artefakt-Benennungskonventionen für die Versionskontrolle","Validierung von Übergabepaketen gegen explizite Akzeptanzkriterien"],"pt":["Geração de pacotes repomix mínimos para entregas eficientes","Criação de convenções de nomes de artefatos previsíveis para controle de versão","Validação de pacotes de entrega contra critérios de aceitação explícitos"],"ru":["Генерация минимальных пакетов repomix для эффективной передачи","Создание предсказуемых конвенций именования артефактов для контроля версий","Проверка пакетов передачи на соответствие явным критериям приемки"],"ar":["إنشاء حزم repomix|minimum لعمليات التسليم الفعالة","إنشاء اتفاقيات تسمية الأثرية القابلة للتوقع لأغراض التحكم بالإصدار","التحقق من حزم التسليم مقابل معايير القبول الصريحة"]},"limitations":{"en":["Requires terminal access","Designed for AI-related software development projects only","Output files are in .txt format"],"zh":["需要终端访问","仅适用于AI相关的软件开发项目","输出文件格式为.txt"],"ja":["ターミナルアクセスが必要","AI関連のソフトウェア開発プロジェクトのみに設計されている","出力ファイルの形式は.txt"],"ko":["터미널 접근이 필요","AI 관련 소프트웨어 개발 프로젝트만을 위해 설계됨","출력 파일 형식은 .txt"],"es":["Requiere acceso a la terminal","Diseñado solo para proyectos de desarrollo de software relacionados con la IA","Los archivos de salida están en formato .txt"],"fr":["Nécessite un accès à la terminal","Conçu uniquement pour les projets de développement de logiciels liés à l''IA","Les fichiers de sortie sont au format .txt"],"de":["Benötigt Terminal-Zugriff","Nur für KI-bezogene Software-Entwicklungsprojekte konzipiert","Ausgabedateien sind im .txt-Format"],"pt":["Requer acesso ao terminal","Projetado apenas para projetos de desenvolvimento de software relacionados à IA","Arquivos de saída estão no formato .txt"],"ru":["Требуется доступ к терминалу","Разработан только для проектов разработки программного обеспечения, связанных с ИИ","Файлы вывода находятся в формате .txt"],"ar":["يتطلب الوصول إلى المحطة","مصمم فقط لمشاريع تطوير البرمجيات المتعلقة بالذكاء الاصطناعي","ملفات الإخراج تكون بامتداد .txt"]},"version":4},"contentHash":"96f19b328a9ee07a5c8c63581472ee482beb3abf8feb8f8c95d07818139f0d64","qualityScore":39}');
