INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yusifeng/formax/formax-repomix-handoff-workflow', 'formax-repomix-handoff-workflow', 'yusifeng', 'formax', 'community', 'formax-repomix-handoff-workflow yusifeng formax community formax-repomix-handoff-workflow is a terminal-first AI assistant that helps software engineers create a clean handoff package with a smallest correct repomix bundle and predictable artifact naming. It benefits developers working on AI-related projects. formax-repomix-handoff-workflow 是一种 Terminal-first AI 助手，用于软件工程任务，提供清晰的手off 包和可预测的构件命名 formax-repomix-handoff-workflow は、ソフトウェアエンジニアリングタスク用の Terminal-first AI エージェントです formax-repomix-handoff-workflow은 터미널 우선 AI 에이전트로, 소프트웨어 엔지니어링 작업을 위한 핸드오버 패키지와 아티팩트命名을 제공합니다 formax-repomix-handoff-workflow es un asistente de IA de terminal para tareas de ingeniería de software que crea paquetes de entrega limpios con la menor cantidad de código correcto formax-repomix-handoff-workflow est un assistant d''IA de terminal pour les tâches d''ingénierie logicielle qui crée des packages de passation de main propres avec le moins de code correct formax-repomix-handoff-workflow ist ein Terminal-IA-Assistent für Software-Engineering-Aufgaben, der saubere Übergabepakete mit minimalem korrektem Code erstellt O formax-repomix-handoff-workflow é um assistente de terminal para tarefas de engenharia de software que cria pacotes de handoff limpos e eficientes formax-repomix-handoff-workflow - это терминальный помощник для задач программной инженерии, создающий чистые и эффективные пакеты передачи formax-repomix-handoff-workflow هو مساعد طرفية لأدوات هندسة البرمجيات التي tạo حزم تسليم نظيفة وفعالة how to use formax-repomix-handoff-workflow formax-repomix-handoff-workflow setup guide formax-repomix-handoff-workflow alternative formax-repomix-handoff-workflow vs Claude Code what is formax-repomix-handoff-workflow formax-repomix-handoff-workflow install AI handoff workflow optimization repomix bundle creation predictable artifact naming Terminal-first AI 工具 软件工程任务 AI repomix 包 构件命名 AI 助手 软件开发工具 Creates a smallest correct repomix bundle for AI handoff Generates a prompt that matches the target environment Includes explicit acceptance criteria and non-goals for clarity Enables predictable artifact naming and validation for consistent uploads Stores all handoff artifacts in a single folder: repomix-output/ Supports bundle output in repomix-<topic>-<tier>.txt format formax-repomix-handoff-workflow is a terminal-first AI assistant for software engineering tasks that creates a clean handoff package with a smallest correct repomix bundle and predictable artifact naming.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hookvibe/hookcode/hookcode-preview-highlight', 'community', 'hookvibe', 'hookcode', 'hookvibe/hookcode', 'hookcode-preview-highlight', 0, 0, 39, '2026-03-08T01:57:15.389Z', '2026-03-08T02:06:00.367Z', 'f7781b3e00e114c07474726098be97544129f7c72e850bc44e3df76fa964331f', '{"id":"hookvibe/hookcode/hookcode-preview-highlight","name":"hookcode-preview-highlight","description":{"en":"hookcode-preview-highlight is a skill that ships JS request scripts for preview highlight flow, supporting independent deployment and real-time task execution monitoring. It benefits developers by automating code review and testing.","zh":"HookCode预览高亮是一个智能代码审查和自动化平台，支持独立部署和实时任务执行监控","ja":"HookCodeプレビューハイライトは、インテリジェントなコードレビューと自動化プラットフォームで、独立したデプロイとリアルタイムのタスク実行モニタリングをサポートします","ko":"HookCode预览 하이라이트는 지능형 코드 리뷰 및 자동화 플랫폼으로 독립 배포 및 실시간 작업 실행 모니터링을 지원합니다","es":"Hookcode-preview-highlight es una habilidad que permite a los desarrolladores ejecutar flujos de trabajo de código inteligente con CLI y Webhooks","fr":"Hookcode-preview-highlight est une compétence qui permet aux développeurs d''exécuter des flux de travail de code intelligent avec CLI et Webhooks","de":"Hookcode-preview-highlight ist eine Fähigkeit, die es Entwicklern ermöglicht, intelligente Code-Workflows mit CLI und Webhooks auszuführen","pt":"O Hookcode Preview Highlight é uma plataforma de revisão e automação de código que utiliza assistentes de codificação CLI e Webhooks para automatizar tarefas de codificação","ru":"Hookcode Preview Highlight — платформа для автоматизации и проверки кода, которая использует CLI-ассистенты и Webhooks для автоматизации задач кодирования","ar":"Hookcode Preview Highlight هو منصة مراجعة وآتمتة الكود التي تستخدم مساعدي الترميز CLI والويب هوك لآتمتة المهام البرمجية"},"seo":{"title":{"en":"hookcode-preview-highlight: Setup Guide for AI Agents","zh":"HookCode预览高亮集成指南","ja":"HookCodeプレビューハイライトの設定方法","ko":"HookCode预览 하이라이트 설정 가이드","es":"Guía de configuración de hookcode-preview-highlight para ...","fr":"Configurer hookcode-preview-highlight : Guide pour les dé...","de":"Einrichtungsleitfaden für hookcode-preview-highlight-Entw...","pt":"Guia de Configuração do Hookcode Preview Highlight","ru":"Настройка Hookcode Preview Highlight: ИИ Агенты для Автом...","ar":"دليل إعداد Hookcode Preview Highlight: أدوات ذكاء اصطناعي..."},"description":{"en":"Unlock efficient code review with hookcode-preview-highlight. Learn how to trigger CLI coding assistants and monitor task execution in real-time. Get started...","zh":"了解HookCode预览高亮的技术细节，包括JS请求脚本、依赖安装和跨域桥接","ja":"HookCodeプレビューハイライトの技術的特徴を解説します。JSリクエストスクリプト、依存関係のインストール、クロスオリジンブリッジを含みます","ko":"HookCode预览 하이라이트의 기술적 세부 사항을 살펴보세요. JS 요청 스크립트, 의존성 설치 및 크로스オリ진 브리지가 포함됩니다","es":"Aprende a configurar hookcode-preview-highlight para mejorar tus flujos de trabajo de desarrollo con herramientas de código inteligentes","fr":"Découvrez comment configurer hookcode-preview-highlight pour améliorer vos flux de travail de développement avec des outils de code intelligents","de":"Erfahren Sie, wie Sie hookcode-preview-highlight konfigurieren, um Ihre Entwicklungsworkflows mit intelligenten Code-Tools zu verbessern","pt":"Aprenda a configurar o Hookcode Preview Highlight para automatizar tarefas de codificação e revisão de código com inteligência artificial","ru":"Узнайте, как настроить Hookcode Preview Highlight для автоматизации задач кодирования и проверки кода с помощью ИИ Агентов","ar":"تعلم كيفية إعداد Hookcode Preview Highlight لآتمتة المهام البرمجية ومراجعة الكود باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"hookcode-preview-highlight is a skill that enables automated code review and preview highlighting through CLI coding assistants and Webhooks, with features like .env loading and protocol notes.","zh":"HookCode预览高亮是一种AI工具，用于触发CLI编码辅助和Webhooks","ja":"HookCodeプレビューハイライトは、CLIコード補助とWebhookをトリガーするAIエージェントの一種です","ko":"HookCode预览 하이라이트는 CLI 코드 보조 및 웹후크를 트리거하는 AI 에이전트의 일종입니다","es":"Hookcode-preview-highlight es una herramienta de código inteligente que facilita la revisión y automatización de código","fr":"Hookcode-preview-highlight est un outil de code intelligent qui facilite la révision et l''automatisation de code","de":"Hookcode-preview-highlight ist ein intelligentes Code-Tool, das die Code-Überprüfung und -Automatisierung erleichtert","pt":"O que é Hookcode Preview Highlight? É uma plataforma de revisão e automação de código que utiliza inteligência artificial para automatizar tarefas de codificação","ru":"Что такое Hookcode Preview Highlight? Это платформа для автоматизации и проверки кода, которая использует ИИ Агенты для автоматизации задач кодирования","ar":"ما هو Hookcode Preview Highlight؟ هو منصة مراجعة وآتمتة الكود التي تستخدم الذكاء الاصطناعي لآتمتة المهام البرمجية"},"features":{"en":["Ships JS request scripts with .env loading for preview highlight flow","Supports independent deployment for flexible integration","Provides real-time task execution monitoring through a visual console","Triggers CLI coding assistants through conversations and Webhooks","Includes protocol notes for cross-origin bridge handshake","Installs dependencies and sends highlight commands for streamlined testing"],"zh":["支持JS请求脚本和.env加载","提供实时任务执行监控","支持跨域桥接","可以安装依赖","支持预览状态检查和预览启动","支持调试和预览停止"],"ja":["JSリクエストスクリプトと.envロードをサポート","リアルタイムのタスク実行モニタリングを提供","クロスオリジンブリッジをサポート","依存関係のインストールを可能に","プレビュー状態の確認とプレビューの開始をサポート","デバッグとプレビューの停止をサポート"],"ko":["JS 요청 스크립트와 .env 로드를 지원","실시간 작업 실행 모니터링을 제공","크로스オリ진 브리지를 지원","의존성 설치를 가능하게","预览 상태 확인 및预览 시작을 지원","디버깅 및预览停止을 지원"],"es":["Ejecución de scripts de solicitud de JS con carga de `.env`","Soporte para despliegue independiente","Consola visual para monitorear la ejecución de tareas en tiempo real","Protocolo de notas para el flujo de resaltado de vista previa","Compatibilidad con CLI y Webhooks"],"fr":["Exécution de scripts de requête JS avec chargement de `.env`","Prise en charge du déploiement indépendant","Console visuelle pour surveiller l''exécution des tâches en temps réel","Protocole de notes pour le flux de mise en surbrillance de l''aperçu","Compatibilité avec CLI et Webhooks"],"de":["Ausführung von JS-Anfrage-Skripten mit `.env`-Ladefunktion","Unterstützung für unabhängige Bereitstellung","Visuelle Konsole zur Überwachung der Aufgabenausführung in Echtzeit","Protokollnotizen für den Vorschauhervorhebungsfluss","Kompatibilität mit CLI und Webhooks"],"pt":["Suporte a deploy independente","Console visual para monitoramento de execução de tarefas em tempo real","Envio de comandos de highlight para pré-visualização de código","Instalação de dependências necessárias para pré-visualização","Parada de pré-visualização após depuração"],"ru":["Поддержка независимого deploy","Визуальная консоль для мониторинга выполнения задач в реальном времени","Отправка команд highlight для предварительного просмотра кода","Установка необходимых зависимостей для предварительного просмотра","Остановка предварительного просмотра после отладки"],"ar":["دعم التثبيت المستقل","واجهة مرئية لمراقبة تنفيذ المهام في الوقت الفعلي","إرسال أوامر التمييز للتنبؤ بالكود","تثبيت الإعتمادات الضرورية لمعاينة","إيقاف معاينة بعد تصحيح الأخطاء"]},"keywords":{"en":["how to use hookcode-preview-highlight","hookcode-preview-highlight setup guide","hookcode-preview-highlight alternative","hookcode-preview-highlight vs automation platforms","hookcode-preview-highlight install","what is hookcode-preview-highlight","hookcode-preview-highlight for AI agents","CLI coding assistants with hookcode-preview-highlight","Webhooks and hookcode-preview-highlight integration"],"zh":["HookCode预览高亮","AI工具","CLI编码辅助","Webhooks","JS请求脚本","依赖安装","跨域桥接","实时任务执行监控"],"ja":["HookCodeプレビューハイライト","AIエージェント","CLIコード補助","Webhook","JSリクエストスクリプト","依存関係のインストール","クロスオリジンブリッジ","リアルタイムのタスク実行モニタリング"],"ko":["HookCode预览 하이라이트","AI 에이전트","CLI 코드 보조","웹후크","JS 요청 스크립트","의존성 설치","크로스オリ진 브리지","실시간 작업 실행 모니터링"],"es":["herramientas de código inteligente","desarrollo de software","CLI","Webhooks","automatización de código","revisión de código","despliegue independiente","monitoreo de tareas"],"fr":["outils de code intelligents","développement de logiciels","CLI","Webhooks","automatisation de code","révision de code","déploiement indépendant","surveillance de tâches"],"de":["intelligente Code-Tools","Software-Entwicklung","CLI","Webhooks","Code-Automatisierung","Code-Überprüfung","unabhängige Bereitstellung","Aufgabenüberwachung"],"pt":["Hookcode Preview Highlight","revisão de código","automação de código","inteligência artificial","CLI","Webhooks","deploy independente","console visual"],"ru":["Hookcode Preview Highlight","проверка кода","автоматизация кода","ИИ Агенты","CLI","Webhooks","независимый deploy","визуальная консоль"],"ar":["Hookcode Preview Highlight","مراجعة الكود","آتمتة الكود","أدوات الذكاء الاصطناعي","CLI","Webhooks","التثبيت المستقل","واجهة مرئية"]}},"owner":"hookvibe","repo":"hookcode","repoPath":"hookvibe/hookcode","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.389Z","topics":[],"category":"community","skillMd":{"name":"hookcode-preview-highlight","description":"End-to-end workflow for HookCode preview DOM highlighting check/start/stop previews, install dependencies, send highlight commands, and verify preview bridge readiness via PAT-authenticated APIs. Use when debugging cross-origin preview iframes, validating bridge integration, or scripting highlight requests against task-group previews.","tags":"","bodyPreview":"{/* Add tags metadata for built-in skill filtering. docs/en/developer/plans/skills-registry-20260225/task_plan.md skills-registry-20260225 */}\n\n# Hookcode Preview Highlight\n\n\n## Overview\n\n\nThis skill ships JS request scripts (with `.env` loading) and protocol notes for the complete preview highlight flow: check preview status, start previews, install dependencies if needed, send highlight commands, and stop previews after debugging. It also explains the bridge handshake required for cross-origin","body":"{/* Add tags metadata for built-in skill filtering. docs/en/developer/plans/skills-registry-20260225/task_plan.md skills-registry-20260225 */}\n\n# Hookcode Preview Highlight\n\n\n## Overview\n\n\nThis skill ships JS request scripts (with `.env` loading) and protocol notes for the complete preview highlight flow: check preview status, start previews, install dependencies if needed, send highlight commands, and stop previews after debugging. It also explains the bridge handshake required for cross-origin iframes so you can confirm whether highlight commands are actually reaching the preview DOM. Selector rules now include CSS selectors plus text/attribute matchers (for example `text:Save`, `attr:data-testid=cta`, `data:testid=cta`, `aria:label=Search`, `role:button`, or loose `data-testid=cta`). If a highlight command includes `targetUrl`, the preview UI will auto-navigate to that URL (and push it to the iframe history) unless the user locks auto-navigation in the toolbar. Target URL matching now supports route patterns like `:id`, `*`, `**`, hash/query wildcards, and `||` alternatives to avoid unnecessary navigation.\n{/* Document auto-navigation + lock behavior for highlight target URLs. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n{/* Document selector matcher rules in the skill overview. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n{/* Document advanced targetUrl route matching rules in the skill overview. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n\n## Capabilities\n\n- Query preview status to discover instance names and availability before highlighting.\n- Start preview instances or install dependencies when the dev server is missing.\n- Send highlight commands with selector/mode/color/padding/scroll options via the backend API.\n- Send optional bubble tooltip payloads alongside highlights (text + placement + theme).\n- Provide CLI flags that map one-to-one with highlight + bubble payload fields.\n{/* Expand highlight capability coverage to include bubble payloads. docs/en/developer/plans/jemhyxnaw3lt4qbxtr48/task_plan.md jemhyxnaw3lt4qbxtr48 */}\n- Support selector matcher rules like `text:`, `attr:`, `data:`, `aria:`, `role:`, and `testid:` when CSS selectors are not enough.\n{/* Describe selector matcher capabilities for highlight requests. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n- Auto-navigate previews when `targetUrl` is supplied, with a lock toggle and route-matching rules to keep the current URL stable.\n{/* Explain auto-navigation support in the preview highlight skill. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n- Verify bridge readiness by checking `subscribers` and bridge error responses.\n- Stop previews after debugging to free ports and resources.\n\n## Quick Start\n\n1. Copy `.env.example` → `.env` inside this skill folder and fill in `HOOKCODE_API_BASE_URL`, `HOOKCODE_PAT`, and `HOOKCODE_TASK_GROUP_ID` (optional: `HOOKCODE_PREVIEW_INSTANCE`).\n2. Fetch preview status to confirm instance names:\n\n```bash\nnode .codex/skills/hookcode-preview-highlight/scripts/preview_status.mjs \\\n  --task-group <taskGroupId>\n```\n\n3. Send a highlight command (highlight parameters must be passed via CLI flags):\n\n```bash\nnode .codex/skills/hookcode-preview-highlight/scripts/preview_highlight.mjs \\\n  --task-group <taskGroupId> \\\n  --instance app \\\n  --selector \".page-kicker\"\n```\n\n4. Send a highlight + bubble command:\n\n```bash\nnode .codex/skills/hookcode-preview-highlight/scripts/preview_highlight.mjs \\\n  --task-group <taskGroupId> \\\n  --instance app \\\n  --selector \".page-kicker\" \\\n  --target-url \"/add\" \\\n  --bubble-text \"Update this headline\" \\\n  --bubble-placement right \\\n  --bubble-theme dark\n```\n{/* Document bubble highlight example for CLI usage. docs/en/developer/plans/jemhyxnaw3lt4qbxtr48/task_plan.md jemhyxnaw3lt4qbxtr48 */}\n\n## Environment Variables\n\n\nSet these in `.env` (or override via CLI flags). Highlight-specific options are CLI-only.\n\n| Variable | Purpose | Used by |\n| --- | --- | --- |\n| `HOOKCODE_API_BASE_URL` | Base URL of the HookCode backend (for example `http://127.0.0.1:4000`). | All scripts |\n| `HOOKCODE_PAT` | PAT token for API authentication. | All scripts |\n| `HOOKCODE_TASK_GROUP_ID` | Default task group id to target. | All scripts |\n| `HOOKCODE_PREVIEW_INSTANCE` | Default preview instance name (for example `app`). | `preview_highlight.mjs` |\n\n## Operations (HTTP)\n\n### 1) Get preview status\n\n**Endpoint**: `GET /api/task-groups/:id/preview/status`\n\n**Purpose**: Confirm the preview is configured, see instance names, and check `running/starting` status before highlighting.\n\n**Script**: `scripts/preview_status.mjs`\n\n```bash\nnode .codex/skills/hookcode-preview-highlight/scripts/preview_status.mjs \\\n  --task-group <taskGroupId>\n```\n\n### 2) Start preview\n\n**Endpoint**: `POST /api/task-groups/:id/preview/start`\n\n**Purpose**: Start all configured preview instances so the highlight API can reach a running dev server.\n\n**Script**: `scripts/preview_start.mjs`\n\n```bash\nnode .codex/skills/hookcode-preview-highlight/scripts/preview_start.mjs \\\n  --task-group <taskGroupId>\n```\n\n### 3) Install preview dependencies\n\n**Endpoint**: `POST /api/task-groups/:id/preview/dependencies/install`\n\n**Purpose**: Run dependency installation without starting the dev server. Use this when highlight requests fail because the dev server never started.\n\n**Script**: `scripts/preview_dependencies_install.mjs`\n\n```bash\nnode .codex/skills/hookcode-preview-highlight/scripts/preview_dependencies_install.mjs \\\n  --task-group <taskGroupId>\n```\n\n### 4) Send highlight command\n\n**Endpoint**: `POST /api/task-groups/:id/preview/:instance/highlight`\n\n**Purpose**: Forward a DOM highlight command to the preview iframe bridge.\n\n**Script**: `scripts/preview_highlight.mjs`\n\n**Parameters**:\n- `selector` (required): CSS selector to highlight (max length 200); supports matcher rules like `text:`, `attr:`, `data:`, `aria:`, `role:`, `testid:`, or loose `data-testid=...`.\n{/* Document selector matcher rules in the parameter list. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n- `targetUrl` (optional): preview URL or path to navigate to before highlighting; matching supports `:param`, `*`, `**`, query/hash wildcards (e.g. `/users/:id?tab=*`), and `||` alternatives (first entry is used for navigation).\n{/* Document target URL route matching behavior in the parameter list. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n\n**TargetUrl matching rules**:\n- `:param` matches a single path segment (e.g. `/users/:id`).\n- `*` matches any characters within a segment; `**` matches across segments (e.g. `/projects/**/settings`).\n- Query rules only require params you declare; use `?tab` for any value or `?tab=*` for wildcard values.\n- Hash rules accept wildcards like `#section-*`.\n- `||` separates alternatives; the first entry is used for navigation if auto-navigation is needed.\n{/* Detail targetUrl route matching rules in the skill docs. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n- `padding` (optional): number of pixels around the element (0-64, default 4).\n- `color` (optional): CSS color string for outline/glow (max length 40).\n- `mode` (optional): `outline` or `mask` (default `outline`).\n- `scrollIntoView` (optional): `true`/`false` (default `false`).\n- `bubble` (optional): object for tooltip rendering near the highlight.\n  - `text` (required when bubble provided): text content to display (1-280 chars).\n  - `placement` (optional): `top` | `right` | `bottom` | `left` | `auto` (default `auto`); auto prefers bottom/top and flips when space is insufficient to avoid clipping.\n  {/* Document bubble placement flipping rules to avoid clipped tooltips. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n  - `align` (optional): `start` | `center` | `end` (default `center`).\n  - `offset` (optional): number of pixels between highlight and bubble (0-64, default `10`).\n  - `maxWidth` (optional): max width in px (120-640, default `320`).\n  - `theme` (optional): `dark` | `light` (default `dark`).\n  - `background` (optional): bubble background CSS color override.\n  - `textColor` (optional): bubble text color override.\n  - `borderColor` (optional): bubble border color override.\n  - `radius` (optional): bubble corner radius in px (0-24, default `12`).\n  - `arrow` (optional): `true`/`false` to show the pointer (default `true`).\n- `requestId` (optional): client-defined id for tracking.\n{/* Expand highlight parameter docs to include bubble payload fields. docs/en/developer/plans/jemhyxnaw3lt4qbxtr48/task_plan.md jemhyxnaw3lt4qbxtr48 */}\n\n**Response**:\n- `success`, `requestId`, `subscribers`, and optional `targetUrl` echo for navigation-aware clients.\n{/* Document highlight response fields including targetUrl echo. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n\n```bash\nnode .codex/skills/hookcode-preview-highlight/scripts/preview_highlight.mjs \\\n  --task-group <taskGroupId> \\\n  --instance app \\\n  --selector \".page-kicker\" \\\n  --mode outline \\\n  --color \"#ff4d4f\" \\\n  --padding 4 \\\n  --scroll true \\\n  --bubble-text \"Edit this title\" \\\n  --bubble-placement top \\\n  --bubble-align center \\\n  --bubble-offset 12 \\\n  --bubble-theme dark\n```\n{/* Add bubble flag example to highlight CLI sample. docs/en/developer/plans/jemhyxnaw3lt4qbxtr48/task_plan.md jemhyxnaw3lt4qbxtr48 */}\n\n### 5) Stop preview\n\n**Endpoint**: `POST /api/task-groups/:id/preview/stop`\n\n**Purpose**: Stop preview instances after debugging to free ports and resources.\n\n**Script**: `scripts/preview_stop.mjs`\n\n```bash\nnode .codex/skills/hookcode-preview-highlight/scripts/preview_stop.mjs \\\n  --task-group <taskGroupId>\n```\n\n## Bridge requirements (must be installed in the preview app)\n\n- Copy `shared/preview-bridge.js` into the preview project and import it in the app entry file.\n- The bridge answers a `hookcode:preview:ping` handshake from HookCode. Only after the handshake does the frontend forward highlight commands.\n- A highlight API response with `subscribers: 0` usually means the preview UI is not connected or the bridge did not answer the ping.\n\n## Troubleshooting\n\n- **`preview_not_running`** (409): Start the preview first or check the instance name.\n- **`selector_required` / `selector_not_found`** (response from bridge): verify the selector exists in the preview DOM.\n- The bridge now retries selector resolution with `querySelectorAll`, simple id/class/tag fallbacks, and open shadow-root scans; when in doubt, send a stable CSS selector that maps to a visible element.\n{/* Note selector fallback strategies in troubleshooting guidance. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n- If a `targetUrl` is supplied but the preview does not navigate, check whether the auto-navigation lock button is enabled in the preview toolbar.\n{/* Document auto-navigation lock behavior in troubleshooting guidance. docs/en/developer/plans/previewhighlightselector20260204/task_plan.md previewhighlightselector20260204 */}\n- **`bubble_text_required`**: a bubble payload was supplied without valid `text`.\n- **`fetch failed`**: the backend is unreachable; check `HOOKCODE_API_BASE_URL` and local network access.\n- **`subscribers: 0`**: the preview UI is not listening or the bridge script is missing.\n{/* Document bubble-specific error messaging. docs/en/developer/plans/jemhyxnaw3lt4qbxtr48/task_plan.md jemhyxnaw3lt4qbxtr48 */}\n\n## References\n\n- `references/highlight-protocol.md` for full protocol details and bridge message formats.\n"},"lastSynced":"2026-03-08T02:06:00.367Z","agentAnalysis":{"suitability":{"en":"Ideal for JavaScript-focused AI Agents requiring automated code review and testing capabilities with real-time task execution monitoring.","zh":"适用于需要自动代码审查和测试能力以及实时任务执行监控的JavaScript专注的AI代理。","ja":"JavaScriptに焦点を当てたAIエージェントが自動コードレビューとテスト機能を必要とする場合に最適です。リアルタイムのタスク実行監視機能もあります。","ko":"자바스크립트에 중점을 둔 AI 에이전트가 자동 코드 리뷰 및 테스트 기능과 실시간 작업 실행 모니터링을 필요로 하는 경우에 적합합니다.","es":"Ideal para agentes de IA enfocados en JavaScript que requieren capacidades de revisión y prueba de código automatizadas con monitoreo de ejecución de tareas en tiempo real.","fr":"Idéal pour les agents d''IA axés sur JavaScript nécessitant des capacités de révision et de test de code automatisées avec un moniteur d''exécution de tâches en temps réel.","de":"Ideal für JavaScript-fokussierte KI-Agents, die automatisierte Code-Überprüfungs- und Testfunktionen mit Echtzeit-Aufgaben-Ausführungsüberwachung erfordern.","pt":"Ideal para Agentes de IA focados em JavaScript que exigem capacidades de revisão e teste de código automatizadas com monitoramento de execução de tarefas em tempo real.","ru":"Идеально подходит для агентов ИИ, ориентированных на JavaScript, требующих автоматизированных возможностей проверки и тестирования кода с мониторингом выполнения задач в режиме реального времени.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي التي تركز على جافا سكريبت وتحتاج إلى khảیات مراجعة واختبار الكود الآلي مع إمكانيات مراقبة تشغيل المهام في الوقت الفعلي."},"recommendation":{"en":"Empowers agents to automate code review and testing by shipping JS request scripts for preview highlight flow, utilizing .env loading and protocol notes for cross-origin bridge handshakes, and supporting independent deployment with real-time monitoring.","zh":"赋予代理自动化代码审查和测试的能力，通过发送JS请求脚本进行预览高亮流，利用.env加载和协议注释进行跨源桥接握手，并支持独立部署和实时监控。","ja":"エージェントにコードレビューとテストを自動化する能力を付与します。JS要求スクリプトをプレビューのハイライトフローに送信し、.envのロードとプロトコルの注釈を使用してクロスオリジンブリッジのハンドシェイクを行い、独立したデプロイとリアルタイム監視をサポートします。","ko":"에이전트가 코드를 자동으로 검토하고 테스트할 수 있는 기능을 부여합니다. JS 요청 스크립트를 미리 보기 강조 흐름으로 보내고, .env 로드 및 프로토콜 주석을 사용하여 크로스 오리진 브리지 핸드 셰이크를 수행하며, 독립적인 배포 및 실시간 모니터링을 지원합니다.","es":"Habilita a los agentes a automatizar la revisión y prueba de código al enviar scripts de solicitud JS para el flujo de resaltado de vista previa, utilizando la carga de .env y notas de protocolo para handshakes de puente de origen cruzado, y admitiendo la implementación independiente con monitoreo en tiempo real.","fr":"Permet aux agents d''automatiser la révision et les tests de code en envoyant des scripts de demande JS pour le flux de mise en surbrillance de l''aperçu, en utilisant le chargement de .env et les notes de protocole pour les handshakes de pont d''origine croisée, et en prenant en charge le déploiement indépendant avec un moniteur en temps réel.","de":"Ermächtigt Agenten, Code-Überprüfung und -Test zu automatisieren, indem JS-Anfrage-Skripte für den Vorschau-Hervorhebungs-Fluss geliefert werden, .env-Ladung und Protokollnotizen für Cross-Origin-Brückenhandschakes genutzt werden und eine unabhängige Bereitstellung mit Echtzeit-Überwachung unterstützt wird.","pt":"Habilita os agentes a automatizar a revisão e teste de código, enviando scripts de solicitação JS para fluxo de destaque de visualização, utilizando carregamento .env e notas de protocolo para apertos de mão de ponte de origem cruzada, e suportando implantação independente com monitoramento em tempo real.","ru":"Наделяет агентов возможностью автоматизировать проверку и тестирование кода, отправляя скрипты запросов JS для потока подсветки предпросмотра, используя загрузку .env и заметки протокола для рукопожатия моста пересечения источников, и поддерживая независимую установку с мониторингом в реальном времени.","ar":"تمكين الوكلاء من توفير مراجعة واختبار الكود آليًا من خلال شحن نصوص طلب جافا سكريبت لمعالجة تدفق المعاينة، واستخدام تحميل .env ومذكرات البروتوكول ل握 الأيدي من جسر الأصل العابر، ودعم النشر المستقل مع مراقبة الوقت الفعلي."},"useCases":{"en":["Automating code reviews with real-time preview status checks","Debugging JavaScript applications with highlight commands and dependency installation","Streamlining development workflows with start and stop preview capabilities"],"zh":["使用实时预览状态检查自动化代码审查","使用高亮命令和依赖项安装调试JavaScript应用程序","使用开始和停止预览功能简化开发工作流"],"ja":["リアルタイムのプレビュー状態チェックを使用してコードレビューを自動化する","ハイライトコマンドと依存関係のインストールを使用してJavaScriptアプリケーションをデバッグする","開始と停止のプレビュー機能を使用して開発ワークフローを簡素化する"],"ko":["실시간 미리 보기 상태 확인을 사용하여 코드 검토를 자동화하는 것","강조 명령과 종속성 설치를 사용하여 자바스크립트 애플리케이션을 디버깅하는 것","시작 및 중지 미리 보기 기능을 사용하여 개발 워크플ロー簡素化"],"es":["Automatizar las revisiones de código con comprobaciones de estado de vista previa en tiempo real","Depurar aplicaciones JavaScript con comandos de resaltado e instalación de dependencias","Optimizar flujos de trabajo de desarrollo con capacidades de vista previa de inicio y detención"],"fr":["Automatiser les révisions de code avec des vérifications d''état d''aperçu en temps réel","Déboguer les applications JavaScript avec des commandes de mise en surbrillance et d''installation de dépendances","Optimiser les flux de travail de développement avec des capacités d''aperçu de démarrage et d''arrêt"],"de":["Automatisieren von Code-Überprüfungen mit Echtzeit-Vorschau-Status-Prüfungen","Debuggen von JavaScript-Anwendungen mit Hervorhebungsbefehlen und Abhängigkeitsinstallation","Optimieren von Entwicklungsworkflows mit Start- und Stopp-Vorschau-Funktionen"],"pt":["Automatizar revisões de código com verificações de status de visualização em tempo real","Depurar aplicações JavaScript com comandos de destaque e instalação de dependências","Racionalizar fluxos de trabalho de desenvolvimento com capacidades de visualização de início e parada"],"ru":["Автоматизировать проверку кода с проверками статуса предпросмотра в реальном времени","Отлаживать приложения JavaScript с командами подсветки и установкой зависимостей","Оптимизировать рабочие процессы разработки с возможностями предпросмотра запуска и остановки"],"ar":["توفير مراجعة الكود آليًا مع فحص حالة المعاينة في الوقت الفعلي","تصحيح أخطاء تطبيقات جافا سكريبت بأوامر التأكيد وتثبيت التبعيات","تبسيط سير عمل التطوير مع إمكانيات المعاينة لتشغيل وايقاف التشغيل"]},"limitations":{"en":["Requires JavaScript environment for script execution","Dependent on correct .env loading for configuration","Limited to supporting protocols noted for cross-origin bridge handshakes"],"zh":["需要JavaScript环境来执行脚本","依赖于正确的.env加载来配置","仅限于支持跨源桥接握手的协议"],"ja":["スクリプトを実行するためにJavaScript環境が必要",".envのロードが正しく行われないと構成できない","クロスオリジンブリッジのハンドシェイクをサポートするプロトコルに限定される"],"ko":["스크립트를 실행하기 위해 자바스크립트 환경이 필요",".env 로드가 올바르지 않으면 구성할 수 없음","크로스 오리진 브리지 핸드 셰이크를 지원하는 프로토콜로 제한"],"es":["Requiere un entorno de JavaScript para la ejecución de scripts","Depende de la carga correcta de .env para la configuración","Limitado a admitir protocolos anotados para handshakes de puente de origen cruzado"],"fr":["Nécessite un environnement JavaScript pour l''exécution de scripts","Dépend de la charge correcte de .env pour la configuration","Limité à prendre en charge les protocoles notés pour les handshakes de pont d''origine croisée"],"de":["Benötigt eine JavaScript-Umgebung für die Skriptausführung","Hängt von der korrekten .env-Ladung für die Konfiguration ab","Begrenzt auf die Unterstützung von Protokollen, die für Cross-Origin-Brückenhandschakes annotiert sind"],"pt":["Exige ambiente JavaScript para execução de scripts","Depende do carregamento correto .env para configuração","Limitado a protocolos observados para apertos de mão de ponte de origem cruzada"],"ru":["Требует среды JavaScript для выполнения скриптов","Зависит от правильной загрузки .env для настройки","Ограничен поддерживаемыми протоколами для рукопожатия моста пересечения источников"],"ar":["يتطلب بيئة جافا سكريبت لتشغيل النصوص البرمجية","يعتمد على تحميل .env الصحيح للتهيئة","محدود بالبروتوكولات المدعومة ل握 الأيدي من جسر الأصل العابر"]},"version":4},"contentHash":"f7781b3e00e114c07474726098be97544129f7c72e850bc44e3df76fa964331f","qualityScore":39}');
