INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CJHarmath/claude-agents-skills/react-performance', 'react-performance', 'CJHarmath', 'claude-agents-skills', 'community', 'react-performance CJHarmath claude-agents-skills community React-Performance is a skill that helps developers optimize React applications by minimizing unnecessary re-renders and computations. It benefits developers building performant web applications. React性能优化是通过理解React的渲染行为和使用memoization等技术来实现的 Reactパフォーマンス最適化は、Reactのレンダリングの動作を理解し、メモ化などのテクニックを使用することで実現できます React 성능 최적화는 React의 렌더링 동작을 이해하고, 메모화 등의 기술을 사용하여 달성할 수 있습니다 Optimiza el rendimiento de tus aplicaciones React con técnicas de memoización y optimización de listas Améliorez les performances de vos applications React avec des techniques de mémorisation et d''optimisation de listes Verbessern Sie die Leistung Ihrer React-Anwendungen mit Memoisierungstechniken und Liste-Optimierungen Otimização de desempenho do React com memoização e técnicas de otimização de lista Оптимизация производительности React с помощью мемоизации и техник оптимизации списка تحسين أداء رياكت باستخدام تقنيات التذكير والت최 ưuية للقائمة how to use react-performance react-performance optimization techniques react-performance vs react-optimization react-performance setup guide what is react-performance react-performance install react-performance alternative react-performance best practices react-performance tutorial react-performance examples React性能优化 memoization useMemo React渲染行为 React列表优化 React表格优化 减少重新渲染 React开发 React性能设置 Utilizes useMemo for memoizing expensive calculations Optimizes lists through filtering and sorting Minimizes unnecessary re-renders for faster rendering Improves application performance through efficient computation handling Applies memoization patterns for optimized rendering behavior Supports optimized rendering for complex React components React-performance is a set of techniques and patterns for improving the rendering speed and efficiency of React applications, including memoization and optimization of lists and computations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ksoichiro/ChronoDawn/doc-maintenance', 'community', 'ksoichiro', 'ChronoDawn', 'ksoichiro/ChronoDawn', 'doc-maintenance', 0, 0, 39, '2026-03-08T01:57:15.408Z', '2026-03-08T02:06:57.363Z', 'dbe8e117d7887acb86f2b81d30de994a1732f20327b271d7073704bbf243668c', '{"id":"ksoichiro/ChronoDawn/doc-maintenance","name":"doc-maintenance","description":{"en":"doc-maintenance is a skill that automates documentation updates for Minecraft modders, supporting tasks like version updates and release preparations. It benefits developers working with Fabric and NeoForge.","zh":"Doc-Maintenance 是一个帮助您更新 Minecraft 依赖版本、添加新内容和准备发布的技能。它支持 Fabric 和 NeoForge。","ja":"Doc-Maintenance は、Minecraft 依存関係バージョンを更新し、新しいコンテンツを追加し、リリースを準備するのに役立つスキルです。Fabric と NeoForge をサポートしています。","ko":"Doc-Maintenance는 Minecraft 종속성 버전을 업데이트하고 새로운 콘텐츠를 추가하고 출시를 준비하는 데 도움이 되는 기능입니다. Fabric와 NeoForge를 지원합니다.","es":"La habilidad doc-maintenance ayuda a mantener la documentación actualizada al cambiar versiones, agregar contenido o preparar lanzamientos en proyectos de Minecraft","fr":"La compétence doc-maintenance aide à maintenir la documentation à jour lors des changements de version, de l''ajout de contenu ou de la préparation de lancements dans les projets Minecraft","de":"Die Fähigkeit doc-maintenance hilft bei der Aktualisierung von Dokumentationen beim Ändern von Versionen, Hinzufügen von Inhalten oder Vorbereiten von Veröffentlichungen in Minecraft-Projekten","pt":"O doc-maintenance é uma habilidade que ajuda a manter a documentação atualizada para Minecraft, incluindo atualizações de versão e dependências","ru":"ИИ Агент doc-maintenance помогает поддерживать актуальную документацию для Minecraft, включая обновления версий и зависимостей","ar":"أداة الذكاء الاصطناعي doc-maintenance تساعد في صيانة الوثائق الحالية لمinecraft، بما في ذلك تحديثات الإصدارات وا