INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jscriptcoder/jshack.me/expectations', 'expectations', 'jscriptcoder', 'jshack.me', 'community', 'expectations jscriptcoder jshack.me community Expectations is a skill that helps AI agents work efficiently with code by thinking deeply, understanding context, and refactoring with value. It benefits developers working on Capture the Flag games. 期望值是AI工具的关键组成部分，涉及深度思考、理解上下文和重构代码等技术细节 期待値はAIエージェントの重要なコンポーネントであり、深い思考、コンテキストの理解、コードのリファクタリングなどの技術的詳細が含まれる 期待값은 AI 에이전트의 핵심 구성 요소로, 깊은思考, 문맥 이해, 코드 리팩토링 등을 포함하는 기술적 세부 정보를 다룹니다 Las herramientas de expectativas ayudan a los desarrolladores a trabajar de manera más efectiva con código, entendiendo el contexto y refactorizando cuando sea necesario Les outils d''expectatives aident les développeurs à travailler de manière plus efficace avec le code, en comprenant le contexte et en refactorisant lorsque nécessaire Erwartungstools helfen Entwicklern, effektiver mit Code zu arbeiten, indem sie den Kontext verstehen und refactorisieren, wenn erforderlich As expectativas são fundamentais para o desenvolvimento de código de qualidade. Aprenda a trabalhar com expectativas de forma eficaz Ожидания являются важнейшим аспектом разработки качественного кода. Узнайте, как эффективно работать с ожиданиями التوقعات أساسية لتنمية код جيد. تعلم كيفية العمل مع التوقعات بفعالية how to use expectations expectations setup guide expectations alternative what is expectations expectations vs coding standards expectations install for AI agents expectations best practices for developers capture the flag game development code refactoring with expectations AI工具 期望值设置 代码编辑 代码重构 项目文档 第一原理 代码性能优化 AI开发最佳实践 Thinks deeply before making code edits Assesses refactoring after every green build Keeps project docs current via CLAUDE.md updates Asks clarifying questions for ambiguous requirements Thinks from first principles to avoid assumptions Understands the full context of code and requirements Expectations is a set of guidelines for working with code, emphasizing deep thinking, context understanding, and value-added refactoring.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('withakay/ito/ito-tasks', 'community', 'withakay', 'ito', 'withakay/ito', 'ito-tasks', 0, 0, 39, '2026-03-08T01:57:15.386Z', '2026-03-08T02:07:04.097Z', 'fb0308b784bee445f70e701de5d3092f85840eddf7499a42f293817d79aa9171', '{"id":"withakay/ito/ito-tasks","name":"ito-tasks","description":{"en":"The ito-tasks skill provides AI assisted engineering workflow tools, enabling developers to track and update implementation tasks efficiently. It benefits developers working on complex projects.","zh":"ito-tasks提供AI Assisted工程工作流工具，使用ito tasks CLI管理实现任务","ja":"ito-tasksはAIエージェントによるエンジニアリングワークフローツールを提供します。ito tasks CLIを使用して実装タスクを管理します","ko":"ito-tasks는 AI 에이전트 엔지니어링 워크플로우 도구를 제공합니다. ito tasks CLI를 사용하여 구현 작업을 관리합니다","es":"ito-tasks es una herramienta de flujo de trabajo de ingeniería asistida por IA que utiliza CLI para realizar seguimiento y actualizar tareas de implementación.","fr":"ito-tasks est un outil de workflow d''ingénierie assisté par l''IA qui utilise CLI pour suivre et mettre à jour les tâches de mise en œuvre.","de":"ito-tasks ist ein KI-gestütztes Ingenieur-Workflow-Tool, das CLI verwendet, um Implementierungsaufgaben zu verfolgen und zu aktualisieren.","pt":"O ito-tasks é uma ferramenta de fluxo de trabalho de engenharia assistida por IA que ajuda a gerenciar tarefas de implementação. Use o CLI ito tasks para acompanhar e atualizar tarefas.","ru":"ИИ Агенты ito-tasks - это инструмент рабочего процесса инженерии, помогающий управлять задачами реализации. Используйте CLI ito tasks для отслеживания и обновления задач.","ar":"أدوات ito-tasks هي أدوات تدفق عمل هندسي مدعومة بالذكاء الاصطناعي تساعد في إدارة مهام التنفيذ. استخدم CLI ito tasks لتتبع وتحديث المهام."},"seo":{"title":{"en":"ito-tasks: AI Assisted Engineering Workflow Tools Setup G...","zh":"ito-tasks_SETUP GUIDE：AI Assisted 工程工作流工具","ja":"ito-tasks セットアップガイド：AIエージェントによるエンジニアリングワークフローツール","ko":"ito-tasks 설정 가이드: AI 에이전트 엔지니어링 워크플로우 도구","es":"Guía de configuración de ito-tasks para flujos de trabajo...","fr":"Guide de mise en place d''ito-tasks pour les outils de wor...","de":"Einrichtungsleitfaden für ito-tasks zur Unterstützung von...","pt":"Guia de Configuração do ito-tasks: Ferramentas de Fluxo d...","ru":"Настройка ИИ Агентов ito-tasks: Инструменты рабочего проц...","ar":"دليل إعداد ito-tasks: أدوات تدفق عمل هندسي مدعومة بالذكاء..."},"description":{"en":"Discover how to streamline your engineering workflow with ito-tasks. Learn how to track and update implementation tasks with the ito tasks CLI and unlock eff...","zh":"使用ito tasks CLI管理实现任务，支持增强的tasks.md功能，包括start、shelve、unshelve和add","ja":"ito tasks CLIを使用して実装タスクを管理します。tasks.mdの強化された機能をサポートしています","ko":"ito tasks CLI를 사용하여 구현 작업을 관리합니다. tasks.md의 강화된 기능을 지원합니다","es":"Descubre cómo utilizar ito-tasks para mejorar tus flujos de trabajo de ingeniería con herramientas de IA. Obtén información sobre CLI y comandos.","fr":"Découvrez comment utiliser ito-tasks pour améliorer vos flux de travail d''ingénierie avec des outils d''IA. Obtenez des informations sur CLI et des commandes.","de":"Erfahren Sie, wie Sie ito-tasks verwenden können, um Ihre Ingenieur-Arbeitsabläufe mit KI-Tools zu verbessern. Erhalten Sie Informationen über CLI und Befehle.","pt":"Aprenda a usar o CLI ito tasks para acompanhar e atualizar tarefas de implementação para alterações no seu fluxo de trabalho de engenharia","ru":"Узнайте, как использовать CLI ito tasks для отслеживания и обновления задач реализации для изменений в вашем рабочем процессе инженерии","ar":"تعرف على كيفية استخدام CLI ito tasks لتتبع وتحديث مهام التنفيذ للتغييرات في تدفق عملك الهندسي"},"definition":{"en":"ito-tasks is a set of AI assisted engineering workflow tools that utilize the ito tasks CLI to manage implementation tasks.","zh":"ito-tasks是一种AI Assisted工程工作流工具，使用CLI管理实现任务","ja":"ito-tasksは、CLIを使用して実装タスクを管理するAIエージェントによるエンジニアリングワークフローツールです","ko":"ito-tasks는 CLI를 사용하여 구현 작업을 관리하는 AI 에이전트 엔지니어링 워크플로우 도구입니다","es":"ito-tasks es una herramienta de flujo de trabajo que utiliza comandos CLI para gestionar tareas de implementación en proyectos de ingeniería.","fr":"ito-tasks est un outil de workflow qui utilise des commandes CLI pour gérer les tâches de mise en œuvre dans les projets d''ingénierie.","de":"ito-tasks ist ein Workflow-Tool, das CLI-Befehle verwendet, um Implementierungsaufgaben in Ingenieurprojekten zu verwalten.","pt":"O ito-tasks é uma ferramenta de fluxo de trabalho de engenharia que usa IA para ajudar a gerenciar tarefas de implementação","ru":"ИИ Агенты ito-tasks - это инструмент рабочего процесса инженерии, использующий ИИ для помощи в управлении задачами реализации","ar":"أدوات ito-tasks هي أدوات تدفق عمل هندسي تستخدم الذكاء الاصطناعي لمساعدة في إدارة مهام التنفيذ"},"features":{"en":["Utilizes the ito tasks CLI to track and update implementation tasks","Supports enhanced tasks.md with start, shelve, unshelve, and add capabilities","Compatible with checkbox-only tasks.md in compat mode","Allows starting and completing tasks by 1-based index","Provides common commands such as ito tasks status, ito tasks next, and ito tasks ready"],"zh":["支持增强的tasks.md功能","包括start、shelve、unshelve和add功能","使用ito tasks CLI管理实现任务","兼容模式支持checkbox-only tasks.md","支持1-based index的任务开始和完成"],"ja":["tasks.mdの強化された機能をサポートしています","start、shelve、unshelve、add機能を含みます","ito tasks CLIを使用して実装タスクを管理します","兼容モードでcheckbox-only tasks.mdをサポートしています","1-based indexのタスク開始と完了をサポートしています"],"ko":["tasks.md의 강화된 기능을 지원합니다","start, shelve, unshelve, add 기능을 포함합니다","ito tasks CLI를 사용하여 구현 작업을 관리합니다","兼容 모드에서 checkbox-only tasks.md를 지원합니다","1-based index의 작업 시작과 완성을 지원합니다"],"es":["Utiliza CLI para realizar seguimiento y actualizar tareas de implementación","Soporta comandos como `start`, `shelve`, `unshelve` y `add`","Compatibilidad con formato de tarea de solo casilla","Soporta inicio y finalización de tareas por índice de base 1","Integración con `tasks.md` para una gestión de tareas más eficiente"],"fr":["Utilise CLI pour suivre et mettre à jour les tâches de mise en œuvre","Prend en charge les commandes comme `start`, `shelve`, `unshelve` et `add`","Compatibilité avec le format de tâche de case à cocher uniquement","Prend en charge le démarrage et la fin des tâches par index de base 1","Intégration avec `tasks.md` pour une gestion de tâches plus efficace"],"de":["Verwenden Sie CLI, um Implementierungsaufgaben zu verfolgen und zu aktualisieren","Unterstützt Befehle wie `start`, `shelve`, `unshelve` und `add`","Kompatibilität mit Checkbox-Format","Unterstützt Start und Abschluss von Aufgaben über 1-basierten Index","Integration mit `tasks.md` für effizientere Aufgabenverwaltung"],"pt":["Suporte a tarefas de implementação com start, shelve, unshelve e add","Compatibilidade com tasks.md em modo compat","Uso de CLI ito tasks para acompanhar e atualizar tarefas","Suporte a tarefas de checkbox-only em modo compat","Comandos comuns: ito tasks status, ito tasks next, ito tasks ready"],"ru":["Поддержка задач реализации с start, shelve, unshelve и add","Совместимость с tasks.md в режиме совместимости","Использование CLI ito tasks для отслеживания и обновления задач","Поддержка задач checkbox-only в режиме совместимости","Общие команды: ito tasks status, ito tasks next, ito tasks ready"],"ar":["دعم مهام التنفيذ مع 开始، وضع على الرف، إزالة من الرف وإضافة","التوافق مع tasks.md في وضع التوافق","استخدام CLI ito tasks لتتبع وتحديث المهام","دعم مهام checkbox-only في وضع التوافق","الأوامر الشائعة: ito tasks status، ito tasks next، ito tasks ready"]},"keywords":{"en":["how to use ito-tasks","ito-tasks setup guide","ito-tasks alternative","ito-tasks vs engineering workflow tools","ito-tasks install","what is ito-tasks","ito-tasks CLI tutorial","ito-tasks for AI agents","engineering workflow management with ito-tasks"],"zh":["ito-tasks","AI Assisted 工程工作流工具","ito tasks CLI","tasks.md","工程工作流管理","AI 工程工具","CLI 工具"],"ja":["ito-tasks","AIエージェント","エンジニアリングワークフローツール","ito tasks CLI","tasks.md","エンジニアリングワークフロー管理","AIエンジニアリングツール","CLIツール"],"ko":["ito-tasks","AI 에이전트","엔지니어링 워크플로우 도구","ito tasks CLI","tasks.md","엔지니어링 워크플로우 관리","AI 엔지니어링 도구","CLI 도구"],"es":["ito-tasks","herramientas de flujo de trabajo de ingeniería","IA asistida","CLI","gestión de tareas","tasks.md","comandos de inicio y finalización","índice de base 1","compatibilidad con formato de casilla"],"fr":["ito-tasks","outils de workflow d''ingénierie","IA assistée","CLI","gestion de tâches","tasks.md","commandes de démarrage et de fin","index de base 1","compatibilité avec le format de case à cocher"],"de":["ito-tasks","Ingenieur-Workflow-Tools","KI-gestützt","CLI","Aufgabenverwaltung","tasks.md","Start- und Endbefehle","1-basierter Index","Kompatibilität mit Checkbox-Format"],"pt":["ito-tasks","ferramentas de fluxo de trabalho de engenharia","IA","CLI ito tasks","tasks.md","gerenciamento de tarefas de implementação"],"ru":["ИИ Агенты ito-tasks","инструменты рабочего процесса инженерии","ИИ","CLI ito tasks","tasks.md","управление задачами реализации"],"ar":["أدوات ito-tasks","أدوات تدفق عمل هندسي","الذكاء الاصطناعي","CLI ito tasks","tasks.md","إدارة مهام التنفيذ"]}},"owner":"withakay","repo":"ito","repoPath":"withakay/ito","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.386Z","topics":[],"category":"community","skillMd":{"name":"ito-tasks","description":"Use Ito tasks CLI to manage tasks.md (status/next/start/complete/shelve/add).","bodyPreview":"Use the `ito tasks` CLI to track and update implementation tasks for a change.\n\n**Rules**\n\n- Prefer `ito tasks ...` over manual editing of `tasks.md`.\n- Enhanced tasks.md supports `start`, `shelve`, `unshelve`, and `add`.\n- Checkbox-only tasks.md is supported in compat mode (supports in-progress via `[~]` / `ito tasks start`, but no shelving); start/complete tasks by 1-based index.\n\n**Common Commands**\n\n```bash\nito tasks status <change-id>\nito tasks next <change-id>\nito tasks ready","body":"Use the `ito tasks` CLI to track and update implementation tasks for a change.\n\n**Rules**\n\n- Prefer `ito tasks ...` over manual editing of `tasks.md`.\n- Enhanced tasks.md supports `start`, `shelve`, `unshelve`, and `add`.\n- Checkbox-only tasks.md is supported in compat mode (supports in-progress via `[~]` / `ito tasks start`, but no shelving); start/complete tasks by 1-based index.\n\n**Common Commands**\n\n```bash\nito tasks status <change-id>\nito tasks next <change-id>\nito tasks ready                               # Show ready tasks across ALL changes\nito tasks ready <change-id>                   # Show ready tasks for a specific change\nito tasks ready --json                        # JSON output for automation\nito tasks start <change-id> <task-id>\nito tasks complete <change-id> <task-id>\nito tasks complete <change-id> <index>\nito tasks shelve <change-id> <task-id>\nito tasks unshelve <change-id> <task-id>\nito tasks add <change-id> \"<task name>\" --wave <n>\nito tasks show <change-id>\n```\n\n**If tasks.md is missing**\n\n- Create enhanced tracking file: `ito tasks init <change-id>`\n\n**If the user asks \"what should I do next?\"**\n\n- If working on a specific change: Run `ito tasks next <change-id>`\n- If looking for any ready work: Run `ito tasks ready` to see all actionable tasks\n- Follow the printed Action/Verify/Done When for the chosen task.\n\n**Guardrails**\n\n- If a task is blocked, run `ito tasks status <change-id>` and either resolve blockers or shelve the task (enhanced only).\n- If `ito tasks shelve` fails because the file is checkbox-only, explain that checkbox compat mode does not support shelving.\n- If `ito tasks start` fails in compat mode, it is usually because the task id is not a 1-based index, or another task is already in-progress.\n"},"lastSynced":"2026-03-08T02:07:04.097Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined engineering workflow management through CLI commands like `ito tasks status` and `ito tasks next`.","zh":"适合需要通过CLI命令（如`ito tasks status`和`ito tasks next`）简化工程工作流管理的开发代理。","ja":"CLIコマンド（例：`ito tasks status`および`ito tasks next`）を使用してエンジニアリングワークフローの管理を簡素化する必要がある開発エージェントに最適。","ko":"CLI 명령어(`ito tasks status` 및 `ito tasks next`와 같은)를 통해 엔지니어링 워크플로우 관리를 간소화해야 하는 개발 에이전트에게 적합합니다.","es":"Ideal para agentes de desarrollo que requieren una gestión de flujo de trabajo de ingeniería optimizada a través de comandos de CLI como `ito tasks status` y `ito tasks next`.","fr":"Idéal pour les agents de développement nécessitant une gestion de workflow d''ingénierie rationalisée via des commandes CLI comme `ito tasks status` et `ito tasks next`.","de":"Ideal für Entwicklungsmittel, die eine optimierte Engineering-Workflow-Verwaltung über CLI-Befehle wie `ito tasks status` und `ito tasks next` erfordern.","pt":"Ideal para Agentes de Desenvolvimento que requerem gerenciamento de fluxo de trabalho de engenharia simplificado por meio de comandos CLI como `ito tasks status` e `ito tasks next`.","ru":"Идеально для агентов разработки, требующих упрощенного управления рабочим процессом инженерии с помощью команд CLI, таких как `ito tasks status` и `ito tasks next`.","ar":"مثالي للوكلاء التطويين الذين يتطلبون إدارة تدفق عمل هندسي مبسط من خلال أوامر CLI مثل `ito tasks status` و `ito tasks next`."},"recommendation":{"en":"Empowers agents to efficiently track and update implementation tasks using enhanced `tasks.md` features like `start`, `shelve`, and `unshelve`, while supporting checkbox-only tasks in compat mode for flexible project management.","zh":"赋予代理高效地跟踪和更新实现任务的能力，使用增强的`tasks.md`功能（如`start`、`shelve`和`unshelve`），同时支持兼容模式下的复选框仅任务，以实现灵活的项目管理。","ja":"エージェントが実装タスクを効率的に追跡および更新できるようにし、`tasks.md`の強化された機能（例：`start`、`shelve`、`unshelve`）を使用し、チェックボックスのみのタスクに対するコンパチブルモードをサポートして、柔軟なプロジェクト管理を可能にします。","ko":"에이전트가 구현 작업을 효율적으로 추적 및 업데이트할 수 있도록 하며, `tasks.md`의 기능 강화(`start`, `shelve`, `unshelve` 등)를 사용하며, 체크박스만의 작업에 대한 호환 모드를 지원하여 유연한 프로젝트 관리를 가능하게 합니다.","es":"Habilita a los agentes a rastrear y actualizar tareas de implementación de manera eficiente utilizando características mejoradas de `tasks.md` como `start`, `shelve` y `unshelve`, al mismo tiempo que admite tareas de casilla de verificación en modo de compatibilidad para una gestión de proyectos flexible.","fr":"Permet aux agents de suivre et de mettre à jour les tâches d''implémentation de manière efficace en utilisant des fonctionnalités améliorées de `tasks.md` comme `start`, `shelve` et `unshelve`, tout en prenant en charge les tâches de case à cocher en mode de compatibilité pour une gestion de projet flexible.","de":"Ermöglicht es Agenten, Implementierungsaufgaben effizient zu verfolgen und zu aktualisieren, indem sie erweiterte `tasks.md`-Funktionen wie `start`, `shelve` und `unshelve` verwenden, während sie gleichzeitig Checkbox-Aufgaben im Kompatibilitätsmodus für eine flexible Projektverwaltung unterstützen.","pt":"Habilita os agentes a rastrear e atualizar tarefas de implementação de forma eficiente usando recursos aprimorados do `tasks.md` como `start`, `shelve` e `unshelve`, além de suportar tarefas somente de caixa de seleção no modo compatível para gerenciamento de projeto flexível.","ru":"Наделяет агентов возможностью эффективно отслеживать и обновлять задачи реализации с помощью улучшенных функций `tasks.md`, таких как `start`, `shelve` и `unshelve`, а также поддерживает задачи только с флажками в режиме совместимости для гибкого управления проектом.","ar":"يمنح الوكلاء القدرة على تتبع وتحديث مهام التنفيذ بفعالية باستخدام ميزات محسنة من `tasks.md` مثل `start` و `shelve` و `unshelve`، بالإضافة إلى دعم المهام فقط مع مربع اختيار في وضع التوافق لإدارة مشروع مرنة."},"useCases":{"en":["Tracking implementation tasks for complex projects","Updating task status using `ito tasks` CLI commands","Managing tasks with `start`, `shelve`, and `unshelve` features"],"zh":["复杂项目的实现任务跟踪","使用`ito tasks` CLI命令更新任务状态","使用`start`、`shelve`、`unshelve`功能管理任务"],"ja":["複雑なプロジェクトの実装タスクの追跡","`ito tasks` CLIコマンドを使用してタスクのステータスを更新","`start`、`shelve`、`unshelve`機能を使用してタスクを管理"],"ko":["복잡한 프로젝트의 구현 작업 추적","`ito tasks` CLI 명령어를 사용하여 작업 상태 업데이트","`start`, `shelve`, `unshelve` 기능을 사용하여 작업 관리"],"es":["Seguimiento de tareas de implementación para proyectos complejos","Actualización del estado de la tarea utilizando comandos de CLI `ito tasks`","Gestión de tareas con características `start`, `shelve` y `unshelve`"],"fr":["Suivi des tâches d''implémentation pour les projets complexes","Mise à jour de l''état de la tâche en utilisant des commandes CLI `ito tasks`","Gestion des tâches avec des fonctionnalités `start`, `shelve` et `unshelve`"],"de":["Nachverfolgung von Implementierungsaufgaben für komplexe Projekte","Aktualisierung des Aufgabenstatus mithilfe von CLI-Befehlen `ito tasks`","Verwaltung von Aufgaben mit Funktionen `start`, `shelve` und `unshelve`"],"pt":["Rastrear tarefas de implementação para projetos complexos","Atualizar status de tarefas usando comandos CLI `ito tasks`","Gerenciar tarefas com recursos `start`, `shelve` e `unshelve`"],"ru":["Отслеживать задачи реализации для сложных проектов","Обновлять статус задач с помощью команд CLI `ito tasks`","Управлять задачами с помощью функций `start`, `shelve` и `unshelve`"],"ar":["تتبع مهام التنفيذ لمشاريع معقدة","تحديث حالة المهام باستخدام أوامر CLI `ito tasks`","إدارة المهام باستخدام ميزات `start` و `shelve` و `unshelve`"]},"limitations":{"en":["Requires `ito tasks` CLI","Compatibility mode has limited features like no shelving for checkbox-only tasks"],"zh":["需要`ito tasks` CLI","兼容模式下功能有限，如复选框仅任务不支持暂存"],"ja":["`ito tasks` CLIが必要","コンパチブルモードでは機能が制限されており、チェックボックスのみのタスクではシェルブがサポートされません"],"ko":["`ito tasks` CLI가 필요","호환 모드에서는 기능이 제한되어 체크박스만의 작업에서는シェル브가 지원되지 않습니다"],"es":["Requiere `ito tasks` CLI","El modo de compatibilidad tiene características limitadas como sin almacenamiento para tareas de casilla de verificación"],"fr":["Nécessite `ito tasks` CLI","Le mode de compatibilité a des fonctionnalités limitées comme pas de mise en attente pour les tâches de case à cocher"],"de":["Benötigt `ito tasks` CLI","Der Kompatibilitätsmodus hat begrenzte Funktionen wie kein Shelving für Checkbox-Aufgaben"],"pt":["Requer `ito tasks` CLI","Modo de compatibilidade tem recursos limitados, como não arquivar tarefas somente de caixa de seleção"],"ru":["Требует `ito tasks` CLI","Режим совместимости имеет ограниченные функции, такие как отсутствие архивации задач только с флажками"],"ar":["يتطلب `ito tasks` CLI","الوضع التوافقي له ميزات محدودة، مثل عدم وجود تarchiving للمهام فقط مع مربع اختيار"]},"version":4},"contentHash":"fb0308b784bee445f70e701de5d3092f85840eddf7499a42f293817d79aa9171","qualityScore":39}');
