INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('withakay/ito/ito-tasks', 'ito-tasks', 'withakay', 'ito', 'community', 'ito-tasks withakay ito community The ito-tasks skill provides AI assisted engineering workflow tools, enabling developers to track and update implementation tasks efficiently. It benefits developers working on complex projects. ito-tasks提供AI Assisted工程工作流工具，使用ito tasks CLI管理实现任务 ito-tasksはAIエージェントによるエンジニアリングワークフローツールを提供します。ito tasks CLIを使用して実装タスクを管理します ito-tasks는 AI 에이전트 엔지니어링 워크플로우 도구를 제공합니다. ito tasks CLI를 사용하여 구현 작업을 관리합니다 ito-tasks es una herramienta de flujo de trabajo de ingeniería asistida por IA que utiliza CLI para realizar seguimiento y actualizar tareas de implementación. ito-tasks est un outil de workflow d''ingénierie assisté par l''IA qui utilise CLI pour suivre et mettre à jour les tâches de mise en œuvre. ito-tasks ist ein KI-gestütztes Ingenieur-Workflow-Tool, das CLI verwendet, um Implementierungsaufgaben zu verfolgen und zu aktualisieren. O ito-tasks é uma ferramenta de fluxo de trabalho de engenharia assistida por IA que ajuda a gerenciar tarefas de implementação. Use o CLI ito tasks para acompanhar e atualizar tarefas. ИИ Агенты ito-tasks - это инструмент рабочего процесса инженерии, помогающий управлять задачами реализации. Используйте CLI ito tasks для отслеживания и обновления задач. أدوات ito-tasks هي أدوات تدفق عمل هندسي مدعومة بالذكاء الاصطناعي تساعد في إدارة مهام التنفيذ. استخدم CLI ito tasks لتتبع وتحديث المهام. how to use ito-tasks ito-tasks setup guide ito-tasks alternative ito-tasks vs engineering workflow tools ito-tasks install what is ito-tasks ito-tasks CLI tutorial ito-tasks for AI agents engineering workflow management with ito-tasks ito-tasks AI Assisted 工程工作流工具 ito tasks CLI tasks.md 工程工作流管理 AI 工程工具 CLI 工具 Utilizes the ito tasks CLI to track and update implementation tasks Supports enhanced tasks.md with start, shelve, unshelve, and add capabilities Compatible with checkbox-only tasks.md in compat mode Allows starting and completing tasks by 1-based index Provides common commands such as ito tasks status, ito tasks next, and ito tasks ready ito-tasks is a set of AI assisted engineering workflow tools that utilize the ito tasks CLI to manage implementation tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bentefay/moneyflow/crdt', 'community', 'bentefay', 'moneyflow', 'bentefay/moneyflow', 'crdt', 0, 0, 39, '2026-03-08T01:57:15.413Z', '2026-03-08T02:07:06.854Z', '0385d5d0542e052a2a6ce4acf1aa63bb44003528261024c6e2daa785db3f5aae', '{"id":"bentefay/moneyflow/crdt","name":"crdt","description":{"en":"crdt is a web app that helps developers track financial transactions efficiently. It benefits developers who need to manage financial data with precision.","zh":"CRDT 是一个 Web 应用，帮助您理解钱的流向。它遵循特定的规则，如_draft-样式突变和软删除","ja":"CRDT は、Web アプリの状態管理を最適化するためのガイドです。Draft スタイルの変異とソフト削除を含む重要なルールを学びましょう","ko":"CRDT는 웹 애플리케이션 상태 관리를 최적화하기 위한 가이드입니다._draft-스타일 변이와 소프트 삭제를 포함하는 중요한 규칙을 학습하세요","es":"crdt es una aplicación web que ayuda a entender el flujo de dinero mediante mutaciones de estilo borrador y seguimiento de cambios","fr":"crdt est une application web qui aide à comprendre le flux d''argent via des mutations de style brouillon et un suivi des modifications","de":"crdt ist eine Webanwendung, die hilft, den Geldfluss durch Mutationen im Entwurfsstil und Änderungsverfolgung zu verstehen","pt":"O CRDT é uma aplicação web que ajuda a entender onde seu dinheiro está indo, com recursos como mutações de estilo de rascunho e acompanhamento de alterações","ru":"CRDT - это веб-приложение, которое помогает понять, куда уходят ваши деньги, с функциями, такими как мутации стиля черновика и отслеживание изменений","ar":"CRDT هو تطبيق ويب يساعد على فهم حيث يذهب أموالك، مع ميزات مثل الطرز التحريرية والتتبع التغييرات"},"seo":{"title":{"en":"crdt: Draft-Style Mutations Setup Guide | AI Agent Skill","zh":"CRDT 设置指南：优化 Web 应用状态管理","ja":"CRDT セットアップガイド：Web アプリの状態管理を最適化する","ko":"CRDT 설정 가이드: 웹 애플리케이션 상태 관리 최적화","es":"Guía de configuración de crdt para herramientas de inteli...","fr":"Guide de mise en place de crdt pour les outils d''agents IA","de":"Einrichtungsleitfaden für crdt bei KI-Tools","pt":"Guia de Configuração CRDT: Melhores Práticas para Ferrame...","ru":"Руководство по настройке CRDT: Лучшие практики для ИИ Аге...","ar":"دليل إعداد CRDT: أفضل الممارسات لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient money tracking with crdt! Learn how to implement draft-style mutations and optimize your financial data management","zh":"了解 CRDT 的关键规则和最佳实践，优化您的 Web 应用状态管理，包括_draft-样式突变和软删除","ja":"CRDT の重要なルールとベストプラクティスを学び、Web アプリの状態管理を最適化しましょう。Draft スタイルの変異とソフト削除を含みます","ko":"CRDT의 중요한 규칙과 최선의 방법을 학습하고 웹 애플리케이션 상태 관리를 최적화 하세요._draft-스타일 변이와 소프트 삭제를 포함합니다","es":"Aprende a implementar crdt en tus aplicaciones web para una gestión eficiente de transacciones","fr":"Découvrez comment mettre en œuvre crdt dans vos applications web pour une gestion efficace des transactions","de":"Erfahren Sie, wie Sie crdt in Ihren Webanwendungen implementieren, um Transaktionen effizient zu verwalten","pt":"Aprenda a configurar o CRDT corretamente com nossas dicas e melhores práticas para desenvolvedores, incluindo TypeScript e gerenciamento de estado","ru":"Узнайте, как правильно настроить CRDT с нашей помощью, включая советы и лучшие практики для разработчиков, с использованием TypeScript и управления состоянием","ar":"تعلم كيفية تكوين CRDT بشكل صحيح باستخدام نصائحنا وأفضل الممارسات للمطورين، بما في ذلك TypeScript وإدارة الحالة"},"definition":{"en":"crdt is a web application designed to help understand where money is going, utilizing draft-style mutations for efficient data management","zh":"CRDT 是一个 Web 应用状态管理工具，提供_draft-样式突变和软删除等功能","ja":"CRDT は、Web アプリの状態管理を最適化するためのツールです。Draft スタイルの変異とソフト削除を含みます","ko":"CRDT는 웹 애플리케이션 상태 관리를 최적화하기 위한 도구입니다._draft-스타일 변이와 소프트 삭제를 포함합니다","es":"crdt es un sistema de gestión de transacciones que utiliza mutaciones de estilo borrador y seguimiento de cambios","fr":"crdt est un système de gestion de transactions qui utilise des mutations de style brouillon et un suivi des modifications","de":"crdt ist ein Transaktionsmanagementsystem, das Mutationen im Entwurfsstil und Änderungsverfolgung verwendet","pt":"O CRDT é uma aplicação web que fornece recursos para gerenciar transações financeiras, incluindo mutações de estado e acompanhamento de alterações","ru":"CRDT - это веб-приложение, которое предоставляет функции для управления финансовыми транзакциями, включая мутации состояния и отслеживание изменений","ar":"CRDT هو تطبيق ويب يقدم ميزات لإدارة المعاملات المالية، بما في ذلك تحويلات الحالة والتتبع التغييرات"},"features":{"en":["Implements draft-style mutations using setState","Utilizes crypto.randomUUID() for unique ID generation","Supports soft deletes via deletedAt timestamp","Imports types from schema.ts for consistent data modeling","Enforces change tracking with in-place state mutations"],"zh":["Draft-样式突变","软删除","使用 crypto.randomUUID() 生成 ID","导入类型从 schema.ts","支持状态管理优化"],"ja":["Draft スタイルの変異","ソフト削除","crypto.randomUUID() を使用した ID 生成","schema.ts からの型のインポート","状態管理の最適化をサポート"],"ko":["_draft-스타일 변이","소프트 삭제","crypto.randomUUID()를 사용한 ID 생성","schema.ts에서 유형을 가져옵니다","상태 관리 최적화를 지원합니다"],"es":["Mutaciones de estilo borrador para actualizar transacciones","Seguimiento de cambios para detectar modificaciones","Uso de crypto.randomUUID() para generar IDs únicos","Eliminaciones suaves mediante la configuración de una marca de tiempo deletedAt","Importación de tipos desde schema.ts para mantener la consistencia"],"fr":["Mutations de style brouillon pour mettre à jour des transactions","Suivi des modifications pour détecter les changements","Utilisation de crypto.randomUUID() pour générer des IDs uniques","Suppressions douces via la configuration d''une marque de temps deletedAt","Importation de types depuis schema.ts pour maintenir la cohérence"],"de":["Mutationen im Entwurfsstil zum Aktualisieren von Transaktionen","Änderungsverfolgung zum Erkennen von Modifikationen","Verwendung von crypto.randomUUID() zum Generieren eindeutiger IDs","Weiche Löschungen durch Konfigurieren einer deletedAt-Zeitstempel","Import von Typen aus schema.ts zur Wahrung der Konsistenz"],"pt":["Mutações de estilo de rascunho com `setState`","Acompanhamento de alterações com `crypto.randomUUID()`","Suporte a soft deletes com `deletedAt` timestamp","Importação de tipos de `schema.ts`","Gerenciamento de estado com TypeScript"],"ru":["Мутации стиля черновика с `setState`","Отслеживание изменений с `crypto.randomUUID()`","Поддержка мягкого удаления с меткой времени `deletedAt`","Импорт типов из `schema.ts`","Управление состоянием с помощью TypeScript"],"ar":["الطرز التحريرية مع `setState`","التتبع التغييرات مع `crypto.randomUUID()`","دعم الحذف الناعم مع توقيع `deletedAt`","استيراد الأنواع من `schema.ts`","إدارة الحالة مع TypeScript"]},"keywords":{"en":["how to use crdt","crdt setup guide","crdt vs financial tracking tools","crdt install","what is crdt","crdt alternative","draft-style mutations example","crypto.randomUUID() usage","soft delete implementation"],"zh":["CRDT","Web 应用状态管理","Draft-样式突变","软删除","crypto.randomUUID()","schema.ts","AI エージェント","状态管理优化"],"ja":["CRDT","Web アプリの状態管理","Draft スタイルの変異","ソフト削除","crypto.randomUUID()","schema.ts","AI エージェント","状態管理の最適化"],"ko":["CRDT","웹 애플리케이션 상태 관리","_draft-스타일 변이","소프트 삭제","crypto.randomUUID()","schema.ts","AI 에이전트","상태 관리 최적화"],"es":["crdt","herramientas de inteligencia artificial","gestión de transacciones","mutaciones de estilo borrador","seguimiento de cambios","crypto.randomUUID()","eliminaciones suaves","importación de tipos","schema.ts"],"fr":["crdt","outils d''agents IA","gestion de transactions","mutations de style brouillon","suivi des modifications","crypto.randomUUID()","suppressions douces","importation de types","schema.ts"],"de":["crdt","KI-Tools","Transaktionsmanagement","Mutationen im Entwurfsstil","Änderungsverfolgung","crypto.randomUUID()","weiche Löschungen","Import von Typen","schema.ts"],"pt":["CRDT","Ferramentas de IA","TypeScript","Gerenciamento de estado","Mutações de estilo de rascunho","Acompanhamento de alterações","Soft deletes","Crypto","UUID"],"ru":["CRDT","ИИ Агенты","TypeScript","Управление состоянием","Мутации стиля черновика","Отслеживание изменений","Мягкое удаление","Crypto","UUID"],"ar":["CRDT","أدوات الذكاء الاصطناعي","TypeScript","إدارة الحالة","الطرز التحريرية","التتبع التغييرات","الحذف الناعم","Crypto","UUID"]}},"owner":"bentefay","repo":"moneyflow","repoPath":"bentefay/moneyflow","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.413Z","topics":[],"category":"community","skillMd":{"name":"crdt","description":"Loro CRDT state management with loro-mirror. Use when working on files in src/lib/crdt/.","bodyPreview":"# CRDT Guidelines\n\n## Critical: Draft-Style Mutations Only\n\n```typescript\n// CORRECT - mutate in place\nsetState((state) => {\n  state.transactions[id] = transaction;\n});\n\n// WRONG - returning new objects breaks change tracking\nsetState((state) => ({\n  ...state,\n  transactions: { ...state.transactions, [id]: transaction },\n}));\n```\n\n## Rules\n\n- Import types from `schema.ts`, don''t redeclare\n- **Soft deletes**: Set `deletedAt` timestamp, never remove from document\n- Use `crypto.randomUUID()` for ID","body":"# CRDT Guidelines\n\n## Critical: Draft-Style Mutations Only\n\n```typescript\n// CORRECT - mutate in place\nsetState((state) => {\n  state.transactions[id] = transaction;\n});\n\n// WRONG - returning new objects breaks change tracking\nsetState((state) => ({\n  ...state,\n  transactions: { ...state.transactions, [id]: transaction },\n}));\n```\n\n## Rules\n\n- Import types from `schema.ts`, don''t redeclare\n- **Soft deletes**: Set `deletedAt` timestamp, never remove from document\n- Use `crypto.randomUUID()` for IDs, `Date.now()` for timestamps\n\n## Schema Pattern\n\n```typescript\nexport const entitySchema = schema.LoroMap({\n  id: schema.String({ required: true }),\n  // ... fields\n  deletedAt: schema.Number(), // 0 = not deleted, >0 = timestamp\n});\n```\n\n## React Hooks\n\n- `useActiveTransactions()` - excludes soft-deleted\n- `useTransactions()` - includes soft-deleted  \n- `useVaultAction()` - for mutations\n\n## Sync\n\n- Updates encrypted before leaving client\n- Loro handles versioning via version vectors\n- Conflicts: last-write-wins per field\n"},"lastSynced":"2026-03-08T02:07:06.854Z","agentAnalysis":{"suitability":{"en":"Perfect for Financial Analysis Agents needing efficient transaction tracking and management with precision using draft-style mutations.","zh":"非常适合需要高效事务跟踪和管理的金融分析代理，使用草稿样式的变异以实现精确管理。","ja":"金融分析エージェントが効率的なトランザクション追跡と管理を行うために必要な、ドラフトスタイルのミューテーションを使用した精密管理に最適です。","ko":"정확한 관리를 위해 草稿スタイル의 뮤테이션을 사용하는 금융 분석 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Análisis Financiero que necesitan un seguimiento y gestión de transacciones eficientes con precisión utilizando mutaciones de estilo de borrador.","fr":"Parfait pour les Agents d''Analyse Financière ayant besoin d''un suivi et d''une gestion de transactions efficaces avec précision en utilisant des mutations de style brouillon.","de":"Perfekt für Finanzanalyse-Agents, die effizientes Transaktions-Tracking und -Management mit Präzision unter Verwendung von Entwurfs-Style-Mutationen benötigen.","pt":"Perfeito para Agentes de Análise Financeira que necessitam de acompanhamento e gerenciamento de transações eficientes com precisão usando mutações do tipo draft.","ru":"Идеально подходит для финансовых аналитических агентов, которым требуется эффективное отслеживание и управление транзакциями с точностью с помощью мутаций чернового типа.","ar":"مثالي لعمليات تحليل مالية تتطلب متابعة واستخدام حركات مالية فعالة ودقيقة باستخدام طفرات من نوع المسودة."},"recommendation":{"en":"Empowers agents to manage financial data with precision, utilizing setState for in-place mutations and crypto.randomUUID for ID generation, while enforcing soft deletes through deletedAt timestamps.","zh":"使得代理能够使用setState进行原地变异、使用crypto.randomUUID进行ID生成，同时通过deletedAt时间戳强制执行软删除。","ja":"setStateを使用したインプレースミューテーション、crypto.randomUUIDを使用したID生成、deletedAtタイムスタンプを使用したソフト削除の適用を可能にします。","ko":"setState를 사용하여 인플레이스 뮤테이션을 수행하고, crypto.randomUUID를 사용하여 ID를 생성하며, deletedAt 타임스탬프를 통해 소프트 삭제를 강제 적용합니다.","es":"Habilita a los agentes a gestionar datos financieros con precisión, utilizando setState para mutaciones in situ y crypto.randomUUID para la generación de ID, mientras se aplican borrados suaves a través de marcas de tiempo deletedAt.","fr":"Permet aux agents de gérer des données financières avec précision, en utilisant setState pour les mutations in situ et crypto.randomUUID pour la génération d''ID, tout en appliquant des suppressions souples via les horodatages deletedAt.","de":"Ermächtigt Agents, Finanzdaten mit Präzision zu verwalten, indem setState für Platzmutationen und crypto.randomUUID für ID-Generierung verwendet werden, während Soft Deletes durch deletedAt-Timestamps durchgesetzt werden.","pt":"Habilita os agentes a gerenciar dados financeiros com precisão, utilizando setState para mutações in-loco e crypto.randomUUID para geração de ID, enquanto impõe exclusões suaves por meio de carimbos de data/hora deletedAt.","ru":"Наделяет агентов возможностью управлять финансовыми данными с точностью, используя setState для мутаций на месте и crypto.randomUUID для генерации идентификаторов, одновременно обеспечивая мягкое удаление через метки времени deletedAt.","ar":"تمكن الوكلاء من إدارة البيانات المالية بدقة، باستخدام setState لمutations في المكان و crypto.randomUUID لتوليد الهوية، بينما يفرض حذفًا ناعمًا من خلال علامات الوقت المحذوفة."},"useCases":{"en":["Tracking financial transactions efficiently","Implementing soft deletes with deletedAt timestamps","Generating unique IDs using crypto.randomUUID"],"zh":["高效地跟踪金融事务","使用deletedAt时间戳实现软删除","使用crypto.randomUUID生成唯一ID"],"ja":["金融トランザクションを効率的に追跡する","deletedAtタイムスタンプを使用してソフト削除を実装する","crypto.randomUUIDを使用して一意のIDを生成する"],"ko":["금융 트랜잭션을 효율적으로 추적하는 것","deletedAt 타임스탬프를 사용하여 소프트 삭제를 구현하는 것","crypto.randomUUID를 사용하여 고유한 ID를 생성하는 것"],"es":["Seguimiento eficiente de transacciones financieras","Implementación de borrados suaves con marcas de tiempo deletedAt","Generación de ID únicos utilizando crypto.randomUUID"],"fr":["Suivi efficace des transactions financières","Mise en œuvre de suppressions souples avec des horodatages deletedAt","Génération d''ID uniques en utilisant crypto.randomUUID"],"de":["Effizientes Tracking von Finanztransaktionen","Implementierung von Soft Deletes mit deletedAt-Timestamps","Generierung eindeutiger IDs unter Verwendung von crypto.randomUUID"],"pt":["Acompanhamento eficiente de transações financeiras","Implementação de exclusões suaves com carimbos de data/hora deletedAt","Geração de IDs únicos usando crypto.randomUUID"],"ru":["Эффективное отслеживание финансовых транзакций","Реализация мягкого удаления с помощью меток времени deletedAt","Генерация уникальных идентификаторов с помощью crypto.randomUUID"],"ar":["متابعة فعالة للحركات المالية","تنفيذ حذف ناعم مع علامات وقت محذوفة","توليد معرفات فريدة باستخدام crypto.randomUUID"]},"limitations":{"en":["Requires adherence to draft-style mutations","Must import types from schema.ts","Limited to soft deletes, never removing documents"],"zh":["需要遵守草稿样式的变异","必须从schema.ts导入类型","仅限于软删除，永远不会删除文档"],"ja":["ドラフトスタイルのミューテーションに従う必要がある","schema.tsからタイプをインポートする必要がある","ソフト削除のみに限定され、ドキュメントは決して削除されない"],"ko":["초안 스타일의 뮤테이션을 따라야 함","schema.ts에서 유형을 가져와야 함","소프트 삭제만으로 제한되며 문서는 절대 삭제되지 않음"],"es":["Requiere adherirse a mutaciones de estilo de borrador","Debe importar tipos desde schema.ts","Limitado a borrados suaves, nunca eliminando documentos"],"fr":["Exige l''adhésion aux mutations de style brouillon","Doit importer des types depuis schema.ts","Limité aux suppressions souples, ne supprimant jamais de documents"],"de":["Benötigt die Einhaltung von Entwurfs-Style-Mutationen","Muss Typen aus schema.ts importieren","Begrenzt auf Soft Deletes, die niemals Dokumente entfernen"],"pt":["Exige aderência a mutações do tipo draft","Deve importar tipos de schema.ts","Limitado a exclusões suaves, nunca removendo documentos"],"ru":["Требует соблюдения мутаций чернового типа","Должен импортировать типы из schema.ts","Ограничен мягким удалением, никогда не удаляя документы"],"ar":["يتطلب الالتزام بالطفرات من نوع المسودة","يجب استيراد الأنواع من schema.ts","محدود للحذف الناعم، أبدًا لا يحذف الوثائق"]},"version":4},"contentHash":"0385d5d0542e052a2a6ce4acf1aa63bb44003528261024c6e2daa785db3f5aae","qualityScore":39}');
