INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bentefay/moneyflow/crdt', 'crdt', 'bentefay', 'moneyflow', 'community', 'crdt bentefay moneyflow community crdt is a web app that helps developers track financial transactions efficiently. It benefits developers who need to manage financial data with precision. CRDT 是一个 Web 应用，帮助您理解钱的流向。它遵循特定的规则，如_draft-样式突变和软删除 CRDT は、Web アプリの状態管理を最適化するためのガイドです。Draft スタイルの変異とソフト削除を含む重要なルールを学びましょう CRDT는 웹 애플리케이션 상태 관리를 최적화하기 위한 가이드입니다._draft-스타일 변이와 소프트 삭제를 포함하는 중요한 규칙을 학습하세요 crdt es una aplicación web que ayuda a entender el flujo de dinero mediante mutaciones de estilo borrador y seguimiento de cambios crdt est une application web qui aide à comprendre le flux d''argent via des mutations de style brouillon et un suivi des modifications crdt ist eine Webanwendung, die hilft, den Geldfluss durch Mutationen im Entwurfsstil und Änderungsverfolgung zu verstehen O CRDT é uma aplicação web que ajuda a entender onde seu dinheiro está indo, com recursos como mutações de estilo de rascunho e acompanhamento de alterações CRDT - это веб-приложение, которое помогает понять, куда уходят ваши деньги, с функциями, такими как мутации стиля черновика и отслеживание изменений CRDT هو تطبيق ويب يساعد على فهم حيث يذهب أموالك، مع ميزات مثل الطرز التحريرية والتتبع التغييرات how to use crdt crdt setup guide crdt vs financial tracking tools crdt install what is crdt crdt alternative draft-style mutations example crypto.randomUUID() usage soft delete implementation CRDT Web 应用状态管理 Draft-样式突变 软删除 crypto.randomUUID() schema.ts AI エージェント 状态管理优化 Implements draft-style mutations using setState Utilizes crypto.randomUUID() for unique ID generation Supports soft deletes via deletedAt timestamp Imports types from schema.ts for consistent data modeling Enforces change tracking with in-place state mutations crdt is a web application designed to help understand where money is going, utilizing draft-style mutations for efficient data management');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tuannvm/pagent/pagent', 'community', 'tuannvm', 'pagent', 'tuannvm/pagent', 'pagent', 0, 0, 39, '2026-03-08T01:57:15.413Z', '2026-03-08T02:07:07.304Z', 'c67591fdeff366a7a61e1aafc1841f99f92062f4fa86080a23a0a07b3ce8e239', '{"id":"tuannvm/pagent/pagent","name":"pagent","description":{"en":"Pagent is an interactive TUI that orchestrates AI agents to generate architecture, test plans, security assessments, and working code from Product Requirement Documents. It benefits developers and teams by streamlining the development process.","zh":"Pagent 是一个 Interactive TUI 工具，用于编排 AI 专家代理，自动化开发流程","ja":"Pagent は、AI エージェントを活用して開発プロセスを自動化する Interactive TUI ツールです","ko":"Pagent는 개발 프로세스를 자동화하기 위한 Interactive TUI 도구로 AI 에이전트를 활용합니다","es":"Pagent es una herramienta de orquestación de agentes de inteligencia artificial que transforma documentos de requisitos de producto en código funcional","fr":"Pagent est un outil d''orchestration d''agents d''intelligence artificielle qui transforme les documents de spécifications de produit en code fonctionnel","de":"Pagent ist ein Orchestrierungstool für KI-Agents, das Produktanforderungsdokumente in funktionierenden Code umwandelt","pt":"O Pagent é uma ferramenta de orquestração de agentes de IA que transforma documentos de requisitos de produto em código funcionando","ru":"Pagent - это инструмент оркестровки ИИ Агентов, который преобразует документы требований продукта в рабочий код","ar":"Pagent هو أداة لتحكم في وكلاء الذكاء الاصطناعي التي تحول مستندات متطلبات المنتج إلى رمز يعمل"},"seo":{"title":{"en":"Pagent: AI Agent Orchestration Setup Guide | AI Agent","zh":"Pagent Interactive TUI 设置指南 - AIエージェント工具","ja":"Pagent Setup Guide - AIエージェントを活用した開発","ko":"Pagent 사용 가이드 - AI 에이전트를 활용한 개발 자동화","es":"Guía de configuración de Pagent: Orquestación de agentes ...","fr":"Guide de démarrage de Pagent: Orchestration d''agents d''in...","de":"Pagent-Setup-Anleitung: Orchestrierung von KI-Agents","pt":"Guia de Configuração do Pagent: Orquestração de Agentes d...","ru":"Настройка Pagent: Руководство по использованию ИИ Агентов","ar":"دليل إعداد Pagent: تحكم في وكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how pagent transforms Product Requirement Documents into working code. Get started with the interactive TUI and specialist AI agents today!","zh":"使用 Pagent Interactive TUI，从 PRD 到工作代码，自动化开发流程，提高效率","ja":"Pagent を使用して、PRD から動作コードまでの開発プロセスを自動化して、効率を向上させる","ko":"Pagent를 사용하여 PRD에서 작동 코드까지 개발 프로세스를 자동화하고 효율성을 높입니다","es":"Aprenda a utilizar Pagent para transformar documentos de requisitos de producto en código funcional con nuestra guía paso a paso","fr":"Découvrez comment utiliser Pagent pour transformer les documents de spécifications de produit en code fonctionnel avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Pagent verwenden, um Produktanforderungsdokumente in funktionierenden Code umzuwandeln, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a usar o Pagent para transformar documentos de requisitos de produto em código funcionando, com especialistas em agentes de IA","ru":"Узнайте, как использовать Pagent для преобразования документов требований продукта в рабочий код с помощью специалистов ИИ Агентов","ar":"تعرف على كيفية استخدام Pagent لتحويل مستندات متطلبات المنتج إلى رمز يعمل، مع خبراء وكلاء الذكاء الاصطناعي"},"definition":{"en":"Pagent is an interactive Terminal User Interface (TUI) that orchestrates specialist AI agents to transform Product Requirement Documents (PRDs) into working code.","zh":"Pagent 是一种用于自动化开发流程的 Interactive TUI 工具，使用 AI 专家代理","ja":"Pagent は、AI エージェントを使用して開発プロセスを自動化するツールです","ko":"Pagent는 개발 프로세스를 자동화하기 위한 도구로 AI 에이전트를 사용합니다","es":"Pagent es una herramienta de inteligencia artificial que orquesta agentes especializados para transformar documentos de requisitos de producto en código","fr":"Pagent est un outil d''intelligence artificielle qui orchestre des agents spécialisés pour transformer les documents de spécifications de produit en code","de":"Pagent ist ein KI-Tool, das spezialisierte Agents orchestriert, um Produktanforderungsdokumente in Code umzuwandeln","pt":"O Pagent é uma ferramenta de linha de comando que orquestra agentes de IA especializados para criar arquitetura, planos de teste e código","ru":"Pagent - это командная строка инструмент, который оркестрирует специалистов ИИ Агентов для создания архитектуры, планов тестирования и кода","ar":"Pagent هو أداة سطر أوامر تحكم في وكلاء الذكاء الاصطناعي المتخصصين لإنشاء هندسة، خطط اختبار ورمز"},"features":{"en":["Runs 5 specialist agents in dependency order: architect, qa, and more","Generates architecture.md files with technical design, API specs, and data models","Supports interactive TUI mode via the `pagent ui` command","Accepts PRD files as input via the `pagent run` command","Provides agent status checks via the `pagent status` command"],"zh":["支持 Interactive TUI 模式","自动化生成架构文档和测试计划","支持多个 AI 专家代理","提供安全评估和代码生成功能","支持 PRD 文件输入"],"ja":["Interactive TUI モードをサポート","アーキテクチャ文書とテスト計画を自動生成","複数の AI エージェントをサポート","セキュリティ評価とコード生成機能を提供","PRD ファイル入力をサポート"],"ko":["Interactive TUI 모드를 지원","아키텍처 문서와 테스트 계획을 자동 생성","여러 개의 AI 에이전트를 지원","보안 평가와 코드 생성 기능을 제공","PRD 파일 입력을 지원"],"es":["Interfaz de usuario interactiva (TUI) para orquestar agentes","Soporte para documentos de requisitos de producto (PRD)","Generación de arquitectura, planes de pruebas y evaluaciones de seguridad","Código funcional generado a partir de documentos de requisitos","Orquestación de 5 agentes especializados en orden de dependencia"],"fr":["Interface utilisateur interactive (TUI) pour orchestrer des agents","Prise en charge des documents de spécifications de produit (PRD)","Génération d''architecture, de plans de tests et d''évaluations de sécurité","Code fonctionnel généré à partir de documents de spécifications","Orchestration de 5 agents spécialisés dans l''ordre de dépendance"],"de":["Interaktive Benutzeroberfläche (TUI) zur Orchestrierung von Agents","Unterstützung für Produktanforderungsdokumente (PRD)","Generierung von Architektur, Testplänen und Sicherheitsbewertungen","Funktionierender Code generiert aus Produktanforderungsdokumenten","Orchestrierung von 5 spezialisierten Agents in Abhängigkeitsreihenfolge"],"pt":["Orquestração de agentes de IA especializados","Criação de arquitetura e planos de teste","Geração de código funcionando a partir de documentos de requisitos de produto","Interface de usuário interativa","Suporte a execução de comandos via linha de comando"],"ru":["Оркестровка специалистов ИИ Агентов","Создание архитектуры и планов тестирования","Генерация рабочего кода из документов требований продукта","Интерактивный интерфейс пользователя","Поддержка выполнения команд через командную строку"],"ar":["تحكم في وكلاء الذكاء الاصطناعي المتخصصين","إنشاء هندسة وخطط اختبار","توليد رمز يعمل من مستندات متطلبات المنتج","واجهة مستخدم تفاعلية","دعم تنفيذ أوامر عبر سطر الأوامر"]},"keywords":{"en":["how to use pagent","pagent setup guide","pagent alternative","pagent vs architect","pagent install","what is pagent","pagent tutorial","pagent documentation","pagent specialist agents"],"zh":["Pagent","AIエージェント","Interactive TUI","自动化开发","PRD 文件","架构文档","测试计划","安全评估","代码生成"],"ja":["Pagent","AIエージェント","Interactive TUI","自動化開発","PRD ファイル","アーキテクチャ文書","テスト計画","セキュリティ評価","コード生成"],"ko":["Pagent","AI 에이전트","Interactive TUI","자동화 개발","PRD 파일","아키텍처 문서","테스트 계획","보안 평가","코드 생성"],"es":["agentes de inteligencia artificial","orquestación de agentes","transformación de documentos de requisitos","código funcional generado","herramientas de inteligencia artificial","desarrollo de software","ingeniería de software","pruebas de software","seguridad de software"],"fr":["agents d''intelligence artificielle","orchestration d''agents","transformation de documents de spécifications","code fonctionnel généré","outils d''intelligence artificielle","développement de logiciels","ingénierie de logiciels","tests de logiciels","sécurité de logiciels"],"de":["KI-Agents","Orchestrierung von Agents","Umwandlung von Produktanforderungsdokumenten","generierter funktionierender Code","KI-Tools","Software-Entwicklung","Software-Ingenieurwesen","Software-Tests","Software-Sicherheit"],"pt":["Pagent","Agentes de IA","Orquestração de agentes","Criação de arquitetura","Planos de teste","Geração de código","Ferramentas de desenvolvimento","Desenvolvimento de software"],"ru":["Pagent","ИИ Агенты","Оркестровка ИИ Агентов","Создание архитектуры","Планы тестирования","Генерация кода","Инструменты разработки","Разработка программного обеспечения"],"ar":["Pagent","وكلاء الذكاء الاصطناعي","تحكم في وكلاء الذكاء الاصطناعي","إنشاء هندسة","خطط اختبار","توليد رمز","أدوات تطوير","تطوير البرمجيات"]}},"owner":"tuannvm","repo":"pagent","repoPath":"tuannvm/pagent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.413Z","topics":[],"category":"community","skillMd":{"name":"pagent","description":"Guide for using pagent - a PRD-to-code orchestration tool. Use when users ask how to use pagent, run agents, create PRDs, or transform requirements into code.","bodyPreview":"# Pagent Usage Guide\n\nPagent orchestrates specialist AI agents to transform Product Requirement Documents (PRDs) into working code.\n\n## Quick Start\n\n```bash\n# Interactive TUI (recommended)\npagent ui\n\n# Run with a PRD file\npagent run ./prd.md\n\n# Check agent status\npagent status\n```\n\n## Agents\n\nPagent runs 5 specialist agents in dependency order:\n\n| Agent | Output | Purpose |\n|-------|--------|---------|\n| `architect` | `architecture.md` | Technical design, API specs, data models |\n| `qa` | `test-","body":"# Pagent Usage Guide\n\nPagent orchestrates specialist AI agents to transform Product Requirement Documents (PRDs) into working code.\n\n## Quick Start\n\n```bash\n# Interactive TUI (recommended)\npagent ui\n\n# Run with a PRD file\npagent run ./prd.md\n\n# Check agent status\npagent status\n```\n\n## Agents\n\nPagent runs 5 specialist agents in dependency order:\n\n| Agent | Output | Purpose |\n|-------|--------|---------|\n| `architect` | `architecture.md` | Technical design, API specs, data models |\n| `qa` | `test-plan.md` | Test cases, acceptance criteria |\n| `security` | `security-assessment.md` | Threat model, security requirements |\n| `implementer` | `code/*` | Working code implementation |\n| `verifier` | `*_test.go`, `verification-report.md` | Tests and validation |\n\n### Execution Order\n\n```\nLevel 0: architect\nLevel 1: qa, security (parallel)\nLevel 2: implementer\nLevel 3: verifier\n```\n\n## Commands\n\n### Run Agents\n\n```bash\n# Run all agents (parallel by default)\npagent run ./prd.md\n\n# Run specific agents\npagent run ./prd.md --agents architect,qa\n\n# Sequential mode\npagent run ./prd.md --sequential\n\n# Resume (skip up-to-date outputs)\npagent run ./prd.md --resume\n\n# Force regeneration\npagent run ./prd.md --force\n\n# Custom output directory\npagent run ./prd.md -o ./docs/\n```\n\n### Interactive TUI\n\n```bash\npagent ui              # Start fresh\npagent ui ./prd.md     # Pre-fill with PRD\npagent ui --accessible # Screen reader support\n```\n\n### Monitor & Control\n\n```bash\npagent status                    # Check running agents\npagent logs <agent>              # View agent output\npagent message <agent> \"text\"    # Send guidance\npagent stop <agent>              # Stop specific agent\npagent stop --all                # Stop all agents\n```\n\n### MCP Server\n\n```bash\npagent mcp                                  # Stdio (Claude Desktop)\npagent mcp --transport http --port 8080     # HTTP mode\npagent mcp --transport http --oauth \\\n  --issuer https://company.okta.com \\\n  --audience api://pagent                   # With OAuth\n```\n\n## Personas\n\nControl implementation style:\n\n| Persona | Use Case |\n|---------|----------|\n| `minimal` | MVP, prototype - ship fast |\n| `balanced` | Standard projects (default) |\n| `production` | Enterprise - comprehensive testing, security |\n\n```bash\npagent run ./prd.md --persona production\n```\n\n## Configuration\n\nInitialize config:\n```bash\npagent init\n```\n\nCreates `.pagent/config.yaml`:\n```yaml\noutput_dir: ./outputs\ntimeout: 300\npersona: balanced\n\npreferences:\n  api_style: rest      # rest | graphql | grpc\n  language: go         # go | python | typescript\n  testing_depth: unit  # none | unit | integration | e2e\n  containerized: true\n  include_ci: true\n\nstack:\n  cloud: aws\n  compute: kubernetes\n  database: postgres\n  cache: redis\n```\n\n## Writing a PRD\n\nA good PRD includes:\n\n```markdown\n# Product: [Name]\n\n## Problem Statement\nWhat problem are we solving?\n\n## Features\n- Feature 1: description\n- Feature 2: description\n\n## Requirements\n- Functional requirements\n- Non-functional requirements (performance, security)\n\n## Constraints\n- Technology constraints\n- Timeline constraints\n```\n\n## Workflows\n\n### Quick Architecture Review\n```bash\npagent run ./prd.md --agents architect\n# Review architecture.md, iterate on PRD\n```\n\n### Full Pipeline\n```bash\npagent ui ./prd.md\n# Select production persona\n# Run all agents\ncd outputs/code && go build ./...\n```\n\n### Iterative Development\n```bash\npagent run ./prd.md --agents architect\n# Review architecture.md\npagent run ./prd.md --resume  # Run remaining agents\n```\n\n## Troubleshooting\n\n| Issue | Fix |\n|-------|-----|\n| Timeout | `pagent run ./prd.md --timeout 600` |\n| Port in use | `pagent stop --all` |\n| Incomplete output | `pagent message <agent> \"Please complete...\"` |\n| Agent stuck | `pagent stop <agent>` then re-run |\n"},"lastSynced":"2026-03-08T02:07:07.304Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined architecture, testing, and code generation from Product Requirement Documents.","zh":"非常适合需要简化架构、测试和从产品需求文档生成代码的开发智能体。","ja":"合理化されたアーキテクチャ、テスト、および製品要求ドキュメントからのコード生成を必要とする開発エージェントに最適です。","ko":"간소화된 아키텍처, 테스트 및 제품 요구사항 문서로부터의 코드 생성이 필요한 개발 에이전트에 완벽합니다.","es":"Ideal para Development Agents que necesitan una arquitectura optimizada, pruebas y generación de código a partir de Product Requirement Documents.","fr":"Parfait pour les Development Agents nécessitant une architecture rationalisée, des tests et une génération de code à partir de Product Requirement Documents.","de":"Perfekt für Development Agents, die eine optimierte Architektur, Tests und Codegenerierung aus Product Requirement Documents benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de uma arquitetura simplificada, testes e geração de código a partir de Documentos de Requisitos do Produto.","ru":"Идеально подходит для Development Agents, которым требуется оптимизированная архитектура, тестирование и генерация кода из Product Requirement Documents.","ar":"مثالي لوكلاء التطوير (Development Agents) الذين يحتاجون إلى هندسة معمارية مبسطة، واختبارات، وإنشاء كود من مستندات متطلبات المنتج (Product Requirement Documents)."},"recommendation":{"en":"Empowers agents to orchestrate specialist AI agents for transforming PRDs into working code, utilizing Markdown files and generating architecture, test plans, and security assessments through a interactive TUI.","zh":"使智能体能够协调专业的AI智能体，将PRD转换为可工作的代码，利用Markdown文件并通过交互式TUI生成架构、测试计划和安全性评估。","ja":"専門的なAIエージェントを調整して、PRDを実働コードに変換し、Markdownファイルを利用し、インタラクティブなTUIを通じてアーキテクチャ、テスト計画、およびセキュリティ評価を生成することをエージェントに可能にします。","ko":"에이전트가 전문 AI 에이전트를 조정하여 PRD를 실제 작동 코드로 변환하고, Markdown 파일을 활용하며, 대화형 TUI를 통해 아키텍처, 테스트 계획 및 보안 평가를 생성할 수 있도록 합니다.","es":"Permite a los agents orquestar specialist AI agents para transformar PRDs en código funcional, utilizando archivos Markdown y generando arquitectura, planes de prueba y evaluaciones de seguridad a través de una TUI interactiva.","fr":"Permet aux agents d''orchestrer des specialist AI agents pour transformer les PRDs en code fonctionnel, en utilisant des fichiers Markdown et en générant l''architecture, les plans de test et les évaluations de sécurité via une TUI interactive.","de":"Ermöglicht es Agents, specialist AI Agents zu orchestrieren, um PRDs in funktionierenden Code zu transformieren, unter Verwendung von Markdown-Dateien und Generierung von Architektur, Testplänen und Sicherheitsbewertungen durch eine interaktive TUI.","pt":"Capacita os agentes a orquestrar agentes de IA especializados para transformar PRDs em código funcional, utilizando arquivos Markdown e gerando arquitetura, planos de teste e avaliações de segurança através de uma TUI interativa.","ru":"Позволяет агентам управлять специализированными ИИ-агентами для преобразования PRD в рабочий код, используя файлы Markdown и генерируя архитектуру, планы тестирования и оценки безопасности через интерактивный TUI.","ar":"يمكّن الوكلاء من تنظيم وكلاء الذكاء الاصطناعي المتخصصين لتحويل PRDs إلى كود عامل، باستخدام ملفات Markdown وإنشاء هندسة معمارية، وخطط اختبار، وتقييمات أمنية من خلال واجهة مستخدم نصية تفاعلية (TUI)."},"useCases":{"en":["Generating technical designs and API specs","Automating test plan creation","Creating working code from Product Requirement Documents"],"zh":["生成技术设计和API规范","自动化测试计划的创建","根据产品需求文档创建可工作的代码"],"ja":["技術設計とAPI仕様の生成","テスト計画作成の自動化","製品要求ドキュメントからの実働コードの作成"],"ko":["기술 설계 및 API 사양 생성","테스트 계획 생성 자동화","제품 요구사항 문서로부터의 작동 코드 생성"],"es":["Generación de diseños técnicos y especificaciones API","Automatización de la creación de planes de prueba","Creación de código funcional a partir de Product Requirement Documents"],"fr":["Génération de conceptions techniques et de spécifications API","Automatisation de la création de plans de test","Création de code fonctionnel à partir de Product Requirement Documents"],"de":["Generierung von technischen Designs und API-Spezifikationen","Automatisierung der Erstellung von Testplänen","Erstellung von funktionierendem Code aus Product Requirement Documents"],"pt":["Geração de designs técnicos e especificações de API","Automação da criação de planos de teste","Criação de código funcional a partir de Documentos de Requisitos do Produto"],"ru":["Генерация технических проектов и спецификаций API","Автоматизация создания планов тестирования","Создание рабочего кода из Product Requirement Documents"],"ar":["إنشاء تصاميم تقنية ومواصفات API","أتمتة إنشاء خطط الاختبار","إنشاء كود عامل من مستندات متطلبات المنتج (Product Requirement Documents)"]},"limitations":{"en":["Requires PRD files in Markdown format","Dependent on specialist AI agents for functionality"],"zh":["需要Markdown格式的PRD文件","功能依赖于专业的AI智能体"],"ja":["Markdown形式のPRDファイルが必要","機能は専門的なAIエージェントに依存"],"ko":["Markdown 형식의 PRD 파일 필요","전문 AI 에이전트에 기능 의존"],"es":["Requiere archivos PRD en formato Markdown","Depende de specialist AI agents para su funcionalidad"],"fr":["Nécessite des fichiers PRD au format Markdown","Dépend de specialist AI agents pour sa fonctionnalité"],"de":["Erfordert PRD-Dateien im Markdown-Format","Abhängig von specialist AI Agents für die Funktionalität"],"pt":["Requer arquivos PRD no formato Markdown","Dependente de agentes de IA especializados para funcionalidade"],"ru":["Требует файлы PRD в формате Markdown","Зависит от специализированных ИИ-агентов для функциональности"],"ar":["يتطلب ملفات PRD بصيغة Markdown","يعتمد على وكلاء الذكاء الاصطناعي المتخصصين للوظيفة"]},"version":4},"contentHash":"c67591fdeff366a7a61e1aafc1841f99f92062f4fa86080a23a0a07b3ce8e239","qualityScore":39}');
