INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tuannvm/pagent/pagent', 'pagent', 'tuannvm', 'pagent', 'community', 'pagent tuannvm pagent community Pagent is an interactive TUI that orchestrates AI agents to generate architecture, test plans, security assessments, and working code from Product Requirement Documents. It benefits developers and teams by streamlining the development process. Pagent 是一个 Interactive TUI 工具，用于编排 AI 专家代理，自动化开发流程 Pagent は、AI エージェントを活用して開発プロセスを自動化する Interactive TUI ツールです Pagent는 개발 프로세스를 자동화하기 위한 Interactive TUI 도구로 AI 에이전트를 활용합니다 Pagent es una herramienta de orquestación de agentes de inteligencia artificial que transforma documentos de requisitos de producto en código funcional Pagent est un outil d''orchestration d''agents d''intelligence artificielle qui transforme les documents de spécifications de produit en code fonctionnel Pagent ist ein Orchestrierungstool für KI-Agents, das Produktanforderungsdokumente in funktionierenden Code umwandelt O Pagent é uma ferramenta de orquestração de agentes de IA que transforma documentos de requisitos de produto em código funcionando Pagent - это инструмент оркестровки ИИ Агентов, который преобразует документы требований продукта в рабочий код Pagent هو أداة لتحكم في وكلاء الذكاء الاصطناعي التي تحول مستندات متطلبات المنتج إلى رمز يعمل how to use pagent pagent setup guide pagent alternative pagent vs architect pagent install what is pagent pagent tutorial pagent documentation pagent specialist agents Pagent AIエージェント Interactive TUI 自动化开发 PRD 文件 架构文档 测试计划 安全评估 代码生成 Runs 5 specialist agents in dependency order: architect, qa, and more Generates architecture.md files with technical design, API specs, and data models Supports interactive TUI mode via the `pagent ui` command Accepts PRD files as input via the `pagent run` command Provides agent status checks via the `pagent status` command Pagent is an interactive Terminal User Interface (TUI) that orchestrates specialist AI agents to transform Product Requirement Documents (PRDs) into working code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Mavrick91/tanstack-start-app/admin-crud', 'community', 'Mavrick91', 'tanstack-start-app', 'Mavrick91/tanstack-start-app', 'admin-crud', 0, 0, 39, '2026-03-08T01:57:15.414Z', '2026-03-08T02:07:11.957Z', 'c947395f5f508df7981b59b6b3a78756a0ec78a517f838fb5b14e615734749d1', '{"id":"Mavrick91/tanstack-start-app/admin-crud","name":"admin-crud","description":{"en":"The admin-crud skill generates admin dashboard pages following established patterns, benefiting developers who need to create list and detail/edit pages.","zh":"Admin CRUD 生成器用于创建管理面板页面，包括列表页和详细编辑页，按照项目的既定模式进行设置","ja":"Admin CRUD は管理ダッシュボード ページの作成に使用され、プロジェクトの既定のパターンに従って設定します","ko":"Admin CRUD 생성기는 관리 대시보드 페이지를 생성하는 데 사용되며 프로젝트의 정해진 패턴에 따라 설정합니다","es":"El generador de CRUD de administración crea páginas de panel de administración siguiendo patrones establecidos. Permite la creación de listas y formularios de recursos","fr":"Le générateur de CRUD d''administration crée des pages de tableau de bord d''administration suivant des modèles établis. Il permet la création de listes et de formulaires de ressources","de":"Der Admin-CRUD-Generator erstellt Verwaltungsdashboard-Seiten nach etablierten Mustern. Er ermöglicht die Erstellung von Ressourcenlisten und -formularen","pt":"O Admin CRUD é um gerador de páginas de dashboard administrativas que segue os padrões estabelecidos do projeto, utilizando React e TypeScript.","ru":"ИИ Агент Admin CRUD - это генератор страниц админ-панели, следующий установленным шаблонам проекта, использующий React и TypeScript.","ar":"Admin CRUD هو مولد صفحات لوحة تحكم إدارية يتبع الأنماط المعتمدة للمشروع، ويستخدم React و TypeScript."},"seo":{"title":{"en":"admin-crud: Admin Dashboard Page Generator | AI Agent Skill","zh":"Admin CRUD Setup Guide - AIエージェント生成器","ja":"Admin CRUD ベストプラクティス - AIエージェントツール","ko":"Admin CRUD 구축 가이드 - AI 에이전트 생성기","es":"Generador de CRUD de administración: Guía de configuración","fr":"Générateur de CRUD d''administration: Meilleures pratiques","de":"Admin-CRUD-Generator: Einrichtungsanleitung","pt":"Guia de Configuração do Admin CRUD: Gerador de Páginas de...","ru":"Настройка ИИ Агента Admin CRUD: Создание Страниц Админ-Па...","ar":"دليل إعداد Admin CRUD: مولد صفحات لوحة التحكم"},"description":{"en":"Discover how to create admin dashboard pages with ease using admin-crud. Learn how to set up and utilize this skill to streamline your development process.","zh":"使用 Admin CRUD 生成器创建管理面板页面，按照项目的既定模式进行设置，包括列表页和详细编辑页","ja":"Admin CRUD を使用して管理ダッシュボード ページを作成し、プロジェクトの既定のパターンに従って設定します","ko":"Admin CRUD 생성기를 사용하여 관리 대시보드 페이지를 생성하고 프로젝트의 정해진 패턴에 따라 설정합니다","es":"Crea páginas de panel de administración con patrones establecidos. Generador de CRUD de administración para desarrolladores","fr":"Créez des pages de tableau de bord d''administration avec des modèles établis. Outil de génération de CRUD d''administration pour les développeurs","de":"Erstellen Sie Verwaltungsdashboard-Seiten mit etablierten Mustern. Admin-CRUD-Generator für Entwickler","pt":"Aprenda a configurar o Admin CRUD para criar páginas de dashboard administrativas personalizadas com React e TypeScript","ru":"Узнайте, как настроить ИИ Агент Admin CRUD для создания индивидуальных страниц админ-панели с помощью React и TypeScript","ar":"تعلم كيفية إعداد Admin CRUD لإنشاء صفحات لوحة تحكم إدارية مخصصة باستخدام React و TypeScript"},"definition":{"en":"admin-crud is a skill that generates admin dashboard pages, including list and detail/edit pages, using a structured approach.","zh":"Admin CRUD 是一种用于生成管理面板页面的工具，包括列表页和详细编辑页","ja":"Admin CRUD は管理ダッシュボード ページを生成するためのツールであり、リスト ページと詳細編集ページを含みます","ko":"Admin CRUD는 관리 대시보드 페이지를 생성하는 도구로 리스트 페이지와 상세 편집 페이지를 포함합니다","es":"Un generador de CRUD de administración es una herramienta que crea páginas de panel de administración con funcionalidades de lista y edición de recursos","fr":"Un générateur de CRUD d''administration est un outil qui crée des pages de tableau de bord d''administration avec des fonctionnalités de liste et d''édition de ressources","de":"Ein Admin-CRUD-Generator ist ein Tool, das Verwaltungsdashboard-Seiten mit Ressourcenlisten- und -bearbeitungsfunktionen erstellt","pt":"O Admin CRUD é um recurso que gera páginas de dashboard administrativas personalizadas","ru":"ИИ Агент Admin CRUD - это функция, генерирующая индивидуальные страницы админ-панели","ar":"Admin CRUD هو ميزة توليد صفحات لوحة تحكم إدارية مخصصة"},"features":{"en":["Generates list pages using index.tsx","Creates detail/edit pages using $resourceId.tsx","Utilizes ResourcesList.tsx as a list container","Employs ResourceForm.tsx for create/edit forms","Leverages ResourceTable.tsx for data tables","Follows a structured approach for admin page organization"],"zh":["支持列表页和详细编辑页的创建","按照项目的既定模式进行设置","使用 React 和 TypeScript 进行开发","包含数据表格和表单组件","支持资源列表和资源表单的创建","使用 CLI 进行生成和配置"],"ja":["リスト ページと詳細編集ページの作成をサポート","プロジェクトの既定のパターンに従って設定","React と TypeScript を使用した開発","データ テーブルとフォーム コンポーネントを含む","リソース リストとリソース フォームの作成をサポート","CLI を使用した生成と設定"],"ko":["리스트 페이지와 상세 편집 페이지의 생성을 지원","프로젝트의 정해진 패턴에 따라 설정","React와 TypeScript를 사용한 개발","데이터 테이블과 폼 컴포넌트를 포함","리소스 리스트와 리소스 폼의 생성을 지원","CLI를 사용한 생성과 설정"],"es":["Generación de páginas de lista de recursos","Creación de formularios de edición de recursos","Uso de patrones de proyecto establecidos","Soporte para rutas de administración personalizadas","Integración con componentes de lista y formulario de recursos","Compatibilidad con TypeScript y React"],"fr":["Génération de pages de liste de ressources","Création de formulaires d''édition de ressources","Utilisation de modèles de projet établis","Prise en charge de routes d''administration personnalisées","Intégration avec des composants de liste et de formulaire de ressources","Compatibilité avec TypeScript et React"],"de":["Erstellung von Ressourcenlisten-Seiten","Erstellung von Ressourcenbearbeitungsformularen","Verwendung von etablierten Projektmustern","Unterstützung für benutzerdefinierte Verwaltungsroutes","Integration mit Ressourcenlisten- und -formularkomponenten","Kompatibilität mit TypeScript und React"],"pt":["Geração de páginas de dashboard administrativas personalizadas","Utilização de React e TypeScript para desenvolvimento","Estrutura de página de lista e detalhe/editar","Componentes reutilizáveis, como ResourcesList e ResourceForm"],"ru":["Генерация индивидуальных страниц админ-панели","Использование React и TypeScript для разработки","Структура страницы списка и деталей/редактирования","Многократно используемые компоненты, такие как ResourcesList и ResourceForm"],"ar":["توليد صفحات لوحة تحكم إدارية مخصصة","استخدام React و TypeScript للتنمية","هيكل صفحة القائمة والتفاصيل/التحرير","مكونات قابلة لإعادة الاستخدام، مثل ResourcesList و ResourceForm"]},"keywords":{"en":["how to use admin-crud","admin-crud setup guide","admin-crud alternative","admin-crud vs custom implementation","admin-crud install","what is admin-crud","admin-crud tutorial","admin-crud best practices","admin-crud for AI agents"],"zh":["Admin CRUD 生成器","AIエージェント工具","管理面板页面","列表页","详细编辑页","React","TypeScript","CLI","数据表格","表单组件"],"ja":["Admin CRUD","AIエージェントツール","管理ダッシュボード ページ","リスト ページ","詳細編集ページ","React","TypeScript","CLI","データ テーブル","フォーム コンポーネント"],"ko":["Admin CRUD 생성기","AI 에이전트 도구","관리 대시보드 페이지","리스트 페이지","상세 편집 페이지","React","TypeScript","CLI","데이터 테이블","폼 컴포넌트"],"es":["generador de CRUD de administración","herramientas de AI para desarrolladores","CRUD de administración","patrones de proyecto","TypeScript","React","desarrollo de software","herramientas de desarrollo","generación de código"],"fr":["générateur de CRUD d''administration","outils de génération de CRUD","CRUD d''administration","modèles de projet","TypeScript","React","développement de logiciels","outils de développement","génération de code"],"de":["Admin-CRUD-Generator","AI-Tools für Entwickler","Admin-CRUD","Projektmuster","TypeScript","React","Softwareentwicklung","Entwicklungstools","Codegenerierung"],"pt":["admin crud","gerador de páginas de dashboard","react","typescript","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["admin crud","генератор страниц админ-панели","react","typescript","разработка программного обеспечения","инструменты разработки"],"ar":["admin crud","مولد صفحات لوحة تحكم","react","typescript","تطوير البرمجيات","أدوات التطوير"]}},"owner":"Mavrick91","repo":"tanstack-start-app","repoPath":"Mavrick91/tanstack-start-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.414Z","topics":[],"category":"community","skillMd":{"name":"admin-crud","description":"Generate admin dashboard pages with data tables, filters, bulk actions, dialogs, and forms. Use when building admin interfaces, management pages, or dashboard components.","bodyPreview":"# Admin CRUD Generator\n\nCreate admin dashboard pages following this project''s established patterns.\n\n## Admin Page Structure\n\n```\nsrc/\n├── routes/admin/\n│   └── resources/\n│       ├── index.tsx          # List page\n│       └── $resourceId.tsx    # Detail/edit page\n└── components/admin/\n    └── resources/\n        ├── ResourcesList.tsx        # List container\n        ├── ResourceForm.tsx         # Create/edit form\n        └── components/\n            ├── ResourceTable.tsx    # Data table","body":"# Admin CRUD Generator\n\nCreate admin dashboard pages following this project''s established patterns.\n\n## Admin Page Structure\n\n```\nsrc/\n├── routes/admin/\n│   └── resources/\n│       ├── index.tsx          # List page\n│       └── $resourceId.tsx    # Detail/edit page\n└── components/admin/\n    └── resources/\n        ├── ResourcesList.tsx        # List container\n        ├── ResourceForm.tsx         # Create/edit form\n        └── components/\n            ├── ResourceTable.tsx    # Data table\n            ├── StatusBadge.tsx      # Status indicator\n            ├── BulkActionsBar.tsx   # Bulk operations\n            └── ResourceActions.tsx  # Row actions\n```\n\n## List Page Template\n\n```typescript\n// src/routes/admin/resources/index.tsx\nimport { createFileRoute } from ''@tanstack/react-router''\nimport { ResourcesList } from ''@/components/admin/resources/ResourcesList''\n\nexport const Route = createFileRoute(''/admin/resources/'')({\n  component: ResourcesPage,\n})\n\nfunction ResourcesPage() {\n  return <ResourcesList />\n}\n```\n\n## List Component with Data Table\n\n```typescript\n// src/components/admin/resources/ResourcesList.tsx\nimport { useQuery } from ''@tanstack/react-query''\nimport { useTranslation } from ''react-i18next''\nimport { Plus } from ''lucide-react''\nimport { Link } from ''@tanstack/react-router''\n\nimport { Button } from ''@/components/ui/button''\nimport { ResourceTable } from ''./components/ResourceTable''\n\nexport function ResourcesList() {\n  const { t } = useTranslation()\n\n  const { data, isLoading, error } = useQuery({\n    queryKey: [''resources''],\n    queryFn: async () => {\n      const res = await fetch(''/api/resources'', { credentials: ''include'' })\n      const json = await res.json()\n      if (!json.success) throw new Error(json.error)\n      return json\n    },\n  })\n\n  if (isLoading) {\n    return (\n      <div className=\"flex items-center justify-center h-64\">\n        <div\n          className=\"animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-pink-500\"\n          role=\"status\"\n          aria-label=\"Loading\"\n        />\n      </div>\n    )\n  }\n\n  if (error) {\n    return (\n      <div className=\"text-center py-12\">\n        <p className=\"text-red-500\">{t(''Failed to load'')}</p>\n      </div>\n    )\n  }\n\n  const { items, total } = data\n\n  if (items.length === 0) {\n    return (\n      <div className=\"text-center py-12\">\n        <Package className=\"mx-auto h-12 w-12 text-muted-foreground\" />\n        <h3 className=\"mt-2 text-sm font-semibold\">{t(''No resources'')}</h3>\n        <p className=\"mt-1 text-sm text-muted-foreground\">\n          {t(''Get started by creating a new resource.'')}\n        </p>\n        <div className=\"mt-6\">\n          <Button asChild>\n            <Link to=\"/admin/resources/new\">\n              <Plus className=\"mr-2 h-4 w-4\" />\n              {t(''Add Resource'')}\n            </Link>\n          </Button>\n        </div>\n      </div>\n    )\n  }\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"flex items-center justify-between\">\n        <h1 className=\"text-2xl font-bold\">{t(''Resources'')}</h1>\n        <Button asChild>\n          <Link to=\"/admin/resources/new\">\n            <Plus className=\"mr-2 h-4 w-4\" />\n            {t(''Add Resource'')}\n          </Link>\n        </Button>\n      </div>\n\n      <ResourceTable resources={items} />\n\n      <div className=\"text-sm text-muted-foreground\">\n        {t(''{{count}} total'', { count: total })}\n      </div>\n    </div>\n  )\n}\n```\n\n## Data Table Component\n\n```typescript\n// src/components/admin/resources/components/ResourceTable.tsx\nimport { useState } from ''react''\nimport { Link } from ''@tanstack/react-router''\nimport { MoreHorizontal, ArrowUpDown, ArrowUp, ArrowDown } from ''lucide-react''\nimport { useTranslation } from ''react-i18next''\n\nimport {\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuItem,\n  DropdownMenuTrigger,\n} from ''@/components/ui/dropdown-menu''\nimport { Button } from ''@/components/ui/button''\nimport { Checkbox } from ''@/components/ui/checkbox''\nimport { StatusBadge } from ''./StatusBadge''\n\ninterface Resource {\n  id: string\n  name: { en: string }\n  status: ''active'' | ''draft'' | ''archived''\n  createdAt: string\n}\n\ninterface Props {\n  resources: Resource[]\n}\n\nexport function ResourceTable({ resources }: Props) {\n  const { t } = useTranslation()\n  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set())\n  const [sortKey, setSortKey] = useState<string>(''createdAt'')\n  const [sortOrder, setSortOrder] = useState<''asc'' | ''desc''>(''desc'')\n\n  const toggleSelect = (id: string) => {\n    const next = new Set(selectedIds)\n    if (next.has(id)) {\n      next.delete(id)\n    } else {\n      next.add(id)\n    }\n    setSelectedIds(next)\n  }\n\n  const toggleSelectAll = () => {\n    if (selectedIds.size === resources.length) {\n      setSelectedIds(new Set())\n    } else {\n      setSelectedIds(new Set(resources.map((r) => r.id)))\n    }\n  }\n\n  const isAllSelected = selectedIds.size === resources.length\n  const isSomeSelected = selectedIds.size > 0 && selectedIds.size < resources.length\n\n  const handleSort = (key: string) => {\n    if (sortKey === key) {\n      setSortOrder(sortOrder === ''asc'' ? ''desc'' : ''asc'')\n    } else {\n      setSortKey(key)\n      setSortOrder(''desc'')\n    }\n  }\n\n  const SortIcon = ({ columnKey }: { columnKey: string }) => {\n    if (sortKey !== columnKey) return <ArrowUpDown className=\"ml-2 h-4 w-4\" />\n    return sortOrder === ''asc''\n      ? <ArrowUp className=\"ml-2 h-4 w-4\" />\n      : <ArrowDown className=\"ml-2 h-4 w-4\" />\n  }\n\n  return (\n    <>\n      {selectedIds.size > 0 && (\n        <BulkActionsBar\n          selectedCount={selectedIds.size}\n          onClearSelection={() => setSelectedIds(new Set())}\n        />\n      )}\n\n      <div className=\"rounded-md border\">\n        <table className=\"w-full\">\n          <thead>\n            <tr className=\"border-b bg-muted/50\">\n              <th className=\"w-12 p-4\">\n                <Checkbox\n                  checked={isAllSelected}\n                  indeterminate={isSomeSelected}\n                  onCheckedChange={toggleSelectAll}\n                />\n              </th>\n              <th className=\"p-4 text-left\">\n                <button\n                  className=\"flex items-center font-medium\"\n                  onClick={() => handleSort(''name'')}\n                >\n                  {t(''Name'')}\n                  <SortIcon columnKey=\"name\" />\n                </button>\n              </th>\n              <th className=\"p-4 text-left\">{t(''Status'')}</th>\n              <th className=\"p-4 text-left\">\n                <button\n                  className=\"flex items-center font-medium\"\n                  onClick={() => handleSort(''createdAt'')}\n                >\n                  {t(''Created'')}\n                  <SortIcon columnKey=\"createdAt\" />\n                </button>\n              </th>\n              <th className=\"w-12 p-4\"></th>\n            </tr>\n          </thead>\n          <tbody>\n            {resources.map((resource) => (\n              <tr\n                key={resource.id}\n                className={`border-b hover:bg-muted/50 group ${\n                  selectedIds.has(resource.id) ? ''bg-pink-500/5'' : ''''\n                }`}\n              >\n                <td className=\"p-4\">\n                  <Checkbox\n                    checked={selectedIds.has(resource.id)}\n                    onCheckedChange={() => toggleSelect(resource.id)}\n                  />\n                </td>\n                <td className=\"p-4\">\n                  <Link\n                    to=\"/admin/resources/$resourceId\"\n                    params={{ resourceId: resource.id }}\n                    className=\"font-medium hover:underline\"\n                  >\n                    {resource.name.en}\n                  </Link>\n                </td>\n                <td className=\"p-4\">\n                  <StatusBadge status={resource.status} />\n                </td>\n                <td className=\"p-4 text-muted-foreground\">\n                  {new Date(resource.createdAt).toLocaleDateString()}\n                </td>\n                <td className=\"p-4\">\n                  <DropdownMenu>\n                    <DropdownMenuTrigger asChild>\n                      <Button variant=\"ghost\" size=\"icon\">\n                        <MoreHorizontal className=\"h-4 w-4\" />\n                      </Button>\n                    </DropdownMenuTrigger>\n                    <DropdownMenuContent align=\"end\">\n                      <DropdownMenuItem asChild>\n                        <Link\n                          to=\"/admin/resources/$resourceId\"\n                          params={{ resourceId: resource.id }}\n                        >\n                          {t(''Edit'')}\n                        </Link>\n                      </DropdownMenuItem>\n                      <DropdownMenuItem className=\"text-destructive\">\n                        {t(''Delete'')}\n                      </DropdownMenuItem>\n                    </DropdownMenuContent>\n                  </DropdownMenu>\n                </td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      </div>\n    </>\n  )\n}\n```\n\n## Status Badge\n\n```typescript\n// src/components/admin/resources/components/StatusBadge.tsx\nimport { cn } from ''@/lib/utils''\n\nconst statusStyles = {\n  active: ''bg-emerald-500/10 text-emerald-500'',\n  draft: ''bg-amber-500/10 text-amber-500'',\n  archived: ''bg-muted text-muted-foreground'',\n  pending: ''bg-blue-500/10 text-blue-500'',\n  processing: ''bg-purple-500/10 text-purple-500'',\n  shipped: ''bg-cyan-500/10 text-cyan-500'',\n  delivered: ''bg-emerald-500/10 text-emerald-500'',\n  cancelled: ''bg-red-500/10 text-red-500'',\n  paid: ''bg-emerald-500/10 text-emerald-500'',\n  failed: ''bg-red-500/10 text-red-500'',\n  refunded: ''bg-amber-500/10 text-amber-500'',\n}\n\ninterface Props {\n  status: keyof typeof statusStyles\n}\n\nexport function StatusBadge({ status }: Props) {\n  return (\n    <span\n      className={cn(\n        ''inline-flex items-center gap-1.5 rounded-full px-2 py-1 text-xs font-medium uppercase'',\n        statusStyles[status] || statusStyles.draft\n      )}\n    >\n      <span className=\"h-1.5 w-1.5 rounded-full bg-current\" />\n      {status}\n    </span>\n  )\n}\n```\n\n## Bulk Actions Bar\n\n```typescript\n// src/components/admin/resources/components/BulkActionsBar.tsx\nimport { useMutation, useQueryClient } from ''@tanstack/react-query''\nimport { useTranslation } from ''react-i18next''\nimport { toast } from ''sonner''\n\nimport { Button } from ''@/components/ui/button''\n\ninterface Props {\n  selectedCount: number\n  selectedIds: string[]\n  onClearSelection: () => void\n}\n\nexport function BulkActionsBar({ selectedCount, selectedIds, onClearSelection }: Props) {\n  const { t } = useTranslation()\n  const queryClient = useQueryClient()\n\n  const bulkUpdate = useMutation({\n    mutationFn: async (action: ''activate'' | ''archive'' | ''delete'') => {\n      const res = await fetch(''/api/resources/bulk'', {\n        method: ''POST'',\n        headers: { ''Content-Type'': ''application/json'' },\n        credentials: ''include'',\n        body: JSON.stringify({ ids: selectedIds, action }),\n      })\n      const json = await res.json()\n      if (!json.success) throw new Error(json.error)\n      return json\n    },\n    onSuccess: () => {\n      queryClient.invalidateQueries({ queryKey: [''resources''] })\n      onClearSelection()\n      toast.success(t(''Updated successfully''))\n    },\n    onError: (error) => {\n      toast.error(error.message)\n    },\n  })\n\n  return (\n    <div className=\"flex items-center gap-4 rounded-lg border bg-muted/50 p-4\">\n      <span className=\"text-sm font-medium\">\n        {t(''{{count}} selected'', { count: selectedCount })}\n      </span>\n      <div className=\"flex gap-2\">\n        <Button\n          size=\"sm\"\n          variant=\"outline\"\n          onClick={() => bulkUpdate.mutate(''activate'')}\n          disabled={bulkUpdate.isPending}\n        >\n          {t(''Activate'')}\n        </Button>\n        <Button\n          size=\"sm\"\n          variant=\"outline\"\n          onClick={() => bulkUpdate.mutate(''archive'')}\n          disabled={bulkUpdate.isPending}\n        >\n          {t(''Archive'')}\n        </Button>\n        <Button\n          size=\"sm\"\n          variant=\"destructive\"\n          onClick={() => bulkUpdate.mutate(''delete'')}\n          disabled={bulkUpdate.isPending}\n        >\n          {t(''Delete'')}\n        </Button>\n      </div>\n      <Button\n        size=\"sm\"\n        variant=\"ghost\"\n        onClick={onClearSelection}\n        className=\"ml-auto\"\n      >\n        {t(''Clear selection'')}\n      </Button>\n    </div>\n  )\n}\n```\n\n## Card-Based Form Layout\n\n```typescript\n// Product form pattern with gradient accent cards\n<div className=\"grid lg:grid-cols-3 gap-6\">\n  {/* Main content - 2 columns */}\n  <div className=\"lg:col-span-2 space-y-6\">\n    {/* Details Card */}\n    <Card className=\"border-border/50 shadow-xl shadow-foreground/5 bg-card/50 backdrop-blur-sm overflow-hidden\">\n      <div className=\"h-1 bg-gradient-to-r from-pink-500 to-purple-500\" />\n      <CardHeader>\n        <CardTitle>{t(''Details'')}</CardTitle>\n      </CardHeader>\n      <CardContent>\n        {/* Form fields */}\n      </CardContent>\n    </Card>\n\n    {/* Media Card */}\n    <Card className=\"overflow-hidden\">\n      <div className=\"h-1 bg-gradient-to-r from-violet-500 to-fuchsia-500\" />\n      <CardHeader>\n        <CardTitle>{t(''Media'')}</CardTitle>\n      </CardHeader>\n      <CardContent>\n        {/* Image uploader */}\n      </CardContent>\n    </Card>\n  </div>\n\n  {/* Sidebar - 1 column, sticky */}\n  <div className=\"space-y-6\">\n    <div className=\"lg:sticky lg:top-4\">\n      {/* Status Card */}\n      <Card>\n        <div className=\"h-1 bg-gradient-to-r from-emerald-500 to-teal-500\" />\n        <CardHeader>\n          <CardTitle>{t(''Status'')}</CardTitle>\n        </CardHeader>\n        <CardContent>\n          {/* Status select */}\n        </CardContent>\n      </Card>\n    </div>\n  </div>\n</div>\n```\n\n## Gradient Accent Colors\n\n| Section  | Gradient                         |\n| -------- | -------------------------------- |\n| Details  | `from-pink-500 to-purple-500`    |\n| Media    | `from-violet-500 to-fuchsia-500` |\n| Options  | `from-blue-500 to-cyan-500`      |\n| Variants | `from-emerald-500 to-teal-500`   |\n| SEO      | `from-amber-500 to-orange-500`   |\n\n## Confirmation Dialog\n\n```typescript\nimport {\n  AlertDialog,\n  AlertDialogAction,\n  AlertDialogCancel,\n  AlertDialogContent,\n  AlertDialogDescription,\n  AlertDialogFooter,\n  AlertDialogHeader,\n  AlertDialogTitle,\n} from ''@/components/ui/alert-dialog''\n\nfunction DeleteConfirmDialog({ open, onOpenChange, onConfirm, resourceName }) {\n  const { t } = useTranslation()\n\n  return (\n    <AlertDialog open={open} onOpenChange={onOpenChange}>\n      <AlertDialogContent>\n        <AlertDialogHeader>\n          <AlertDialogTitle>{t(''Delete Resource'')}</AlertDialogTitle>\n          <AlertDialogDescription>\n            {t(''Are you sure you want to delete \"{{name}}\"? This action cannot be undone.'', {\n              name: resourceName,\n            })}\n          </AlertDialogDescription>\n        </AlertDialogHeader>\n        <AlertDialogFooter>\n          <AlertDialogCancel>{t(''Cancel'')}</AlertDialogCancel>\n          <AlertDialogAction\n            onClick={onConfirm}\n            className=\"bg-destructive text-destructive-foreground hover:bg-destructive/90\"\n          >\n            {t(''Delete'')}\n          </AlertDialogAction>\n        </AlertDialogFooter>\n      </AlertDialogContent>\n    </AlertDialog>\n  )\n}\n```\n\n## See Also\n\n- `src/components/admin/products/` - Full product CRUD example\n- `src/components/admin/orders/` - Order management\n- `src/hooks/useDataTable.ts` - Table state management\n- `forms` skill - Form patterns with FNForm\n"},"lastSynced":"2026-03-08T02:07:11.957Z","agentAnalysis":{"suitability":{"en":"Ideal for Full Stack Agents needing rapid admin dashboard development with CRUD operations.","zh":"适合需要快速开发管理仪表板且具有CRUD操作的全栈代理。","ja":"管理ダッシュボードの迅速な開発とCRUD操作が必要なフルスタックエージェントに最適です。","ko":"CRUD 연산을 포함한 관리 대시보드를 신속하게 개발해야 하는 풀스택 에이전트에 적합합니다.","es":"Ideal para Agentes de Full Stack que necesitan un desarrollo rápido de paneles de administración con operaciones CRUD.","fr":"Idéal pour les agents Full Stack ayant besoin d''un développement rapide de tableaux de bord d''administration avec des opérations CRUD.","de":"Ideal für Full-Stack-Agents, die eine schnelle Entwicklung von Admin-Dashboards mit CRUD-Operationen benötigen.","pt":"Ideal para Agentes Full Stack que necessitam de desenvolvimento rápido de painéis de administração com operações CRUD.","ru":"Идеально подходит для Full Stack агентов, которым требуется быстрая разработка панелей администрирования с операциями CRUD.","ar":"مثالي لعميل متكامل يحتاج إلى إنشاء لوحات تحكم إدارية سريعة مع عمليات CRUD."},"recommendation":{"en":"Empowers agents to generate admin dashboard pages following established patterns, utilizing TypeScript and React components like ResourcesList.tsx and ResourceForm.tsx, and creates list and detail/edit pages with src/routes/admin and components/admin structures.","zh":"赋予代理生成管理仪表板页面的能力，遵循既定的模式，利用TypeScript和React组件，如ResourcesList.tsx和ResourceForm.tsx，并在src/routes/admin和components/admin结构中创建列表和详细/编辑页面。","ja":"エージェントに、既存のパターンに従って管理ダッシュボードページを生成する能力を付与し、TypeScriptとReactコンポーネント（例：ResourcesList.tsxとResourceForm.tsx）を利用し、src/routes/adminとcomponents/admin構造内にリストと詳細/編集ページを作成します。","ko":"에이전트에게 정해진 패턴을 따라 관리 대시보드 페이지를 생성할 수 있는 능력을 부여하며, TypeScript와 React 컴포넌트(예: ResourcesList.tsx와 ResourceForm.tsx)를 사용하며, src/routes/admin과 components/admin 구조 내에 목록 및 자세한/편집 페이지를 생성합니다.","es":"Permite a los agentes generar páginas del panel de administración siguiendo patrones establecidos, utilizando TypeScript y componentes de React como ResourcesList.tsx y ResourceForm.tsx, y crea páginas de lista y detalle/edición con estructuras src/routes/admin y components/admin.","fr":"Permet aux agents de générer des pages de tableau de bord d''administration en suivant des modèles établis, en utilisant TypeScript et des composants React tels que ResourcesList.tsx et ResourceForm.tsx, et crée des pages de liste et de détail/édition avec des structures src/routes/admin et components/admin.","de":"Ermöglicht es Agenten, Admin-Dashboard-Seiten nach etablierten Mustern zu generieren, indem sie TypeScript und React-Komponenten wie ResourcesList.tsx und ResourceForm.tsx verwenden, und erstellt Listen- und Detail-/Bearbeitungsseiten mit src/routes/admin- und components/admin-Strukturen.","pt":"Habilita os agentes a gerar páginas de painel de administração seguindo padrões estabelecidos, utilizando TypeScript e componentes React como ResourcesList.tsx e ResourceForm.tsx, e cria páginas de lista e detalhe/edição com estruturas src/routes/admin e components/admin.","ru":"Позволяет агентам создавать страницы панели администрирования, следуя установленным шаблонам, используя TypeScript и компоненты React, такие как ResourcesList.tsx и ResourceForm.tsx, и создает страницы списка и детализации/редактирования со структурами src/routes/admin и components/admin.","ar":"تمكّن الوكيل من إنشاء صفحات لوحة التحكم الإدارية اتباعًا لأنماط محددة، مستخدمًا TypeScript ومكونات React مثل ResourcesList.tsx وResourceForm.tsx، وينشئ صفحات قائمة وتفاصيل/تحرير بتراكيب src/routes/admin ومكونات/admin."},"useCases":{"en":["Generating admin dashboard pages for resource management","Creating list and detail/edit pages for custom resources","Automating CRUD operations for admin interfaces"],"zh":["为资源管理生成管理仪表板页面","为自定义资源创建列表和详细/编辑页面","自动执行管理接口的CRUD操作"],"ja":["リソース管理の管理ダッシュボードページを生成する","カスタムリソースのリストと詳細/編集ページを作成する","管理インターフェイスのCRUD操作を自動化する"],"ko":["리소스 관리를 위한 관리 대시보드 페이지 생성","사용자 정의 리소스에 대한 목록 및 자세한/편집 페이지 생성","관리 인터페이스의 CRUD 연산 자동화"],"es":["Generación de páginas del panel de administración para la gestión de recursos","Creación de páginas de lista y detalle/edición para recursos personalizados","Automatización de operaciones CRUD para interfaces de administración"],"fr":["Génération de pages de tableau de bord d''administration pour la gestion des ressources","Création de pages de liste et de détail/édition pour des ressources personnalisées","Automatisation des opérations CRUD pour les interfaces d''administration"],"de":["Erstellung von Admin-Dashboard-Seiten für die Ressourcenverwaltung","Erstellung von Listen- und Detail-/Bearbeitungsseiten für benutzerdefinierte Ressourcen","Automatisierung von CRUD-Operationen für Admin-Oberflächen"],"pt":["Geração de páginas de painel de administração para gerenciamento de recursos","Criação de páginas de lista e detalhe/edição para recursos personalizados","Automatização de operações CRUD para interfaces de administração"],"ru":["Генерация страниц панели администрирования для управления ресурсами","Создание страниц списка и детализации/редактирования для пользовательских ресурсов","Автоматизация операций CRUD для интерфейсов администрирования"],"ar":["إنشاء صفحات لوحة التحكم الإدارية لإدارة الموارد","إنشاء صفحات قائمة وتفاصيل/تحرير للموارد المخصصة","تأتمتة عمليات CRUD لواجهات الإدارة"]},"limitations":{"en":["Requires established project patterns","Limited to React and TypeScript environments"],"zh":["需要已建立的项目模式","仅限React和TypeScript环境"],"ja":["既存のプロジェクトパターンが必要","ReactとTypeScript環境のみで使用可能"],"ko":["이미 설정된 프로젝트 패턴이 필요","React와 TypeScript 환경에서만 사용 가능"],"es":["Requiere patrones de proyecto establecidos","Limitado a entornos React y TypeScript"],"fr":["Nécessite des modèles de projet établis","Limité aux environnements React et TypeScript"],"de":["Erfordert etablierte Projektmodelle","Begrenzt auf React- und TypeScript-Umgebungen"],"pt":["Exige padrões de projeto estabelecidos","Limitado a ambientes React e TypeScript"],"ru":["Требует установленных шаблонов проекта","Ограничен средами React и TypeScript"],"ar":["يتطلب نماذج مشروع محددة","محدود ببيئات React وTypeScript"]},"version":4},"contentHash":"c947395f5f508df7981b59b6b3a78756a0ec78a517f838fb5b14e615734749d1","qualityScore":39}');
