INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Mavrick91/tanstack-start-app/admin-crud', 'admin-crud', 'Mavrick91', 'tanstack-start-app', 'community', 'admin-crud Mavrick91 tanstack-start-app community The admin-crud skill generates admin dashboard pages following established patterns, benefiting developers who need to create list and detail/edit pages. Admin CRUD 生成器用于创建管理面板页面，包括列表页和详细编辑页，按照项目的既定模式进行设置 Admin CRUD は管理ダッシュボード ページの作成に使用され、プロジェクトの既定のパターンに従って設定します Admin CRUD 생성기는 관리 대시보드 페이지를 생성하는 데 사용되며 프로젝트의 정해진 패턴에 따라 설정합니다 El generador de CRUD de administración crea páginas de panel de administración siguiendo patrones establecidos. Permite la creación de listas y formularios de recursos Le générateur de CRUD d''administration crée des pages de tableau de bord d''administration suivant des modèles établis. Il permet la création de listes et de formulaires de ressources Der Admin-CRUD-Generator erstellt Verwaltungsdashboard-Seiten nach etablierten Mustern. Er ermöglicht die Erstellung von Ressourcenlisten und -formularen O Admin CRUD é um gerador de páginas de dashboard administrativas que segue os padrões estabelecidos do projeto, utilizando React e TypeScript. ИИ Агент Admin CRUD - это генератор страниц админ-панели, следующий установленным шаблонам проекта, использующий React и TypeScript. Admin CRUD هو مولد صفحات لوحة تحكم إدارية يتبع الأنماط المعتمدة للمشروع، ويستخدم React و TypeScript. how to use admin-crud admin-crud setup guide admin-crud alternative admin-crud vs custom implementation admin-crud install what is admin-crud admin-crud tutorial admin-crud best practices admin-crud for AI agents Admin CRUD 生成器 AIエージェント工具 管理面板页面 列表页 详细编辑页 React TypeScript CLI 数据表格 表单组件 Generates list pages using index.tsx Creates detail/edit pages using $resourceId.tsx Utilizes ResourcesList.tsx as a list container Employs ResourceForm.tsx for create/edit forms Leverages ResourceTable.tsx for data tables Follows a structured approach for admin page organization admin-crud is a skill that generates admin dashboard pages, including list and detail/edit pages, using a structured approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('coco4atJP/Tepora-alpha/add-backend-tool', 'community', 'coco4atJP', 'Tepora-alpha', 'coco4atJP/Tepora-alpha', 'add-backend-tool', 0, 0, 39, '2026-03-08T01:57:15.416Z', '2026-03-08T02:07:15.932Z', '215d63c14b56d50af5d3de98c0aff20bd6265488e924edf0fe142c21a6fb4897', '{"id":"coco4atJP/Tepora-alpha/add-backend-tool","name":"add-backend-tool","description":{"en":"The add-backend-tool skill enables developers to extend Tepora''s backend with custom tools. It provides a guide on modifying the tooling.rs file and implementing new tool logic.","zh":"add-backend-tool技能为Tepora项目添加新工具提供了一个全面的指南，涵盖工具定义、注册和JSON Schema配置","ja":"バックエンドツールの追加技能は、Teporaプロジェクトに新しいツールを追加するための包括的なガイドを提供します","ko":"백엔드 툴 추가 스킬은 Тепора 프로젝트에 새로운 툴을 추가하는 방법에 대한 포괄적인 가이드를 제공합니다","es":"add-backend-tool es una habilidad que permite agregar nuevas herramientas de backend a proyectos Tepora. Proporciona una guía para implementar herramientas personalizadas para agentes de inteligencia artificial.","fr":"add-backend-tool est une compétence qui permet d''ajouter de nouvelles outils de backend aux projets Tepora. Elle fournit un guide pour mettre en œuvre des outils personnalisés pour les agents d''intelligence artificielle.","de":"add-backend-tool ist eine Fähigkeit, die das Hinzufügen neuer Backend-Tools zu Tepora-Projekten ermöglicht. Sie bietet eine Anleitung zur Implementierung benutzerdefinierter Tools für KI-Agents.","pt":"O add-backend-tool é uma habilidade que permite adicionar novas ferramentas ao backend do Tepora. Ele fornece um guia passo a passo para implementar novas funcionalidades.","ru":"Add-backend-tool - это навык, который позволяет добавлять новые инструменты в бэкэнд Tepora. Он предоставляет пошаговое руководство по реализации новых функций.","ar":"أداة إضافة الخلفية هي مهارة تسمح بإضافة أدوات جديدة إلى الخلفية Tepora. توفر إرشادات خطوة بخطوة لتنفيذ وظائف جديدة."},"seo":{"title":{"en":"add-backend-tool: Setup Guide for AI Agents | Tepora Project","zh":"添加后端工具 Setup Guide - AIエージェント集成","ja":"バックエンドツールの追加 Setup Guide - AIエージェント","ko":"백엔드 툴 추가 Setup Guide - AI 에이전트 통합","es":"Configuración de Herramientas de Agente de Inteligencia A...","fr":"Guide d''installation d''outils d''agent d''intelligence arti...","de":"Einrichten von KI-Tools mit add-backend-tool: Eine Schrit...","pt":"Guia de Configuração do add-backend-tool para Desenvolved...","ru":"Настройка ИИ Агентов с помощью add-backend-tool: Лучшие П...","ar":"إعداد أداة الخلفية باستخدام add-backend-tool: دليل المطورين"},"description":{"en":"Discover how to add new tools to Tepora''s backend with our step-by-step guide. Learn to modify tooling.rs and implement new tool logic today!","zh":"学习如何使用add-backend-tool技能为Tepora项目添加新工具，包括工具定义、注册和JSON Schema配置","ja":"Teporaプロジェクトに新しいツールを追加するためのガイド。ツール定義、登録、JSON Schema設定など","ko":"Tepora 프로젝트에 새로운 툴을 추가하는 방법에 대한 가이드. 툴 정의, 등록, JSON Schema 설정 등","es":"Aprende a agregar herramientas de backend a tu proyecto Tepora con add-backend-tool. Descubre cómo implementar herramientas personalizadas para agentes de in...","fr":"Découvrez comment ajouter des outils de backend à votre projet Tepora avec add-backend-tool. Apprenez à mettre en œuvre des outils personnalisés pour les age...","de":"Erfahren Sie, wie Sie mit add-backend-tool Tools für KI-Agents in Ihrem Tepora-Projekt hinzufügen. Lernen Sie, wie Sie benutzerdefinierte Tools implementieren.","pt":"Aprenda a adicionar novas ferramentas ao backend do Tepora com o add-backend-tool. Descubra como melhorar a funcionalidade do seu projeto.","ru":"Узнайте, как добавить новые инструменты в бэкэнд Tepora с помощью add-backend-tool. Улучшите функциональность своего проекта.","ar":"تعرف على كيفية إضافة أدوات جديدة إلى الخلفية Tepora باستخدام add-backend-tool. تحسين أداء مشروعك."},"definition":{"en":"add-backend-tool is a skill that allows developers to add new tools to Tepora''s backend, enabling customization and extension of the project''s functionality.","zh":"add-backend-tool技能是用于为Tepora项目添加新工具的技术指南","ja":"バックエンドツールの追加技能は、Teporaプロジェクトに新しいツールを追加するための技術ガイドです","ko":"백엔드 툴 추가 스킬은 Тепора 프로젝트에 새로운 툴을 추가하는 기술 가이드입니다","es":"add-backend-tool es una habilidad que permite agregar herramientas de backend personalizadas a proyectos Tepora para agentes de inteligencia artificial.","fr":"add-backend-tool est une compétence qui permet d''ajouter des outils de backend personnalisés aux projets Tepora pour les agents d''intelligence artificielle.","de":"add-backend-tool ist eine Fähigkeit, die das Hinzufügen benutzerdefinierter Backend-Tools zu Tepora-Projekten für KI-Agents ermöglicht.","pt":"O add-backend-tool é uma habilidade que permite adicionar novas ferramentas ao backend do Tepora, melhorando a funcionalidade do projeto.","ru":"Add-backend-tool - это навык, который позволяет добавлять новые инструменты в бэкэнд Tepora, улучшая функциональность проекта.","ar":"أداة إضافة الخلفية هي مهارة تسمح بإضافة أدوات جديدة إلى الخلفية Tepora، وتحسين أداء المشروع."},"features":{"en":["Modifies tooling.rs to add new tool definitions","Implements new tool logic using Rust programming language","Registers new tools in the tooling.rs file using match statements","Supports JSON schema definition for tool configuration","Enables customization of Tepora''s backend functionality"],"zh":["工具定义的创建","工具注册到tooling.rs","JSON Schema配置","Rust编程语言支持","Tepora项目集成"],"ja":["ツール定義の作成","ツールの登録","JSON Schema設定","Rustプログラミング言語のサポート","Teporaプロジェクトとの統合"],"ko":["툴 정의의 생성","툴 등록","JSON Schema 설정","Rust 프로그래밍 언어 지원","Tepora 프로젝트 통합"],"es":["Creación de herramientas de backend personalizadas","Implementación de lógica de herramientas en Rust","Registro de herramientas en el archivo tooling.rs","Uso de la función execute_tool para dispatch de herramientas","Compatibilidad con la estructura de proyecto Tepora"],"fr":["Création d''outils de backend personnalisés","Mise en œuvre de la logique d''outils en Rust","Enregistrement d''outils dans le fichier tooling.rs","Utilisation de la fonction execute_tool pour le dispatch d''outils","Compatibilité avec la structure de projet Tepora"],"de":["Erstellung benutzerdefinierter Backend-Tools","Implementierung der Tool-Logik in Rust","Registrierung von Tools in der Datei tooling.rs","Verwendung der Funktion execute_tool für das Dispatchen von Tools","Kompatibilität mit der Tepora-Projektstruktur"],"pt":["Criação de definição de ferramenta","Registro de ferramenta no arquivo tooling.rs","Implementação de lógica de ferramenta","Uso de estruturas de dados Rust","Integração com o backend do Tepora"],"ru":["Создание определения инструмента","Регистрация инструмента в файле tooling.rs","Реализация логики инструмента","Использование структур данных Rust","Интеграция с бэкэндом Tepora"],"ar":["إنشاء تعريف الأداة","تسجيل الأداة في ملف tooling.rs","تنفيذ منطق الأداة","استخدام هياكل البيانات Rust","التكامل مع الخلفية Tepora"]},"keywords":{"en":["how to use add-backend-tool","add-backend-tool setup guide","Tepora project backend customization","add-backend-tool alternative","add-backend-tool vs other backend tools","Rust programming language for backend development","JSON schema definition for tool configuration"],"zh":["AIエージェント","add-backend-tool","Tepora项目","Rust编程","JSON Schema","工具定义","工具注册"],"ja":["AIエージェント","バックエンドツールの追加","Teporaプロジェクト","Rustプログラミング","JSON Schema","ツール定義","ツールの登録"],"ko":["AI 에이전트","백엔드 툴 추가","Tepora 프로젝트","Rust 프로그래밍","JSON Schema","툴 정의","툴 등록"],"es":["add-backend-tool","agentes de inteligencia artificial","herramientas de backend","proyectos Tepora","Rust","tooling.rs","execute_tool","desarrollo de software","IA"],"fr":["add-backend-tool","agents d''intelligence artificielle","outils de backend","projets Tepora","Rust","tooling.rs","execute_tool","développement de logiciels","IA"],"de":["add-backend-tool","KI-Agents","Backend-Tools","Tepora-Projekte","Rust","tooling.rs","execute_tool","Software-Entwicklung","Künstliche Intelligenz"],"pt":["add-backend-tool","Tepora","backend","ferramentas","Rust","desenvolvimento de software","programação","IA","agentes de IA"],"ru":["add-backend-tool","Tepora","бэкэнд","инструменты","Rust","разработка программного обеспечения","программирование","ИИ","ИИ Агенты"],"ar":["أداة إضافة الخلفية","Tepora","الخلفية","الأدوات","Rust","تطوير البرمجيات","البرمجة","الذكاء الاصطناعي","وكلاء الذكاء الاصطناعي"]}},"owner":"coco4atJP","repo":"Tepora-alpha","repoPath":"coco4atJP/Tepora-alpha","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.416Z","topics":[],"category":"community","skillMd":{"name":"add-backend-tool","description":"バックエンドに新しいネイティブツール（Function Calling用）を追加する手順です。","bodyPreview":"# `add-backend-tool` Skill\n\nTeporaのバックエンドに新しいツール（エージェントが使用する機能）を追加するためのガイドです。\n\n## 手順\n\n1.  **ツール定義の作成**\n    - `Tepora-app/backend-rs/src/tooling.rs` を編集します。\n    - 新しいツールの構造体や、ツールロジックを実装する関数を追加します。\n\n2.  **ツールレジストリへの登録**\n    - `tooling.rs` 内の `execute_tool` 関数（またはツールをディスパッチしている箇所）に、新しいツールの `case` を追加します。\n\n    ```rust\n    match tool_name {\n        \"existing_tool\" => { ... },\n        \"new_tool_name\" => {\n            // ツールロジックの呼び出し\n        },\n        _ => Err(...)\n    }\n    ```\n\n3.  **ツール定義（JSON Sche","body":"# `add-backend-tool` Skill\n\nTeporaのバックエンドに新しいツール（エージェントが使用する機能）を追加するためのガイドです。\n\n## 手順\n\n1.  **ツール定義の作成**\n    - `Tepora-app/backend-rs/src/tooling.rs` を編集します。\n    - 新しいツールの構造体や、ツールロジックを実装する関数を追加します。\n\n2.  **ツールレジストリへの登録**\n    - `tooling.rs` 内の `execute_tool` 関数（またはツールをディスパッチしている箇所）に、新しいツールの `case` を追加します。\n\n    ```rust\n    match tool_name {\n        \"existing_tool\" => { ... },\n        \"new_tool_name\" => {\n            // ツールロジックの呼び出し\n        },\n        _ => Err(...)\n    }\n    ```\n\n3.  **ツール定義（JSON Schema）の追加**\n    - エージェントにツールの存在を知らせるため、`api.rs` の `list_tools` エンドポイント（または設定ファイル）にツールのメタデータ（名前、説明、引数スキーマ）を追加します。\n\n## 注意点\n- ツール名は一意である必要があります。\n- エージェントがツールを正しく使えるよう、`description` (説明) は明確に記述してください。\n"},"lastSynced":"2026-03-08T02:07:15.932Z","agentAnalysis":{"suitability":{"en":"Essential for Rust-based AI Agents requiring backend extension capabilities in Tepora environments.","zh":"对于基于 Rust 的 AI Agent 在 Tepora 环境中需要后端扩展功能而言，这是必不可少的。","ja":"Tepora 環境においてバックエンド拡張機能を必要とする Rust ベースの AI Agent にとって必須です。","ko":"Tepora 환경에서 백엔드 확장 기능이 필요한 Rust 기반 AI Agent에게 필수적입니다.","es":"Esencial para agentes de inteligencia artificial basados en Rust que requieren capacidades de extensión de backend en entornos de Tepora.","fr":"Essentiel pour les agents d''intelligence artificielle basés sur Rust nécessitant des capacités d''extension de backend dans les environnements Tepora.","de":"Wesentlich für auf Rust basierende KI-Agents, die Backend-Erweiterungsfähigkeiten in Tepora-Umgebungen erfordern.","pt":"Essencial para Agentes de IA baseados em Rust que requerem capacidades de extensão de backend em ambientes Tepora.","ru":"Необходимо для агентов ИИ на основе Rust, требующих возможностей расширения бэкенда в средах Tepora.","ar":"ضروري لوكلاء الذكاء الاصطناعي الذين يعتمدون على Rust الذين يتطلبون إمكانيات تمديد الخلفية في بيئات Tepora."},"recommendation":{"en":"Enables direct modification of Tepora''s backend-rs tooling infrastructure through Rust struct implementation and tool registry integration. Provides the foundation for custom tool execution by extending the match dispatcher in tooling.rs.","zh":"通过 Rust struct 实现和 tool registry 集成，支持直接修改 Tepora 的 backend-rs 工具基础设施。通过扩展 tooling.rs 中的 match dispatcher，为自定义工具执行提供了基础。","ja":"Rust struct の実装と tool registry の統合を通じて、Tepora の backend-rs ツーリングインフラストラクチャを直接変更できるようにします。tooling.rs 内の match dispatcher を拡張することで、カスタムツール実行の基盤を提供します。","ko":"Rust struct 구현 및 tool registry 통합을 통해 Tepora의 backend-rs 도구 인프라를 직접 수정할 수 있게 합니다. tooling.rs의 match dispatcher를 확장하여 사용자 정의 도구 실행을 위한 기반을 제공합니다.","es":"Permite la modificación directa de la infraestructura de herramientas de backend-rs de Tepora a través de la implementación de estructuras de Rust y la integración del registro de herramientas. Proporciona la base para la ejecución de herramientas personalizadas al ampliar el despachador de coincidencias en tooling.rs.","fr":"Permet la modification directe de l''infrastructure d''outils de backend-rs de Tepora via la mise en œuvre de structures Rust et l''intégration du registre d''outils. Fournit la base pour l''exécution d''outils personnalisés en étendant le dispatcheur de correspondance dans tooling.rs.","de":"Ermöglicht die direkte Modifizierung der Infrastruktur der Backend-rs-Tooling von Tepora durch die Implementierung von Rust-Strukturen und die Integration des Tool-Registers. Bietet die Grundlage für die Ausführung von benutzerdefinierten Tools durch die Erweiterung des Match-Dispatchers in tooling.rs.","pt":"Permite a modificação direta da infraestrutura de ferramentas backend-rs da Tepora por meio da implementação de estruturas Rust e integração do registro de ferramentas. Fornece a base para a execução personalizada de ferramentas, estendendo o despachante de correspondência no tooling.rs.","ru":"Позволяет вносить прямые изменения в инфраструктуру инструментов backend-rs Tepora посредством реализации структур Rust и интеграции реестра инструментов. Предоставляет основу для настраиваемой исполнения инструментов, расширяя диспетчер соответствия в tooling.rs.","ar":"يسمح بالتعديل المباشر على بنية الأدوات الخلفية backend-rs الخاصة بشركة Tepora من خلال تنفيذ هيكل Rust وتكامل سجل الأدوات. يوفر الأساس للتشغيل المخصص للأدوات من خلال توسيع مشغل المطابقة في tooling.rs."},"useCases":{"en":["Extending Tepora backend functionality","Implementing custom agent tools","Modifying tool execution logic","Registering new tools in the execution registry"],"zh":["扩展 Tepora 后端功能","实现自定义 Agent 工具","修改工具执行逻辑","在执行注册表中注册新工具"],"ja":["Tepora バックエンド機能の拡張","カスタム Agent ツールの実装","ツール実行ロジックの変更","実行レジストリへの新しいツールの登録"],"ko":["Tepora 백엔드 기능 확장","사용자 정의 Agent 도구 구현","도구 실행 로직 수정","실행 레지스트리에 새로운 도구 등록"],"es":["Ampliar la funcionalidad de backend de Tepora","Implementar herramientas de agente personalizadas","Modificar la lógica de ejecución de herramientas","Registrar nuevas herramientas en el registro de ejecución"],"fr":["Étendre la fonctionnalité de backend de Tepora","Mettre en œuvre des outils d''agent personnalisés","Modifier la logique d''exécution des outils","Enregistrer de nouveaux outils dans le registre d''exécution"],"de":["Erweiterung der Backend-Funktionalität von Tepora","Implementierung von benutzerdefinierten Agenten-Tools","Modifizierung der Tool-Ausführungslogik","Registrierung neuer Tools im Ausführungsregister"],"pt":["Estender a funcionalidade de backend da Tepora","Implementar ferramentas de agente personalizadas","Modificar a lógica de execução de ferramentas","Registrar novas ferramentas no registro de execução"],"ru":["Расширение функциональности бэкенда Tepora","Реализация пользовательских инструментов агента","Модификация логики выполнения инструментов","Регистрация новых инструментов в реестре выполнения"],"ar":["توسيع وظيفة الخلفية الخاصة بشركة Tepora","تنفيذ أدوات وكيل مخصصة","تعديل منطق تشغيل الأدوات","تسجيل أدوات جديدة في سجل التشغيل"]},"limitations":{"en":["Requires Rust development environment","Tepora-specific backend-rs architecture only","Needs manual modification of tooling.rs file"],"zh":["需要 Rust 开发环境","仅限 Tepora 特定的 backend-rs 架构","需要手动修改 tooling.rs 文件"],"ja":["Rust 開発環境が必要","Tepora 固有の backend-rs アーキテクチャのみ対応","tooling.rs ファイルの手動変更が必要"],"ko":["Rust 개발 환경 필요","Tepora 전용 backend-rs 아키텍처만 해당","tooling.rs 파일 수동 수정 필요"],"es":["Requiere un entorno de desarrollo de Rust","Arquitectura de backend-rs específica de Tepora solo","Requiere modificación manual del archivo tooling.rs"],"fr":["Nécessite un environnement de développement Rust","Architecture de backend-rs spécifique à Tepora uniquement","Nécessite une modification manuelle du fichier tooling.rs"],"de":["Benötigt eine Rust-Entwicklungsumgebung","Tepora-spezifische Backend-rs-Architektur nur","Benötigt manuelle Modifizierung der Datei tooling.rs"],"pt":["Requer um ambiente de desenvolvimento Rust","Arquitetura de backend-rs específica da Tepora apenas","Necessita de modificação manual do arquivo tooling.rs"],"ru":["Требуется среда разработки Rust","Только архитектура backend-rs, специфичная для Tepora","Требуется ручное изменение файла tooling.rs"],"ar":["يتطلب بيئة تطوير Rust","هندسة backend-rs الخاصة بشركة Tepora فقط","يحتاج إلى تعديل يدوي لملف tooling.rs"]},"version":4},"contentHash":"215d63c14b56d50af5d3de98c0aff20bd6265488e924edf0fe142c21a6fb4897","qualityScore":39}');
