uery v5.","zh":"TanStack Query是一种用于React的查询库，提供了强大的数据获取和缓存功能","ja":"TanStack QueryはReact用のクエリライブラリであり，強力なデータ取得とキャッシュ機能を提供","ko":"TanStack Query는 React용 쿼리 라이브러리로서 강력한 데이터 가져오기와 캐시 기능을 제공","es":"tanstack-query es una herramienta de gestión de estado para aplicaciones React que utiliza React Query","fr":"tanstack-query est un outil de gestion d''état pour les applications React qui utilise React Query","de":"tanstack-query ist ein Tool für die Zustandsverwaltung in React-Anwendungen, das React Query verwendet","pt":"O que é TanStack Query? É uma biblioteca de gerenciamento de dados para React que simplifica a carga e o cache de dados.","ru":"Что такое TanStack Query? Это библиотека управления данными для React, которая упрощает загрузку и кэширование данных.","ar":"ما هو TanStack Query؟ هو مكتبة لإدارة البيانات في React تبسط عملية تحميل وذاكرة التخزين المؤقت للبيانات."},"features":{"en":["Provides useMutationState for cross-component mutation tracking","Supports React 18.0+ with useSyncExternalStore","Requires TypeScript 4.7+ for optimal performance","Includes @tanstack/react-query-devtools for debugging and testing","Enables access to mutation state from anywhere without prop drilling","Offers version 5.90.19 of @tanstack/react-query for improved stability"],"zh":["useMutationState：跨组件的变异跟踪","支持React 18.0+和TypeScript 4.7+","提供强大的数据获取和缓存功能","跨组件的变异状态访问","支持@tanstack/react-query@5.90.19和@tanstack/react-query-devtools@5.91.2"],"ja":["useMutationState：クロスコンポーネントのミューテーショントラッキング","React 18.0+とTypeScript 4.7+をサポート","強力なデータ取得とキャッシュ機能を提供","クロスコンポーネントのミューテーション状態アクセス","@tanstack/react-query@5.90.19と@tanstack/react-query-devtools@5.91.2をサポート"],"ko":["useMutationState：跨コンポーネント의 변이 추적","React 18.0+와 TypeScript 4.7+를 지원","강력한 데이터 가져오기와 캐시 기능을 제공","跨コンポーネント의 변이 상태 접근","@tanstack/react-query@5.90.19와 @tanstack/react-query-devtools@5.91.2를 지원"],"es":["useMutationState para el seguimiento de mutaciones entre componentes","Soporte para React 18.0+ con useSyncExternalStore","Compatibilidad con TypeScript 4.7+","Nuevas características en la versión 5 de React Query","Integración con React Query Devtools","Mejora de la gestión de estado en aplicaciones React"],"fr":["useMutationState pour le suivi des mutations entre composants","Prise en charge de React 18.0+ avec useSyncExternalStore","Compatibilité avec TypeScript 4.7+","Nouvelles fonctionnalités dans la version 5 de React Query","Intégration avec React Query Devtools","Amélioration de la gestion d''état dans les applications React"],"de":["useMutationState für die Nachverfolgung von Mutationen zwischen Komponenten","Unterstützung für React 18.0+ mit useSyncExternalStore","Kompatibilität mit TypeScript 4.7+","Neue Funktionen in der Version 5 von React Query","Integration mit React Query Devtools","Verbesserung der Zustandsverwaltung in React-Anwendungen"],"pt":["useMutationState para rastreamento de mutações entre componentes","Compatibilidade com React 18.0+ e useSyncExternalStore","Suporte a TypeScript 4.7+ para desenvolvimento mais eficiente","Otimização da carga e do cache de dados para melhor desempenho","Integração com @tanstack/react-query-devtools para depuração avançada"],"ru":["useMutationState для отслеживания мутаций между компонентами","Совместимость с React 18.0+ и useSyncExternalStore","Поддержка TypeScript 4.7+ для более эффективного развития","Оптимизация загрузки и кэширования данных для лучшей производительности","Интеграция с @tanstack/react-query-devtools для расширенной отладки"],"ar":["useMutationState لتتبع المتغيرات بين المكونات","التوافق مع React 18.0+ و useSyncExternalStore","دعم TypeScript 4.7+ لتحسين التطوير","تحسين تحميل وذاكرة التخزين المؤقت للبيانات لتحقيق أداء أفضل","التكامل مع @tanstack/react-query-devtools للتحليل المتقدم"]},"keywords":{"en":["how to use tanstack-query","tanstack-query vs react-query","tanstack-query install","react query v5 setup guide","tanstack-query alternative","what is tanstack-query","tanstack-query react 18","tanstack-query typescript","tanstack-query devtools","tanstack-query mutation tracking"],"zh":["TanStack Query","React Query","useMutationState","跨组件变异跟踪","React 18.0+","TypeScript 4.7+","AIエージェント","React开发","数据获取","缓存功能"],"ja":["TanStack Query","React Query","useMutationState","クロスコンポーネントミューテーショントラッキング","React 18.0+","TypeScript 4.7+","AIエージェント","React開発","データ取得","キャッシュ機能"],"ko":["TanStack Query","React Query","useMutationState","跨コンポーネント変이추적","React 18.0+","TypeScript 4.7+","AI Tools","React开发","데이터 가져오기","캐시 기능"],"es":["tanstack-query","React Query","gestión de estado en React","useMutationState","React 18.0+","TypeScript 4.7+","herramientas de desarrollo para React","mejores prácticas para React","react query devtools"],"fr":["tanstack-query","React Query","gestion d''état dans React","useMutationState","React 18.0+","TypeScript 4.7+","outils de développement pour React","meilleures pratiques pour React","react query devtools"],"de":["tanstack-query","React Query","Zustandsverwaltung in React","useMutationState","React 18.0+","TypeScript 4.7+","Entwicklungstools für React","beste Praktiken für React","react query devtools"],"pt":["TanStack Query","React Query","gerenciamento de dados","otimização de carga","cache de dados","React 18.0+","TypeScript 4.7+","useSyncExternalStore","useMutationState"],"ru":["TanStack Query","React Query","управление данными","оптимизация загрузки","кэширование данных","React 18.0+","TypeScript 4.7+","useSyncExternalStore","useMutationState"],"ar":["TanStack Query","React Query","إدارة البيانات","تحسين التحميل","ذاكرة التخزين المؤقت للبيانات","React 18.0+","TypeScript 4.7+","useSyncExternalStore","useMutationState"]}},"owner":"HuynhSang2005","repo":"blog-personal-nextjs","repoPath":"HuynhSang2005/blog-personal-nextjs","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.418Z","topics":[],"category":"community","skillMd":{"name":"tanstack-query","description":"|","bodyPreview":"# TanStack Query (React Query) v5\n\n**Last Updated**: 2026-01-20\n**Versions**: @tanstack/react-query@5.90.19, @tanstack/react-query-devtools@5.91.2\n**Requires**: React 18.0+ (useSyncExternalStore), TypeScript 4.7+ (recommended)\n\n---\n\n## v5 New Features\n\n### useMutationState - Cross-Component Mutation Tracking\n\nAccess mutation state from anywhere without prop drilling:\n\n```tsx\nimport { useMutationState } from ''@tanstack/react-query''\n\nfunction GlobalLoadingIndicator() {\n  // Get all pending mutatio","body":"# TanStack Query (React Query) v5\n\n**Last Updated**: 2026-01-20\n**Versions**: @tanstack/react-query@5.90.19, @tanstack/react-query-devtools@5.91.2\n**Requires**: React 18.0+ (useSyncExternalStore), TypeScript 4.7+ (recommended)\n\n---\n\n## v5 New Features\n\n### useMutationState - Cross-Component Mutation Tracking\n\nAccess mutation state from anywhere without prop drilling:\n\n```tsx\nimport { useMutationState } from ''@tanstack/react-query''\n\nfunction GlobalLoadingIndicator() {\n  // Get all pending mutations\n  const pendingMutations = useMutationState({\n    filters: { status: ''pending'' },\n    select: (mutation) => mutation.state.variables,\n  })\n\n  if (pendingMutations.length === 0) return null\n  return <div>Saving {pendingMutations.length} items...</div>\n}\n\n// Filter by mutation key\nconst todoMutations = useMutationState({\n  filters: { mutationKey: [''addTodo''] },\n})\n```\n\n### Simplified Optimistic Updates\n\nNew pattern using `variables` - no cache manipulation, no rollback needed:\n\n```tsx\nfunction TodoList() {\n  const { data: todos } = useQuery({ queryKey: [''todos''], queryFn: fetchTodos })\n\n  const addTodo = useMutation({\n    mutationKey: [''addTodo''],\n    mutationFn: (newTodo) => api.addTodo(newTodo),\n    onSuccess: () => {\n      queryClient.invalidateQueries({ queryKey: [''todos''] })\n    },\n  })\n\n  // Show optimistic UI using variables from pending mutations\n  const pendingTodos = useMutationState({\n    filters: { mutationKey: [''addTodo''], status: ''pending'' },\n    select: (mutation) => mutation.state.variables,\n  })\n\n  return (\n    <ul>\n      {todos?.map(todo => <li key={todo.id}>{todo.title}</li>)}\n      {/* Show pending items with visual indicator */}\n      {pendingTodos.map((todo, i) => (\n        <li key={`pending-${i}`} style={{ opacity: 0.5 }}>{todo.title}</li>\n      ))}\n    </ul>\n  )\n}\n```\n\n### throwOnError - Error Boundaries\n\nRenamed from `useErrorBoundary` (breaking change):\n\n```tsx\nimport { QueryErrorResetBoundary } from ''@tanstack/react-query''\nimport { ErrorBoundary } from ''react-error-boundary''\n\nfunction App() {\n  return (\n    <QueryErrorResetBoundary>\n      {({ reset }) => (\n        <ErrorBoundary onReset={reset} fallbackRender={({ resetErrorBoundary }) => (\n          <div>\n            Error! <button onClick={resetErrorBoundary}>Retry</button>\n          </div>\n        )}>\n          <Todos />\n        </ErrorBoundary>\n      )}\n    </QueryErrorResetBoundary>\n  )\n}\n\nfunction Todos() {\n  const { data } = useQuery({\n    queryKey: [''todos''],\n    queryFn: fetchTodos,\n    throwOnError: true, // ✅ v5 (was useErrorBoundary in v4)\n  })\n  return <div>{data.map(...)}</div>\n}\n```\n\n### Network Mode (Offline/PWA Support)\n\nControl behavior when offline:\n\n```tsx\nconst queryClient = new QueryClient({\n  defaultOptions: {\n    queries: {\n      networkMode: ''offlineFirst'', // Use cache when offline\n    },\n  },\n})\n\n// Per-query override\nuseQuery({\n  queryKey: [''todos''],\n  queryFn: fetchTodos,\n  networkMode: ''always'', // Always try, even offline (for local APIs)\n})\n```\n\n| Mode | Behavior |\n|------|----------|\n| `online` (default) | Only fetch when online |\n| `always` | Always try (useful for local/service worker APIs) |\n| `offlineFirst` | Use cache first, fetch when online |\n\n**Detecting paused state:**\n```tsx\nconst { isPending, fetchStatus } = useQuery(...)\n// isPending + fetchStatus === ''paused'' = offline, waiting for network\n```\n\n### useQueries with Combine\n\nCombine results from parallel queries:\n\n```tsx\nconst results = useQueries({\n  queries: userIds.map(id => ({\n    queryKey: [''user'', id],\n    queryFn: () => fetchUser(id),\n  })),\n  combine: (results) => ({\n    data: results.map(r => r.data),\n    pending: results.some(r => r.isPending),\n    error: results.find(r => r.error)?.error,\n  }),\n})\n\n// Access combined result\nif (results.pending) return <Loading />\nconsole.log(results.data) // [user1, user2, user3]\n```\n\n### infiniteQueryOptions Helper\n\nType-safe factory for infinite queries (parallel to `queryOptions`):\n\n```tsx\nimport { infiniteQueryOptions, useInfiniteQuery, prefetchInfiniteQuery } from ''@tanstack/react-query''\n\nconst todosInfiniteOptions = infiniteQueryOptions({\n  queryKey: [''todos'', ''infinite''],\n  queryFn: ({ pageParam }) => fetchTodosPage(pageParam),\n  initialPageParam: 0,\n  getNextPageParam: (lastPage) => lastPage.nextCursor,\n})\n\n// Reuse across hooks\nuseInfiniteQuery(todosInfiniteOptions)\nuseSuspenseInfiniteQuery(todosInfiniteOptions)\nprefetchInfiniteQuery(queryClient, todosInfiniteOptions)\n```\n\n### maxPages - Memory Optimization\n\nLimit pages stored in cache for infinite queries:\n\n```tsx\nuseInfiniteQuery({\n  queryKey: [''posts''],\n  queryFn: ({ pageParam }) => fetchPosts(pageParam),\n  initialPageParam: 0,\n  getNextPageParam: (lastPage) => lastPage.nextCursor,\n  getPreviousPageParam: (firstPage) => firstPage.prevCursor, // Required with maxPages\n  maxPages: 3, // Only keep 3 pages in memory\n})\n```\n\n**Note:** `maxPages` requires bi-directional pagination (`getNextPageParam` AND `getPreviousPageParam`).\n\n---\n\n## Quick Setup\n\n```bash\nnpm install @tanstack/react-query@latest\nnpm install -D @tanstack/react-query-devtools@latest\n```\n\n### Step 2: Provider + Config\n\n```tsx\n// src/main.tsx\nimport { QueryClient, QueryClientProvider } from ''@tanstack/react-query''\nimport { ReactQueryDevtools } from ''@tanstack/react-query-devtools''\n\nconst queryClient = new QueryClient({\n  defaultOptions: {\n    queries: {\n      staleTime: 1000 * 60 * 5, // 5 min\n      gcTime: 1000 * 60 * 60, // 1 hour (v5: renamed from cacheTime)\n      refetchOnWindowFocus: false,\n    },\n  },\n})\n\n<QueryClientProvider client={queryClient}>\n  <App />\n  <ReactQueryDevtools initialIsOpen={false} />\n</QueryClientProvider>\n```\n\n### Step 3: Query + Mutation Hooks\n\n```tsx\n// src/hooks/useTodos.ts\nimport { useQuery, useMutation, useQueryClient, queryOptions } from ''@tanstack/react-query''\n\n// Query options factory (v5 pattern)\nexport const todosQueryOptions = queryOptions({\n  queryKey: [''todos''],\n  queryFn: async () => {\n    const res = await fetch(''/api/todos'')\n    if (!res.ok) throw new Error(''Failed to fetch'')\n    return res.json()\n  },\n})\n\nexport function useTodos() {\n  return useQuery(todosQueryOptions)\n}\n\nexport function useAddTodo() {\n  const queryClient = useQueryClient()\n  return useMutation({\n    mutationFn: async (newTodo) => {\n      const res = await fetch(''/api/todos'', {\n        method: ''POST'',\n        headers: { ''Content-Type'': ''application/json'' },\n        body: JSON.stringify(newTodo),\n      })\n      if (!res.ok) throw new Error(''Failed to add'')\n      return res.json()\n    },\n    onSuccess: () => {\n      queryClient.invalidateQueries({ queryKey: [''todos''] })\n    },\n  })\n}\n\n// Usage:\nfunction TodoList() {\n  const { data, isPending, isError, error } = useTodos()\n  const { mutate } = useAddTodo()\n\n  if (isPending) return <div>Loading...</div>\n  if (isError) return <div>Error: {error.message}</div>\n  return <ul>{data.map(todo => <li key={todo.id}>{todo.title}</li>)}</ul>\n}\n```\n\n---\n\n## Critical Rules\n\n### Always Do\n\n✅ **Use object syntax for all hooks**\n```tsx\n// v5 ONLY supports this:\nuseQuery({ queryKey, queryFn, ...options })\nuseMutation({ mutationFn, ...options })\n```\n\n✅ **Use array query keys**\n```tsx\nqueryKey: [''todos'']              // List\nqueryKey: [''todos'', id]          // Detail\nqueryKey: [''todos'', { filter }]  // Filtered\n```\n\n✅ **Configure staleTime appropriately**\n```tsx\nstaleTime: 1000 * 60 * 5 // 5 min - prevents excessive refetches\n```\n\n✅ **Use isPending for initial loading state**\n```tsx\nif (isPending) return <Loading />\n// isPending = no data yet AND fetching\n```\n\n✅ **Throw errors in queryFn**\n```tsx\nif (!response.ok) throw new Error(''Failed'')\n```\n\n✅ **Invalidate queries after mutations**\n```tsx\nonSuccess: () => {\n  queryClient.invalidateQueries({ queryKey: [''todos''] })\n}\n```\n\n✅ **Use queryOptions factory for reusable patterns**\n```tsx\nconst opts = queryOptions({ queryKey, queryFn })\nuseQuery(opts)\nuseSuspenseQuery(opts)\nprefetchQuery(opts)\n```\n\n✅ **Use gcTime (not cacheTime)**\n```tsx\ngcTime: 1000 * 60 * 60 // 1 hour\n```\n\n### Never Do\n\n❌ **Never use v4 array/function syntax**\n```tsx\n// v4 (removed in v5):\nuseQuery([''todos''], fetchTodos, options) // ❌\n\n// v5 (correct):\nuseQuery({ queryKey: [''todos''], queryFn: fetchTodos }) // ✅\n```\n\n❌ **Never use query callbacks (onSuccess, onError, onSettled in queries)**\n```tsx\n// v5 removed these from queries:\nuseQuery({\n  queryKey: [''todos''],\n  queryFn: fetchTodos,\n  onSuccess: (data) => {}, // ❌ Removed in v5\n})\n\n// Use useEffect instead:\nconst { data } = useQuery({ queryKey: [''todos''], queryFn: fetchTodos })\nuseEffect(() => {\n  if (data) {\n    // Do something\n  }\n}, [data])\n\n// Or use mutation callbacks (still supported):\nuseMutation({\n  mutationFn: addTodo,\n  onSuccess: () => {}, // ✅ Still works for mutations\n})\n```\n\n❌ **Never use deprecated options**\n```tsx\n// Deprecated in v5:\ncacheTime: 1000 // ❌ Use gcTime instead\nisLoading: true // ❌ Meaning changed, use isPending\nkeepPreviousData: true // ❌ Use placeholderData instead\nonSuccess: () => {} // ❌ Removed from queries\nuseErrorBoundary: true // ❌ Use throwOnError instead\n```\n\n❌ **Never assume isLoading means \"no data yet\"**\n```tsx\n// v5 changed this:\nisLoading = isPending && isFetching // ❌ Now means \"pending AND fetching\"\nisPending = no data yet // ✅ Use this for initial load\n```\n\n❌ **Never forget initialPageParam for infinite queries**\n```tsx\n// v5 requires this:\nuseInfiniteQuery({\n  queryKey: [''projects''],\n  queryFn: ({ pageParam }) => fetchProjects(pageParam),\n  initialPageParam: 0, // ✅ Required in v5\n  getNextPageParam: (lastPage) => lastPage.nextCursor,\n})\n```\n\n❌ **Never use enabled with useSuspenseQuery**\n```tsx\n// Not allowed:\nuseSuspenseQuery({\n  queryKey: [''todo'', id],\n  queryFn: () => fetchTodo(id),\n  enabled: !!id, // ❌ Not available with suspense\n})\n\n// Use conditional rendering instead:\n{id && <TodoComponent id={id} />}\n```\n\n❌ **Never rely on refetchOnMount: false for errored queries**\n```tsx\n// Doesn''t work - errors are always stale\nuseQuery({\n  queryKey: [''data''],\n  queryFn: failingFetch,\n  refetchOnMount: false,  // ❌ Ignored when query has error\n})\n\n// Use retryOnMount instead\nuseQuery({\n  queryKey: [''data''],\n  queryFn: failingFetch,\n  refetchOnMount: false,\n  retryOnMount: false,  // ✅ Prevents refetch for errored queries\n  retry: 0,\n})\n```\n\n---\n\n## Known Issues Prevention\n\nThis skill prevents **16 documented issues** from v5 migration, SSR/hydration bugs, and common mistakes:\n\n### Issue #1: Object Syntax Required\n**Error**: `useQuery is not a function` or type errors\n**Source**: [v5 Migration Guide](https://tanstack.com/query/latest/docs/framework/react/guides/migrating-to-v5#removed-overloads-in-favor-of-object-syntax)\n**Why It Happens**: v5 removed all function overloads, only object syntax works\n**Prevention**: Always use `useQuery({ queryKey, queryFn, ...options })`\n\n**Before (v4):**\n```tsx\nuseQuery([''todos''], fetchTodos, { staleTime: 5000 })\n```\n\n**After (v5):**\n```tsx\nuseQuery({\n  queryKey: [''todos''],\n  queryFn: fetchTodos,\n  staleTime: 5000\n})\n```\n\n### Issue #2: Query Callbacks Removed\n**Error**: Callbacks don''t run, TypeScript errors\n**Source**: [v5 Breaking Changes](https://tanstack.com/query/latest/docs/framework/react/guides/migrating-to-v5#callbacks-on-usequery-and-queryobserver-have-been-removed)\n**Why It Happens**: onSuccess, onError, onSettled removed from queries (still work in mutations)\n**Prevention**: Use `useEffect` for side effects, or move logic to mutation callbacks\n\n**Before (v4):**\n```tsx\nuseQuery({\n  queryKey: [''todos''],\n  queryFn: fetchTodos,\n  onSuccess: (data) => {\n    console.log(''Todos loaded:'', data)\n  },\n})\n```\n\n**After (v5):**\n```tsx\nconst { data } = useQuery({ queryKey: [''todos''], queryFn: fetchTodos })\nuseEffect(() => {\n  if (data) {\n    console.log(''Todos loaded:'', data)\n  }\n}, [data])\n```\n\n### Issue #3: Status Loading → Pending\n**Error**: UI shows wrong loading state\n**Source**: [v5 Migration: isLoading renamed](https://tanstack.com/query/latest/docs/framework/react/guides/migrating-to-v5#isloading-and-isfetching-flags)\n**Why It Happens**: `status: ''loading''` renamed to `status: ''pending''`, `isLoading` meaning changed\n**Prevention**: Use `isPending` for initial load, `isLoading` for \"pending AND fetching\"\n\n**Before (v4):**\n```tsx\nconst { data, isLoading } = useQuery(...)\nif (isLoading) return <div>Loading...</div>\n```\n\n**After (v5):**\n```tsx\nconst { data, isPending, isLoading } = useQuery(...)\nif (isPending) return <div>Loading...</div>\n// isLoading = isPending && isFetching (fetching for first time)\n```\n\n### Issue #4: cacheTime → gcTime\n**Error**: `cacheTime is not a valid option`\n**Source**: [v5 Migration: gcTime](https://tanstack.com/query/latest/docs/framework/react/guides/migrating-to-v5#cachetime-has-been-replaced-by-gctime)\n**Why It Happens**: Renamed to better reflect \"garbage collection time\"\n**Prevention**: Use `gcTime` instead of `cacheTime`\n\n**Before (v4):**\n```tsx\nuseQuery({\n  queryKey: [''todos''],\n  queryFn: fetchTodos,\n  cacheTime: 1000 * 60 * 60,\n})\n```\n\n**After (v5):**\n```tsx\nuseQuery({\n  queryKey: [''todos''],\n  queryFn: fetchTodos,\n  gcTime: 1000 * 60 * 60,\n})\n```\n\n### Issue #5: useSuspenseQuery + enabled\n**Error**: Type error, enabled option not available\n**Source**: [GitHub Discussion #6206](https://github.com/TanStack/query/discussions/6206)\n**Why It Happens**: Suspense guarantees data is available, can''t conditionally disable\n**Prevention**: Use conditional rendering instead of `enabled` option\n\n**Before (v4/incorrect):**\n```tsx\nuseSuspenseQuery({\n  queryKey: [''todo'', id],\n  queryFn: () => fetchTodo(id),\n  enabled: !!id, // ❌ Not allowed\n})\n```\n\n**After (v5/correct):**\n```tsx\n// Conditional rendering:\n{id ? (\n  <TodoComponent id={id} />\n) : (\n  <div>No ID selected</div>\n)}\n\n// Inside TodoComponent:\nfunction TodoComponent({ id }: { id: number }) {\n  const { data } = useSuspenseQuery({\n    queryKey: [''todo'', id],\n    queryFn: () => fetchTodo(id),\n    // No enabled option needed\n  })\n  return <div>{data.title}</div>\n}\n```\n\n### Issue #6: initialPageParam Required\n**Error**: `initialPageParam is required` type error\n**Source**: [v5 Migration: Infinite Queries](https://tanstack.com/query/latest/docs/framework/react/guides/migrating-to-v5#new-required-initialPageParam-option)\n**Why It Happens**: v4 passed `undefined` as first pageParam, v5 requires explicit value\n**Prevention**: Always specify `initialPageParam` for infinite queries\n\n**Before (v4):**\n```tsx\nuseInfiniteQuery({\n  queryKey: [''projects''],\n  queryFn: ({ pageParam = 0 }) => fetchProjects(pageParam),\n  getNextPageParam: (lastPage) => lastPage.nextCursor,\n})\n```\n\n**After (v5):**\n```tsx\nuseInfiniteQuery({\n  queryKey: [''projects''],\n  queryFn: ({ pageParam }) => fetchProjects(pageParam),\n  initialPageParam: 0, // ✅ Required\n  getNextPageParam: (lastPage) => lastPage.nextCursor,\n})\n```\n\n### Issue #7: keepPreviousData Removed\n**Error**: `keepPreviousData is not a valid option`\n**Source**: [v5 Migration: placeholderData](https://tanstack.com/query/latest/docs/framework/react/guides/migrating-to-v5#removed-keeppreviousdata-in-favor-of-placeholderdata-identity-function)\n**Why It Happens**: Replaced with more flexible `placeholderData` function\n**Prevention**: Use `placeholderData: keepPreviousData` helper\n\n**Before (v4):**\n```tsx\nuseQuery({\n  queryKey: [''todos'', page],\n  queryFn: () => fetchTodos(page),\n  keepPreviousData: true,\n})\n```\n\n**After (v5):**\n```tsx\nimport { keepPreviousData } from ''@tanstack/react-query''\n\nuseQuery({\n  queryKey: [''todos'', page],\n  queryFn: () => fetchTodos(page),\n  placeholderData: keepPreviousData,\n})\n```\n\n### Issue #8: TypeScript Error Type Default\n**Error**: Type errors with error handling\n**Source**: [v5 Migration: Error Types](https://tanstack.com/query/latest/docs/framework/react/guides/migrating-to-v5#typeerror-is-now-the-default-error)\n**Why It Happens**: v4 used `unknown`, v5 defaults to `Error` type\n**Prevention**: If throwing non-Error types, specify error type explicitly\n\n**Before (v4 - error was unknown):**\n```tsx\nconst { error } = useQuery({\n  queryKey: [''data''],\n  queryFn: async () => {\n    if (Math.random() > 0.5) throw ''custom error string''\n    return data\n  },\n})\n// error: unknown\n```\n\n**After (v5 - specify custom error type):**\n```tsx\nconst { error } = useQuery<DataType, string>({\n  queryKey: [''data''],\n  queryFn: async () => {\n    if (Math.random() > 0.5) throw ''custom error string''\n    return data\n  },\n})\n// error: string | null\n\n// Or better: always throw Error objects\nconst { error } = useQuery({\n  queryKey: [''data''],\n  queryFn: async () => {\n    if (Math.random() > 0.5) throw new Error(''custom error'')\n    return data\n  },\n})\n// error: Error | null (default)\n```\n\n### Issue #9: Streaming Server Components Hydration Error\n**Error**: `Hydration failed because the initial UI does not match what was rendered on the server`\n**Source**: [GitHub Issue #9642](https://github.com/TanStack/query/issues/9642)\n**Affects**: v5.82.0+ with streaming SSR (void prefetch pattern)\n**Why It Happens**: Race condition where `hydrate()` resolves synchronously but `query.fetch()` creates async retryer, causing isFetching/isStale mismatch between server and client\n**Prevention**: Don''t conditionally render based on `fetchStatus` with `useSuspenseQuery` and streaming prefetch, OR await prefetch instead of void pattern\n\n**Before (causes hydration error):**\n```tsx\n// Server: void prefetch\nstreamingQueryClient.prefetchQuery({ queryKey: [''data''], queryFn: getData });\n\n// Client: conditional render on fetchStatus\nconst { data, isFetching } = useSuspenseQuery({ queryKey: [''data''], queryFn: getData });\nreturn <>{data && <div>{data}</div>} {isFetching && <Loading />}</>;\n```\n\n**After (workaround):**\n```tsx\n// Option 1: Await prefetch\nawait streamingQueryClient.prefetchQuery({ queryKey: [''data''], queryFn: getData });\n\n// Option 2: Don''t render based on fetchStatus with Suspense\nconst { data } = useSuspenseQuery({ queryKey: [''data''], queryFn: getData });\nreturn <div>{data}</div>;  // No conditional on isFetching\n```\n\n**Status**: Known issue, being investigated by maintainers. Requires implementation of `getServerSnapshot` in useSyncExternalStore.\n\n### Issue #10: useQuery Hydration Error with Prefetching\n**Error**: Text content mismatch during hydration\n**Source**: [GitHub Issue #9399](https://github.com/TanStack/query/issues/9399)\n**Affects**: v5.x with server-side prefetching\n**Why It Happens**: `tryResolveSync` detects resolved promises in RSC payload and extracts data synchronously during hydration, bypassing normal pending state\n**Prevention**: Use `useSuspenseQuery` instead of `useQuery` for SSR, or avoid conditional rendering based on `isLoading`\n\n**Before (causes hydration error):**\n```tsx\n// Server Component\nconst queryClient = getServerQueryClient();\nawait queryClient.prefetchQuery({ queryKey: [''todos''], queryFn: fetchTodos });\n\n// Client Component\nfunction Todos() {\n  const { data, isLoading } = useQuery({ queryKey: [''todos''], queryFn: fetchTodos });\n  if (isLoading) return <div>Loading...</div>;  // Server renders this\n  return <div>{data.length} todos</div>;  // Client hydrates with this\n}\n```\n\n**After (workaround):**\n```tsx\n// Use useSuspenseQuery instead\nfunction Todos() {\n  const { data } = useSuspenseQuery({ queryKey: [''todos''], queryFn: fetchTodos });\n  return <div>{data.length} todos</div>;\n}\n```\n\n**Status**: \"At the top of my OSS list of things to fix\" - maintainer Ephem (Nov 2025). Requires implementing `getServerSnapshot` in useSyncExternalStore.\n\n### Issue #11: refetchOnMount Not Respected for Errored Queries\n**Error**: Queries refetch on mount despite `refetchOnMount: false`\n**Source**: [GitHub Issue #10018](https://github.com/TanStack/query/issues/10018)\n**Affects**: v5.90.16+\n**Why It Happens**: Errored queries with no data are always treated as stale. This is intentional to avoid permanently showing error states\n**Prevention**: Use `retryOnMount: false` instead of (or in addition to) `refetchOnMount: false`\n\n**Before (refetches despite setting):**\n```tsx\nconst { data, error } = useQuery({\n  queryKey: [''data''],\n  queryFn: () => { throw new Error(''Fails'') },\n  refetchOnMount: false,  // Ignored when query is in error state\n  retry: 0,\n});\n// Query refetches every time component mounts\n```\n\n**After (correct):**\n```tsx\nconst { data, error } = useQuery({\n  queryKey: [''data''],\n  queryFn: failingFetch,\n  refetchOnMount: false,\n  retryOnMount: false,  // ✅ Prevents refetch on mount for errored queries\n  retry: 0,\n});\n```\n\n**Status**: Documented behavior (intentional). The name `retryOnMount` is slightly misleading - it controls whether errored queries trigger a new fetch on mount, not automatic retries.\n\n### Issue #12: Mutation Callback Signature Breaking Change (v5.89.0)\n**Error**: TypeScript errors in mutation callbacks\n**Source**: [GitHub Issue #9660](https://github.com/TanStack/query/issues/9660)\n**Affects**: v5.89.0+\n**Why It Happens**: `onMutateResult` parameter added between `variables` and `context`, changing callback signatures from 3 params to 4\n**Prevention**: Update all mutation callbacks to accept 4 parameters instead of 3\n\n**Before (v5.88 and earlier):**\n```tsx\nuseMutation({\n  mutationFn: addTodo,\n  onError: (error, variables, context) => {\n    // context is now onMutateResult, missing final context param\n  },\n  onSuccess: (data, variables, context) => {\n    // Same issue\n  }\n});\n```\n\n**After (v5.89.0+):**\n```tsx\nuseMutation({\n  mutationFn: addTodo,\n  onError: (error, variables, onMutateResult, context) => {\n    // onMutateResult = return value from onMutate\n    // context = mutation function context\n  },\n  onSuccess: (data, variables, onMutateResult, context) => {\n    // Correct signature with 4 parameters\n  }\n});\n```\n\n**Note**: If you don''t use `onMutate`, the `onMutateResult` parameter will be undefined. This breaking change was introduced in a patch version.\n\n### Issue #13: Readonly Query Keys Break Partial Matching (v5.90.8)\n**Error**: `Type ''readonly [\"todos\", string]'' is not assignable to type ''[\"todos\", string]''`\n**Source**: [GitHub Issue #9871](https://github.com/TanStack/query/issues/9871) | Fixed in [PR #9872](https://github.com/TanStack/query/pull/9872)\n**Affects**: v5.90.8 only (fixed in v5.90.9)\n**Why It Happens**: Partial query matching broke TypeScript types for readonly query keys (using `as const`)\n**Prevention**: Upgrade to v5.90.9+ or use type assertions if stuck on v5.90.8\n\n**Before (v5.90.8 - TypeScript error):**\n```tsx\nexport function todoQueryKey(id?: string) {\n  return id ? [''todos'', id] as const : [''todos''] as const;\n}\n// Type: readonly [''todos'', string] | readonly [''todos'']\n\nuseMutation({\n  mutationFn: addTodo,\n  onSuccess: () => {\n    queryClient.invalidateQueries({\n      queryKey: todoQueryKey(''123'')\n      // Error: readonly [''todos'', string] not assignable to [''todos'', string]\n    });\n  }\n});\n```\n\n**After (v5.90.9+):**\n```tsx\n// Works correctly with readonly types\nqueryClient.invalidateQueries({\n  queryKey: todoQueryKey(''123'')  // ✅ No type error\n});\n```\n\n**Status**: Fixed in v5.90.9. Particularly affected users of code generators like `openapi-react-query` that produce readonly query keys.\n\n### Issue #14: useMutationState Type Inference Lost\n**Error**: `mutation.state.variables` typed as `unknown` instead of actual type\n**Source**: [GitHub Issue #9825](https://github.com/TanStack/query/issues/9825)\n**Affects**: All v5.x versions\n**Why It Happens**: Fuzzy mutation key matching prevents guaranteed type inference (same issue as `queryClient.getQueryCache().find()`)\n**Prevention**: Explicitly cast types in the `select` callback\n\n**Before (type inference doesn''t work):**\n```tsx\nconst addTodo = useMutation({\n  mutationKey: [''addTodo''],\n  mutationFn: (todo: Todo) => api.addTodo(todo),\n});\n\nconst pendingTodos = useMutationState({\n  filters: { mutationKey: [''addTodo''], status: ''pending'' },\n  select: (mutation) => {\n    return mutation.state.variables;  // Type: unknown\n  },\n});\n```\n\n**After (with explicit cast):**\n```tsx\nconst pendingTodos = useMutationState({\n  filters: { mutationKey: [''addTodo''], status: ''pending'' },\n  select: (mutation) => mutation.state.variables as Todo,\n});\n// Or cast the entire state:\nselect: (mutation) => mutation.state as MutationState<Todo, Error, Todo, unknown>\n```\n\n**Status**: Known limitation of fuzzy matching. No planned fix.\n\n### Issue #15: Query Cancellation in StrictMode with fetchQuery\n**Error**: `CancelledError` when using `fetchQuery()` with `useQuery`\n**Source**: [GitHub Issue #9798](https://github.com/TanStack/query/issues/9798)\n**Affects**: Development only (React StrictMode)\n**Why It Happens**: StrictMode causes double mount/unmount. When `useQuery` unmounts and is the last observer, it cancels the query even if `fetchQuery()` is also running\n**Prevention**: This is expected development-only behavior. Doesn''t affect production\n\n**Example:**\n```tsx\nasync function loadData() {\n  try {\n    const data = await queryClient.fetchQuery({\n      queryKey: [''data''],\n      queryFn: fetchData,\n    });\n    console.log(''Loaded:'', data);  // Never logs in StrictMode\n  } catch (error) {\n    console.error(''Failed:'', error);  // CancelledError\n  }\n}\n\nfunction Component() {\n  const { data } = useQuery({ queryKey: [''data''], queryFn: fetchData });\n  // In StrictMode, component unmounts/remounts, cancelling fetchQuery\n}\n```\n\n**Workaround:**\n```tsx\n// Keep query observed with staleTime\nconst { data } = useQuery({\n  queryKey: [''data''],\n  queryFn: fetchData,\n  staleTime: Infinity,  // Keeps query active\n});\n```\n\n**Status**: Expected StrictMode behavior, not a bug. Production builds are unaffected.\n\n### Issue #16: invalidateQueries Only Refetches Active Queries\n**Error**: Inactive queries not refetching despite `invalidateQueries()` call\n**Source**: [GitHub Issue #9531](https://github.com/TanStack/query/issues/9531)\n**Affects**: All v5.x versions\n**Why It Happens**: Documentation was misleading - `invalidateQueries()` only refetches \"active\" queries by default, not \"all\" queries\n**Prevention**: Use `refetchType: ''all''` to force refetch of inactive queries\n\n**Default behavior:**\n```tsx\n// Only active queries (currently being observed) will refetch\nqueryClient.invalidateQueries({ queryKey: [''todos''] });\n```\n\n**To refetch inactive queries:**\n```tsx\nqueryClient.invalidateQueries({\n  queryKey: [''todos''],\n  refetchType: ''all''  // Refetch active AND inactive\n});\n```\n\n**Status**: Documentation fixed to clarify \"active\" queries. This is the intended behavior.\n\n---\n\n## Community Tips\n\n> **Note**: These tips come from community experts and maintainer blogs. Verify against your version.\n\n### Tip: Query Options with Multiple Listeners\n\n**Source**: [TkDodo''s Blog - API Design Lessons](https://tkdodo.eu/blog/react-query-api-design-lessons-learned) | **Confidence**: HIGH\n**Applies to**: v5.27.3+\n\nWhen multiple components use the same query with different options (like `staleTime`), the \"last write wins\" rule applies for future fetches, but the current in-flight query uses its original options. This can cause unexpected behavior when components mount at different times.\n\n**Example of unexpected behavior:**\n```tsx\n// Component A mounts first\nfunction ComponentA() {\n  const { data } = useQuery({\n    queryKey: [''todos''],\n    queryFn: fetchTodos,\n    staleTime: 5000,  // Applied initially\n  });\n}\n\n// Component B mounts while A''s query is in-flight\nfunction ComponentB() {\n  const { data } = useQuery({\n    queryKey: [''todos''],\n    queryFn: fetchTodos,\n    staleTime: 60000,  // Won''t affect current fetch, only future ones\n  });\n}\n```\n\n**Recommended approach:**\n```tsx\n// Write options as functions that reference latest values\nconst getStaleTime = () => shouldUseLongCache ? 60000 : 5000;\n\nuseQuery({\n  queryKey: [''todos''],\n  queryFn: fetchTodos,\n  staleTime: getStaleTime(),  // Evaluated on each render\n});\n```\n\n### Tip: refetch() is NOT for Changed Parameters\n\n**Source**: [Avoiding Common Mistakes with TanStack Query](https://www.buncolak.com/posts/avoiding-common-mistakes-with-tanstack-query-part-1/) | **Confidence**: HIGH\n\nThe `refetch()` function should ONLY be used for refreshing with the same parameters (like a manual \"reload\" button). For new parameters (filters, page numbers, search terms, etc.), include them in the query key instead.\n\n**Anti-pattern:**\n```tsx\n// ❌ Wrong - using refetch() for different parameters\nconst [page, setPage] = useState(1);\nconst { data, refetch } = useQuery({\n  queryKey: [''todos''],  // Same key for all pages\n  queryFn: () => fetchTodos(page),\n});\n\n// This refetches with OLD page value, not new one\n<button onClick={() => { setPage(2); refetch(); }}>Next</button>\n```\n\n**Correct pattern:**\n```tsx\n// ✅ Correct - include parameters in query key\nconst [page, setPage] = useState(1);\nconst { data } = useQuery({\n  queryKey: [''todos'', page],  // Key changes with page\n  queryFn: () => fetchTodos(page),\n  // Query automatically refetches when page changes\n});\n\n<button onClick={() => setPage(2)}>Next</button>  // Just update state\n```\n\n**When to use refetch():**\n```tsx\n// ✅ Manual refresh of same data (refresh button)\nconst { data, refetch } = useQuery({\n  queryKey: [''todos''],\n  queryFn: fetchTodos,\n});\n\n<button onClick={() => refetch()}>Refresh</button>  // Same parameters\n```\n\n---\n\n## Key Patterns\n\n**Dependent Queries** (Query B waits for Query A):\n```tsx\nconst { data: posts } = useQuery({\n  queryKey: [''users'', userId, ''posts''],\n  queryFn: () => fetchUserPosts(userId),\n  enabled: !!user, // Wait for user\n})\n```\n\n**Parallel Queries** (fetch multiple at once):\n```tsx\nconst results = useQueries({\n  queries: ids.map(id => ({ queryKey: [''todos'', id], queryFn: () => fetchTodo(id) })),\n})\n```\n\n**Prefetching** (preload on hover):\n```tsx\nqueryClient.prefetchQuery({ queryKey: [''todo'', id], queryFn: () => fetchTodo(id) })\n```\n\n**Infinite Scroll** (useInfiniteQuery):\n```tsx\nuseInfiniteQuery({\n  queryKey: [''todos'', ''infinite''],\n  queryFn: ({ pageParam }) => fetchTodosPage(pageParam),\n  initialPageParam: 0, // Required in v5\n  getNextPageParam: (lastPage) => lastPage.nextCursor,\n})\n```\n\n**Query Cancellation** (auto-cancel on queryKey change):\n```tsx\nqueryFn: async ({ signal }) => {\n  const res = await fetch(`/api/todos?q=${search}`, { signal })\n  return res.json()\n}\n```\n\n**Data Transformation** (select):\n```tsx\nselect: (data) => data.filter(todo => todo.completed)\n```\n\n**Avoid Request Waterfalls**: Fetch in parallel when possible (don''t chain queries unless truly dependent)\n\n---\n\n**Official Docs**: https://tanstack.com/query/latest | **v5 Migration**: https://tanstack.com/query/latest/docs/framework/react/guides/migrating-to-v5 | **GitHub**: https://github.com/TanStack/query | **Context7**: `/websites/tanstack_query`\n"},"lastSynced":"2026-03-08T02:07:19.356Z","agentAnalysis":{"suitability":{"en":"Essential for React-based AI Agents requiring optimized data fetching and state synchronization across components.","zh":"适用于基于React的AI代理，需要优化数据获取和状态同步跨组件。","ja":"ReactベースのAIエージェントに最適で、コンポーネント間のデータ取得と状態同期が最適化される。","ko":"React 기반 AI 에이전트에 적합하며, 컴포넌트 간의 데이터 가져오기 및 상태 동기화를 최적화한다.","es":"Esencial para los agentes de IA basados en React que requieren una recuperación de datos optimizada y una sincronización de estado entre componentes.","fr":"Essentiel pour les agents d''IA basés sur React nécessitant une récupération de données optimisée et une synchronisation d''état entre les composants.","de":"Wesentlich für React-basierte KI-Agents, die eine optimierte Datenabfrage und eine Zustandssynchronisierung zwischen Komponenten erfordern.","pt":"Essencial para Agentes de IA baseados em React que requerem busca de dados otimizada e sincronização de estado entre componentes.","ru":"Необходимо для агентов ИИ на основе React, требующих оптимизированной выборки данных и синхронизации состояния между компонентами.","ar":"ضروري لعميل الذكاء الاصطناعي المبني على React الذي يتطلب جلب بيانات محسّن وتزامن حالة عبر المكونات."},"recommendation":{"en":"Enables real-time mutation state tracking with useMutationState and provides efficient caching mechanisms through React Query''s stale-while-revalidate pattern. Integrates seamlessly with React 18''s useSyncExternalStore for consistent state management.","zh":"启用实时变异状态跟踪，使用useMutationState，并通过React Query的stale-while-revalidate模式提供高效的缓存机制。无缝集成React 18的useSyncExternalStore以实现一致的状态管理。","ja":"useMutationStateを使用してリアルタイムのミューテーション状態の追跡を可能にし、React Queryのstale-while-revalidateパターンを通じて効率的なキャッシュメカニズムを提供する。また、React 18のuseSyncExternalStoreとシームレスに統合して一貫した状態管理を実現する。","ko":"useMutationState를 사용하여 실시간 변이 상태 추적을 가능하게 하고, React Query의 stale-while-revalidate 패턴을 통해 효율적인 캐싱 메커니즘을 제공한다. 또한 React 18의 useSyncExternalStore와 무결점으로 통합하여 일관된 상태 관리를 구현한다.","es":"Habilita la seguimiento del estado de mutación en tiempo real con useMutationState y proporciona mecanismos de caché eficientes a través del patrón stale-while-revalidate de React Query. Se integra perfectamente con useSyncExternalStore de React 18 para una gestión de estado coherente.","fr":"Permet le suivi de l''état de mutation en temps réel avec useMutationState et fournit des mécanismes de mise en cache efficaces via le modèle stale-while-revalidate de React Query. S''intègre sans problème avec useSyncExternalStore de React 18 pour une gestion d''état cohérente.","de":"Ermöglicht die Nachverfolgung des Mutationstatus in Echtzeit mit useMutationState und bietet effiziente Cachemechanismen durch das stale-while-revalidate-Muster von React Query. Integriert sich nahtlos mit useSyncExternalStore von React 18 für eine konsistente Zustandsverwaltung.","pt":"Permite o acompanhamento em tempo real do estado de mutação com useMutationState e fornece mecanismos de cache eficientes por meio do padrão stale-while-revalidate do React Query. Integra-se perfeitamente com o useSyncExternalStore do React 18 para gerenciamento de estado consistente.","ru":"Позволяет отслеживать состояние мутации в режиме реального времени с помощью useMutationState и обеспечивает эффективные механизмы кэширования через шаблон stale-while-revalidate React Query. Интегрируется без проблем с useSyncExternalStore React 18 для последовательного управления состоянием.","ar":"يسمح بالتتبع في الوقت الفعلي لحالة الطفرة باستخدام useMutationState ويوفر آليات ذاكرة مؤقتة فعالة من خلال نمط stale-while-revalidate من React Query. يدمج بشكل متجانس مع useSyncExternalStore من React 18 لإدارة حالة متسقة."},"useCases":{"en":["Synchronizing mutation states across distributed agent components","Optimizing data fetching strategies for real-time applications","Debugging API call patterns with React Query DevTools integration"],"zh":["分布式代理组件之间的变异状态同步","实时应用的数据获取策略优化","使用React Query DevTools集成调试API调用模式"],"ja":["分散エージェントコンポーネント間のミューテーション状態の同期","リアルタイムアプリケーションのデータ取得戦略の最適化","React Query DevTools統合を使用したAPI呼び出しパターンのデバッグ"],"ko":["분산 에이전트 컴포넌트 간의 변이 상태 동기화","실시간 애플리케이션의 데이터 가져오기 전략 최적화","React Query DevTools 통합을 사용한 API 호출 패턴 디버깅"],"es":["Sincronización de estados de mutación entre componentes de agentes distribuidos","Optimización de estrategias de recuperación de datos para aplicaciones en tiempo real","Depuración de patrones de llamadas de API con la integración de React Query DevTools"],"fr":["Synchronisation des états de mutation entre les composants d''agents distribués","Optimisation des stratégies de récupération de données pour les applications en temps réel","Débogage des modèles d''appels d''API avec l''intégration de React Query DevTools"],"de":["Synchronisierung von Mutationstatus zwischen verteilter Agentenkomponenten","Optimierung von Datenabfragemustern für Echtzeitanwendungen","Fehlerbehebung von API-Aufrufmustern mit der Integration von React Query DevTools"],"pt":["Sincronizar estados de mutação em componentes de agente distribuídos","Otimizar estratégias de busca de dados para aplicações em tempo real","Depurar padrões de chamadas de API com integração do React Query DevTools"],"ru":["Синхронизировать состояния мутации в распределенных компонентах агента","Оптимизировать стратегии выборки данных для приложений в реальном времени","Отлаживать шаблоны вызовов API с помощью интеграции React Query DevTools"],"ar":["مزامنة حالات الطفرة عبر مكونات العميل الموزعة","تحسين استراتيجيات جلب البيانات لتطبيقات الوقت الفعلي","تصحيح أخطاء أنماط الاتصال بالواجهة البرمجية باستخدام تكامل أدوات تطوير React Query"]},"limitations":{"en":["Requires React 18.0+ for useSyncExternalStore compatibility","TypeScript 4.7+ recommended for full type safety","Limited to React ecosystem implementations"],"zh":["需要React 18.0+以兼容useSyncExternalStore","建议使用TypeScript 4.7+以实现完整的类型安全","仅限于React生态系统实现"],"ja":["useSyncExternalStoreとの互換性を保つためにReact 18.0+が必要","完全なタイプセーフティを実現するためにTypeScript 4.7+を推奨","Reactエコシステムの実装に限定"],"ko":["useSyncExternalStore와의 호환성을 유지하려면 React 18.0+가 필요","완전한 유형 안전을実現하기 위해 TypeScript 4.7+를 권장","React 생태계 구현에만 국한"],"es":["Requiere React 18.0+ para la compatibilidad con useSyncExternalStore","Se recomienda TypeScript 4.7+ para una seguridad de tipo completa","Limitado a implementaciones del ecosistema de React"],"fr":["Nécessite React 18.0+ pour la compatibilité avec useSyncExternalStore","TypeScript 4.7+ est recommandé pour une sécurité de type complète","Limité aux implémentations de l''écosystème React"],"de":["Benötigt React 18.0+ für die Kompatibilität mit useSyncExternalStore","TypeScript 4.7+ wird für eine vollständige Typsicherheit empfohlen","Begrenzt auf Implementierungen des React-Ökosystems"],"pt":["Requer React 18.0+ para compatibilidade com useSyncExternalStore","TypeScript 4.7+ recomendado para segurança de tipo completa","Limitado a implementações do ecossistema React"],"ru":["Требует React 18.0+ для совместимости с useSyncExternalStore","TypeScript 4.7+ рекомендуется для полной безопасности типа","Ограничен реализациями экосистемы React"],"ar":["يتطلب React 18.0+ للتوافق مع useSyncExternalStore","TypeScript 4.7+ مُقترح لسلامة النوع الكاملة","محدود بتطبيق نظام React"]},"version":4},"contentHash":"13536ede9b50f37e5ded7bd2e333c5bb2387241e31cc727f5d3741dd960313ae","qualityScore":39}');
DELETE FROM skills_fts WHERE id = 'HuynhSang2005/blog-personal-nextjs/tanstack-query';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HuynhSang2005/blog-personal-nextjs/tanstack-query', 'tanstack-query', 'HuynhSang2005', 'blog-personal-nextjs', 'community', 'tanstack-query HuynhSang2005 blog-personal-nextjs community tanstack-query is a React library that enables efficient data fetching and caching. It benefits React developers by providing a robust set of features for managing data and mutations. TanStack Query v5是一个用于React的强大查询库，支持useMutationState和跨组件的变异跟踪 TanStack Query v5はReact用の強力なクエリライブラリであり，useMutationStateとクロスコンポーネントのミューテーショントラッキングをサポート TanStack Query v5는 React용 강력한 쿼리 라이브러리로서 useMutationState와跨コンポーネント의 변이 추적을 지원 tanstack-query es una biblioteca de gestión de estado para React. Ofrece características como useMutationState para el seguimiento de mutaciones entre componentes tanstack-query est une bibliothèque de gestion d''état pour React. Elle propose des fonctionnalités comme useMutationState pour le suivi des mutations entre composants tanstack-query ist eine Bibliothek für die Zustandsverwaltung in React. Sie bietet Funktionen wie useMutationState für die Nachverfolgung von Mutationen zwischen Komponenten O TanStack Query é uma biblioteca de gerenciamento de dados para React que oferece recursos avançados para otimizar a carga e o cache de dados. TanStack Query — это библиотека управления данными для React, которая предоставляет продвинутые возможности для оптимизации загрузки и кэширования данных. TanStack Query هو مكتبة لإدارة البيانات في React تقدم ميزات متقدمة لتحسين تحميل وذاكرة التخزين المؤقت للبيانات. how to use tanstack-query tanstack-query vs react-query tanstack-query install react query v5 setup guide tanstack-query alternative what is tanstack-query tanstack-query react 18 tanstack-query typescript tanstack-query devtools tanstack-query mutation tracking TanStack Query React Query useMutationState 跨组件变异跟踪 React 18.0+ TypeScript 4.7+ AIエージェント React开发 数据获取 缓存功能 Provides useMutationState for cross-component mutation tracking Supports React 18.0+ with useSyncExternalStore Requires TypeScript 4.7+ for optimal performance Includes @tanstack/react-query-devtools for debugging and testing Enables access to mutation state from anywhere without prop drilling Offers version 5.90.19 of @tanstack/react-query for improved stability tanstack-query is a JavaScript library for React that provides data fetching, caching, and mutation management capabilities, also known as React Query v5.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('srdjan/zigttp/zig-expert', 'community', 'srdjan', 'zigttp', 'srdjan/zigttp', 'zig-expert', 0, 0, 39, '2026-03-08T01:57:15.425Z', '2026-03-08T02:07:28.117Z', '4e95bdb4fad789a04c1ea79dcb63ba5dcc0a679fcaff867d959346a2b89f1d44', '{"id":"srdjan/zigttp/zig-expert","name":"zig-expert","description":{"en":"The zig-expert skill provides expert guidance for writing idiomatic Zig code, embodying the Zen of Zig principles for explicit intent and compile-time optimization. It benefits developers seeking to master Zig programming.","zh":"zig-expert 是一个 Native Zig TypeScript 运行时，提供 idiomatic Zig 编程指导","ja":"zig-expert は、Idiomatic Zig コーディングを指導するネイティブ Zig TypeScript ランタイムです","ko":"zig-expert는 아이디어매틱 Zig 프로그래밍을 위한 가이드를 제공하는 네이티브 Zig TypeScript 런타임입니다","es":"zig-expert es un runtime nativo de Zig para TypeScript que evolucionó desde un port de mquickjs. Ofrece orientación experta para escribir código Zig idiomático que encarna el Zen de Zig.","fr":"zig-expert est un runtime natif Zig pour TypeScript ayant évolué d''un portage de mquickjs. Il offre un guide expert pour écrire du code Zig idiomatique incarnant le Zen de Zig.","de":"zig-expert ist eine native Zig-TypeScript-Laufzeitumgebung, die aus einem Port von mquickjs entstanden ist. Sie bietet Expertenanleitung zum Schreiben von idiomatischem Zig-Code, der das Zen von Zig verkörpert.","pt":"O zig-expert é um runtime de TypeScript nativo em Zig que visa desenvolver código idiômático, com foco em explicitar a intenção e evitar comportamentos indefinidos","ru":"ИИ Агент zig-expert является родным средством выполнения TypeScript в Zig, предназначенным для написания идjomатичного кода, с учетом принципов явного намерения и отсутствия неопределенных поведений","ar":"zig-expert هو وقت تشغيل TypeScript أصلي في لغة Zig، يهدف إلى تطوير код أصلية، مع التركيز على توضيح النية وتجنب ا