INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('srdjan/zigttp/zig-expert', 'zig-expert', 'srdjan', 'zigttp', 'community', 'zig-expert srdjan zigttp community The zig-expert skill provides expert guidance for writing idiomatic Zig code, embodying the Zen of Zig principles for explicit intent and compile-time optimization. It benefits developers seeking to master Zig programming. zig-expert 是一个 Native Zig TypeScript 运行时，提供 idiomatic Zig 编程指导 zig-expert は、Idiomatic Zig コーディングを指導するネイティブ Zig TypeScript ランタイムです zig-expert는 아이디어매틱 Zig 프로그래밍을 위한 가이드를 제공하는 네이티브 Zig TypeScript 런타임입니다 zig-expert es un runtime nativo de Zig para TypeScript que evolucionó desde un port de mquickjs. Ofrece orientación experta para escribir código Zig idiomático que encarna el Zen de Zig. zig-expert est un runtime natif Zig pour TypeScript ayant évolué d''un portage de mquickjs. Il offre un guide expert pour écrire du code Zig idiomatique incarnant le Zen de Zig. zig-expert ist eine native Zig-TypeScript-Laufzeitumgebung, die aus einem Port von mquickjs entstanden ist. Sie bietet Expertenanleitung zum Schreiben von idiomatischem Zig-Code, der das Zen von Zig verkörpert. O zig-expert é um runtime de TypeScript nativo em Zig que visa desenvolver código idiômático, com foco em explicitar a intenção e evitar comportamentos indefinidos ИИ Агент zig-expert является родным средством выполнения TypeScript в Zig, предназначенным для написания идjomатичного кода, с учетом принципов явного намерения и отсутствия неопределенных поведений zig-expert هو وقت تشغيل TypeScript أصلي في لغة Zig، يهدف إلى تطوير код أصلية، مع التركيز على توضيح النية وتجنب السلوكيات الغير محددة how to use zig-expert zig-expert alternative zig-expert setup guide what is zig-expert zig-expert vs mquickjs install zig-expert idiomatic zig programming zen of zig principles zig typescript runtime zig-expert idiomatic Zig Zen of Zig explicit intent no hidden control flow 读取性能优化 edge cases Provides expert guidance on idiomatic Zig programming Emphasizes explicit intent and compile-time optimization Follows the Zen of Zig principles for efficient code Optimizes for reading over writing, reducing undefined behaviors Supports edge case handling for robust code zig-expert is a native Zig TypeScript runtime that provides expert guidance for writing idiomatic Zig code, following the Zen of Zig principles');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chongdashu/threejs-forest-census/threejs-builder', 'community', 'chongdashu', 'threejs-forest-census', 'chongdashu/threejs-forest-census', 'threejs-builder', 0, 0, 39, '2026-03-08T01:57:15.430Z', '2026-03-08T02:07:31.912Z', '540a50b6bf71b87ddcfd6e03b10ab6ecc55d02d7bc591d44478b32c9573930de', '{"id":"chongdashu/threejs-forest-census/threejs-builder","name":"threejs-builder","description":{"en":"The threejs-builder skill provides a framework for shipping elegant, performant Three.js web experiences with modern ES modules, ideal for developers building 3D games and interactive web experiences.","zh":"Three.js Builder 是一个 Codex-ready 框架，用于构建高性能的 3D 网页体验，支持现代 ES 模块","ja":"Three.js Builder は、モダン ES モジュールを使用して高性能な 3D Web 体験を構築するための Codex-ready フレームワークです","ko":"Three.js Builder는 최신 ES 모듈을 사용하여 고성능 3D 웹 경험을 구축하기 위한 Codex-ready 프레임워크입니다","es":"Three.js Builder es un framework para crear experiencias web 3D con modernos módulos ES. Incluye guías para cargar modelos 3D y calibrar marcos de referencia.","fr":"Three.js Builder est un framework pour créer des expériences web 3D avec des modules ES modernes. Il inclut des guides pour charger des modèles 3D et calibrer des cadres de référence.","de":"Three.js Builder ist ein Framework für die Erstellung von 3D-Web-Erlebnissen mit modernen ES-Modulen. Es enthält Anleitungen zum Laden von 3D-Modellen und zur Kalibrierung von Referenzrahmen.","pt":"O Three.js Builder é um framework para criar experiências web 3D com módulos ES modernos. Aprenda a configurá-lo","ru":"Three.js Builder — это фреймворк для создания веб-опытов 3D с современными модулями ES. Узнайте, как его настроить","ar":"Three.js Builder هو إطار عمل لإنشاء تجارب ويب 3D مع وحدات ES الحديثة. تعلم كيفية إعداده"},"seo":{"title":{"en":"threejs-builder: Setup Guide for AI Agents | AI Agent Skill","zh":"Three.js Builder 快速入门指南 - AIエージェント","ja":"Three.js Builder のベストプラクティス - AIエージェント","ko":"Three.js Builder 설정 가이드 - AI 도구","es":"Guía de configuración de Three.js Builder para experienci...","fr":"Guide de mise en place de Three.js Builder pour des expér...","de":"Einrichtungsleitfaden für Three.js Builder für 3D-Web-Erl...","pt":"Guia de Configuração do Three.js Builder para Experiência...","ru":"Руководство по настройке Three.js Builder для создания ИИ...","ar":"دليل إعداد Three.js Builder لإنشاء تجارب الويب 3D"},"description":{"en":"Unlock the full potential of Three.js with threejs-builder. Discover how to load, cache, and clone 3D models with ease. Get started now!","zh":"使用 Three.js Builder 构建高性能的 3D 网页体验，了解如何加载和缓存 3D 模型，使用现代 ES 模块","ja":"Three.js Builder を使用して高性能な 3D Web 体験を構築する方法を学び、3D モデルのロードとキャッシュ、モダン ES モジュールの使用について","ko":"Three.js Builder로 고성능 3D 웹 경험을 구축하는 방법을 배우고 3D 모델 로딩 및 캐싱, 최신 ES 모듈 사용에 대해 알아보세요","es":"Aprende a crear experiencias web 3D elegantes y performantes con Three.js Builder y Codex CLI","fr":"Découvrez comment créer des expériences web 3D élégantes et performantes avec Three.js Builder et Codex CLI","de":"Erfahren Sie, wie Sie mit Three.js Builder und Codex CLI elegante und performante 3D-Web-Erlebnisse erstellen","pt":"Aprenda a configurar o Three.js Builder para criar experiências web 3D elegantes e performáticas com módulos ES modernos","ru":"Узнайте, как настроить Three.js Builder для создания элегантных и производительных веб-опытов 3D с современными модулями ES","ar":"تعلم كيفية إعداد Three.js Builder لإنشاء تجارب ويب 3D أنيقة وذات أداء высок مع وحدات ES الحديثة"},"definition":{"en":"threejs-builder is a Codex-ready framework for building Three.js web experiences, supporting features like GLTF model loading and reference frames.","zh":"Three.js Builder 是一个用于构建高性能 3D 网页体验的框架","ja":"Three.js Builder は、高性能な 3D Web 体験を構築するためのフレームワークです","ko":"Three.js Builder는 고성능 3D 웹 경험을 구축하기 위한 프레임워크입니다","es":"Three.js Builder es un framework de código abierto para crear experiencias web 3D con Three.js y Codex CLI","fr":"Three.js Builder est un framework open source pour créer des expériences web 3D avec Three.js et Codex CLI","de":"Three.js Builder ist ein Open-Source-Framework für die Erstellung von 3D-Web-Erlebnissen mit Three.js und Codex CLI","pt":"O que é Three.js Builder? É um framework para criar experiências web 3D elegantes e performáticas","ru":"Что такое Three.js Builder? Это фреймворк для создания элегантных и производительных веб-опытов 3D","ar":"ما هو Three.js Builder? إنه إطار عمل لإنشاء تجارب ويب 3D أنيقة وذات أداء высок"},"features":{"en":["Loads, caches, and clones 3D models using GLTF","Supports reference frames for calibration and anchoring","Utilizes SkeletonUtils for 3D model manipulation","Provides a guide for loading and caching 3D models in references/gltf-loading-guide.md","Follows the reference frame contract outlined in references/reference-frame-contract.md"],"zh":["支持现代 ES 模块","高性能 3D 网页体验","加载和缓存 3D 模型","使用 SkeletonUtils","支持 GLTF 模型"],"ja":["モダン ES モジュールを使用","高性能な 3D Web 体験","3D モデルのロードとキャッシュ","SkeletonUtils を使用","GLTF モデルをサポート"],"ko":["최신 ES 모듈 지원","고성능 3D 웹 경험","3D 모델 로딩 및 캐싱","SkeletonUtils 사용","GLTF 모델 지원"],"es":["Carga de modelos 3D con GLTF","Calibración de marcos de referencia","Compatibilidad con módulos ES modernos","Integración con Codex CLI","Guías para cargar y calibrar modelos 3D","Soporte para SkeletonUtils"],"fr":["Chargement de modèles 3D avec GLTF","Étalonnage de cadres de référence","Compatibilité avec des modules ES modernes","Intégration avec Codex CLI","Guides pour charger et étalonner des modèles 3D","Prise en charge de SkeletonUtils"],"de":["Laden von 3D-Modellen mit GLTF","Kalibrierung von Referenzrahmen","Kompatibilität mit modernen ES-Modulen","Integration mit Codex CLI","Anleitungen zum Laden und Kalibrieren von 3D-Modellen","Unterstützung für SkeletonUtils"],"pt":["Criação de experiências web 3D com módulos ES modernos","Suporte a modelos GLTF","Referência de quadros para calibração e ancoragem","Suporte a SkeletonUtils para clonagem de modelos 3D","Integração com Codex CLI para desenvolvimento ágil"],"ru":["Создание веб-опытов 3D с современными модулями ES","Поддержка моделей GLTF","Референс-фреймы для калибровки и якорения","Поддержка SkeletonUtils для клонирования 3D-моделей","Интеграция с Codex CLI для гибкой разработки"],"ar":["إنشاء تجارب ويب 3D مع وحدات ES الحديثة","دعم نماذج GLTF","إطار مرجعي للتعريف والتثبيت","دعم SkeletonUtils لاستنساخ نماذج 3D","التكامل مع Codex CLI لتطوير مرن"]},"keywords":{"en":["how to use threejs-builder","threejs-builder setup guide","threejs-builder vs other frameworks","threejs-builder install","what is threejs-builder","threejs-builder alternative","threejs-builder documentation","threejs-builder tutorial","threejs-builder examples"],"zh":["Three.js Builder","AIエージェント","3D 网页体验","高性能","现代 ES 模块","GLTF 模型","SkeletonUtils","Codex-ready"],"ja":["Three.js Builder","AIエージェント","3D Web 体験","高性能","モダン ES モジュール","GLTF モデル","SkeletonUtils","Codex-ready"],"ko":["Three.js Builder","AI 도구","3D 웹 경험","고성능","최신 ES 모듈","GLTF 모델","SkeletonUtils","Codex-ready"],"es":["Three.js Builder","experiencias web 3D","Codex CLI","GLTF","carga de modelos 3D","calibración de marcos de referencia","módulos ES modernos","SkeletonUtils","herramientas de desarrollo web 3D","frameworks de código abierto para web 3D"],"fr":["Three.js Builder","expériences web 3D","Codex CLI","GLTF","chargement de modèles 3D","étalonnage de cadres de référence","modules ES modernes","SkeletonUtils","outils de développement web 3D","frameworks open source pour web 3D"],"de":["Three.js Builder","3D-Web-Erlebnisse","Codex CLI","GLTF","Laden von 3D-Modellen","Kalibrierung von Referenzrahmen","moderne ES-Module","SkeletonUtils","Entwicklungstools für 3D-Web","Open-Source-Frameworks für 3D-Web"],"pt":["Three.js Builder","experiências web 3D","módulos ES modernos","GLTF","SkeletonUtils","Codex CLI","desenvolvimento web 3D","ferramentas de desenvolvimento"],"ru":["Three.js Builder","веб-опыты 3D","современные модули ES","GLTF","SkeletonUtils","Codex CLI","разработка веб-опытов 3D","инструменты разработки"],"ar":["Three.js Builder","تجارب ويب 3D","وحدات ES الحديثة","GLTF","SkeletonUtils","Codex CLI","تطوير تجارب ويب 3D","أدوات التطوير"]}},"owner":"chongdashu","repo":"threejs-forest-census","repoPath":"chongdashu/threejs-forest-census","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.430Z","topics":[],"category":"community","skillMd":{"name":"threejs-builder","description":"Design and implement lightweight Three.js (r150+) ES-module scenes—hero sections, interactive product viewers, particle backdrops, GLTF showcases, or quick prototypes—whenever prompts mention three.js/threejs scene, 3D web background, orbit controls, or WebGL demo.","bodyPreview":"# Three.js Builder\n\nA Codex-ready framework for shipping elegant, performant Three.js web experiences with modern ES modules.\n\n## Reference Files\n\n> **Read the appropriate reference when working on specific topics:**\n\n| Topic | File | Use When |\n|-------|------|----------|\n| **GLTF Models** | `references/gltf-loading-guide.md` | Loading, caching, cloning 3D models, SkeletonUtils |\n| **Reference Frames** | `references/reference-frame-contract.md` | Calibration, anchoring, axis correctness, debugg","body":"# Three.js Builder\n\nA Codex-ready framework for shipping elegant, performant Three.js web experiences with modern ES modules.\n\n## Reference Files\n\n> **Read the appropriate reference when working on specific topics:**\n\n| Topic | File | Use When |\n|-------|------|----------|\n| **GLTF Models** | `references/gltf-loading-guide.md` | Loading, caching, cloning 3D models, SkeletonUtils |\n| **Reference Frames** | `references/reference-frame-contract.md` | Calibration, anchoring, axis correctness, debugging |\n| **Game Development** | `references/game-patterns.md` | State machines, animation switching, parallax, pooling |\n| **Advanced Topics** | `references/advanced-topics.md` | Post-processing, shaders, physics, instancing |\n| **Calibration Helpers** | `scripts/README.md` | GLTF calibration helper installation and usage |\n\n---\n\n## Philosophy: Start from Scene Intent\n\nThree.js work lives inside a scene graph: parents transform children, and everything in `scene` is rendered.\n\n**Before writing code, ask**:\n- What is the core visual element or metaphor (hero object, particle field, data glyph)?\n- How should visitors manipulate or perceive it (static hero, orbit control, camera-relative movement)?\n- What level of hardware/performance do we target (mobile hero snippet vs. desktop interactive)?\n- Which animation best communicates the story (continuous rotation, bobbing, interaction-driven)?\n\n**Core principles**:\n1. **Scene graph first** – model hierarchy and transforms before materials.\n2. **Intent-driven primitives** – boxes, spheres, torus, planes cover 80% of hero cases; reach for GLTF only when fidelity demands it.\n3. **Animation as transformation** – treat animation as evolving position/rotation/scale with `renderer.setAnimationLoop`.\n4. **Performance through restraint** – reuse geometries/materials, clamp device pixel ratio, keep draw calls low.\n\n---\n\n## Foundational Principle: Lock a “Reference Frame Contract” First\n\nMost Three.js bugs are not “rendering bugs” — they’re **reference-frame bugs**: wrong origin, wrong up-axis assumption, wrong forward direction, wrong “ground = y=0” semantics, wrong color space, or wrong loading environment.\n\nTreat your scene like a contract you must prove once, then never violate:\n- **Axes**: which way is forward for gameplay, and how do models map to it?\n- **Anchors**: what does “on the ground” mean for each asset class?\n- **Units**: what is 1 unit (meter-ish? pixel-ish?) and how do imported assets fit?\n- **Color**: are textures and output color space correct?\n\nIf you don’t lock this contract early, you will chase symptoms: inverted movement, floating/sinking models, “wrongly loaded” textures, and end-state hangs caused by tangled state transitions.\n\n### The Calibration Pass (do this before building gameplay)\nDo a 60-second calibration scene and lock constants (axes/anchors/scale/color) before shipping gameplay systems.\n\nDeep guide + troubleshooting map: `references/reference-frame-contract.md`\n\n### Mesh Forward Verification (Do Not Guess)\nDon’t “eyeball rotate until it looks right” and don’t assume “GLTF faces `-Z`”.\n\nIn the calibration scene, **prove** each imported model’s forward direction and lock it as a constant (global `MODEL_YAW_OFFSET` or per-asset `yawOffset`).\n\nIf you want a reusable helper module instead of hand-rolling arrows/box helpers each time:\n- Install (repo-scoped): run `python3 .codex/skills/threejs-builder/scripts/install-gltf-calibration-helpers.py --out ./gltf-calibration-helpers.mjs`\n- Install (from within the skill folder): run `python3 scripts/install-gltf-calibration-helpers.py --out ./gltf-calibration-helpers.mjs`\n- Use: import and call `attachGltfCalibrationHelpers(...)` (see `scripts/README.md`)\n\nMinimal check:\n```js\n// In Three.js, an Object3D’s \"forward\" is its local -Z axis.\nconst localForward = new THREE.Vector3(0, 0, -1);\n\n// Attach a visible arrow to the model so you can *see* its forward.\nconst forwardArrow = new THREE.ArrowHelper(localForward, new THREE.Vector3(0, 1.2, 0), 1.2, 0xff00ff);\nmodelRoot.add(forwardArrow);\n\n// Also log the current world-forward for debugging (post-normalization and post-rotation).\nconst worldForward = new THREE.Vector3();\nmodelRoot.getWorldDirection(worldForward);\nconsole.log(''model world forward (-Z):'', worldForward.toArray());\n```\n\nThen decide:\n- If the mesh runs backward, set `yawOffset = Math.PI`.\n- If it faces the camera (common symptom), your yaw convention is wrong—flip the offset and re-check.\n\n## Coordinate System & Camera Awareness (Critical)\n\nThree.js is right-handed: +X right, +Y up, +Z toward the camera. Many GLTF assets are authored facing `-Z`, but **verify per pack** (don’t assume). Camera-relative controls must project the camera forward vector onto the XZ plane, normalize, then derive the right vector via a right-handed cross product to avoid inverted WASD when the camera orbits.\n\n```\nconst forward = new THREE.Vector3();\ncamera.getWorldDirection(forward);\nforward.y = 0;\nforward.normalize();\n// Right-handed basis (DON''T swap arguments): right = forward × up\nconst right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0));\n```\n\nPractical rule:\n- If A/D is inverted, your cross product order is wrong (or you need to flip `forward` with `forward.negate()` depending on your convention). Fix the basis, not the key mapping.\n\n---\n\n## Origins & “Ground” Anchors (Stop Guessing)\n\nAnchoring is an asset-contract decision, not a “tweak until it looks right” decision.\n\nRule of thumb:\n- Characters/props: `minY = 0`\n- Ground tiles: often `maxY = 0` (walkable surface)\n\nDeep guide + example code: `references/reference-frame-contract.md`\n\n---\n\n## Build Flow\n\n### 1. Frame the Experience\n- Define the vibe (portfolio, gamey, data viz) and jot a mini mood board (colors, light style, animation verbs).\n- Choose interaction tier: static render, auto-rotation, OrbitControls, or custom camera/gameplay loop.\n- Sketch layout: do you need a ground plane, backdrop gradient, floating particles, or spotlight object?\n\n### 2. Establish Runtime Foundations\n- Use modern ES modules—no global `THREE`. Import from `three` package or CDN versions (>=0.150).\n- Minimal HTML template:\n\n```html\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>Three.js Scene</title>\n  <style>body{margin:0;overflow:hidden;background:#010103;}canvas{display:block;}</style>\n</head>\n<body>\n  <script type=\"module\">\n    import * as THREE from ''https://unpkg.com/three@0.160.0/build/three.module.js'';\n\n    const scene = new THREE.Scene();\n    const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 2000);\n    camera.position.set(0, 1.5, 4.5);\n\n    const renderer = new THREE.WebGLRenderer({ antialias: true });\n    renderer.setSize(innerWidth, innerHeight);\n    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));\n    renderer.outputColorSpace = THREE.SRGBColorSpace;\n    document.body.appendChild(renderer.domElement);\n\n    window.addEventListener(''resize'', () => {\n      camera.aspect = innerWidth / innerHeight;\n      camera.updateProjectionMatrix();\n      renderer.setSize(innerWidth, innerHeight);\n    });\n  </script>\n</body>\n</html>\n```\n\n- Plug OrbitControls from `three/addons/controls/OrbitControls.js` when interaction is needed, enable damping, and call `controls.update()` each frame.\n\n### 2.5 GLTF Loading Guardrails (When You Use Models)\n- Run via a local server (not `file://`) so relative resources resolve reliably.\n- For animated/skinned GLTF instancing, use `SkeletonUtils.clone()` (plain `.clone()` breaks skeleton links).\n- Always log animation clip names after load and select by exact string (avoid “best guess” name matching unless it’s a deliberate fallback).\n- If your asset pack uses an atlas, avoid “multiply tinting” materials (it can turn textured models into weird flat colors). Prefer leaving `material.color` at white and using emissive/lighting for emphasis.\n\n### 3. Compose the Scene\n- **Geometries**: prefer built-ins (Box, Sphere, Torus, Plane, Cone, Icosahedron). For particle clouds use `BufferGeometry` + `Float32Array` positions.\n- **Materials**: pick `MeshStandardMaterial` as default (tweak `roughness`/`metalness`), `MeshPhysicalMaterial` for glass/liquids, `MeshBasicMaterial` for unlit accents, `PointsMaterial` for particles.\n- **Lighting**: start with Ambient (0.3–0.5) + Directional key + colored fill; enable shadows only when necessary and set `renderer.shadowMap.enabled = true` + map sizes of 1024–2048.\n- **Color palettes**: define constants (e.g., `const COLORS = { primary: 0xff6600, accent: 0x0ff0ff }`) and keep backgrounds dark to let emissive tones pop.\n\n### 4. Animate & Interact\n- Implement animation loops with `renderer.setAnimationLoop((time) => { ... renderer.render(scene, camera); });`.\n- Common patterns:\n  - Continuous rotation with `mesh.rotation.y = time * 0.001`.\n  - Bobbing via `mesh.position.y = Math.sin(time * 0.002) * 0.4`.\n  - Mouse-reactive tilt: normalize pointer coords and lerp rotations for smoothness.\n  - Camera-relative character motion for interactive demos (see snippet above for direction vectors).\n- Store state outside the loop (e.g., `const inputState = { up: false, ... }`).\n\n### 4.5 State Machines & “Time Ran Out” Bugs\nIf your app “hangs” at time-out, it’s almost always because multiple systems are competing to transition state.\n\nGuardrails:\n- Use a single `state.mode` and a single transition function.\n- Treat `timeLeft <= 0` as terminal and clamp it once: `timeLeft = Math.max(0, timeLeft - dt)`.\n- Add a one-way latch like `hasEnded` so the end transition can only happen once.\n\n### 5. Polish & Performance\n- Cap `renderer.setPixelRatio(Math.min(devicePixelRatio, 2))` to keep 4K laptops smooth.\n- Reuse geometries/materials, avoid instantiating inside the animation loop.\n- Use helpers (GridHelper, AxesHelper) for debugging, but remove them for production scenes.\n- Separate setup helpers (e.g., `createLights()`/`createMeshes()`) to keep files navigable.\n\n---\n\n## Anti-Patterns to Avoid\n\n❌ **Legacy global builds**: Using `<script src=\"three.js\"></script>` and accessing `THREE` globals breaks tree-shaking and OrbitControls imports. Use ES modules.\n\n❌ **Camera-blind controls**: Mapping WASD directly to world axes feels wrong once the camera rotates. Always derive movement vectors from the camera orientation.\n\n❌ **Floating/sinking fixes by “random y offsets”**: If you’re tweaking `position.y` in 5 places, your anchoring strategy is missing.\nWhy bad: you’ll never converge across ground tiles vs characters vs props.\nBetter: normalize each asset to a declared anchor (`minY` or `maxY`) at load time and only place the wrapper.\n\n❌ **Asset guessing**: Assuming GLTF forward direction, scale, or animation names without a calibration pass.\nBetter: build a 60-second calibration scene and lock constants (forward offsets, anchors, heights).\n\n❌ **Off-center canvases from transform math**: Mixing `translate()` + `scale()` with the wrong `transform-origin` makes the render area drift.\nBetter: center via layout (flex/grid) and apply `scale()` only, with `transform-origin: center`.\n\n❌ **Geometry churn inside loops**: Creating geometries/materials each frame tanks GC and FPS. Instantiate once and mutate transforms only.\n\n❌ **Overly dense primitives**: Jumping to `SphereGeometry(1, 128, 128)` without purpose wastes perf; start with defaults and scale segments only when silhouetted edges demand it.\n\n❌ **Unbounded pixel ratio**: Forgetting to clamp `devicePixelRatio` makes retina users suffer. Always clamp to ≤2 unless photorealism is mandatory.\n\n---\n\n## Variation Guidance\n\n- **Purpose-specific styling**:\n  - Portfolio hero → slow easing, glossy lighting, analogous palettes.\n  - Game prototype → punchy colors, contrasty lights, camera-relative controls, particles.\n  - Data viz → clean planes, grid helpers, consistent units, annotations.\n  - Background loop → subtle gradients, low-frequency motion, ambient glow.\n- **Mix geometry/material** choices: cycle through spheres, rounded boxes, low-poly icosahedrons, tubes. Experiment with `flatShading`, `wireframe`, emissive blooms.\n- **Camera moods**: alternate between dolly-in hero (z≈4), aerial tilt (camera.set(8, 11, -6)), or isometric (45° yaw). Pair with matching movement logic.\n- **Animation verbs**: rotate, pulse, orbit, flock, noise-driven drift. Avoid always rotating cubes at `0.001` speed.\n\n---\n\n## Remember\n\nThree.js scenes succeed when the mental model (scene graph + intent) guides the build. Lead with philosophy, respect the coordinate system, keep loops lean, and vary geometry, lighting, and animation so every experience feels purpose-built. Let these patterns unlock creativity—they are rails, not cages.\n\nFor specific topics, see the **Reference Files** table at the top of this document.\n"},"lastSynced":"2026-03-08T02:07:31.912Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced 3D web experience development with Three.js and modern ES modules.","zh":"非常适合需要使用Three.js和现代ES模块开发高级3D网页体验的前端代理。","ja":"Three.jsとモダンなESモジュールを使用して高度な3D Web体験を開発する必要があるフロントエンドエージェントに最適です。","ko":"Three.js와 현대적인 ES 모듈을 사용하여 고급 3D 웹 경험을 개발해야 하는 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes Frontend que necesitan experiencia avanzada de desarrollo web 3D con Three.js y módulos ES modernos.","fr":"Parfait pour les agents Frontend qui ont besoin d''une expérience de développement web 3D avancée avec Three.js et des modules ES modernes.","de":"Perfekt für Frontend-Agents, die eine fortschrittliche 3D-Web-Erlebnisentwicklung mit Three.js und modernen ES-Modulen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de experiência avançada de desenvolvimento web 3D com Three.js e módulos ES modernos.","ru":"Идеально подходит для агентов Frontend, которым необходима продвинутая разработка веб-опыта 3D с помощью Three.js и современных модулей ES.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى خبرة متقدمة في تطوير الويب ثلاثي الأبعاد باستخدام Three.js ووحدات ES الحديثة."},"recommendation":{"en":"Empowers agents to ship elegant, performant Three.js web experiences by utilizing modern ES modules, loading and caching GLTF models, and calibrating reference frames with SkeletonUtils and axis correctness protocols.","zh":"通过利用现代ES模块、加载和缓存GLTF模型，并使用SkeletonUtils和轴向正确性协议来校准参考帧，赋予代理创建优雅、高性能的Three.js网页体验的能力。","ja":"モダンなESモジュールを利用し、GLTFモデルを読み込みおよびキャッシュし、SkeletonUtilsおよび軸方向の正確性プロトコルを使用して参照フレームを較正することで、エージェントが優雅で高性能のThree.js Web体験を配信できるようにします。","ko":"现代적인 ES 모듈을 활용하고 GLTF 모델을 로딩하고 캐싱하며, SkeletonUtils와 축 방향 정확성 프로토콜을 사용하여 참조 프레임을 校准함으로써, 에이전트가 우아하고 고성능의 Three.js 웹 경험을 제공할 수 있도록 합니다.","es":"Habilita a los agentes a entregar experiencias web elegantes y de alto rendimiento de Three.js mediante la utilización de módulos ES modernos, la carga y el almacenamiento en caché de modelos GLTF y la calibración de marcos de referencia con SkeletonUtils y protocolos de corrección de ejes.","fr":"Permet aux agents de livrer des expériences web Three.js élégantes et performantes en utilisant des modules ES modernes, en chargeant et en mettant en cache des modèles GLTF, et en calibrant des cadres de référence avec SkeletonUtils et des protocoles de correction d''axe.","de":"Ermächtigt Agents, elegante und leistungsstarke Three.js-Web-Erlebnisse auszuliefern, indem moderne ES-Module verwendet werden, GLTF-Modelle geladen und zwischengespeichert werden und Referenzrahmen mit SkeletonUtils und Achsenkorrekturprotokollen kalibriert werden.","pt":"Habilita os agentes a enviar experiências web elegantes e de alto desempenho do Three.js, utilizando módulos ES modernos, carregando e armazenando em cache modelos GLTF e calibrando quadros de referência com SkeletonUtils e protocolos de correção de eixo.","ru":"Наделяет агентов возможностью доставлять элегантные и производительные веб-опыты Three.js, используя современные модули ES, загружая и кешируя модели GLTF, а также калибруя системы координат с помощью SkeletonUtils и протоколов осевой точности.","ar":"يمنح الوكلاء القدرة على إرسال تجارب الويب ثلاثية الأبعاد الأنيقة ذات الأداء العالي من Three.js، باستخدام وحدات ES الحديثة وتحميل نموذج GLTF وتخزينه في الذاكرة والمصافحة الإطار المرجعي مع SkeletonUtils وبروتوكولات تصحيح المحور."},"useCases":{"en":["Building interactive 3D games","Loading and caching GLTF models for web experiences","Calibrating and anchoring reference frames for precise 3D rendering"],"zh":["构建交互式3D游戏","为网页体验加载和缓存GLTF模型","校准和锚定参考帧以实现精确的3D渲染"],"ja":["インタラクティブな3Dゲームの構築","Web体験用のGLTFモデルの読み込みおよびキャッシュ","精密な3Dレンダリングのための参照フレームの較正およびアンカー"],"ko":["인터랙티브 3D 게임 구축","웹 경험을 위한 GLTF 모델 로딩 및 캐싱","정밀한 3D 렌더링을 위한 참조 프레임 校准 및 앵커"],"es":["Construir juegos de 3D interactivos","Cargar y almacenar en caché modelos GLTF para experiencias web","Calibrar y anclar marcos de referencia para una representación 3D precisa"],"fr":["Construire des jeux 3D interactifs","Charger et mettre en cache des modèles GLTF pour des expériences web","Calibrer et ancrer des cadres de référence pour un rendu 3D précis"],"de":["Interaktive 3D-Spiele erstellen","GLTF-Modelle für Web-Erlebnisse laden und zwischenspeichern","Referenzrahmen für präzise 3D-Darstellung kalibrieren und verankern"],"pt":["Construir jogos interativos 3D","Carregar e armazenar em cache modelos GLTF para experiências web","Calibrar e ancorar quadros de referência para renderização 3D precisa"],"ru":["Создание интерактивных 3D-игр","Загрузка и кеширование моделей GLTF для веб-опытов","Калибровка и крепление систем координат для точной 3D-рендеринга"],"ar":["بناء ألعاب تفاعلية ثلاثية الأبعاد","تحميل نموذج GLTF وتخزينه في الذاكرة لتجارب الويب","المصافحة والإرساء الإطار المرجعي للتصيير ثلاثي الأبعاد الدقيق"]},"limitations":{"en":["Requires knowledge of Three.js and modern ES modules","Specific to web-based 3D experiences"],"zh":["需要了解Three.js和现代ES模块","仅适用于基于网页的3D体验"],"ja":["Three.jsおよびモダンなESモジュールの知識が必要","Webベースの3D体験にのみ特化"],"ko":["Three.js와 현대적인 ES 모듈에 대한 지식이 필요","웹 기반 3D 경험에만 특화"],"es":["Requiere conocimiento de Three.js y módulos ES modernos","Específico para experiencias 3D basadas en web"],"fr":["Nécessite des connaissances en Three.js et des modules ES modernes","Spécifique aux expériences 3D basées sur le web"],"de":["Benötigt Kenntnisse von Three.js und modernen ES-Modulen","Spezifisch für webbasierte 3D-Erlebnisse"],"pt":["Exige conhecimento de Three.js e módulos ES modernos","Específico para experiências web 3D baseadas na web"],"ru":["Требует знания Three.js и современных модулей ES","Специфичен для веб-опытов 3D на основе веба"],"ar":["يتطلب معرفة Three.js ووحدات ES الحديثة","محدد لتجارب الويب ثلاثية الأبعاد القائمة على الويب"]},"version":4},"contentHash":"540a50b6bf71b87ddcfd6e03b10ab6ecc55d02d7bc591d44478b32c9573930de","qualityScore":39}');
