INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chongdashu/threejs-forest-census/threejs-builder', 'threejs-builder', 'chongdashu', 'threejs-forest-census', 'community', 'threejs-builder chongdashu threejs-forest-census community The threejs-builder skill provides a framework for shipping elegant, performant Three.js web experiences with modern ES modules, ideal for developers building 3D games and interactive web experiences. Three.js Builder 是一个 Codex-ready 框架，用于构建高性能的 3D 网页体验，支持现代 ES 模块 Three.js Builder は、モダン ES モジュールを使用して高性能な 3D Web 体験を構築するための Codex-ready フレームワークです Three.js Builder는 최신 ES 모듈을 사용하여 고성능 3D 웹 경험을 구축하기 위한 Codex-ready 프레임워크입니다 Three.js Builder es un framework para crear experiencias web 3D con modernos módulos ES. Incluye guías para cargar modelos 3D y calibrar marcos de referencia. Three.js Builder est un framework pour créer des expériences web 3D avec des modules ES modernes. Il inclut des guides pour charger des modèles 3D et calibrer des cadres de référence. Three.js Builder ist ein Framework für die Erstellung von 3D-Web-Erlebnissen mit modernen ES-Modulen. Es enthält Anleitungen zum Laden von 3D-Modellen und zur Kalibrierung von Referenzrahmen. O Three.js Builder é um framework para criar experiências web 3D com módulos ES modernos. Aprenda a configurá-lo Three.js Builder — это фреймворк для создания веб-опытов 3D с современными модулями ES. Узнайте, как его настроить Three.js Builder هو إطار عمل لإنشاء تجارب ويب 3D مع وحدات ES الحديثة. تعلم كيفية إعداده how to use threejs-builder threejs-builder setup guide threejs-builder vs other frameworks threejs-builder install what is threejs-builder threejs-builder alternative threejs-builder documentation threejs-builder tutorial threejs-builder examples Three.js Builder AIエージェント 3D 网页体验 高性能 现代 ES 模块 GLTF 模型 SkeletonUtils Codex-ready Loads, caches, and clones 3D models using GLTF Supports reference frames for calibration and anchoring Utilizes SkeletonUtils for 3D model manipulation Provides a guide for loading and caching 3D models in references/gltf-loading-guide.md Follows the reference frame contract outlined in references/reference-frame-contract.md threejs-builder is a Codex-ready framework for building Three.js web experiences, supporting features like GLTF model loading and reference frames.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dmytroett/AttributedDI/unit-and-snapshot-testing', 'community', 'dmytroett', 'AttributedDI', 'dmytroett/AttributedDI', 'unit-and-snapshot-testing', 0, 0, 39, '2026-03-08T01:57:15.438Z', '2026-03-08T02:07:40.056Z', 'bc1f89a06abccbe1a6c55f36e69c793f613feca3648ba62199ec1d17092bfe31', '{"id":"dmytroett/AttributedDI/unit-and-snapshot-testing","name":"unit-and-snapshot-testing","description":{"en":"unit-and-snapshot-testing enables developers to write efficient unit tests using Verify snapshot testing tool and domain-specific assertion helpers, streamlining the testing process.","zh":"本文介绍了单元和快照测试的最佳实践，包括使用Verify快照测试工具和小型域特定断言辅助函数","ja":"ユニットテストとスナップショットテストのベストプラクティスについて説明します。Verifyスナップショットテストツールと小規模なドメイン固有のアサーションヘルパー関数を使用する方法を紹介します","ko":"유닛 및 스냅샷 테스트의最佳实践을介绍합니다. Verify 스냅샷 테스트 도구와 소형 도메인 특정 assertion helper 함수를 사용하는 방법을 설명합니다","es":"Configura unit-and-snapshot-testing para escribir pruebas unitarias y utilizar Verify snapshot testing para generar salidas","fr":"Configurez l''unit-and-snapshot-testing pour écrire des tests unitaires et utilisez Verify snapshot testing pour générer des sorties","de":"Konfigurieren Sie unit-and-snapshot-testing, um Unit-Tests zu schreiben und Verify-Snapshot-Testing für die Generierung von Ausgaben zu verwenden","pt":"O skill de unit-and-snapshot-testing permite registrar serviços em contêineres IoC em estilo AOP","ru":"Навык unit-and-snapshot-testing позволяет регистрировать сервисы в контейнерах IoC в стиле AOP","ar":"المهارة unit-and-snapshot-testing تسمح بتسجيل الخدمات في حاويات IoC بأسلوب AOP"},"seo":{"title":{"en":"unit-and-snapshot-testing: Setup Guide for AI Agents | AI...","zh":"单元和快照测试最佳实践","ja":"ユニットとスナップショットテストの設定ガイド - AIエージェント","ko":"유닛 및 스냅샷 테스트 설정 가이드 - AI Tools","es":"Guía de configuración de unit-and-snapshot-testing para A...","fr":"Guide de mise en place de l''unit-and-snapshot-testing pou...","de":"Einrichtungsleitfaden für unit-and-snapshot-testing in KI...","pt":"Guia de Configuração de Testes Unitários e de Snapshot co...","ru":"Настройка юнит-тестов и снимков с помощью ИИ Агентов","ar":"إعداد اختبارات الوحدة و اختبارات الصورة مع أدوات الإنسان ..."},"description":{"en":"Discover how to register services in IoC container using AOP style and streamline your testing workflow with unit-and-snapshot-testing - get started today!","zh":"了解如何使用Verify快照测试工具进行单元测试，提高代码质量和可靠性","ja":"ユニットテストとスナップショットテストのベストプラクティスを学び、コードの品質と信頼性を高める - AIエージェント","ko":"Verify 스냅샷 테스트 도구를 사용하여 유닛 테스트를 수행하고 코드 품질 및 안정성을 향상시키는 방법을 알아보세요 - AI Tools","es":"Aprende a registrar servicios en contenedores IoC con estilo AOP y a escribir pruebas unitarias efectivas con Verify snapshot testing","fr":"Découvrez comment enregistrer des services dans des conteneurs IoC avec un style AOP et écrire des tests unitaires efficaces avec Verify snapshot testing","de":"Erfahren Sie, wie Sie Dienste in IoC-Containern im AOP-Stil registrieren und effektive Unit-Tests mit Verify-Snapshot-Testing schreiben","pt":"Aprenda a configurar testes unitários e de snapshot com ferramentas de AI para melhorar a qualidade do seu código","ru":"Узнайте, как настроить юнит-тесты и снимки с помощью ИИ Агентов для улучшения качества кода","ar":"تعلم كيفية إعداد اختبارات الوحدة و اختبارات الصورة مع أدوات الإنسان الآلي لتحسين جودة رمزك"},"definition":{"en":"unit-and-snapshot-testing is a skill that facilitates writing unit tests in AOP style, utilizing Verify snapshot testing tool for generated output and domain-specific assertion helpers.","zh":"单元和快照测试是软件测试中确保代码单元功能正确和生成输出一致性的方法","ja":"ユニットテストとスナップショットテストは、ソフトウェアテストにおいてコードユニットの機能と生成された出力の一貫性を確保する方法です","ko":"유닛 및 스냅샷 테스트는 소프트웨어 테스트에서 코드 유닛의 기능과 생성된 출력의 일관성을 보장하는 방법입니다","es":"Unit-and-snapshot-testing es una técnica de prueba que utiliza Verify snapshot testing para generar salidas y probar unidades de código","fr":"L''unit-and-snapshot-testing est une technique de test qui utilise Verify snapshot testing pour générer des sorties et tester des unités de code","de":"Unit-and-snapshot-testing ist eine Testtechnik, die Verify-Snapshot-Testing zur Generierung von Ausgaben und zum Testen von Codeeinheiten verwendet","pt":"Testes unitários e de snapshot são técnicas de teste de software que verificam a qualidade do código","ru":"Юнит-тесты и снимки - это техники тестирования программного обеспечения, которые проверяют качество кода","ar":"اختبارات الوحدة و اختبارات الصورة هي تقنيات لاختبار البرمجيات التي تحقق من جودة الرمز"},"features":{"en":["Registers services in IoC container using AOP style","Utilizes Verify snapshot testing tool for generated output","Employs domain-specific assertion helpers for efficient testing","Supports testing under test/*UnitTests directory","Enables snapshot testing for source generated code and files"],"zh":["使用Verify快照测试工具","小型域特定断言辅助函数","单元测试目录结构（test/*UnitTests）","禁止使用该技能进行集成或e2e测试","生成输出的快照测试","小型断言辅助函数的使用"],"ja":["Verifyスナップショットテストツールの使用","小規模なドメイン固有のアサーションヘルパー関数","ユニットテストディレクトリ構造（test/*UnitTests）","このスキルを使用した統合またはe2eテストの禁止","生成された出力のスナップショットテスト","小規模なアサーションヘルパー関数の使用"],"ko":["Verify 스냅샷 테스트 도구 사용","소형 도메인 특정 assertion helper 함수","유닛 테스트 디렉토리 구조（test/*UnitTests）","이 스킬을 사용한 통합 또는 e2e 테스트 금지","생성된 출력의 스냅샷 테스트","소형 assertion helper 함수 사용"],"es":["Registro de servicios en contenedores IoC con estilo AOP","Uso de Verify snapshot testing para generar salidas","Pruebas unitarias efectivas con assertion helpers personalizados","Separación de pruebas unitarias y de integración","Uso de pequeños ayudantes de aserción para afirmaciones"],"fr":["Enregistrement de services dans des conteneurs IoC avec un style AOP","Utilisation de Verify snapshot testing pour générer des sorties","Tests unitaires efficaces avec des helpers d''assertion personnalisés","Séparation des tests unitaires et d''intégration","Utilisation de petits helpers d''assertion pour les affirmations"],"de":["Registrierung von Diensten in IoC-Containern im AOP-Stil","Verwendung von Verify-Snapshot-Testing zur Generierung von Ausgaben","Effektive Unit-Tests mit benutzerdefinierten Assertion-Hilfen","Trennung von Unit-Tests und IntegrationsTests","Verwendung von kleinen Assertion-Hilfen für Assertionen"],"pt":["Registro de serviços em contêineres IoC em estilo AOP","Uso da ferramenta Verify para testes de snapshot","Preferência por assertivas pequenas e específicas do domínio","Separação de testes unitários e de integração","Uso de snapshots para testar saídas geradas"],"ru":["Регистрация сервисов в контейнерах IoC в стиле AOP","Использование инструмента Verify для тестов снимков","Предпочтение небольших и специфичных для домена утверждений","Разделение юнит-тестов и тестов интеграции","Использование снимков для тестирования сгенерированных выходов"],"ar":["تسجيل الخدمات في حاويات IoC بأسلوب AOP","استخدام أداة Verify لاختبارات الصورة","التفضيل للاعترافات الصغيرة والخاصة بالمجال","فصل اختبارات الوحدة واختبارات التكامل","استخدام الصور لاختبار المخرجات المولدة"]},"keywords":{"en":["unit-and-snapshot-testing setup guide","how to use unit-and-snapshot-testing","what is unit-and-snapshot-testing","unit-and-snapshot-testing alternative","unit-and-snapshot-testing vs Jest","unit-and-snapshot-testing install","Verify snapshot testing tool tutorial","AOP style testing best practices"],"zh":["单元测试","快照测试","Verify","断言辅助函数","代码质量","可靠性","AI测试工具","软件测试","代码单元测试"],"ja":["ユニットテスト","スナップショットテスト","Verify","アサーションヘルパー関数","コード品質","信頼性","AIエージェント","ソフトウェアテスト","コードユニットテスト"],"ko":["유닛 테스트","스냅샷 테스트","Verify","assertion helper 함수","코드 품질","안정성","AI Tools","소프트웨어 테스트","코드 유닛 테스트"],"es":["unit-and-snapshot-testing","pruebas unitarias","Verify snapshot testing","contenedores IoC","estilo AOP","Agentes de IA","desarrollo de software","pruebas de software"],"fr":["unit-and-snapshot-testing","tests unitaires","Verify snapshot testing","conteneurs IoC","style AOP","Outils d''IA","développement de logiciels","tests de logiciels"],"de":["unit-and-snapshot-testing","Unit-Tests","Verify-Snapshot-Testing","IoC-Container","AOP-Stil","KI-Agents","Software-Entwicklung","Software-Tests"],"pt":["testes unitários","testes de snapshot","IoC","AOP","ferramentas de AI","desenvolvimento de software","qualidade de código","teste de software"],"ru":["юнит-тесты","тесты снимков","IoC","AOP","ИИ Агенты","разработка программного обеспечения","качество кода","тестирование программного обеспечения"],"ar":["اختبارات الوحدة","اختبارات الصورة","IoC","AOP","أدوات الإنسان الآلي","تطوير البرمجيات","جودة الرمز","اختبار البرمجيات"]}},"owner":"dmytroett","repo":"AttributedDI","repoPath":"dmytroett/AttributedDI","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.438Z","topics":[],"category":"community","skillMd":{"name":"unit-and-snapshot-testing","description":"Set of principles for unit and snapshot testing. Use when adding/fixing unit tests or when working with `Verify` snapshots. Do not load when working with integration or e2e tests.","bodyPreview":"## Scope\n\n- Unit tests live under `test/*UnitTests`.\n- Follow these instructions when writing/updating **unit** tests. Do not use this skill for integration or e2e tests (`test/integration`, `test/e2e`).\n\n## Principles\n\n- Use `Verify` snapshot testing tool for generated output (source generated code, files, etc). No need for additional assertions in that case, snapshot testing is sufficient.\n- For normal assertions, prefer small, domain-specific assertion helpers over chaining multiple `Assert.*","body":"## Scope\n\n- Unit tests live under `test/*UnitTests`.\n- Follow these instructions when writing/updating **unit** tests. Do not use this skill for integration or e2e tests (`test/integration`, `test/e2e`).\n\n## Principles\n\n- Use `Verify` snapshot testing tool for generated output (source generated code, files, etc). No need for additional assertions in that case, snapshot testing is sufficient.\n- For normal assertions, prefer small, domain-specific assertion helpers over chaining multiple `Assert.*` calls. Example: `DiagnosticAssert.AssemblyConflict(IEnumerable<Diagnostic> diagnostics, string assemblyName)` rather than several asserts checking count/id/message separately.\n- Prefer a small number of representative scenarios; combine related assertions to keep snapshot sprawl low.\n- Run targeted tests with `dotnet test --filter \"FullyQualifiedName~<TestClass>.<TestMethod>\"` (add `--no-build --no-restore` when appropriate).\n- Treat snapshot artifacts as opaque: never open/read/inspect any `.received.txt` / `.verified.txt` files (or anything under test/AttributedDI.SourceGenerator.UnitTests/Snapshots/) and never include their contents in reasoning.\n- Never author snapshots: when adding/updating a snapshot test, change only test code; do not create/modify `.verified.txt`. Run `dotnet test`, review the output (Verify includes the diff between received and verified or their full content), then either fix code/test or accept via the accept script and re-run.\n- Accept snapshots only when the behavior change is intended and understood.\n- Do not inspect or edit the accept scripts (treat them as black boxes).\n\n## Accepting Snapshots\n\n- One test: `.codex/skills/unit-and-snapshot-testing/scripts/accept-snapshot.ps1 <TestClassName> <TestMethodName>`\n- All tests: `.codex/skills/unit-and-snapshot-testing/scripts/accept-all-snapshots.ps1`\n- Re-run corresponding tests after accepting snapshots to ensure they pass.\n\n## Recognizing a Verify Failure\n\nEvery time there is a mismatch between received/verified files following will be included in `dotnet test` output. Example:\n\n```\nVerifyException : Directory: /home/me/projects/AttributedDI/test/AttributedDI.SourceGenerator.UnitTests/Snapshots\n  NotEqual:\n    - Received: AddAttributedDiTests.GeneratesAddAttributedDiForEntryPoint.DotNet9_0.received.txt\n      Verified: AddAttributedDiTests.GeneratesAddAttributedDiForEntryPoint.verified.txt\n\n  FileContent:\n\n  NotEqual:\n      Received: AddAttributedDiTests.GeneratesAddAttributedDiForEntryPoint.DotNet9_0.received.txt\n      ...\n      Verified: AddAttributedDiTests.GeneratesAddAttributedDiForEntryPoint.verified.txt\n      ...\n```\n"},"lastSynced":"2026-03-08T02:07:40.056Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing efficient unit testing and snapshot verification capabilities.","zh":"适用于需要高效单元测试和快照验证能力的代码分析代理。","ja":"コード分析エージェントが効率的なユニットテストとスナップショットの検証機能を必要とする場合に適しています。","ko":"코드 분석 에이전트가 효율적인 단위 테스트와 스냅샷 확인 기능을 필요로 할 때 적합합니다.","es":"Perfecto para agentes de análisis de código que necesitan pruebas unitarias eficientes y capacidades de verificación de instantáneas.","fr":"Parfait pour les agents d''analyse de code nécessitant des tests unitaires efficaces et des capacités de vérification d''instantanés.","de":"Perfekt für Code-Analyse-Agents, die effiziente Unit-Tests und Momentaufnahmeverifizierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de teste de unidade eficiente e capacidades de verificação de instantâneo.","ru":"Идеально подходит для агентов анализа кода, которым требуются эффективные возможности юнит-тестирования и верификации снимков.","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى اختبار الوحدة الفعال ويعتمد على التحقق من صحة لقطة الشاشة."},"recommendation":{"en":"Empowers agents to streamline unit testing using Verify snapshot testing tool and domain-specific assertion helpers, ensuring efficient testing of generated output and source code. It provides a structured approach to testing, leveraging snapshot testing for generated output and small assertion helpers for normal assertions.","zh":"赋予代理使用 Verify 快照测试工具和特定领域的断言帮助器来简化单元测试，确保生成的输出和源代码的高效测试。它提供了一种结构化的测试方法，利用快照测试来测试生成的输出和小的断言帮助器来进行正常的断言。","ja":"Verify スナップショットテストツールとドメイン固有のアサーションヘルパーを使用してユニットテストを簡素化することで、エージェントに力を与え、生成された出力とソースコードの効率的なテストを保証する。生成された出力のスナップショットテストと通常のアサーションに小さなアサーションヘルパーを使用する構造化されたテストアプローチを提供する。","ko":"Verify 스냅샷 테스트 도구와 특정 도메인의 assertion 헬퍼를 사용하여 단위 테스트를 간소화함으로써 에이전트에 힘을 부여하여 생성된 출력과 소스 코드의 효율적인 테스트를 보장한다. 생성된 출력의 스냅샷 테스트와 일반 assertion에 작은 assertion 헬퍼를 사용하는 구조화된 테스트 접근 방식을 제공한다.","es":"Habilita a los agentes a optimizar las pruebas unitarias utilizando la herramienta de prueba de instantáneas Verify y ayuda de aserción específica del dominio, garantizando pruebas eficientes de la salida generada y del código fuente. Proporciona un enfoque estructurado para las pruebas, aprovechando las pruebas de instantáneas para la salida generada y pequeñas ayudas de aserción para aserciones normales.","fr":"Permet aux agents de rationaliser les tests unitaires en utilisant l''outil de test d''instantané Verify et des aides d''assertion spécifiques au domaine, garantissant ainsi des tests efficaces de la sortie générée et du code source. Fournit une approche structurée du test, en exploitant les tests d''instantanés pour la sortie générée et de petites aides d''assertion pour les assertions normales.","de":"Ermächtigt Agents, Unit-Tests mit dem Verify-Snapshot-Testtool und domänenspezifischen Assert-Hilfen zu optimieren, um eine effiziente Überprüfung der generierten Ausgabe und des Quellcodes zu gewährleisten. Es bietet einen strukturierten Ansatz für Tests, indem es Snapshot-Tests für die generierte Ausgabe und kleine Assert-Hilfen für normale Asserts nutzt.","pt":"Permite que os agentes otimizem os testes de unidade usando a ferramenta de teste de instantâneo Verify e ajudantes de afirmação específicos de domínio, garantindo testes eficientes da saída gerada e do código-fonte. Ele fornece uma abordagem estruturada para testes, aproveitando o teste de instantâneo para saída gerada e pequenos ajudantes de afirmação para afirmações normais.","ru":"Наделяет агентов возможностью оптимизировать юнит-тесты с помощью инструмента Verify для тестирования снимков и специфичных для домена помощников утверждений, гарантируя эффективное тестирование сгенерированного вывода и исходного кода. Он обеспечивает структурированный подход к тестированию, используя тестирование снимков для сгенерированного вывода и небольших помощников утверждений для обычных утверждений.","ar":"تمكّن الوكيل من简 spermaة اختبارات الوحدة باستخدام أداة اختبار لقطة Verify وأدوات مساعدة للافتراضات الخاصة بالمجال، مما يضمن اختبارات فعالة للإخراج المولد و شفرة المصدر. كما يوفر نهجًا منظمًا للاختبارات، يستفيد من اختبار لقطة للاخراج المولد والمساعدين الصغار للافتراضات العادية."},"useCases":{"en":["Writing efficient unit tests for source generated code","Streamlining testing processes with Verify snapshot testing tool","Creating domain-specific assertion helpers for robust testing"],"zh":["为源代码生成的代码编写高效的单元测试","使用 Verify 快照测试工具简化测试流程","创建特定领域的断言帮助器以实现强大的测试"],"ja":["生成されたコードのための効率的なユニットテストを記述する","Verify スナップショットテストツールを使用してテストプロセスを簡素化する","強力なテストのためにドメイン固有のアサーションヘルパーを作成する"],"ko":["생성된 코드를 위한 효율적인 단위 테스트를 작성하다","Verify 스냅샷 테스트 도구를 사용하여 테스트 프로세스를 간소화하다","강력한 테스트를 위한 특정 도메인의 assertion 헬퍼를 생성하다"],"es":["Escribir pruebas unitarias eficientes para el código generado por el origen","Optimizar los procesos de prueba con la herramienta de prueba de instantáneas Verify","Crear ayudas de aserción específicas del dominio para pruebas robustas"],"fr":["Rédiger des tests unitaires efficaces pour le code généré par la source","Rationaliser les processus de test avec l''outil de test d''instantané Verify","Créer des aides d''assertion spécifiques au domaine pour des tests robustes"],"de":["Effiziente Unit-Tests für den vom Quellcode generierten Code schreiben","Testprozesse mit dem Verify-Snapshot-Testtool optimieren","Domänenspezifische Assert-Hilfen für robuste Tests erstellen"],"pt":["Escrita de testes de unidade eficientes para código gerado pela fonte","Otimização dos processos de teste com a ferramenta de teste de instantâneo Verify","Criação de ajudantes de afirmação específicos de domínio para testes robustos"],"ru":["Написание эффективных юнит-тестов для сгенерированного исходного кода","Оптимизация процессов тестирования с помощью инструмента Verify для тестирования снимков","Создание помощников утверждений, специфичных для домена, для надёжного тестирования"],"ar":["كتابة اختبارات وحدة فعالة للشفرة المولدة من المصدر","تبسيط عمليات الاختبار باستخدام أداة اختبار لقطة Verify","إنشاء مساعد افتراض خاص بالمجال للاختبارات القوية"]},"limitations":{"en":["Limited to unit tests, not applicable for integration or e2e tests","Requires Verify snapshot testing tool"],"zh":["仅限于单元测试，不适用于集成或端到端测试","需要 Verify 快照测试工具"],"ja":["ユニットテストに限定され、統合テストやエンドツーエンドテストには適用できない","Verify スナップショットテストツールが必要"],"ko":["단위 테스트에만 적용되며, 통합 또는 끝에서 끝까지 테스트에는 적용할 수 없음","Verify 스냅샷 테스트 도구가 필요"],"es":["Limitado a pruebas unitarias, no se aplica a pruebas de integración o de extremo a extremo","Requiere la herramienta de prueba de instantáneas Verify"],"fr":["Limité aux tests unitaires, non applicable aux tests d''intégration ou de bout en bout","Nécessite l''outil de test d''instantané Verify"],"de":["Begrenzt auf Unit-Tests, nicht anwendbar für Integrationstests oder End-to-End-Tests","Benötigt das Verify-Snapshot-Testtool"],"pt":["Limitado a testes de unidade, não aplicável a testes de integração ou e2e","Exige a ferramenta de teste de instantâneo Verify"],"ru":["Ограничен юнит-тестами, не применимо к интеграционным или e2e-тестам","Требует инструмента Verify для тестирования снимков"],"ar":["محدود باختبارات الوحدة، لا ينطبق على اختبارات التكامل أو من النهاية إلى النهاية","يتطلب أداة اختبار لقطة Verify"]},"version":4},"contentHash":"bc1f89a06abccbe1a6c55f36e69c793f613feca3648ba62199ec1d17092bfe31","qualityScore":39}');
